def _weight_matmul_dispatch_status(codec: str) -> dict:
    if codec == "turboquant_codebook":
        return {
            "primary": "jang_tools_turboquant_custom_kernels",
            "uses_mlx_quantized_matmul": False,
            "metal_na_eligible": False,
            "reason": "turboquant_codebook_uses_custom_tq_kernels",
        }
    if codec == "affine_quantized_matmul":
        return {
            "primary": "mlx_affine_quantized_matmul",
            "uses_mlx_quantized_matmul": True,
            "metal_na_eligible": True,
            "reason": None,
        }
    return {
        "primary": "full_precision_or_unknown",
        "uses_mlx_quantized_matmul": False,
        "metal_na_eligible": False,
        "reason": "not_quantized_matmul",
    }


def _normalize_jangtq_mpp_nax_mode(raw: str | None = None) -> tuple[str, str | None]:
    """Normalize the internal JANGTQ acceleration env."""
    value = os.environ.get("JANGTQ_MPP_NAX", "auto") if raw is None else raw
    text = str(value or "").strip().lower()
    if text in ("", "0", "false", "no", "off"):
        return "off", None
    if text == "auto":
        return "auto", None
    if text in ("1", "true", "yes", "on"):
        return "on", None
    return "auto", f"invalid JANGTQ_MPP_NAX={value!r}; expected off/auto/on"


@functools.lru_cache(maxsize=1)
def _jangtq_mpp_nax_available() -> tuple[bool, str | None]:
    try:
        from jang_tools.turboquant.mpp_nax_kernel import mpp_nax_tensorops_available

        # This must stay a non-executing capability query. The implementation in
        # jang-tools intentionally avoids a smoke Metal dispatch because /health
        # can run after a large mmap-backed model has claimed most of the MLX
        # working set. Real generation kernels still compile/dispatch on demand
        # and fall back unless strict mode is enabled.
        return bool(mpp_nax_tensorops_available()), None
    except Exception as exc:
        return False, f"{type(exc).__name__}: {exc}"


def _jangtq_mpp_nax_runtime_status(host: dict | None = None) -> dict:
    mode, mode_issue = _normalize_jangtq_mpp_nax_mode()
    requested = mode in ("auto", "on")
    host = host or _host_supports_metal_na()
    host_supported = bool(host.get("supported"))
    available, availability_error = (
        _jangtq_mpp_nax_available() if requested else (False, None)
    )

    active = bool(requested and host_supported and available)
    reason = None
    if mode_issue:
        reason = mode_issue
    elif not requested:
        reason = "disabled"
    elif not host_supported:
        reason = host.get("reason") or "host_not_known_na_capable"
    elif not available:
        reason = availability_error or "mpp_nax_tensorops_unavailable"

    return {
        "mode": mode,
        "requested": requested,
        "available": bool(available),
        "active": active,
        "uses_mlx_quantized_matmul": False,
        "reason": reason,
    }


def _bundle_index_tensor_prefix_status(
    bundle_path: str | None,
    prefix: str,
) -> tuple[bool, str | None]:
    if not bundle_path:
        return False, None
    try:
        from pathlib import Path

        index_path = Path(bundle_path) / "model.safetensors.index.json"
        if not index_path.is_file():
            return False, None
        index = json.loads(index_path.read_text())
        weight_map = index.get("weight_map") if isinstance(index, dict) else None
        if not isinstance(weight_map, dict):
            return False, "model.safetensors.index.json has no weight_map object"
        return any(str(key).startswith(prefix) for key in weight_map), None
    except Exception as exc:
        return False, f"model.safetensors.index.json read failed: {type(exc).__name__}: {exc}"


def _bundle_index_mtp_layer_count(bundle_path: str | None) -> int | None:
    """Count distinct ``mtp.N.*`` layer indexes in the bundle's weight map.

    Returns the highest-N + 1 (i.e. layer count) when at least one mtp.N tensor
    is present, else None. Used to cross-check
    ``config.num_nextn_predict_layers`` so a bundle that ships partial MTP
    weights doesn't silently report ``artifact_available=True`` with a wrong
    layer count.
    """
    try:
        from .native_mtp import bundle_index_mtp_layer_count

        return bundle_index_mtp_layer_count(bundle_path)
    except Exception:
        pass
    if not bundle_path:
        return None
    try:
        from pathlib import Path
        import re as _re

        index_path = Path(bundle_path) / "model.safetensors.index.json"
        if not index_path.is_file():
            return None
        index = json.loads(index_path.read_text())
        weight_map = index.get("weight_map") if isinstance(index, dict) else None
        if not isinstance(weight_map, dict):
            return None
        layer_re = _re.compile(r"^mtp\.(\d+)(?:\.|$)")
        indexes: set[int] = set()
        for key in weight_map:
            m = layer_re.match(str(key))
            if m:
                indexes.add(int(m.group(1)))
        if not indexes:
            return None
        return len(indexes)
    except Exception:
        return None


_JANGMTP_FAMILY_ALIAS = {
    "qwen3_5_moe_text": "qwen3_5_moe",
    "hy3": "hy_v3",
    "zaya_vl": "zaya1_vl",
    # "mininax" was here as an alias for "minimax" — a typo introduced whole
    # in b4a06b876 that never fired, because the key never occurs as a real
    # family name. Corrected rather than kept: an alias map that silently does
    # nothing is worse than no alias, since it reads as coverage.
    "minimax_m2": "minimax",
    "minimax_m2_5": "minimax",
}

_JANGMTP_SUPPORTED_FAMILIES: set[str] = {
    "qwen3_5",
    "qwen3_5_moe",
    "qwen3_next",
    "gemma4",
    "nemotron",
    "nemotron_h",
    "hy_v3",
    "minimax",
    "zaya",
    "zaya1_vl",
}


def _normalize_jangmtp_family(name: str | None) -> str | None:
    if not name:
        return None
    normalized = str(name).strip().lower()
    return _JANGMTP_FAMILY_ALIAS.get(normalized, normalized)


def _bundle_mtp_family(bundle_path: str | None) -> str | None:
    if not bundle_path:
        return None
    try:
        from .model_config_registry import get_model_config_registry

        cfg = get_model_config_registry().lookup(bundle_path)
        family_name = getattr(cfg, "family_name", None)
        if family_name:
            normalized = _normalize_jangmtp_family(family_name)
            if normalized and normalized != "unknown":
                return normalized
    except Exception:
        # Keep telemetry functional even if registry is unavailable.
        pass

    cfg = _read_bundle_json(bundle_path, "config.json")
    return _normalize_jangmtp_family(cfg.get("model_type"))


def _bundle_mtp_runtime_supported(family: str | None) -> bool:
    """Is this family actually served by the native MTP runtime?

    Defers to native_mtp's set, which is the ONLY list that governs engagement
    at runtime. The local _JANGMTP_SUPPORTED_FAMILIES literal below listed ten
    families — including gemma4, nemotron_h and minimax — that the live runtime
    rejects, so on the one path that reaches it (inspect_native_mtp_bundle
    raising) it would have reported MTP supported for models that silently run
    autoregressive. Kept only as a last-resort fallback so behaviour on that
    path does not become "unsupported for everything".
    """
    if not family:
        return False
    normalized = _normalize_jangmtp_family(family)
    try:
        from .native_mtp import _RUNTIME_SUPPORTED_FAMILIES

        return normalized in _RUNTIME_SUPPORTED_FAMILIES
    except Exception:  # noqa: BLE001
        return normalized in _JANGMTP_SUPPORTED_FAMILIES


def _model_mtp_status(bundle_path: str | None) -> dict:
    """Describe whether a bundle contains usable multi-token prediction heads."""
    try:
        from .native_mtp import inspect_native_mtp_bundle

        return inspect_native_mtp_bundle(bundle_path)
    except Exception:
        pass
    cfg = _read_bundle_json(bundle_path, "config.json")
    jang_cfg = _read_bundle_json(bundle_path, "jang_config.json")
    family = _bundle_mtp_family(bundle_path)
    raw_layers = cfg.get("num_nextn_predict_layers")
    invalid_config_layers = False
    try:
        config_layers = int(raw_layers) if raw_layers is not None else None
    except (TypeError, ValueError):
        config_layers = None
        invalid_config_layers = True
    drop_mtp_raw = jang_cfg.get("drop_mtp")
    # Strict boolean check: only literal True is treated as "drop". Truthy
    # non-bool values (e.g. "yes", 1) historically slipped past the
    # `drop_mtp is True` identity check and were silently treated as "don't
    # drop", which then claimed weights_present_runtime_unwired even when the
    # bundle author tried to disable MTP. Flag invalid types loudly.
    drop_mtp_invalid_type = (
        drop_mtp_raw is not None and not isinstance(drop_mtp_raw, bool)
    )
    drop_mtp = drop_mtp_raw if isinstance(drop_mtp_raw, bool) else None
    has_mtp_tensors, index_error = _bundle_index_tensor_prefix_status(
        bundle_path,
        "mtp.",
    )
    indexed_mtp_layer_count = _bundle_index_mtp_layer_count(bundle_path)

    issues: list[str] = []
    if index_error:
        issues.append(index_error)
    if invalid_config_layers:
        issues.append(
            "config.num_nextn_predict_layers is invalid; expected an integer"
        )
    if config_layers is not None and config_layers < 0:
        # Negative layer count is corrupt metadata. Pin loudly so callers
        # don't silently treat it as "configured without runtime".
        issues.append(
            "config.num_nextn_predict_layers is negative "
            f"({config_layers}); expected a non-negative integer"
        )
    if drop_mtp_invalid_type:
        issues.append(
            "jang_config.drop_mtp must be a boolean; got "
            f"{type(drop_mtp_raw).__name__}: {drop_mtp_raw!r}"
        )
    if config_layers and config_layers > 0 and drop_mtp is not True and not has_mtp_tensors:
        issues.append(
            "config expects MTP next-token prediction layers, but the bundle "
            "index has no mtp.* tensors"
        )
    if config_layers in (None, 0) and drop_mtp is not True and has_mtp_tensors:
        issues.append(
            "bundle indexes mtp.* tensors but config disables MTP runtime"
        )
    if drop_mtp is True and config_layers not in (None, 0):
        issues.append(
            "jang_config.drop_mtp=true but config.num_nextn_predict_layers="
            f"{config_layers}"
        )
    if (
        config_layers is not None
        and config_layers > 0
        and indexed_mtp_layer_count is not None
        and indexed_mtp_layer_count != config_layers
        and drop_mtp is not True
    ):
        # Bundle indexes a different number of distinct mtp.N layers than the
        # config claims. Either the converter wrote partial MTP weights
        # (artifact corruption) or num_nextn_predict_layers was edited
        # without re-running the converter. Either way, runtime acceleration
        # would silently use the wrong layer count.
        issues.append(
            f"config.num_nextn_predict_layers={config_layers} but bundle "
            f"index has {indexed_mtp_layer_count} distinct mtp.N layer(s)"
        )
    if drop_mtp is True and has_mtp_tensors:
        issues.append("jang_config.drop_mtp=true but bundle still indexes mtp.* tensors")

    artifact_available = bool(
        config_layers
        and config_layers > 0
        and drop_mtp is not True
        and has_mtp_tensors
        and not issues
    )
    runtime_supported = _bundle_mtp_runtime_supported(family)
    # vMLX does not yet have a verifier / accept-reject MTP decode path wired
    # through the scheduler. Presence of mtp.* weights is an artifact fact, not
    # proof that runtime acceleration is active.
    runtime_available = False
    runtime_reason = None
    if issues:
        status = "metadata_inconsistent"
        runtime_reason = "metadata_inconsistent"
    elif drop_mtp is True:
        status = "dropped"
        runtime_reason = "jang_config.drop_mtp=true"
    elif artifact_available:
        status = "weights_present_runtime_unwired"
        if runtime_supported:
            runtime_reason = (
                "MTP metadata is present and family is in the JangMTP "
                "candidate set; runtime decode wiring is not implemented in vMLX yet"
            )
        else:
            runtime_reason = (
                f"MTP metadata is present for family '{family or 'unknown'}', but "
                "this family is not currently on the JangMTP support map"
            )
    elif config_layers:
        status = "configured_without_runtime"
        runtime_reason = "config requests MTP but runtime requirements are incomplete"
    else:
        status = "not_configured"
        runtime_reason = "config does not request MTP"

    return {
        "config_num_nextn_predict_layers": config_layers,
        "jang_drop_mtp": drop_mtp,
        "index_has_mtp_tensors": has_mtp_tensors,
        "artifact_available": artifact_available,
        "family": family,
        "runtime_supported": runtime_supported,
        "runtime_available": runtime_available,
        "runtime_reason": runtime_reason,
        "status": status,
        "issues": issues,
    }


def _mllm_native_mtp_request_gate_status() -> tuple[bool, str]:
    """Return the live MLLM sampled-request gate and its health description.

    Keep this tied to the generator's imported flag rather than re-reading the
    environment: the process-level value is frozen when the runtime module is
    imported, and health must describe the code path the loaded process will
    actually execute.
    """
    try:
        from .mllm_batch_generator import _NATIVE_MTP_STOCHASTIC_ACCEPT

        stochastic_enabled = bool(_NATIVE_MTP_STOCHASTIC_ACCEPT)
    except Exception:
        stochastic_enabled = False
    gate = "greedy=identity-verify; stochastic=" + (
        "rejection-sampling-acceptance"
        if stochastic_enabled
        else "skipped-by-policy"
    )
    return stochastic_enabled, gate


def _model_mtp_status_with_loaded_runtime(bundle_path: str | None) -> dict:
    """MTP artifact status plus the currently loaded runtime activation bit."""
    status = dict(_model_mtp_status(bundle_path))
    from .native_mtp import native_mtp_disabled_by_env

    try:
        from .metal.native_mtp_verify_qmm import native_mtp_verify_qmm_status

        # This is intentionally live rather than bundle-derived.  The
        # dispatcher used to log itself as active even when dflash-mlx's own
        # environment gate made every eligible call fall back to stock MLX.
        # Exposing the dependency bit and eligible-call counter lets health
        # distinguish configured intent from an actually exercised kernel.
        status["verify_qmm"] = native_mtp_verify_qmm_status()
    except Exception:
        pass

    native_disabled = native_mtp_disabled_by_env()
    status["request_policy"] = (
        "disabled" if native_disabled else os.environ.get(
            "VMLINUX_NATIVE_MTP_SAMPLING_POLICY",
            _native_mtp_sampling_policy,
        )
    )
    _depth_policy_raw = os.environ.get(
        "VMLINUX_NATIVE_MTP_ADAPTIVE_DEPTH",
        os.environ.get("VMLX_NATIVE_MTP_ADAPTIVE_DEPTH", "1"),
    ).strip().lower()
    status["depth_policy"] = (
        "fixed" if _depth_policy_raw in {"0", "false", "no", "off"} else "adaptive"
    )
    # Greedy requests take identity verify. Sampled MLLM requests use the
    # shared rejection-sampling rule when enabled; the kill switch restores
    # the old deterministic-only gate. Publish the imported runtime value so
    # health cannot claim stochastic support while the generator skips it.
    stochastic_enabled, request_gate = _mllm_native_mtp_request_gate_status()
    status["stochastic_acceptance_enabled"] = stochastic_enabled
    status["stochastic_requests_allowed"] = bool(
        stochastic_enabled and status["request_policy"] not in {"disabled", "greedy-only"}
    )
    status["request_gate"] = (
        "greedy=enforced; stochastic=blocked-by-server-policy"
        if status["request_policy"] == "greedy-only"
        else request_gate
    )
    try:
        from .native_mtp import model_has_native_mtp_runtime

        model = _get_raw_model_from_engine()
        active = bool(model is not None and model_has_native_mtp_runtime(model))
        status["runtime_active"] = False if native_disabled else active
        if native_disabled and status.get("runtime_available"):
            status["runtime_reason"] = "native MTP disabled by --disable-native-mtp/VMLINUX_NATIVE_MTP=0"
        if (not native_disabled) and active and status.get("runtime_available"):
            status["status"] = "native_runtime_active"
            scope = status.get("runtime_scope") or "text"
            status["runtime_reason"] = f"native MTP runtime is active for {scope}"
            if status.get("effective_depth") is None:
                try:
                    from .native_mtp import native_mtp_effective_depth

                    depth, source = native_mtp_effective_depth()
                    status["effective_depth"] = depth
                    status["effective_depth_source"] = source
                except Exception:
                    pass
    except Exception:
        pass
    return status


def _model_quantization_status(bundle_path: str | None) -> dict:
    """Describe the loaded weight codec from bundle metadata without guessing.

    This is intentionally separate from live KV-cache quantization. Weight
    quantization decides which matmul kernel family is used; TQ-KV decides how
    prefix/cache tensors are stored.
    """
    cfg = _read_bundle_json(bundle_path, "config.json")
    jang_cfg = _read_bundle_json(bundle_path, "jang_config.json")
    q_cfg = cfg.get("quantization") if isinstance(cfg.get("quantization"), dict) else {}
    q_jang = (
        jang_cfg.get("quantization")
        if isinstance(jang_cfg.get("quantization"), dict)
        else {}
    )

    weight_format = (
        cfg.get("weight_format")
        or jang_cfg.get("weight_format")
        or q_jang.get("format")
        or q_jang.get("weight_format")
        or q_cfg.get("format")
    )
    # A generic "mlx" stamp names the loader, not the codec. The 2026-08
    # Nemotron bundles carry the actual codec in quantization.mode/method
    # (mxfp8/mxfp4) — surface that instead of the uninformative wrapper.
    if str(weight_format or "").strip().lower() in ("", "mlx"):
        _codec = (
            q_cfg.get("mode")
            or q_cfg.get("method")
            or q_jang.get("mode")
            or q_jang.get("method")
        )
        if isinstance(_codec, str) and _codec.strip().lower() not in ("", "none", "mlx"):
            weight_format = _codec.strip().lower()
    backend = q_jang.get("quantization_backend") or q_jang.get("backend")
    profile = q_jang.get("profile") or jang_cfg.get("profile") or cfg.get("profile")
    mxtq_bits = (
        cfg.get("mxtq_bits")
        or jang_cfg.get("mxtq_bits")
        or q_jang.get("mxtq_bits")
        or q_jang.get("bits_default")
    )
    affine_bits = (
        cfg.get("affine_bits")
        or jang_cfg.get("affine_bits")
        or q_jang.get("affine_bits")
    )
    profile_bits = _jangtq_bits_from_profile(profile)
    normalized_format = str(weight_format or "").lower()
    is_affine_jang_metadata = normalized_format in ("affine", "jang", "jjqf", "mxq")
    bits_by_role = affine_bits if is_affine_jang_metadata and affine_bits else mxtq_bits
    routed_expert_bits_raw = (
        bits_by_role.get("routed_expert")
        if isinstance(bits_by_role, dict)
        else bits_by_role
    )
    if routed_expert_bits_raw is None:
        routed_expert_bits_raw = profile_bits
    routed_expert_bits = None
    routed_expert_bits_by_projection = None
    routed_expert_bits_label = None
    if isinstance(routed_expert_bits_raw, dict):
        order = ("gate_proj", "up_proj", "down_proj")
        routed_expert_bits_by_projection = {
            key: int(routed_expert_bits_raw[key])
            for key in order
            if key in routed_expert_bits_raw
        }
        for key, value in routed_expert_bits_raw.items():
            if key not in routed_expert_bits_by_projection:
                routed_expert_bits_by_projection[str(key)] = int(value)
        short = {
            "gate_proj": "gate",
            "up_proj": "up",
            "down_proj": "down",
        }
        routed_expert_bits_label = (
            "/".join(
                f"{short.get(key, key)}={value}"
                for key, value in routed_expert_bits_by_projection.items()
            )
            + "-bit"
        )
    elif routed_expert_bits_raw is not None:
        routed_expert_bits = int(routed_expert_bits_raw)
    target_bits = (
        q_jang.get("target_bits")
        or q_jang.get("bits")
        or routed_expert_bits
        or (
            min(routed_expert_bits_by_projection.values())
            if routed_expert_bits_by_projection
            else None
        )
        or profile_bits
        or q_cfg.get("bits")
    )
    actual_bits = (
        q_jang.get("actual_bits")
        or q_jang.get("actual_bits_per_weight")
        or jang_cfg.get("actual_bits")
    )
    routed_layer_bits, routed_layer_bits_source = _find_routed_layer_bit_plan(
        cfg, jang_cfg, q_jang
    )
    routed_projection_bits, routed_projection_bits_source = (
        _find_routed_projection_bit_plan(cfg, jang_cfg, q_jang)
    )
    routed_down_layer_bits, routed_down_layer_bits_source = (
        _find_routed_down_layer_bit_plan(cfg, jang_cfg, q_jang)
    )
    weight_index = _bundle_weight_index_status(bundle_path)

    try:
        from pathlib import Path

        root = Path(bundle_path) if bundle_path else None
        has_jangtq_sidecar = bool(root and (root / "jangtq_runtime.safetensors").is_file())
        has_jang_config = bool(root and (root / "jang_config.json").is_file())
        has_prestacked_bundle = _bundle_has_prestacked_jangtq(bundle_path)
    except Exception:
        has_jangtq_sidecar = False
        has_jang_config = False
        has_prestacked_bundle = False

    normalized_backend = str(backend or "").lower()
    if normalized_format in ("mxtq", "jangtq") or has_jangtq_sidecar:
        codec = "turboquant_codebook"
    elif normalized_format in ("mxfp4", "mxfp8", "nvfp4", "fp4", "fp8"):
        codec = "affine_quantized_matmul"
    elif normalized_format in ("jang", "jjqf", "mxq"):
        codec = "affine_quantized_matmul"
    elif normalized_backend in ("mlx", "mlx_uniform", "affine"):
        codec = "affine_quantized_matmul"
    elif q_cfg or target_bits or actual_bits:
        codec = "affine_quantized_matmul"
    else:
        codec = "full_precision_or_unknown"

    model_types = {
        str(cfg.get("model_type") or "").lower(),
        str(
            cfg.get("text_config", {}).get("model_type")
            if isinstance(cfg.get("text_config"), dict)
            else ""
        ).lower(),
    }
    hybrid_conv_families = {
        "qwen3_next",
        "qwen3_5",
        "qwen3_5_moe",
        "nemotron_h",
        "nemotron_h_v2",
        "mamba",
        "mamba2",
        "codestral_mamba",
        "bailing_hybrid",
        "bailing_moe_v2_5",
        "granitemoehybrid",
        "lfm2_moe",
    }
    compat_warnings = []
    if codec == "turboquant_codebook" and (
        profile_bits == 1 or routed_expert_bits == 1
    ):
        compat_warnings.append(
            "JANGTQ1 is recognized for metadata compatibility only and is not "
            "production-supported; use JANGTQ2/JANGTQ4 or affine JANG for "
            "release-quality generation."
        )
    if (
        has_jang_config
        and model_types.intersection(hybrid_conv_families)
        and q_jang.get("passthrough_tensor_count") is None
    ):
        compat_warnings.append(
            "Hybrid SSM/Mamba bundle does not report fp16 state passthrough "
            "metadata; vMLX applies a runtime grouped-Conv1d layout backstop, "
            "but direct mlx_lm users should re-convert with a newer jang build."
        )
    routed_experts_cfg = (
        q_jang.get("routed_experts")
        if isinstance(q_jang.get("routed_experts"), dict)
        else {}
    )
    runtime_cfg = (
        jang_cfg.get("runtime")
        if isinstance(jang_cfg.get("runtime"), dict)
        else {}
    )
    affine_dsv4_routed = (
        "deepseek_v4" in model_types
        and codec == "affine_quantized_matmul"
        and (
            normalized_format == "affine"
            or str(q_jang.get("method") or "").lower() == "affine"
            or str(routed_experts_cfg.get("codec") or "").lower() == "affine"
        )
        and routed_experts_cfg
    )
    dsv4_affine_verified = bool(
        jang_cfg.get("coherency_verified")
        or jang_cfg.get("runtime_verified")
        or runtime_cfg.get("coherency_verified")
        or runtime_cfg.get("ar_coherency_verified")
    )
    if affine_dsv4_routed and not dsv4_affine_verified:
        compat_warnings.append(
            "DSV4 affine routed JANG runtime is loaded but not coherency-verified; "
            "require a live DeepSeek-V4 AR logits/decode gate before production use."
        )

    result = {
        "codec": codec,
        "weight_format": weight_format,
        "backend": backend,
        "profile": profile,
        "mxtq_bits": mxtq_bits if not isinstance(mxtq_bits, dict) else None,
        "mxtq_bits_by_role": mxtq_bits if isinstance(mxtq_bits, dict) else None,
        "affine_bits": affine_bits if not isinstance(affine_bits, dict) else None,
        "affine_bits_by_role": affine_bits if isinstance(affine_bits, dict) else None,
        "routed_expert_bits": routed_expert_bits,
        "routed_expert_bits_by_projection": routed_expert_bits_by_projection,
        "routed_expert_bits_label": routed_expert_bits_label,
        "target_bits": target_bits,
        "actual_bits": actual_bits,
        "config_bits": q_cfg.get("bits"),
        "group_size": q_cfg.get("group_size") or q_jang.get("group_size") or q_jang.get("block_size"),
        "routed_layer_bits": routed_layer_bits,
        "routed_layer_bits_source": routed_layer_bits_source,
        "routed_projection_bits": routed_projection_bits,
        "routed_projection_bits_source": routed_projection_bits_source,
        "routed_down_layer_bits": routed_down_layer_bits,
        "routed_down_layer_bits_source": routed_down_layer_bits_source,
        "passthrough_bit_widths_used": q_jang.get("passthrough_bit_widths_used"),
        "passthrough_tensor_count": q_jang.get("passthrough_tensor_count"),
        "weight_index": weight_index,
        "weight_matmul_dispatch": _weight_matmul_dispatch_status(codec),
        "compat_warnings": compat_warnings or None,
        "sidecar": {
            "jang_config": has_jang_config,
            "jangtq_runtime": has_jangtq_sidecar,
            "prestacked_bundle": has_prestacked_bundle,
        },
    }
    return {k: v for k, v in result.items() if v is not None}


def _model_routing_status(bundle_path: str | None) -> dict:
    """Expose trained MoE active-expert K and any explicit JANGTQ override."""
    cfg = _read_bundle_json(bundle_path, "config.json")

    def _config_sections():
        yield "config", cfg
        for key in ("text_config", "language_config", "llm_config"):
            sub = cfg.get(key)
            if isinstance(sub, dict):
                yield f"config.{key}", sub

    def _first_int(keys: tuple[str, ...]) -> tuple[int | None, str | None]:
        for prefix, section in _config_sections():
            for key in keys:
                raw = section.get(key)
                if raw is None:
                    continue
                try:
                    value = int(raw)
                except (TypeError, ValueError):
                    continue
                if value > 0:
                    return value, f"{prefix}.{key}"
        return None, None

    trained_k, trained_source = _first_int(
        (
            "num_experts_per_tok",
            "top_k_experts",
            "moe_router_topk",
            "num_activated_experts",
            "top_k",
        )
    )
    routed_experts, _routed_source = _first_int(
        ("n_routed_experts", "num_local_experts", "num_experts")
    )

    if trained_k is None and routed_experts is None:
        return {}

    effective_k = trained_k
    effective_source = "trained_default" if trained_k is not None else None

    result = {
        "trained_active_experts": trained_k,
        "trained_active_experts_source": trained_source,
        "n_routed_experts": routed_experts,
        "override_env": None,
        "effective_active_experts": effective_k,
        "effective_active_experts_source": effective_source,
    }
    return {k: v for k, v in result.items() if v is not None or k == "override_env"}


def _mlx_metal_na_status() -> dict:
    """Return cached MLX metallib NA symbol availability for this process."""
    try:
        import importlib
        import mlx
        from pathlib import Path

        mlx_file = getattr(mlx, "__file__", None)
        if mlx_file:
            mlx_dir = Path(mlx_file).resolve().parent
        else:
            # `mlx` can be a namespace package with `__file__ == None`; the
            # compiled extension path lives on `mlx.core.__file__`.
            mlx_core = importlib.import_module("mlx.core")
            mlx_dir = Path(getattr(mlx_core, "__file__")).resolve().parent

        metallib = mlx_dir / "lib" / "mlx.metallib"
        key = str(metallib)
        if key in _metal_na_status_cache:
            return dict(_metal_na_status_cache[key])
        if not metallib.is_file():
            status = {
                "metallib": key,
                "available": False,
                "nax_symbols": 0,
                "naxtile_symbols": 0,
                "affine_qmm_symbols": 0,
                "affine_gather_qmm_symbols": 0,
            }
        else:
            data = metallib.read_bytes()
            nax = data.count(b"_nax_")
            naxtile = data.count(b"NAXTile")
            affine_qmm = data.count(b"affine_qmm")
            affine_gather_qmm = data.count(b"affine_gather_qmm")
            status = {
                "metallib": key,
                "available": bool(nax or naxtile or affine_qmm or affine_gather_qmm),
                "nax_symbols": nax,
                "naxtile_symbols": naxtile,
                "affine_qmm_symbols": affine_qmm,
                "affine_gather_qmm_symbols": affine_gather_qmm,
            }
        _metal_na_status_cache[key] = dict(status)
        return status
    except Exception as exc:
        return {
            "available": False,
            "nax_symbols": 0,
            "naxtile_symbols": 0,
            "affine_qmm_symbols": 0,
            "affine_gather_qmm_symbols": 0,
            "error": type(exc).__name__,
        }


def _host_supports_metal_na() -> dict:
    """Best-effort host check for Apple NA-capable GPU generations."""
    if platform.system() != "Darwin":
        return {"supported": False, "reason": "not_darwin"}
    try:
        proc = subprocess.run(
            ["sysctl", "-n", "machdep.cpu.brand_string"],
            capture_output=True,
            text=True,
            timeout=1.0,
            check=False,
        )
        brand = (proc.stdout or "").strip()
    except Exception:
        brand = ""
    # Be conservative: report active only on known M5+ Apple Silicon names.
    supported = bool(re.search(r"\bApple M([5-9]|\d{2,})\b", brand))
    return {
        "supported": supported,
        "brand": brand or None,
        "reason": None if supported else "host_not_known_na_capable",
    }


def _loaded_acceleration_attestation() -> dict[str, Any] | None:
    """Find loader-owned acceleration facts on the active model graph."""

    from .acceleration_contract import find_acceleration_attestation

    roots: list[Any] = []
    if _engine is not None:
        roots.append(_engine)
    try:
        scheduler = _get_scheduler()
    except Exception:
        scheduler = None
    if scheduler is not None:
        roots.append(scheduler)

    candidates: list[Any] = []
    pending = list(roots)
    seen: set[int] = set()
    while pending and len(candidates) < 24:
        candidate = pending.pop(0)
        if candidate is None or id(candidate) in seen:
            continue
        seen.add(id(candidate))
        candidates.append(candidate)
        for name in (
            "_model",
            "model",
            "language_model",
            "_engine",
            "engine",
        ):
            nested = _diagnostic_attr(candidate, name)
            if nested is not None and id(nested) not in seen:
                pending.append(nested)
    return find_acceleration_attestation(candidates)


def _dsv4_indexer_runtime_feature(status: dict[str, Any]) -> dict[str, Any]:
    """Separate successful DSV4 indexer calls from later stock fallbacks."""

    calls = int(status.get("calls", 0) or 0)
    return {
        "installed": status.get("self_test") == "passed",
        "observed_calls": calls,
        "reason": None if calls else status.get("reason") or status.get("declined"),
        "last_fallback_reason": status.get("declined"),
    }


def _family_acceleration_contract(bundle_path: str | None) -> dict[str, Any]:
    """Return configured and loader-attested acceleration without inference."""

    from .acceleration_contract import (
        acceleration_family_from_config,
        build_acceleration_contract,
        canonical_acceleration_family,
    )

    config = _read_bundle_json(bundle_path, "config.json")
    family = acceleration_family_from_config(config)
    recorded = _loaded_acceleration_attestation()
    if family is None and isinstance(recorded, dict):
        family = canonical_acceleration_family(recorded.get("family"))
    if family is None:
        current = _current_model_config()
        family = canonical_acceleration_family(
            getattr(current, "family_name", None) if current is not None else None
        )

    runtime = dict(recorded) if isinstance(recorded, dict) else {}
    runtime_features = {
        key: dict(value)
        for key, value in runtime.get("features", {}).items()
        if isinstance(value, dict)
    }
    try:
        if family == "qwen4_exp":
            from .metal.affine_moe_pair_decode import affine_moe_pair_status
            from .metal.gated_rmsnorm_decode import gated_rmsnorm_decode_status
            from .metal.gdn_conv_decode import qwen4_gdn_conv_status
            from .metal.ple_conv_decode import qwen4_ple_conv_status
            from .metal.qwen4_affine_moe_decode import qwen4_affine_moe_status
            from .metal.sparse_index_score_decode import sparse_index_score_status

            runtime_features["affine_moe"] = {
                **runtime_features.get("affine_moe", {}),
                **qwen4_affine_moe_status(),
            }
            runtime_features["affine_moe_pair"] = {
                **runtime_features.get("affine_moe_pair", {}),
                **affine_moe_pair_status("qwen4_exp"),
            }
            runtime_features["gdn_conv_state"] = qwen4_gdn_conv_status()
            runtime_features["ple_conv_state"] = qwen4_ple_conv_status()
            runtime_features["qsa_sparse_score"] = sparse_index_score_status(
                "qwen4_exp"
            )
            runtime_features["gated_rmsnorm"] = gated_rmsnorm_decode_status()
        elif family == "glm5_next":
            from .metal.affine_moe_pair_decode import affine_moe_pair_status
            from .metal.gated_rmsnorm_decode import gated_rmsnorm_decode_status
            from .metal.glm5_hc_place_decode import glm5_hc_place_status
            from .metal.glm5_mhc_decode import glm5_mhc_status
            from .metal.kda_conv_decode import glm5_kda_conv_status
            from .metal.kda_step_decode import glm5_kda_step_status
            from .metal.sparse_index_score_decode import sparse_index_score_status

            runtime_features["affine_moe_pair"] = {
                **runtime_features.get("affine_moe_pair", {}),
                **affine_moe_pair_status("glm5_next"),
            }
            runtime_features["kda_conv_state"] = glm5_kda_conv_status()
            runtime_features["kda_recurrent_step"] = glm5_kda_step_status()
            runtime_features["mhc_transform"] = glm5_mhc_status()
            runtime_features["hc_place"] = glm5_hc_place_status()
            runtime_features["dsa_sparse_score"] = sparse_index_score_status(
                "glm5_next"
            )
            runtime_features["gated_rmsnorm"] = gated_rmsnorm_decode_status()
        elif family in {"qwen3_5", "qwen3_5_moe"}:
            from .metal.gdn_conv_decode import qwen35_gdn_conv_status
            from .metal.native_mtp_verify_qmm import native_mtp_verify_qmm_status
            from .metal.qwen35_gdn_gate_terms import (
                qwen35_gdn_gate_terms_status,
            )
            from .models.qwen3_5_family.register import (
                qwen3_5_family_runtime_status,
            )

            runtime_features["vendored_hybrid_runtime"] = (
                qwen3_5_family_runtime_status()
            )
            runtime_features["gdn_conv_state"] = qwen35_gdn_conv_status()
            runtime_features["gdn_gate_terms"] = qwen35_gdn_gate_terms_status()
            runtime_features["mtp_verify_qmm"] = native_mtp_verify_qmm_status()
        elif family == "deepseek_v4":
            from jang_tools.dsv4.indexer_scores_kernel import (
                fused_indexer_status,
            )

            from .metal.fused_pair_moe_decode import dsv4_fused_pair_moe_status

            runtime_features["indexer_scores"] = (
                _dsv4_indexer_runtime_feature(fused_indexer_status())
            )
            runtime_features["fused_moe_pair"] = {
                **runtime_features.get("fused_moe_pair", {}),
                **dsv4_fused_pair_moe_status(),
            }
    except Exception as exc:
        runtime["status_collection_error"] = type(exc).__name__

    runtime["features"] = runtime_features
    return build_acceleration_contract(family, runtime)


def _model_acceleration_status(bundle_path: str | None = None) -> dict:
    quantization = _model_quantization_status(bundle_path or _model_path)
    codec = quantization.get("codec")
    na_status = _mlx_metal_na_status()
    host = _host_supports_metal_na()

    if codec == "turboquant_codebook":
        mpp_nax = _jangtq_mpp_nax_runtime_status(host)
        active = bool(mpp_nax.get("active"))
        kernel_type = (
            "turboquant_codebook_mpp_nax" if active else "turboquant_codebook"
        )
        reason = None
        if not active:
            reason = (
                "turboquant_custom_kernels_do_not_use_mlx_na"
                if mpp_nax.get("mode") == "off"
                else (
                    mpp_nax.get("reason")
                    or "turboquant_custom_kernels_do_not_use_mlx_na"
                )
            )
        metal_na_capable = bool(
            mpp_nax.get("requested") and host.get("supported") and mpp_nax.get("available")
        )
    elif codec == "affine_quantized_matmul":
        kernel_type = "affine_quantized_matmul"
        active = bool(na_status.get("available") and host.get("supported"))
        reason = None if active else "mlx_na_symbols_or_host_support_unavailable"
        metal_na_capable = True
    else:
        kernel_type = "full_precision_or_unknown"
        active = False
        reason = "not_affine_quantized_matmul"
        metal_na_capable = False

    result = {
        "kernel_type": kernel_type,
        "metal_na_capable": metal_na_capable,
        "metal_na_active_on_host": active,
        "reason": reason,
        "metal_na_symbols": {
            "available": bool(na_status.get("available")),
            "nax_symbols": na_status.get("nax_symbols", 0),
            "naxtile_symbols": na_status.get("naxtile_symbols", 0),
            "affine_qmm_symbols": na_status.get("affine_qmm_symbols", 0),
            "affine_gather_qmm_symbols": na_status.get("affine_gather_qmm_symbols", 0),
        },
        "host": host,
    }
    if codec == "turboquant_codebook":
        result["jangtq_acceleration"] = mpp_nax
    result["family_runtime"] = _family_acceleration_contract(
        bundle_path or _model_path
    )
    return result


def _turboquant_kv_cache_status(engine=None, scheduler=None) -> dict:
    """Detect live TurboQuant KV cache patching across LLM and MLLM engines."""
    tq_active = bool(getattr(scheduler, "_tq_active", False)) if scheduler else False

    def _check_make_cache(obj):
        mc = getattr(obj, "make_cache", None)
        return mc is not None and getattr(mc, "__name__", "") in (
            "_tq_make_cache",
            "_turboquant_make_cache",
            "_hybrid_turboquant_make_cache",
        )

    if not tq_active and engine is not None:
        # Walk the candidate chain and probe each level + .language_model.
        _seen = set()
        _stack = []
        for _attr in ("_model", "model"):
            _v = _diagnostic_attr(engine, _attr)
            if _v is not None:
                _stack.append(_v)
        while _stack:
            _v = _stack.pop()
            if id(_v) in _seen:
                continue
            _seen.add(id(_v))
            if _check_make_cache(_v):
                tq_active = True
                break
            for _next_attr in ("model", "language_model"):
                _nxt = _diagnostic_attr(_v, _next_attr)
                if _nxt is not None and id(_nxt) not in _seen:
                    _stack.append(_nxt)

    if tq_active:
        compress_after = 0
        template_layers = []
        auto_policy = None
        configured_key_bits = 0
        configured_value_bits = 0
        if engine is not None or scheduler is not None:
            _seen = set()
            _stack = []
            if engine is not None:
                for _attr in ("_model", "model"):
                    _value = _diagnostic_attr(engine, _attr)
                    if _value is not None:
                        _stack.append(_value)
            # The health endpoint receives BatchedEngine plus its Scheduler.
            # Some loader wrappers keep the patched language model only on
            # scheduler.model, so probing the engine chain alone reports active
            # TQ objects but loses their bits/policy and falsely labels storage
            # native. The scheduler's own model is also the object generation
            # calls make_cache() on, making it the authoritative fallback.
            if scheduler is not None:
                _scheduler_model = _diagnostic_attr(scheduler, "model")
                if _scheduler_model is not None:
                    _stack.append(_scheduler_model)
            while _stack and not template_layers:
                _value = _stack.pop()
                if id(_value) in _seen:
                    continue
                _seen.add(id(_value))
                make_cache = getattr(_value, "make_cache", None)
                if _check_make_cache(_value):
                    compress_after = int(
                        getattr(make_cache, "_vmlx_tq_compress_after", 0) or 0
                    )
                    auto_policy = getattr(
                        make_cache, "_vmlx_tq_auto_policy", None
                    )
                    configured_key_bits = int(
                        getattr(make_cache, "_vmlx_tq_default_key_bits", 0) or 0
                    )
                    configured_value_bits = int(
                        getattr(make_cache, "_vmlx_tq_default_value_bits", 0) or 0
                    )
                    try:
                        template_layers = list(make_cache() or [])
                    except Exception:
                        template_layers = []
                for _next_attr in ("model", "language_model"):
                    _next = _diagnostic_attr(_value, _next_attr)
                    if _next is not None and id(_next) not in _seen:
                        _stack.append(_next)
        tq_layers = [
            layer
            for layer in template_layers
            if type(layer).__name__ == "TurboQuantKVCache"
        ]
        if tq_layers:
            compress_after = max(
                compress_after,
                max(int(getattr(layer, "compress_after", 0) or 0) for layer in tq_layers),
            )
        key_bits_values = sorted(
            {int(getattr(layer, "key_bits", 0) or 0) for layer in tq_layers}
            - {0}
        )
        value_bits_values = sorted(
            {int(getattr(layer, "value_bits", 0) or 0) for layer in tq_layers}
            - {0}
        )
        if not configured_key_bits and key_bits_values:
            configured_key_bits = key_bits_values[0]
        if not configured_value_bits and value_bits_values:
            configured_value_bits = value_bits_values[0]
        live_encode_enabled = compress_after > 0
        live_telemetry = None
        try:
            from jang_tools.turboquant.cache import TurboQuantKVCache

            live_telemetry = getattr(
                TurboQuantKVCache, "_vmlx_last_compress", None
            )
        except Exception:
            live_telemetry = None
        kv_bits = int(getattr(scheduler, "_kv_cache_bits", 0) or 0) if scheduler else 0
        native_tq_storage = bool(
            tq_layers
            and scheduler is not None
            and any(
                getattr(scheduler, attr, None) is not None
                for attr in ("block_aware_cache", "memory_aware_cache", "prefix_cache")
            )
        )
        mixed_native_bits = bool(
            native_tq_storage
            and (len(key_bits_values) > 1 or len(value_bits_values) > 1)
        )
        stored_prefix = (
            "turboquant-"
            + "/".join(f"q{bits}" for bits in key_bits_values)
            + "-mixed"
            if mixed_native_bits
            else f"turboquant-q{configured_key_bits}"
            if native_tq_storage and configured_key_bits > 0
            else (f"q{kv_bits}" if kv_bits > 0 else "native")
        )
        status = {
            "enabled": True,
            "objects_active": True,
            "live_encode_enabled": live_encode_enabled,
            "compress_after": compress_after,
            "stored_prefix_quantization": stored_prefix,
            "storage_encode_enabled": native_tq_storage,
            "storage_key_bits": configured_key_bits or None,
            "storage_value_bits": configured_value_bits or None,
            "key_bits_values": key_bits_values,
            "value_bits_values": value_bits_values,
            "auto_policy": auto_policy,
            # Compatibility fields, now derived from the real cache template.
            "default_bits": configured_key_bits or 3,
            "critical_bits": max(key_bits_values, default=configured_key_bits or 3),
            "critical_layers": "model-configured",
            "resident_memory_reduction_claimed": False,
            "description": (
                f"TQ objects active; live encode enabled after {compress_after} tokens; "
                f"stored prefix {stored_prefix}; packed serialization active; no "
                "resident-memory reduction claimed"
                if live_encode_enabled
                else f"TQ objects active; live encode disabled; stored prefix {stored_prefix}"
            ),
        }
        if live_telemetry is not None:
            # This class-level signal belongs to live cache-object compression.
            # The paged/L2 block codec bypasses TurboQuantKVCache.compress() and
            # is reported separately from tq_disk_store below.
            telemetry = dict(live_telemetry)
            status["codec_compress_telemetry"] = telemetry
            if live_encode_enabled:
                status["live_encode_telemetry"] = telemetry
        cfg = getattr(scheduler, "config", None) if scheduler is not None else None
        if cfg is not None:
            batch_api = bool(getattr(scheduler, "_tq_batch_api", False))
            single_sequence_only = not batch_api
            runtime = {
                "batch_api": "turboquant_kv_v1" if batch_api else None,
                "single_sequence_only": single_sequence_only,
                "effective_max_num_seqs": getattr(cfg, "max_num_seqs", None),
                "effective_prefill_batch_size": getattr(
                    cfg, "prefill_batch_size", None
                ),
                "effective_completion_batch_size": getattr(
                    cfg, "completion_batch_size", None
                ),
            }
            if single_sequence_only:
                runtime["single_sequence_reason"] = "cache_extend_not_supported"
            status.update(
                {k: v for k, v in runtime.items() if v is not None}
            )
        return status
    return {"enabled": False}


def _cache_storage_runtime_telemetry() -> dict[str, Any]:
    """Return volatile storage-codec observations outside topology identity."""
    telemetry: dict[str, Any] = {
        "schema": "vmlx-cache-storage-runtime-telemetry-v1",
    }
    try:
        from .tq_disk_store import tq_block_codec_telemetry

        telemetry["turboquant_block_codec"] = tq_block_codec_telemetry()
    except Exception:
        telemetry["turboquant_block_codec"] = {
            "schema": "vmlx-tq-block-codec-v1",
            "available": False,
        }
    return telemetry


def _current_model_config():
    """Return the loaded model registry config for status endpoints."""
    model_key = _model_path or _model_name or ""
    if not model_key:
        return None
    try:
        from .model_config_registry import get_model_config_registry

        return get_model_config_registry().lookup(model_key)
    except Exception:
        return None


def _dsv4_model_candidates(model: Any) -> list[Any]:
    """Return the small set of wrappers that may own JANG runtime attestations."""

    candidates: list[Any] = []
    seen: set[int] = set()
    pending = [model]
    while pending and len(candidates) < 4:
        candidate = pending.pop(0)
        if candidate is None or id(candidate) in seen:
            continue
        seen.add(id(candidate))
        candidates.append(candidate)
        for name in ("model", "language_model"):
            nested = getattr(candidate, name, None)
            if nested is not None:
                pending.append(nested)
    return candidates


def _optional_runtime_bool(value: Any) -> bool | None:
    """Accept only explicit runtime booleans; never turn missing truth into False."""

    return value if isinstance(value, bool) else None


def _dsv4_activation_qat_status(model: Any) -> dict[str, Any]:
    """Report requested/configured/observed activation-QAT without inference.

    The environment is only the request. The JANG graph owns effective and
    observed truth through a non-executing model attestation; an older runtime
    that lacks that contract reports ``None`` instead of echoing the request as
    success. FP32 compressor staging is deliberately separate from this toggle.
    """

    raw_env = os.environ.get("DSV4_ACTIVATION_QAT", "0")
    requested = str(raw_env).strip().lower() in {"1", "true", "yes", "on"}
    effective: bool | None = None
    observed: bool | None = None
    supported: bool | None = None
    runtime_requested: bool | None = None
    attested: bool | None = None
    paths: dict[str, bool | None] | None = None
    transform_families: list[Any] | None = None
    attestation_scope: str | None = None
    fused_e4m3_available: bool | None = None
    fused_indexer_available: bool | None = None
    source: str | None = None
    fp32_staging_observed: bool | None = None

    for candidate in _dsv4_model_candidates(model):
        raw_status = getattr(candidate, "_vmlx_dsv4_activation_qat_status", None)
        if isinstance(raw_status, dict):
            runtime_requested = _optional_runtime_bool(raw_status.get("requested"))
            effective = _optional_runtime_bool(raw_status.get("effective"))
            observed = _optional_runtime_bool(raw_status.get("observed"))
            attested = _optional_runtime_bool(raw_status.get("attested"))
            supported = _optional_runtime_bool(
                raw_status.get(
                    "implementation_available",
                    raw_status.get("supported"),
                )
            )
            paths = {
                "attention_kv_and_pool_e4m3": _optional_runtime_bool(
                    raw_status.get("e4m3_kv_pool_observed")
                ),
                "indexer_hadamard128_fp4_e2m1": _optional_runtime_bool(
                    raw_status.get("hadamard_fp4_indexer_observed")
                ),
            }
            raw_transform_families = raw_status.get("transform_families")
            if isinstance(raw_transform_families, (list, tuple)):
                transform_families = list(raw_transform_families)
            raw_attestation_scope = raw_status.get("attestation_scope")
            if isinstance(raw_attestation_scope, str):
                attestation_scope = raw_attestation_scope
            fused_e4m3_available = _optional_runtime_bool(
                raw_status.get("fused_e4m3_available")
            )
            fused_indexer_available = _optional_runtime_bool(
                raw_status.get("fused_indexer_available")
            )
            fp32_staging_observed = _optional_runtime_bool(
                raw_status.get(
                    "fp32_compressor_staging_unconditional",
                    raw_status.get("fp32_compressor_staging_observed"),
                )
            )
            source = type(candidate).__name__ + "._vmlx_dsv4_activation_qat_status"
            break

        candidate_effective = _optional_runtime_bool(
            getattr(candidate, "_vmlx_dsv4_activation_qat_effective", None)
        )
        candidate_observed = _optional_runtime_bool(
            getattr(candidate, "_vmlx_dsv4_activation_qat_observed", None)
        )
        if candidate_effective is not None or candidate_observed is not None:
            effective = candidate_effective
            observed = candidate_observed
            attested = observed is not None
            supported = _optional_runtime_bool(
                getattr(candidate, "_vmlx_dsv4_activation_qat_supported", None)
            )
            fp32_staging_observed = _optional_runtime_bool(
                getattr(
                    candidate,
                    "_vmlx_dsv4_fp32_compressor_staging_observed",
                    None,
                )
            )
            source = type(candidate).__name__ + ".vmlx_activation_qat_attributes"
            break

    paths_match_request = bool(paths) and all(
        value is requested for value in paths.values()
    )

    return {
        "requested": requested,
        "runtime_requested": runtime_requested,
        "effective": effective,
        "observed": observed,
        "attested": attested,
        "supported": supported,
        "matches_request": (
            effective is not None
            and observed is not None
            and attested is True
            and supported is True
            and (runtime_requested is None or runtime_requested == requested)
            and effective == requested
            and observed == requested
            and paths_match_request
        ),
        "env": str(raw_env),
        "attestation_source": source,
        "paths": paths,
        "attestation_scope": attestation_scope,
        "transform_families": transform_families,
        "fused_kernels": {
            "e4m3_available": fused_e4m3_available,
            "indexer_available": fused_indexer_available,
        },
        "controls": [
            "attention_kv_e4m3_roundtrip",
            "compressed_pool_e4m3_roundtrip",
            "indexer_hadamard128_fp4_e2m1_roundtrip",
        ],
        "fp32_compressor_staging": {
            "controlled_by_toggle": False,
            "observed": fp32_staging_observed,
            "reason": "separate_precision_contract",
        },
    }


def _dsv4_model_config(model: Any) -> Any | None:
    """Return the actual DSV4 config, never an unrelated outer wrapper config."""

    def config_value(config: Any, name: str) -> Any:
        return (
            config.get(name)
            if isinstance(config, dict)
            else getattr(config, name, None)
        )

    def is_dsv4_config(config: Any) -> bool:
        model_type = str(config_value(config, "model_type") or "").lower()
        family_name = str(config_value(config, "family_name") or "").lower()
        architectures = config_value(config, "architectures") or []
        if isinstance(architectures, str):
            architectures = [architectures]
        architecture_names = {str(name).lower() for name in architectures}
        return (
            model_type == "deepseek_v4"
            or family_name == "deepseek_v4"
            or any(
                "deepseekv4" in name or "deepseek_v4" in name
                for name in architecture_names
            )
        )

    matching_configs: list[Any] = []
    for candidate in _dsv4_model_candidates(model):
        outer_config = getattr(candidate, "config", None) or getattr(
            candidate, "args", None
        )
        if outer_config is None:
            continue
        configs = [outer_config]
        text_config = config_value(outer_config, "text_config")
        if text_config is not None:
            configs.append(text_config)
        for config in configs:
            if is_dsv4_config(config):
                matching_configs.append(config)

    def has_estimator_dimensions(config: Any) -> bool:
        layers = (
            config_value(config, "num_hidden_layers")
            or config_value(config, "n_layers")
            or config_value(config, "num_layers")
        )
        kv_heads = (
            config_value(config, "num_key_value_heads")
            or config_value(config, "n_kv_heads")
            or config_value(config, "num_kv_heads")
            or config_value(config, "num_attention_heads")
            or config_value(config, "n_heads")
        )
        head_dim = config_value(config, "head_dim")
        hidden_size = config_value(config, "hidden_size") or config_value(
            config, "d_model"
        )
        attention_heads = (
            config_value(config, "num_attention_heads")
            or config_value(config, "n_heads")
            or config_value(config, "attention_heads")
        )
        try:
            has_layers = int(layers or 0) > 0
            has_kv_heads = int(kv_heads or 0) > 0
            has_head_width = int(head_dim or 0) > 0 or (
                int(hidden_size or 0) > 0 and int(attention_heads or 0) > 0
            )
        except (TypeError, ValueError):
            return False
        return has_layers and has_kv_heads and has_head_width

    for config in matching_configs:
        if has_estimator_dimensions(config):
            return config
    return matching_configs[0] if matching_configs else None


_DSV4_NATIVE_CACHE_COMPONENTS = [
    "swa_local",
    "csa_compressed_pool",
    "csa_indexer_pool",
    "hca_compressed_pool",
    "incomplete_tail_state",
]


def _dsv4_memory_estimate_payload(estimate: Any) -> dict[str, Any]:
    component_bytes = {
        "swa_local": int(estimate.local_swa_bytes),
        "csa_compressed_pool": int(estimate.csa_pool_bytes),
        "csa_indexer_pool": int(estimate.csa_indexer_bytes),
        "hca_compressed_pool": int(estimate.hca_pool_bytes),
        "incomplete_tail_state": int(estimate.tail_bytes),
    }
    total_bytes = int(estimate.total_bytes)
    return {
        "tokens": int(estimate.token_count),
        "total_bytes": total_bytes,
        "total_gib": round(total_bytes / (1024**3), 6),
        "component_bytes": component_bytes,
        "component_gib": {
            key: round(value / (1024**3), 6)
            for key, value in component_bytes.items()
        },
        "pool_quant_enabled": bool(estimate.pool_quant_enabled),
        "layer_counts": {
            "ratio_0_swa": int(estimate.ratio_zero_layers),
            "ratio_4_csa": int(estimate.ratio_four_layers),
            "ratio_high_hca": int(estimate.ratio_high_layers),
        },
    }


def _dsv4_native_state_memory_status(
    scheduler: Any,
    model: Any,
    *,
    pool_quant_observed: bool | None,
) -> dict[str, Any]:
    """Estimate only DSV4's architecture-native live state, never generic KV.

    This is distinct from the retained prefix-cache L1 counters reported by
    ``_cache_telemetry_snapshot``. It describes one live DSV4 sequence's
    bounded SWA ring plus cumulative CSA/indexer/HCA pools at the current/last
    prompt and at the model's declared maximum context.
    """

    config = _dsv4_model_config(model)
    result: dict[str, Any] = {
        "basis": "architecture_estimate_not_allocator_measurement",
        "includes": list(_DSV4_NATIVE_CACHE_COMPONENTS),
        "excludes": ["model_weights", "prefix_cache_l1", "block_disk_l2"],
        "retained_l1_reported_separately": True,
        "pool_quant_observed": pool_quant_observed,
    }
    if config is None:
        result.update({"available": False, "reason": "loaded_model_config_unavailable"})
        return result
    if pool_quant_observed is None:
        result.update({"available": False, "reason": "pool_quant_runtime_unattested"})
        return result

    try:
        from vmlx_engine.utils.memory_limits import (
            estimate_dsv4_cache_memory_from_config,
        )

        running = getattr(scheduler, "running", None)
        if isinstance(running, dict):
            running_requests = list(running.values())
        elif isinstance(running, (list, tuple)):
            running_requests = list(running)
        else:
            running_requests = []
        def request_token_counts(request: Any) -> tuple[int, int]:
            prompt_tokens = int(
                getattr(request, "num_prompt_tokens", 0)
                or len(getattr(request, "prompt_token_ids", None) or [])
            )
            output_tokens = int(getattr(request, "num_output_tokens", 0) or 0)
            raw_total = getattr(request, "num_tokens", 0)
            total_tokens = int(raw_total or (prompt_tokens + output_tokens))
            return prompt_tokens, max(total_tokens, prompt_tokens + output_tokens)

        running_counts = [request_token_counts(request) for request in running_requests]
        current_prompt_tokens = max((count[0] for count in running_counts), default=0)
        current_sequence_tokens = max((count[1] for count in running_counts), default=0)
        batch_generator = getattr(scheduler, "batch_generator", None)
        generator_requests = getattr(batch_generator, "_requests", None)
        if current_sequence_tokens <= 0 and isinstance(generator_requests, list):
            current_sequence_tokens = max(
                (
                    len(getattr(request, "context_tokens", None) or [])
                    for request in generator_requests
                ),
                default=0,
            )
        last_execution = getattr(scheduler, "_last_cache_execution", None)
        last_prompt_tokens = (
            int(last_execution.get("prompt_tokens", 0) or 0)
            if isinstance(last_execution, dict)
            else 0
        )
        declared_context_tokens = _declared_context_limit_from_config(config)

        def estimate_for_tokens(token_count: int) -> dict[str, Any] | None:
            if token_count <= 0:
                return None
            estimate = estimate_dsv4_cache_memory_from_config(
                config,
                token_count,
                pool_quant_enabled=pool_quant_observed,
            )
            return (
                _dsv4_memory_estimate_payload(estimate)
                if estimate is not None
                else None
            )

        snapshot_bytes = int(
            getattr(batch_generator, "prompt_snapshot_last_estimated_bytes", 0)
            or 0
        )

        estimates = {
            "current_prompt": estimate_for_tokens(current_prompt_tokens),
            "current_sequence": estimate_for_tokens(current_sequence_tokens),
            "last_prompt": estimate_for_tokens(last_prompt_tokens),
            "max_context": estimate_for_tokens(declared_context_tokens),
        }
        requested_estimates = {
            "current_prompt": current_prompt_tokens,
            "current_sequence": current_sequence_tokens,
            "last_prompt": last_prompt_tokens,
            "max_context": declared_context_tokens,
        }
        unavailable_estimates = [
            name
            for name, token_count in requested_estimates.items()
            if token_count > 0 and estimates[name] is None
        ]
        if unavailable_estimates:
            result.update(
                {
                    "available": False,
                    "reason": "native_estimator_unavailable",
                    "unavailable_estimates": unavailable_estimates,
                    "declared_context_tokens": declared_context_tokens or None,
                }
            )
            return result

        result.update(
            {
                "available": True,
                "current_prompt": estimates["current_prompt"],
                "current_sequence": estimates["current_sequence"],
                "current_sequence_basis": "prompt_plus_generated_tokens",
                "last_prompt": estimates["last_prompt"],
                "max_context": estimates["max_context"],
                "declared_context_tokens": declared_context_tokens or None,
                "last_prompt_snapshot": (
                    {
                        "estimated_bytes": snapshot_bytes,
                        "estimated_gib": round(snapshot_bytes / (1024**3), 6),
                        "source": (
                            "DSV4BatchGenerator."
                            "prompt_snapshot_last_estimated_bytes"
                        ),
                    }
                    if snapshot_bytes > 0
                    else None
                ),
            }
        )
        return result
    except Exception as exc:
        result.update(
            {
                "available": False,
                "reason": "architecture_estimate_failed",
                "error": f"{type(exc).__name__}: {exc}",
            }
        )
        return result


def _native_cache_status(
    scheduler=None,
    *,
    family: str | None = None,
    cfg=None,
    turboquant_status: dict[str, Any] | None = None,
) -> dict:
    """Report architecture-native cache contracts separately from generic TQ-KV."""
    if scheduler is None and family is None and cfg is None:
        return {}

    scheduler_family = str(getattr(scheduler, "_model_type_for_runtime", "") or "")
    family_name = family or scheduler_family
    cache_type = getattr(cfg, "cache_type", None) if cfg is not None else None
    cache_subtype = getattr(cfg, "cache_subtype", None) if cfg is not None else None
    block_aware_cache = getattr(scheduler, "block_aware_cache", None)
    paged_cache_manager = getattr(scheduler, "paged_cache_manager", None)
    block_disk_store = (
        getattr(paged_cache_manager, "_disk_store", None)
        if paged_cache_manager is not None
        else None
    )
    block_disk_only = bool(
        block_aware_cache is not None
        and paged_cache_manager is not None
        and getattr(paged_cache_manager, "disk_only", False)
    )
    paged_backend_active = bool(
        block_aware_cache is not None
        and paged_cache_manager is not None
        and not block_disk_only
    )
    disk_cache = getattr(scheduler, "disk_cache", None)

    # Cache family/registry metadata is a routing hint.  The source of truth
    # for what the loaded model will actually carry through decode is the
    # object graph returned by model.make_cache().  Both schedulers capture a
    # tensor-free description at startup; attach it to every native-cache
    # branch so /health and the visible Cache panel can expose disagreements
    # instead of silently trusting the selected lane.
    raw_runtime_layout = getattr(scheduler, "_runtime_cache_layout", None)
    runtime_layout = (
        dict(raw_runtime_layout)
        if isinstance(raw_runtime_layout, dict)
        else {}
    )

    def _runtime_indices(name: str) -> list[int]:
        raw = runtime_layout.get(name, [])
        if not isinstance(raw, (list, tuple)):
            return []
        result = []
        for value in raw:
            try:
                index = int(value)
            except (TypeError, ValueError):
                continue
            if index >= 0:
                result.append(index)
        return result

    runtime_layer_count = int(runtime_layout.get("layer_count", 0) or 0)
    runtime_attention_indices = _runtime_indices("attention_layer_indices")
    runtime_cumulative_indices = _runtime_indices("cumulative_layer_indices")
    runtime_parallel_indices = _runtime_indices("parallel_layer_indices")
    runtime_rotating_indices = _runtime_indices("rotating_layer_indices")
    runtime_quantized_indices = _runtime_indices("quantized_layer_indices")
    runtime_unknown_indices = _runtime_indices("unknown_layer_indices")
    runtime_layout_source = str(
        runtime_layout.get("source") or "instantiated_make_cache"
    )
    runtime_layout_complete = bool(
        runtime_layer_count > 0 and not runtime_unknown_indices
    )

    runtime_status: dict[str, Any] = {}
    if runtime_layer_count > 0:
        runtime_status = {
            "runtime_cache_layout_source": runtime_layout_source,
            "runtime_cache_factory": runtime_layout.get("factory"),
            "runtime_cache_factory_delegated_to_model_make_cache": bool(
                runtime_layout.get("delegated_to_model_make_cache", False)
            ),
            "runtime_cache_layer_count": runtime_layer_count,
            "runtime_cache_slot_types": list(
                runtime_layout.get("slot_types", []) or []
            ),
            "runtime_cache_slot_schema_tags": list(
                runtime_layout.get("slot_schema_tags", []) or []
            ),
            "runtime_cache_slot_class_counts": dict(
                runtime_layout.get("slot_class_counts", {}) or {}
            ),
            "runtime_cache_effective_class_counts": dict(
                runtime_layout.get("effective_class_counts", {}) or {}
            ),
            "runtime_cache_owner_component_types": list(
                runtime_layout.get("owner_component_types", []) or []
            ),
            "runtime_cache_owner_component_class_counts": dict(
                runtime_layout.get("owner_component_class_counts", {}) or {}
            ),
            "runtime_cache_owner_component_source": runtime_layout.get(
                "owner_component_source"
            ),
            "parameter_dtype_harmonization": dict(
                runtime_layout.get("parameter_dtype_harmonization", {}) or {}
            ),
            "runtime_cache_attention_layer_indices": runtime_attention_indices,
            "runtime_cache_cumulative_layer_indices": runtime_cumulative_indices,
            "runtime_cache_parallel_layer_indices": runtime_parallel_indices,
            "runtime_cache_rotating_layer_indices": runtime_rotating_indices,
            "runtime_cache_quantized_layer_indices": runtime_quantized_indices,
            "runtime_cache_unknown_layer_indices": runtime_unknown_indices,
            "runtime_cache_layout_complete": runtime_layout_complete,
        }

    def _with_runtime_layout(status: dict[str, Any]) -> dict[str, Any]:
        if not runtime_status:
            return status
        status.update(runtime_status)
        if runtime_layout_complete:
            # Compatibility aliases drive the existing visible layer cards.
            # Overwrite registry-derived values only when every instantiated
            # slot has a known attention/cumulative semantic classification.
            status["cache_layer_count"] = runtime_layer_count
            status["kv_layer_indices"] = runtime_attention_indices
            status["kv_layer_indices_source"] = runtime_layout_source
            status["companion_layer_indices"] = runtime_cumulative_indices
            status["companion_layer_count"] = len(runtime_cumulative_indices)
            status["sliding_attention_layer_indices"] = runtime_rotating_indices
            rotating = set(runtime_rotating_indices)
            status["full_attention_layer_indices"] = [
                index
                for index in runtime_attention_indices
                if index not in rotating
            ]
            owner_types = list(
                runtime_layout.get("owner_component_types", []) or []
            )
            if len(owner_types) == runtime_layer_count:
                companion_owners: dict[str, int] = {}
                for index in runtime_cumulative_indices:
                    owner = str(owner_types[index])
                    companion_owners[owner] = companion_owners.get(owner, 0) + 1
                status["companion_state_owner_class_counts"] = companion_owners
                if len(companion_owners) == 1:
                    status["companion_state_owner"] = next(
                        iter(companion_owners)
                    )
        return status

    if getattr(scheduler, "_uses_dsv4_cache", False) or family_name == "deepseek_v4":
        pool_quant_requested = str(os.environ.get("DSV4_POOL_QUANT", "0")).lower() in (
            "1",
            "true",
            "yes",
            "on",
        )
        model = getattr(scheduler, "model", None)
        activation_qat = _dsv4_activation_qat_status(model)
        layout: dict[str, Any] = {}
        pool_quant_observed: bool | None = None
        cache_class_counts: dict[str, int] = {}
        layout_error: str | None = None
        try:
            cache_layers = model.make_cache() if model is not None else None
            if cache_layers:
                ratios: list[int | None] = []
                windows: list[int] = []
                for layer_cache in cache_layers:
                    cache_class = type(layer_cache).__name__
                    cache_class_counts[cache_class] = (
                        cache_class_counts.get(cache_class, 0) + 1
                    )
                    ratio = getattr(layer_cache, "compress_ratio", None)
                    if (
                        ratio is None
                        and type(layer_cache).__name__ == "RotatingKVCache"
                    ):
                        # DSV4 ratio-zero layers intentionally use mlx-lm's
                        # bounded rotating SWA cache rather than a
                        # DeepseekV4Cache object with compress_ratio=0. Report
                        # the instantiated topology as ratio 0 instead of
                        # presenting those proven runtime layers as unknown.
                        ratio = 0
                    try:
                        ratios.append(int(ratio) if ratio is not None else None)
                    except (TypeError, ValueError):
                        ratios.append(None)
                    local_cache = getattr(layer_cache, "local", None)
                    window = getattr(local_cache, "max_size", None)
                    if window is not None:
                        try:
                            windows.append(int(window))
                        except (TypeError, ValueError):
                            pass
                ratio_counts: dict[str, int] = {}
                for ratio in ratios:
                    key = "unknown" if ratio is None else str(ratio)
                    ratio_counts[key] = ratio_counts.get(key, 0) + 1
                layout = {
                    "layers": len(cache_layers),
                    "compress_ratios": [
                        "unknown" if ratio is None else ratio for ratio in ratios
                    ],
                    "compress_ratio_counts": ratio_counts,
                    "cache_class_counts": cache_class_counts,
                }
                compressed_layers = [
                    layer_cache
                    for layer_cache, ratio in zip(cache_layers, ratios)
                    if ratio not in (None, 0)
                ]
                if compressed_layers:
                    pool_quant_flags = [
                        type(layer_cache).__name__ == "PoolQuantizedV4Cache"
                        for layer_cache in compressed_layers
                    ]
                    if all(pool_quant_flags):
                        pool_quant_observed = True
                    elif any(pool_quant_flags):
                        pool_quant_observed = None
                        mixed_error = (
                            "mixed DSV4 compressed cache classes: "
                            f"{cache_class_counts}"
                        )
                        layout_error = (
                            f"{layout_error}; {mixed_error}"
                            if layout_error
                            else mixed_error
                        )
                    else:
                        pool_quant_observed = False
                if windows:
                    layout["sliding_window"] = windows[0]
                    if len(set(windows)) > 1:
                        layout["sliding_windows"] = windows
        except Exception as exc:
            layout_error = str(exc)
            layout = {}
        status = {
            "family": "deepseek_v4",
            "schema": "deepseek_v4_v10_delta",
            "cache_type": "native_composite",
            "components": list(_DSV4_NATIVE_CACHE_COMPONENTS),
            "generic_turboquant_kv": {
                "enabled": False,
                "reason": "native_dsv4_composite",
            },
            "pool_quant": {
                "requested": pool_quant_requested,
                "enabled": pool_quant_observed is True,
                "observed": pool_quant_observed,
                "matches_request": (
                    pool_quant_observed is not None
                    and pool_quant_observed == pool_quant_requested
                ),
                "env": os.environ.get("DSV4_POOL_QUANT", "0"),
                "error": layout_error,
            },
            # Full runtime observation is intentionally outside the stable
            # cache-topology attestation because per-path observations become
            # populated only after the first forward pass.
            "activation_qat": activation_qat,
            "activation_qat_configuration": {
                "requested": activation_qat["requested"],
                "runtime_requested": activation_qat["runtime_requested"],
                "effective": activation_qat["effective"],
                "supported": activation_qat["supported"],
                "controls": activation_qat["controls"],
                "fp32_compressor_staging_controlled": False,
            },
            "layer_cache_roles": {
                "ratio_0": "swa_local_only",
                "ratio_4": "csa_overlap_compressed_pool_plus_indexer",
                "ratio_128": "hca_compressed_pool",
            },
            "cache_store_policy": {
                "prompt_boundary_snapshot": "preferred",
                "post_generation_trim": "disabled_unless_explicit_unsafe_override",
                "generic_kv_quantization": "forced_off",
            },
            "decode_activation_order": [
                "make_cache_builds_per_layer_swa_or_composite_cache",
                "prefill_updates_local_swa_and_compressor_indexer_pools",
                "prompt_boundary_snapshot_or_clean_reprefill_is_stored_for_prefix",
                "decode_appends_new_tokens_to_live_composite_cache",
                "cache_hit_restores_full_nested_state_and_refeeds_last_prompt_token",
            ],
            "prefix": bool(block_aware_cache is not None),
            "paged": paged_backend_active,
            "block_disk_only": block_disk_only,
            "block_disk_l2": bool(block_disk_store is not None),
        }
        native_state_memory = _dsv4_native_state_memory_status(
            scheduler,
            getattr(scheduler, "model", None),
            pool_quant_observed=pool_quant_observed,
        )
        if native_state_memory:
            status["native_state_memory"] = native_state_memory
        status.update(layout)
        return _with_runtime_layout(status)

    if (
        family_name in {"glm5_next", "glm5_next_text"}
        or scheduler_family in {"glm5_next", "glm5_next_text"}
        or cache_subtype in {"glm5_next_native_v1", "glm5_next_native_v2"}
        or getattr(scheduler, "_glm5_next_cache_unsupported", False)
    ):
        # GLM's executable cache is a mixed, path-dependent structure: KDA
        # convolution/recurrent state plus MLA KV and DSA indexer state. Only
        # the exact N-1 typed snapshot/prompt-disk path may advertise reuse;
        # generic paged blocks remain unsupported.
        prefix_configured = bool(
            getattr(
                scheduler,
                "_prefix_cache_requested",
                getattr(getattr(scheduler, "config", None), "enable_prefix_cache", False),
            )
        )
        prompt_disk_configured = bool(
            getattr(
                scheduler,
                "_prompt_disk_cache_requested",
                getattr(getattr(scheduler, "config", None), "enable_disk_cache", False),
            )
        )
        block_disk_configured = bool(
            getattr(
                scheduler,
                "_block_disk_cache_requested",
                getattr(
                    getattr(scheduler, "config", None),
                    "enable_block_disk_cache",
                    False,
                ),
            )
        )
        schema_implemented = bool(
            getattr(scheduler, "_uses_glm5_next_cache", False)
            and not getattr(scheduler, "_glm5_next_cache_unsupported", False)
        )
        runtime_schema_tags = list(
            runtime_layout.get("slot_schema_tags", []) or []
        )
        absorbed_mla = any(
            isinstance(tag, (list, tuple))
            and tuple(tag[:2])
            == ("glm5_next_native_v2", "mla_absorbed")
            for tag in runtime_schema_tags
        )
        native_schema = (
            "glm5_next_native_v2" if absorbed_mla else "glm5_next_native_v1"
        )
        native_components = [
            "kda_conv_state",
            "kda_recurrent_state",
            "mla_latent" if absorbed_mla else "mla_kv",
            "dsa_indexer_state",
        ]
        memory_cache = getattr(scheduler, "memory_aware_cache", None)
        prompt_disk_cache = getattr(scheduler, "disk_cache", None)
        if not schema_implemented:
            return _with_runtime_layout(
                {
                    "family": "glm5_next",
                    "schema": native_schema,
                    "schema_implemented": False,
                    "cache_type": "native_mixed_state_fail_closed",
                    "cache_subtype": native_schema,
                    "components": native_components,
                    "reason": "typed_glm5_next_native_state_schema_not_implemented",
                    "cache_store_policy": {
                        "generic_prefix_restore": "unsupported",
                        "generic_paged_blocks": "unsupported",
                        "prompt_disk_l2": "unsupported",
                        "every_request_recomputes_full_prefix": True,
                    },
                    "generic_turboquant_kv": {
                        "enabled": False,
                        "reason": "mixed_path_dependent_native_state",
                    },
                    "prefix_configured": prefix_configured,
                    "prompt_disk_l2_configured": prompt_disk_configured,
                    "block_disk_l2_configured": block_disk_configured,
                    "prefix": False,
                    "paged": False,
                    "prompt_disk_l2": False,
                    "block_disk_l2": False,
                }
            )
        return _with_runtime_layout(
            {
                "family": "glm5_next",
                "schema": native_schema,
                "schema_implemented": True,
                "cache_type": "native_mixed_state_exact_boundary",
                "cache_subtype": native_schema,
                "components": native_components,
                "reason": None,
                "cache_store_policy": {
                    "prompt_boundary": "exact_n_minus_one",
                    "generic_prefix_restore": "unsupported",
                    "generic_paged_blocks": "unsupported",
                    "prompt_disk_l2": "typed_full_state",
                    "every_request_recomputes_full_prefix": False,
                },
                "generic_turboquant_kv": {
                    "enabled": False,
                    "reason": "mixed_path_dependent_native_state",
                },
                "prefix_configured": prefix_configured,
                "prompt_disk_l2_configured": prompt_disk_configured,
                "block_disk_l2_configured": block_disk_configured,
                "prefix": bool(
                    memory_cache is not None or prompt_disk_cache is not None
                ),
                "paged": False,
                "prompt_disk_l2": bool(prompt_disk_cache is not None),
                "block_disk_l2": False,
            }
        )

    if (
        family_name == "openpangu_v2"
        or scheduler_family == "openpangu_v2"
        or cache_subtype == "openpangu_v2_composite"
    ):
        # openPangu's layer cache is path-dependent and composite.  Exact N-1
        # prompt-boundary snapshots now round-trip the full typed state, while
        # generic trim-based paged/block reuse remains unsupported.
        prefix_configured = bool(
            getattr(
                scheduler,
                "_prefix_cache_requested",
                getattr(getattr(scheduler, "config", None), "enable_prefix_cache", False),
            )
        )
        return _with_runtime_layout({
            "family": "openpangu_v2",
            "schema": "openpangu_v2_composite_v2",
            "cache_type": "native_path_dependent_composite",
            "cache_subtype": "openpangu_v2_composite",
            "components": [
                "mla_latent_kv",
                "dsa_indexer_state",
                "swa_rotating_window",
                "path_dependent_conv_state",
            ],
            "generic_turboquant_kv": {
                "enabled": False,
                "reason": "mla_and_path_dependent_conv_state",
            },
            "cache_store_policy": {
                "prompt_boundary_snapshot": "exact_typed_n_minus_1",
                "state_roundtrip": "kv_indexer_swa_meta_and_three_conv_states",
                "reverse_truncation": "unsupported_clean_miss",
                "generic_paged_blocks": "unsupported",
                "prompt_disk_l2": "exact_typed_full_precision",
                "reuse": "exact_or_forward_prefix_from_typed_boundary",
            },
            "prefix_configured": prefix_configured,
            "prefix": bool(
                getattr(scheduler, "memory_aware_cache", None) is not None
            ),
            "paged": False,
            "prompt_disk_l2_configured": bool(
                getattr(scheduler, "_prompt_disk_cache_requested", disk_cache is not None)
            ),
            "block_disk_l2_configured": bool(
                getattr(scheduler, "_block_disk_cache_requested", block_disk_store is not None)
            ),
            "prompt_disk_l2": bool(disk_cache is not None),
            "block_disk_l2": False,
        })

    family_probe_parts = [family_name, scheduler_family]
    if cfg is not None:
        if isinstance(cfg, dict):
            family_probe_parts.append(cfg.get("model_type"))
            text_cfg = cfg.get("text_config")
            if isinstance(text_cfg, dict):
                family_probe_parts.append(text_cfg.get("model_type"))
        else:
            family_probe_parts.append(getattr(cfg, "model_type", None))
            text_cfg = getattr(cfg, "text_config", None)
            if isinstance(text_cfg, dict):
                family_probe_parts.append(text_cfg.get("model_type"))
            else:
                family_probe_parts.append(getattr(text_cfg, "model_type", None))
    family_probe = " ".join(str(part).lower() for part in family_probe_parts if part)
    if "minimax_m3" in family_probe or "minimax-m3" in family_probe:
        layout: dict[str, Any] = {}
        try:
            model = getattr(scheduler, "model", None)
            cache_layers = model.make_cache() if model is not None else None
            if cache_layers:
                class_names = [type(layer_cache).__name__ for layer_cache in cache_layers]
                sparse_layers = [
                    idx
                    for idx, class_name in enumerate(class_names)
                    if class_name == "MiniMaxM3SparseCache"
                ]
                layout = {
                    "layers": len(cache_layers),
                    "sparse_msa_layers": sparse_layers,
                    "dense_kv_layers": [
                        idx for idx in range(len(cache_layers)) if idx not in sparse_layers
                    ],
                }
        except Exception:
            layout = {}
        status = {
            "family": family_name or scheduler_family or "minimax_m3",
            "schema": "minimax_m3_msa_v1",
            "cache_type": "native_msa_sparse_kv",
            "components": [
                "attention_kv",
                "msa_idx_keys",
                "absolute_block_index",
            ],
            "generic_turboquant_kv": {
                "enabled": False,
                "reason": "native_minimax_m3_msa_idx_keys",
            },
            "storage_quantization": {
                "enabled": False,
                "reason": "generic_kv_quantization_forced_off_for_msa_idx_keys",
            },
            "cache_store_policy": {
                "prompt_boundary_snapshot": "required",
                "generic_kv_quantization": "forced_off",
                "disk_tuple_tag": "minimax_m3",
                "paged_required_for_ssd_l2": False,
                "prompt_disk_l2": "m3_sparse_cache_tuple",
            },
            "prefix": bool(block_aware_cache is not None),
            "paged": paged_backend_active,
            "block_disk_only": block_disk_only,
            "prompt_disk_l2": bool(disk_cache is not None),
            "block_disk_l2": bool(block_disk_store is not None),
        }
        status.update(layout)
        return _with_runtime_layout(status)

    if (
        family_name == "zaya"
        or cache_subtype == "zaya_cca"
        or getattr(scheduler, "_uses_zaya_cache", False)
    ):
        return _with_runtime_layout({
            "family": "zaya",
            "schema": "zaya_cca_v1",
            "cache_type": "typed_cca",
            "components": [
                "standard_kv",
                "cca_conv_state",
                "cca_prev_hidden",
                "moe_no_state_slots",
            ],
            "generic_turboquant_kv": {"enabled": False, "reason": "cca_state_is_path_dependent"},
            "prefix": bool(block_aware_cache is not None),
            "paged": paged_backend_active,
            "block_disk_only": block_disk_only,
            "block_disk_l2": bool(block_disk_store is not None),
        })

    if (
        (getattr(scheduler, "_is_hybrid", False) or cache_type == "hybrid")
        and not getattr(scheduler, "_uses_dsv4_cache", False)
        and not getattr(scheduler, "_uses_zaya_cache", False)
    ):
        batch_generator = getattr(scheduler, "batch_generator", None)
        ssm_cache = getattr(scheduler, "_ssm_state_cache", None)
        if ssm_cache is None and batch_generator is not None:
            ssm_cache = getattr(batch_generator, "_ssm_state_cache", None)
        ssm_disk = (
            getattr(ssm_cache, "_disk", None)
            if ssm_cache is not None
            else getattr(scheduler, "_ssm_companion_disk_store", None)
        )
        if ssm_cache is not None:
            try:
                cache_size = getattr(ssm_cache, "size", None)
                ssm_entries = (
                    int(cache_size or 0)
                    if cache_size is not None
                    else len(getattr(ssm_cache, "_store", {}) or {})
                )
            except Exception:
                ssm_entries = len(getattr(ssm_cache, "_store", {}) or {})
            ssm_resident_bytes = int(
                getattr(ssm_cache, "total_nbytes", 0) or 0
            )
            ssm_ram_enabled = bool(
                getattr(ssm_cache, "ram_enabled", False)
            )
        else:
            config = getattr(scheduler, "config", None)
            configured_entries = int(
                getattr(config, "ssm_state_cache_size", 0) or 0
            )
            configured_mb = getattr(config, "ssm_state_cache_max_mb", None)
            ssm_entries = 0
            ssm_resident_bytes = 0
            ssm_ram_enabled = bool(
                configured_entries > 0
                and (configured_mb is None or int(configured_mb) > 0)
            )
        ssm_disk_enabled = ssm_disk is not None
        if ssm_ram_enabled:
            ssm_storage = "ram_and_ssd" if ssm_disk_enabled else "ram_only"
        else:
            ssm_storage = "ssd_only" if ssm_disk_enabled else "disabled"
        hybrid_live_tq_policy = getattr(
            scheduler, "_hybrid_live_tq_policy", None
        )
        hybrid_tq_enabled = bool(
            getattr(scheduler, "_tq_active", False)
            and hybrid_live_tq_policy == "attention_kv_only"
        )
        hybrid_tq_attention_layers = list(
            getattr(scheduler, "_hybrid_live_tq_attention_layers", []) or []
        )
        hybrid_tq_companion_layers = list(
            getattr(scheduler, "_hybrid_live_tq_companion_layers", []) or []
        )
        # The multimodal scheduler owns the batch generator, and the generator
        # is the object that resolves the instantiated hybrid cache layout.
        # Reading only the wrapper scheduler made live Qwen3.8 health claim an
        # empty attention-layer list even though the runtime had resolved all
        # 16 full-attention positions. Keep the text-scheduler owner first,
        # then fall back to the MLLM owner before using TQ metadata.
        scheduler_kv_positions = list(
            getattr(scheduler, "_hybrid_kv_positions", []) or []
        )
        runtime_kv_positions = list(
            getattr(scheduler, "_runtime_cache_kv_positions", []) or []
        )
        batch_kv_positions = list(
            getattr(batch_generator, "_hybrid_kv_positions", []) or []
        )
        if scheduler_kv_positions:
            hybrid_kv_positions = scheduler_kv_positions
            hybrid_kv_positions_source = "scheduler_runtime_cache"
        elif runtime_kv_positions:
            hybrid_kv_positions = runtime_kv_positions
            hybrid_kv_positions_source = "instantiated_make_cache"
        elif batch_kv_positions:
            hybrid_kv_positions = batch_kv_positions
            hybrid_kv_positions_source = "mllm_batch_generator"
        else:
            hybrid_kv_positions = hybrid_tq_attention_layers
            hybrid_kv_positions_source = (
                "turboquant_runtime" if hybrid_tq_attention_layers else None
            )
        hybrid_cache_layer_count = int(
            getattr(scheduler, "_hybrid_num_layers", 0)
            or getattr(scheduler, "_runtime_cache_num_layers", 0)
            or getattr(batch_generator, "_hybrid_num_layers", 0)
            or 0
        )
        # Live encode is gated by compress_after (default 0 -> objects-only, no
        # live decode-time encoding). Report the truthful mode: "live_decode"
        # ONLY when compress_after > 0 actually enables encoding; otherwise
        # "attention_kv_objects" (TQ objects installed but not encoding). The
        # authoritative live-encode counters live in the top-level
        # turboquant_kv_cache block (_turboquant_kv_cache_status).
        hybrid_tq_compress_after = int(
            getattr(scheduler, "_hybrid_live_tq_compress_after", 0) or 0
        )
        hybrid_tq_live_encode = hybrid_tq_enabled and hybrid_tq_compress_after > 0
        hybrid_tq_storage_enabled = bool(
            hybrid_tq_enabled and block_aware_cache is not None
        )
        hybrid_tq_key_bits = int(
            getattr(scheduler, "_hybrid_tq_default_key_bits", 0) or 0
        )
        hybrid_tq_value_bits = int(
            getattr(scheduler, "_hybrid_tq_default_value_bits", 0) or 0
        )
        hybrid_tq_auto_policy = getattr(
            scheduler, "_hybrid_tq_auto_policy", None
        )
        try:
            stored_kv_bits = int(getattr(scheduler, "_kv_cache_bits", 0) or 0)
        except (TypeError, ValueError):
            stored_kv_bits = 0
        try:
            stored_kv_group = int(getattr(scheduler, "_kv_cache_group_size", 64) or 64)
        except (TypeError, ValueError):
            stored_kv_group = 64
        return _with_runtime_layout({
            "family": family_name or scheduler_family or "hybrid",
            "schema": "hybrid_ssm_v1",
            "cache_type": "hybrid_ssm_typed",
            "components": [
                "attention_kv",
                "ssm_companion_state",
                "async_rederive",
            ],
            "generic_turboquant_kv": {
                "enabled": hybrid_tq_enabled,
                "reason": (
                    "hybrid_attention_kv_only"
                    if hybrid_tq_enabled
                    else "hybrid_ssm_state"
                ),
            },
            "live_attention_tq_kv": {
                "enabled": hybrid_tq_enabled,
                "mode": (
                    ("live_decode" if hybrid_tq_live_encode else "attention_kv_objects")
                    if hybrid_tq_enabled
                    else None
                ),
                "compress_after": hybrid_tq_compress_after if hybrid_tq_enabled else None,
                "applies_to": "attention_kv_layers_only",
                "ssm_policy": "native_full_precision_companion_state",
                "attention_layers": hybrid_tq_attention_layers,
                "companion_layers": hybrid_tq_companion_layers,
            },
            "attention_kv_storage_quantization": (
                {
                    "enabled": True,
                    "mode": "storage_boundary",
                    "codec": "turboquant_native",
                    "bits": hybrid_tq_key_bits or None,
                    "value_bits": hybrid_tq_value_bits or None,
                    "group_size": None,
                    "auto_policy": hybrid_tq_auto_policy,
                    "applies_to": "attention_kv_layers_only",
                    "ssm_policy": "native_companion_state",
                    "rederive": "async_clean_prefill_on_miss_or_warm_pass",
                }
                if hybrid_tq_storage_enabled
                else {
                    "enabled": stored_kv_bits > 0,
                    "mode": "storage_boundary",
                    "bits": stored_kv_bits if stored_kv_bits > 0 else None,
                    "group_size": stored_kv_group if stored_kv_bits > 0 else None,
                    "applies_to": "attention_kv_layers_only",
                    "ssm_policy": "native_companion_state",
                    "rederive": "async_clean_prefill_on_miss_or_warm_pass",
                }
            ),
            "prefix": bool(block_aware_cache is not None),
            "paged": paged_backend_active,
            "block_disk_only": block_disk_only,
            "block_disk_l2": bool(block_disk_store is not None),
            "ssm_entries": ssm_entries,
            "ssm_resident_bytes": ssm_resident_bytes,
            "ssm_ram_enabled": ssm_ram_enabled,
            "ssm_storage": ssm_storage,
            "kv_layer_indices": hybrid_kv_positions,
            "kv_layer_indices_source": hybrid_kv_positions_source,
            "cache_layer_count": hybrid_cache_layer_count,
            "companion_layer_count": max(
                0, hybrid_cache_layer_count - len(hybrid_kv_positions)
            ),
        })

    if (
        getattr(scheduler, "_mixed_attention_cache_model", False)
        or cache_subtype
        in {"mixed_swa_kv", "step3p7_full_sliding_kv", "mimo_v2_asymmetric_swa"}
    ):
        tq_objects_active = bool(getattr(scheduler, "_tq_active", False))
        tq_live_encode = (
            bool(turboquant_status.get("live_encode_enabled"))
            if turboquant_status is not None
            else tq_objects_active
        )
        try:
            stored_kv_bits = int(getattr(scheduler, "_kv_cache_bits", 0) or 0)
        except (TypeError, ValueError):
            stored_kv_bits = 0
        try:
            stored_kv_group = int(getattr(scheduler, "_kv_cache_group_size", 64) or 64)
        except (TypeError, ValueError):
            stored_kv_group = 64
        if stored_kv_bits <= 0 and turboquant_status is not None:
            try:
                stored_kv_bits = int(
                    turboquant_status.get("storage_key_bits", 0) or 0
                )
            except (TypeError, ValueError):
                stored_kv_bits = 0
        native_tq_storage = bool(
            turboquant_status is not None
            and turboquant_status.get("storage_encode_enabled")
        )
        storage_quantized = bool(
            stored_kv_bits > 0
            or native_tq_storage
        )
        storage_quantization = {
            "enabled": storage_quantized,
            "mode": "storage_boundary",
            "bits": stored_kv_bits if storage_quantized else None,
            "group_size": stored_kv_group if storage_quantized else None,
            "applies_to": (
                "full_attention_kv_only"
                if native_tq_storage
                else "full_and_sliding_attention_kv"
            ),
            "metadata_policy": "preserve_rotating_window_metadata",
        }
        if native_tq_storage:
            storage_quantization["sliding_window_policy"] = (
                "native_rotating_kv_state"
            )
            storage_quantization["restore_policy"] = (
                "decode_full_attention_tq_and_restore_rotating_state"
            )
        return _with_runtime_layout({
            "family": family_name or scheduler_family or "mixed_attention",
            "schema": "mixed_swa_kv_v1",
            "cache_type": "mixed_swa_kv",
            "cache_subtype": cache_subtype or "mixed_swa_kv",
            "components": [
                "full_attention_kv",
                "sliding_window_kv",
                "rotating_window_metadata",
            ],
            "generic_turboquant_kv": {
                "enabled": tq_live_encode,
                "reason": (
                    "mixed_swa_live_attention_kv"
                    if tq_live_encode
                    else "storage_only" if storage_quantized else "not_active"
                ),
            },
            "storage_quantization": storage_quantization,
            "prefix": bool(block_aware_cache is not None),
            "paged": paged_backend_active,
            "block_disk_only": block_disk_only,
            "block_disk_l2": bool(block_disk_store is not None),
        })

    tq_enabled = bool(getattr(scheduler, "_tq_active", False))
    try:
        stored_kv_bits = int(getattr(scheduler, "_kv_cache_bits", 0) or 0)
    except (TypeError, ValueError):
        stored_kv_bits = 0
    try:
        stored_kv_group = int(getattr(scheduler, "_kv_cache_group_size", 64) or 64)
    except (TypeError, ValueError):
        stored_kv_group = 64
    return _with_runtime_layout({
        "family": family_name or scheduler_family or "plain_attention",
        "schema": "plain_kv_v1",
        "cache_type": "block_disk_kv" if block_disk_only else "paged_kv",
        "components": ["attention_kv"],
        "generic_turboquant_kv": {
            "enabled": tq_enabled,
            "reason": "plain_attention_kv" if tq_enabled else "not_active",
        },
        "storage_quantization": {
            "enabled": stored_kv_bits > 0,
            "bits": stored_kv_bits if stored_kv_bits > 0 else None,
            "group_size": stored_kv_group if stored_kv_bits > 0 else None,
        },
        "prefix": bool(block_aware_cache is not None),
        "paged": paged_backend_active,
        "block_disk_only": block_disk_only,
        "block_disk_l2": bool(block_disk_store is not None),
    })


def _stat_int(stats: dict[str, Any] | None, *keys: str) -> int:
    """Return the first integer-like stat value for any key."""
    if not isinstance(stats, dict):
        return 0
    for key in keys:
        value = stats.get(key)
        if value is None:
            continue
        try:
            return int(value)
        except (TypeError, ValueError):
            continue
    return 0


def _kv_cache_quantization_status(
    scheduler: Any | None,
    turboquant_status: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Return a truthful stored-KV quantization status block.

    The scheduler keeps ``_kv_cache_bits=0`` when stored-cache quantization is
    inactive. Exposing that raw integer makes the UI render a bogus "0-bit"
    cache codec, so both /health and /v1/cache/stats normalize through this
    helper.

    ``_kv_cache_bits`` only tracks the explicit legacy live-quantization
    setting. When the TurboQuant STORAGE codec is active (Auto policy,
    ``storage_encode_enabled``), stored KV really is quantized at the cache
    boundary, and reporting ``enabled: false`` here contradicted the
    ``turboquant_kv_cache`` section on the same response
    (HEALTH-KV-QUANT-FLAG-FALSE-WHILE-TQ-ACTIVE). Callers pass the computed
    TurboQuant status so this summary tells the same truth.
    """
    if scheduler is None or not hasattr(scheduler, "_kv_cache_bits"):
        return None
    try:
        bits = int(getattr(scheduler, "_kv_cache_bits", 0) or 0)
    except (TypeError, ValueError):
        bits = 0
    if bits <= 0:
        tq = turboquant_status or {}
        if tq.get("storage_encode_enabled"):
            return {
                "enabled": True,
                "mode": "turboquant-storage",
                # bits mirrors key_bits for consumers that render a single
                # "N-bit" figure (panel PerformancePanel).
                "bits": tq.get("storage_key_bits"),
                "stored_prefix_quantization": tq.get(
                    "stored_prefix_quantization"
                ),
                "key_bits": tq.get("storage_key_bits"),
                "value_bits": tq.get("storage_value_bits"),
                "auto_policy": tq.get("auto_policy"),
                "live_encode_enabled": bool(tq.get("live_encode_enabled")),
            }
        return {"enabled": False}
    return {
        "enabled": True,
        "mode": "live",
        "bits": bits,
        "group_size": getattr(scheduler, "_kv_cache_group_size", 64),
    }


def _request_bound_ssm_prefix_lookup(
    scheduler: Any,
) -> dict[str, Any] | None:
    """Return only a typed SSM lookup owned by the latest cache execution."""

    def _telemetry_attr(value: Any, name: str, default: Any = None) -> Any:
        try:
            return getattr(value, name, default)
        except Exception:
            return default

    scheduler_stats: Any = None
    stats_fn = _telemetry_attr(scheduler, "get_stats")
    if callable(stats_fn):
        try:
            scheduler_stats = stats_fn()
        except Exception:
            scheduler_stats = None
    if not isinstance(scheduler_stats, dict):
        batch_generator = _telemetry_attr(scheduler, "batch_generator")
        batch_stats = _telemetry_attr(batch_generator, "_stats")
        execution = _telemetry_attr(batch_stats, "last_cache_execution")
    else:
        execution = scheduler_stats.get("last_cache_execution")
    if not isinstance(execution, dict):
        return None

    raw_execution_request_id = execution.get("request_id")
    lookup = execution.get("ssm_prefix_lookup")
    if (
        raw_execution_request_id is None
        or not isinstance(lookup, dict)
        or lookup.get("request_id") is None
    ):
        return None
    execution_request_id = normalize_ssm_telemetry_request_id(
        raw_execution_request_id
    )
    lookup_request_id = normalize_ssm_telemetry_request_id(
        lookup.get("request_id")
    )
    if lookup_request_id != execution_request_id:
        return None

    attempted = execution.get("attempted_cached_tokens")
    fallback_max_len = (
        attempted if type(attempted) is int and attempted >= 0 else 0
    )
    sanitized = sanitize_ssm_prefix_lookup(
        lookup,
        request_id=execution_request_id,
        fallback_max_len=fallback_max_len,
    )
    if sanitized.get("max_len") != fallback_max_len:
        return sanitize_ssm_prefix_lookup(
            None,
            request_id=execution_request_id,
            fallback_max_len=fallback_max_len,
        )
    return sanitized


def _ssm_companion_snapshot(scheduler: Any) -> dict[str, Any] | None:
    """Collect SSM companion L1/L2 stats without assuming scheduler flavor."""
    def _telemetry_attr(value: Any, name: str, default: Any = None) -> Any:
        try:
            return getattr(value, name, default)
        except Exception:
            return default

    if scheduler is None:
        return None
    ssm_cache = _telemetry_attr(scheduler, "_ssm_state_cache")
    if ssm_cache is None:
        batch_generator = _telemetry_attr(scheduler, "batch_generator")
        if batch_generator is not None:
            ssm_cache = _telemetry_attr(batch_generator, "_ssm_state_cache")
    if ssm_cache is None:
        # MLLM creates HybridSSMStateCache lazily with the batch generator, but
        # its scheduler owns the L2 disk store at startup. Surface that
        # configured L2 tier before the first request so /health and
        # /v1/cache/stats don't falsely imply SSM persistence is absent.
        disk = _telemetry_attr(scheduler, "_ssm_companion_disk_store")
        if disk is None:
            return None
        cfg = _telemetry_attr(scheduler, "config")
        max_entries = int(
            _telemetry_attr(cfg, "ssm_state_cache_size", 0) or 0
        )
        max_mb = _telemetry_attr(cfg, "ssm_state_cache_max_mb")
        snapshot: dict[str, Any] = {
            "entries": 0,
            "max_entries": max_entries,
            "nbytes": 0,
            "nbytes_mb": 0.0,
            "max_bytes": (
                int(max_mb) * 1024 * 1024
                if max_mb is not None
                else None
            ),
            "max_bytes_mb": (
                round(float(max_mb), 2)
                if max_mb is not None
                else None
            ),
            "disk_enabled": True,
            "disk_directory": str(_telemetry_attr(disk, "directory") or ""),
        }
        snapshot["ram_enabled"] = bool(
            max_entries > 0 and (max_mb is None or int(max_mb) > 0)
        )
        snapshot["storage"] = (
            "ram_and_ssd" if snapshot["ram_enabled"] else "ssd_only"
        )
        stats_fn = _telemetry_attr(disk, "stats")
        if callable(stats_fn):
            try:
                snapshot["disk"] = stats_fn()
            except Exception as exc:
                snapshot["disk"] = {"enabled": True, "error": str(exc)}
        request_lookup = _request_bound_ssm_prefix_lookup(scheduler)
        if request_lookup is not None:
            snapshot["last_prefix_lookup"] = request_lookup
        return snapshot

    entries = _telemetry_attr(ssm_cache, "size")
    if entries is None:
        entries = len(_telemetry_attr(ssm_cache, "_store", {}) or {})
    max_entries = _telemetry_attr(ssm_cache, "max_entries")
    if max_entries is None:
        max_entries = _telemetry_attr(ssm_cache, "_max_entries", 0)
    nbytes = int(_telemetry_attr(ssm_cache, "total_nbytes", 0) or 0)
    max_bytes = _telemetry_attr(ssm_cache, "max_bytes")
    if max_bytes is None:
        max_bytes = _telemetry_attr(ssm_cache, "_max_bytes")
    if max_bytes is not None:
        max_bytes = int(max_bytes)
    ram_enabled = _telemetry_attr(ssm_cache, "ram_enabled")
    if ram_enabled is None:
        ram_enabled = bool(
            int(max_entries or 0) > 0
            and (max_bytes is None or max_bytes > 0)
        )
    disk_enabled = bool(
        _telemetry_attr(ssm_cache, "disk_enabled", False)
    )
    snapshot: dict[str, Any] = {
        "entries": int(entries or 0),
        "max_entries": int(max_entries or 0),
        "nbytes": nbytes,
        "nbytes_mb": round(nbytes / (1024 * 1024), 2),
        "evictions": int(_telemetry_attr(ssm_cache, "evictions", 0) or 0),
        "evicted_bytes": int(
            _telemetry_attr(ssm_cache, "evicted_bytes", 0) or 0
        ),
        "evicted_bytes_mb": round(
            int(_telemetry_attr(ssm_cache, "evicted_bytes", 0) or 0)
            / (1024 * 1024),
            2,
        ),
        "max_bytes": max_bytes,
        "max_bytes_mb": (
            round(max_bytes / (1024 * 1024), 2)
            if max_bytes is not None
            else None
        ),
        "ram_enabled": bool(ram_enabled),
        "disk_enabled": disk_enabled,
        "storage": (
            "ram_and_ssd"
            if ram_enabled and disk_enabled
            else "ram_only"
            if ram_enabled
            else "ssd_only"
            if disk_enabled
            else "disabled"
        ),
        "disk_directory": _telemetry_attr(ssm_cache, "disk_directory"),
    }
    disk = _telemetry_attr(ssm_cache, "_disk")
    stats_fn = _telemetry_attr(disk, "stats")
    if disk is not None and callable(stats_fn):
        try:
            snapshot["disk"] = stats_fn()
        except Exception as exc:
            snapshot["disk"] = {"enabled": True, "error": str(exc)}
    request_lookup = _request_bound_ssm_prefix_lookup(scheduler)
    if request_lookup is not None:
        snapshot["last_prefix_lookup"] = request_lookup
    return snapshot


def _cache_telemetry_snapshot(scheduler: Any | None = None) -> dict[str, Any]:
    """Summarize effective cache state for /health and /v1/cache/stats."""
    scheduler = scheduler if scheduler is not None else (_get_scheduler() if _engine else None)
    result: dict[str, Any] = {}

    scheduler_cache = None
    if _engine is not None and hasattr(_engine, "get_cache_stats"):
        try:
            scheduler_cache = _engine.get_cache_stats()
        except Exception:
            scheduler_cache = None
    if scheduler_cache:
        result["scheduler_cache"] = scheduler_cache
        vision_cache = (
            scheduler_cache.get("vision_cache")
            if isinstance(scheduler_cache, dict)
            and isinstance(scheduler_cache.get("vision_cache"), dict)
            else None
        )
        if vision_cache is not None:
            result["vision_memory_cache"] = vision_cache

    disk_cache = getattr(scheduler, "disk_cache", None) if scheduler else None
    if disk_cache is not None and hasattr(disk_cache, "stats"):
        try:
            result["disk_cache"] = disk_cache.stats()
        except Exception as exc:
            result["disk_cache"] = {"enabled": True, "error": str(exc)}

    paged_mgr = getattr(scheduler, "paged_cache_manager", None) if scheduler else None
    block_store = getattr(paged_mgr, "_disk_store", None) if paged_mgr else None
    if block_store is not None and hasattr(block_store, "get_stats"):
        try:
            result["block_disk_cache"] = block_store.get_stats()
        except Exception as exc:
            result["block_disk_cache"] = {"enabled": True, "error": str(exc)}

    ssm = _ssm_companion_snapshot(scheduler)
    if ssm is not None:
        result["ssm_companion"] = ssm

    if result:
        disk_tokens = _stat_int(result.get("disk_cache"), "total_tokens_on_disk", "total_cached_tokens")
        block_tokens = _stat_int(result.get("block_disk_cache"), "total_tokens_on_disk", "total_cached_tokens")
        ssm_disk = result.get("ssm_companion", {}).get("disk") if isinstance(result.get("ssm_companion"), dict) else None
        ssm_tokens = _stat_int(ssm_disk, "total_tokens_on_disk", "total_cached_tokens")
        l2_store_sum = disk_tokens + block_tokens + ssm_tokens
        l1_indexed_tokens = _stat_int(
            scheduler_cache,
            "total_tokens_cached",
            "total_cached_tokens",
            "tokens_cached",
        )
        paged_cache = (
            scheduler_cache.get("paged_cache")
            if isinstance(scheduler_cache, dict)
            and isinstance(scheduler_cache.get("paged_cache"), dict)
            else None
        )
        if paged_mgr is not None:
            resident_blocks = [
                block
                for block in getattr(paged_mgr, "blocks", ())
                if getattr(block, "cache_data", None) is not None
                and int(getattr(block, "resident_bytes", 0) or 0) > 0
            ]
            transient_blocks = [
                block
                for block in resident_blocks
                if bool(getattr(block, "cache_data_transient", False))
            ]
            paged_cache = {
                "backend_mode": (
                    "block_disk_only"
                    if bool(getattr(paged_mgr, "disk_only", False))
                    else "paged"
                ),
                "paged_ram_enabled": not bool(
                    getattr(paged_mgr, "disk_only", False)
                ),
                "disk_only": bool(getattr(paged_mgr, "disk_only", False)),
                "paged_frugal": bool(
                    getattr(paged_mgr, "paged_frugal", False)
                ),
                "ram_mirror_policy": str(
                    getattr(paged_mgr, "ram_mirror_policy", "resident")
                ),
                "resident_tokens": sum(
                    int(getattr(block, "token_count", 0) or 0)
                    for block in resident_blocks
                ),
                "resident_bytes": int(
                    getattr(paged_mgr, "resident_bytes", 0) or 0
                ),
                "transient_resident_tokens": sum(
                    int(getattr(block, "token_count", 0) or 0)
                    for block in transient_blocks
                ),
                "transient_resident_bytes": sum(
                    int(getattr(block, "resident_bytes", 0) or 0)
                    for block in transient_blocks
                ),
                "transient_disk_promotions": int(
                    getattr(paged_mgr, "transient_disk_promotions", 0) or 0
                ),
                "transient_disk_peak_bytes": int(
                    getattr(paged_mgr, "transient_disk_peak_bytes", 0) or 0
                ),
                "max_resident_bytes": int(
                    getattr(paged_mgr, "max_resident_bytes", 0) or 0
                ),
                "evictions": int(
                    getattr(getattr(paged_mgr, "stats", None), "evictions", 0)
                    or 0
                ),
            }
        # In frugal paged-cache mode, ordinary KV blocks are indexed in L1 but
        # their tensor payloads live only in L2. Do not label indexed tokens as
        # resident RAM. Older scheduler snapshots lack the resident fields, so
        # retain their historical value as a compatibility fallback.
        ram_tokens_cached = (
            int(paged_cache.get("resident_tokens", 0) or 0)
            if paged_cache is not None and "resident_tokens" in paged_cache
            else l1_indexed_tokens
        )
        l1_resident_bytes = (
            int(paged_cache.get("resident_bytes", 0) or 0)
            if paged_cache is not None
            else 0
        )
        l1_max_resident_bytes = (
            int(paged_cache.get("max_resident_bytes", 0) or 0)
            if paged_cache is not None
            else 0
        )
        # Account every retained prefix-cache payload tier, not just paged KV.
        # In SSD-only block mode scheduler_cache.nbytes is index metadata (or
        # absent), while a standalone memory-aware/legacy prefix cache reports
        # its actual payload bytes there. SSM companion state is a distinct L1
        # that previously hid >1 GB while this total reported zero.
        prefix_resident_bytes = (
            _stat_int(scheduler_cache, "nbytes") if paged_mgr is None else 0
        )
        prefix_max_resident_bytes = (
            _stat_int(scheduler_cache, "max_bytes") if paged_mgr is None else 0
        )
        ssm_snapshot = (
            result.get("ssm_companion")
            if isinstance(result.get("ssm_companion"), dict)
            else {}
        )
        ssm_resident_bytes = int(ssm_snapshot.get("nbytes", 0) or 0)
        ssm_max_resident_bytes = int(ssm_snapshot.get("max_bytes", 0) or 0)
        vision_snapshot = (
            result.get("vision_memory_cache")
            if isinstance(result.get("vision_memory_cache"), dict)
            else {}
        )
        vision_resident_bytes = int(
            vision_snapshot.get("retained_bytes", 0) or 0
        )
        paged_ram_enabled = bool(
            paged_cache is not None
            and paged_cache.get("paged_ram_enabled", False)
        )
        prefix_ram_enabled = bool(
            paged_mgr is None and prefix_max_resident_bytes > 0
        )
        ssm_ram_enabled = bool(ssm_snapshot.get("ram_enabled", False))
        vision_ram_enabled = bool(vision_snapshot.get("enabled", False))
        retained_cache_bytes = (
            l1_resident_bytes
            + prefix_resident_bytes
            + ssm_resident_bytes
            + vision_resident_bytes
        )
        retained_cache_max_bytes = (
            l1_max_resident_bytes
            + prefix_max_resident_bytes
            + ssm_max_resident_bytes
        )
        retained_cache_ram_enabled = bool(
            paged_ram_enabled
            or prefix_ram_enabled
            or ssm_ram_enabled
            or vision_ram_enabled
        )
        result["totals"] = {
            "ram_tokens_cached": ram_tokens_cached,
            "l1_indexed_tokens": l1_indexed_tokens,
            "l1_resident_bytes": l1_resident_bytes,
            "l1_resident_bytes_mb": round(l1_resident_bytes / (1024 * 1024), 2),
            "l1_max_resident_bytes": l1_max_resident_bytes,
            "l1_max_resident_bytes_mb": round(
                l1_max_resident_bytes / (1024 * 1024), 2
            ),
            "l1_evictions": (
                int(paged_cache.get("evictions", 0) or 0)
                if paged_cache is not None
                else 0
            ),
            "prefix_resident_bytes": prefix_resident_bytes,
            "ssm_resident_bytes": ssm_resident_bytes,
            "vision_memory_resident_bytes": vision_resident_bytes,
            "retained_cache_bytes": retained_cache_bytes,
            "retained_cache_bytes_mb": round(
                retained_cache_bytes / (1024 * 1024), 2
            ),
            "retained_cache_max_bytes": retained_cache_max_bytes,
            "retained_cache_max_bytes_mb": round(
                retained_cache_max_bytes / (1024 * 1024), 2
            ),
            "retained_cache_ram_enabled": retained_cache_ram_enabled,
            "retained_cache_policy": (
                "enabled" if retained_cache_ram_enabled else "disabled"
            ),
            "retained_cache_components": {
                "block_kv_bytes": l1_resident_bytes,
                "prefix_bytes": prefix_resident_bytes,
                "ssm_companion_bytes": ssm_resident_bytes,
                "vision_processor_bytes": vision_resident_bytes,
            },
            "l2_prompt_tokens_on_disk": disk_tokens,
            "l2_block_tokens_on_disk": block_tokens,
            "l2_ssm_tokens_on_disk": ssm_tokens,
            "ssm_tokens_on_disk": ssm_tokens,
            "l2_tokens_on_disk": l2_store_sum,
            "l2_tokens_on_disk_store_sum": l2_store_sum,
            "l2_tokens_on_disk_note": "store_sum_across_prompt_block_ssm_l2; tiers_may_overlap",
        }
    return result


def _request_lifecycle_health_snapshot(
    engine_stats: dict[str, Any],
    scheduler_stats: dict[str, Any],
) -> dict[str, Any]:
    """Build a prompt-free, engine-owned request lifecycle attestation.

    Prefix-cache ``active_requests`` counts request tables and can legitimately
    disappear before ``scheduler.running`` during terminal cleanup.  It is
    therefore cache telemetry, not proof of gateway request ownership.  This
    snapshot instead joins the engine's output collectors with scheduler
    waiting/running IDs and the terminal-persistence gate.  Counts are derived
    from the ID lists so consumers cannot accidentally attest mismatched
    counters.
    """

    def _request_ids(value: Any) -> list[str] | None:
        if not isinstance(value, list):
            return None
        if any(not isinstance(item, str) or not item for item in value):
            return None
        if len(set(value)) != len(value):
            return None
        return sorted(value)

    collector_ids = _request_ids(
        engine_stats.get("engine_collector_request_ids")
    )
    waiting_ids = _request_ids(
        scheduler_stats.get(
            "waiting_request_ids",
            engine_stats.get("waiting_request_ids"),
        )
    )
    running_ids = _request_ids(
        scheduler_stats.get(
            "running_request_ids",
            engine_stats.get("running_request_ids"),
        )
    )
    declared_collector_count = engine_stats.get("engine_collector_count")
    declared_waiting_count = scheduler_stats.get(
        "num_waiting",
        engine_stats.get("num_waiting"),
    )
    declared_running_count = scheduler_stats.get(
        "num_running",
        engine_stats.get("num_running"),
    )

    def _count_matches_ids(value: Any, request_ids: list[str] | None) -> bool:
        return (
            request_ids is not None
            and isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 0
            and value == len(request_ids)
        )

    def _running_status_rows(
        value: Any,
        request_ids: list[str] | None,
    ) -> list[dict[str, str]] | None:
        # Status rows are diagnostic, but a non-empty running set still needs
        # one row per request so the public lifecycle cannot attest an
        # incomplete scheduler view.  An absent field is therefore equivalent
        # to an empty list only while there are no running requests.
        if value is None:
            return [] if request_ids == [] else None
        if not isinstance(value, list) or request_ids is None:
            return None
        result_rows: list[dict[str, str]] = []
        seen: set[str] = set()
        for row in value:
            if not isinstance(row, dict):
                return None
            request_id = row.get("request_id")
            if (
                not isinstance(request_id, str)
                or not request_id
                or request_id not in request_ids
                or request_id in seen
            ):
                return None
            status = row.get("status")
            if status is not None and not isinstance(status, str):
                return None
            seen.add(request_id)
            result_rows.append(
                {
                    "request_id": request_id,
                    **({"status": status} if status is not None else {}),
                }
            )
        if seen != set(request_ids):
            return None
        return result_rows

    source_running_status = _running_status_rows(
        scheduler_stats.get("running_requests"),
        running_ids,
    )
    cleanup_pending = engine_stats.get("terminal_cleanup_pending")
    available = (
        collector_ids is not None
        and waiting_ids is not None
        and running_ids is not None
        and _count_matches_ids(declared_collector_count, collector_ids)
        and _count_matches_ids(declared_waiting_count, waiting_ids)
        and _count_matches_ids(declared_running_count, running_ids)
        and source_running_status is not None
        and isinstance(cleanup_pending, bool)
    )
    result: dict[str, Any] = {
        "schema": "vmlx-request-lifecycle-v1",
        "request_id_encoding": "sha256-utf8-lowerhex",
        "available": available,
    }
    if not available:
        return result

    def _request_id_sha256(request_id: str) -> str:
        return hashlib.sha256(request_id.encode("utf-8")).hexdigest()

    collector_id_hashes = sorted(
        _request_id_sha256(request_id) for request_id in collector_ids
    )
    waiting_id_hashes = sorted(
        _request_id_sha256(request_id) for request_id in waiting_ids
    )
    running_id_hashes = sorted(
        _request_id_sha256(request_id) for request_id in running_ids
    )
    running_status = []
    for row in source_running_status:
        request_id = row["request_id"]
        status = row.get("status")
        running_status.append(
            {
                "request_id_sha256": _request_id_sha256(request_id),
                **({"status": status} if isinstance(status, str) else {}),
            }
        )
    running_status.sort(key=lambda row: row["request_id_sha256"])

    active_id_hashes = sorted(
        set(collector_id_hashes)
        | set(waiting_id_hashes)
        | set(running_id_hashes)
    )
    result.update(
        {
            "engine_collector_count": len(collector_id_hashes),
            "engine_collector_request_ids_sha256": collector_id_hashes,
            "scheduler_waiting_count": len(waiting_id_hashes),
            "scheduler_waiting_request_ids_sha256": waiting_id_hashes,
            "scheduler_running_count": len(running_id_hashes),
            "scheduler_running_request_ids_sha256": running_id_hashes,
            "scheduler_running_requests": running_status,
            "active_request_count": len(active_id_hashes),
            "active_request_ids_sha256": active_id_hashes,
            "terminal_cleanup_pending": cleanup_pending,
        }
    )
    return result


# The heavy diagnostics assembled by /health (engine/scheduler stats, Metal
# allocator gauges, KV-quant + cache telemetry walks, attestations) contend
# with the decode thread for the GIL, the Metal allocator lock and scheduler
# state. With the panel's 5s poll this measured as a 330-410ms inter-token
# stall per poll during DSV4 decode (2026-08-09 stall-map/log alignment).
# Policy: while any request is running or queued, serve the last idle-time
# snapshot with live O(1) overlays; recompute the full payload only when the
# engine is idle, so idle polls stay perfectly fresh and busy polls cost
# nothing on the generation path.
_health_snapshot_cache: dict[str, Any] = {"result": None}


def _live_last_cache_execution(scheduler: Any) -> dict[str, Any] | None:
    """Cheap live read of the newest cache-execution record.

    Pure attribute reads only — safe to call while requests are in flight
    (unlike the full get_stats assembly, which can race the chunked-prefill
    loop). Preference order matches get_stats: generator record, then the
    MLLM admission record, then the text scheduler's own record.
    """
    if scheduler is None:
        return None
    for source in (
        getattr(getattr(scheduler, "batch_generator", None), "_stats", None),
        scheduler,
    ):
        for attr in ("last_cache_execution", "_admission_cache_execution",
                     "_last_cache_execution"):
            record = getattr(source, attr, None) if source is not None else None
            if isinstance(record, dict) and record:
                return dict(record)
    return None


def _live_ssm_prefix_lookup(scheduler: Any) -> dict[str, Any] | None:
    """Cheap live read of the SSM companion's newest prefix lookup.

    Same attribute-read-only discipline as _live_last_cache_execution; the
    companion cache resolves through the scheduler or its batch generator.
    """
    if scheduler is None:
        return None
    ssm_cache = getattr(scheduler, "_ssm_state_cache", None)
    if ssm_cache is None:
        ssm_cache = getattr(
            getattr(scheduler, "batch_generator", None),
            "_ssm_state_cache",
            None,
        )
    lookup = getattr(ssm_cache, "last_prefix_lookup", None)
    return dict(lookup) if isinstance(lookup, dict) and lookup else None


def _live_batch_generator_request_records(
    scheduler: Any,
) -> dict[str, dict[str, Any] | None] | None:
    """Read request-correlated MLLM records without assembling full stats."""
    stats = getattr(
        getattr(scheduler, "batch_generator", None),
        "_stats",
        None,
    )
    if stats is None:
        return None
    records: dict[str, dict[str, Any] | None] = {}
    for attr in (
        "last_cache_execution",
        "last_durability",
        "last_native_mtp",
        "last_native_mtp_skip",
    ):
        record = getattr(stats, attr, None)
        records[attr] = (
            dict(record) if isinstance(record, dict) and record else None
        )
    return records


def _live_mllm_request_lifecycle_snapshot(
    scheduler: Any,
) -> dict[str, Any] | None:
    """Read the MLLM request lifecycle without running heavy cache stats.

    Busy ``/health`` responses intentionally reuse the last idle diagnostics
    snapshot so polling cannot stall decode.  The MLLM scheduler already owns
    a lock-protected, prompt-free view of collectors, waiting requests,
    running requests, and terminal cleanup.  Rebuild only that small view so
    the cached response never reports an in-flight gateway request as idle.
    """
    lock = getattr(scheduler, "_queue_lock", None)
    output_queues = getattr(scheduler, "output_queues", None)
    waiting = getattr(scheduler, "waiting", None)
    running = getattr(scheduler, "running", None)
    cleanup_event = getattr(scheduler, "_terminal_cleanup_complete", None)
    if (
        lock is None
        or not isinstance(output_queues, dict)
        or waiting is None
        or not isinstance(running, dict)
        or cleanup_event is None
        or not callable(getattr(cleanup_event, "is_set", None))
    ):
        return None
    try:
        with lock:
            collector_request_ids = sorted(output_queues)
            waiting_request_ids = [
                request.request_id for request in waiting
            ]
            running_request_ids = sorted(running)
            lifecycle_stats = {
                "engine_collector_count": len(collector_request_ids),
                "engine_collector_request_ids": collector_request_ids,
                "num_waiting": len(waiting_request_ids),
                "waiting_request_ids": waiting_request_ids,
                "num_running": len(running_request_ids),
                "running_request_ids": running_request_ids,
                "running_requests": [
                    {
                        "request_id": request_id,
                        "status": getattr(
                            getattr(running[request_id], "status", None),
                            "name",
                            str(getattr(running[request_id], "status", "")),
                        ),
                    }
                    for request_id in running_request_ids
                ],
                "terminal_cleanup_pending": not cleanup_event.is_set(),
            }
    except Exception:
        return None
    return _request_lifecycle_health_snapshot(
        lifecycle_stats,
        lifecycle_stats,
    )


def _health_status_value() -> str:
    if _standby_state:
        return f"standby_{_standby_state}"  # "standby_soft" or "standby_deep"
    if _model_type == "image":
        return (
            "healthy"
            if (_image_gen is not None and _image_gen.is_loaded)
            else "no_model"
        )
    return "healthy" if _engine is not None else "no_model"


@app.get("/health")
async def health():
    """Health check endpoint."""
    if _standby_state == "deep" and _engine is None:
        await _post_async_engine_teardown_mlx_cleanup("health_standby_deep")

    scheduler_probe = _get_scheduler() if _engine is not None else None
    num_running = num_waiting = 0
    if scheduler_probe is not None:
        # Strict len() semantics: anything that is not a real sized container
        # (e.g. test mocks) counts as idle so the full payload is computed.
        try:
            num_running = len(scheduler_probe.running)
            num_waiting = len(scheduler_probe.waiting)
        except Exception:
            num_running = num_waiting = 0
    cached_result = _health_snapshot_cache.get("result")
    if (num_running or num_waiting) and cached_result is not None:
        import copy as _copy

        result = _copy.deepcopy(cached_result)
        result["status"] = _health_status_value()
        result["last_request_time"] = (
            _last_request_time if _last_request_time > 0 else None
        )
        sched_block = result.get("scheduler")
        if isinstance(sched_block, dict):
            sched_block["num_running"] = num_running
            sched_block["num_waiting"] = num_waiting
            # Request-correlated cache proofs need the CURRENT execution
            # record, but this cached branch serves whenever a request is
            # running or waiting — and a finished request lingers in
            # `running` through its terminal cache cleanup, so pollers that
            # read health right after a response saw the PRE-request
            # snapshot (lce null on cold first requests, the prior
            # request's record otherwise; proven live via the hierarchy
            # gate on 32k chunked prefills). Overlay the live record — a
            # cheap attribute read, no expensive stats assembly.
            _live_lce = _live_last_cache_execution(scheduler_probe)
            if _live_lce is not None:
                sched_block["last_cache_execution"] = _live_lce
            _live_generator_records = _live_batch_generator_request_records(
                scheduler_probe
            )
            _generator_block = sched_block.get("batch_generator")
            if (
                isinstance(_generator_block, dict)
                and _live_generator_records is not None
            ):
                _current_request_id = (
                    _live_lce.get("request_id")
                    if isinstance(_live_lce, dict)
                    else None
                )
                _generator_lce = _live_generator_records.get(
                    "last_cache_execution"
                )
                if _generator_lce is not None:
                    _generator_block["last_cache_execution"] = _generator_lce
                else:
                    _generator_block.pop("last_cache_execution", None)
                for _record_name in (
                    "last_native_mtp",
                    "last_native_mtp_skip",
                ):
                    _record = _live_generator_records.get(_record_name)
                    if (
                        isinstance(_record, dict)
                        and _current_request_id
                        and _record.get("request_id") == _current_request_id
                    ):
                        _generator_block[_record_name] = _record
                    else:
                        _generator_block.pop(_record_name, None)
        # Same staleness applies to the SSM companion prefix lookup the
        # cache-correlation gates read: overlay the live lookup when it is
        # BOUND to the live execution record, and drop the cached one when
        # it is not — a stale lookup mislabels the row, absence is honest.
        _cache_block = result.get("cache")
        _companion_block = (
            _cache_block.get("ssm_companion")
            if isinstance(_cache_block, dict)
            else None
        )
        if isinstance(_companion_block, dict):
            # The request-BOUND lookup lives embedded in the execution
            # record (the generator stamps the request id there); the
            # companion cache's own attribute is constructed without one,
            # so an attr-vs-lce id comparison can never bind. Source from
            # the embedded copy first — the same record the non-cached
            # health path exposes via _request_bound_ssm_prefix_lookup.
            # Runs even when the cached snapshot has NO lookup key: a
            # snapshot taken BEFORE the request legitimately lacks it, and
            # gating on prior presence suppressed the bound live lookup for
            # exactly the rows that need it (observed live: r4 refault lce
            # bound with a bound embedded lookup, companion field null).
            _live_lookup = None
            _live_lce_id = (
                _live_lce.get("request_id")
                if isinstance(_live_lce, dict)
                else None
            )
            if isinstance(_live_lce, dict):
                _embedded_lookup = _live_lce.get("ssm_prefix_lookup")
                if (
                    isinstance(_embedded_lookup, dict)
                    and _embedded_lookup
                    and _embedded_lookup.get("request_id") == _live_lce_id
                ):
                    _live_lookup = dict(_embedded_lookup)
            if _live_lookup is None:
                _attr_lookup = _live_ssm_prefix_lookup(scheduler_probe)
                if (
                    isinstance(_attr_lookup, dict)
                    and _live_lce_id
                    and _attr_lookup.get("request_id") == _live_lce_id
                ):
                    _live_lookup = _attr_lookup
            if _live_lookup is not None:
                _companion_block["last_prefix_lookup"] = _live_lookup
            else:
                _companion_block.pop("last_prefix_lookup", None)
        _live_lifecycle = _live_mllm_request_lifecycle_snapshot(
            scheduler_probe
        )
        if _live_lifecycle is not None:
            result["request_lifecycle"] = _live_lifecycle
        result["health_gauges_cached"] = True
        result["wake_in_progress"] = _wake_in_progress
        result["load_progress"] = _lifecycle_progress.snapshot()
        return result

    mcp_info = None
    if _mcp_manager is not None:
        connected = sum(
            1 for s in _mcp_manager.get_server_status() if s.state.value == "connected"
        )
        total = len(_mcp_manager.get_server_status())
        mcp_info = {
            "enabled": True,
            "servers_connected": connected,
            "servers_total": total,
            "tools_available": len(_mcp_manager.get_all_tools(policy=_mcp_policy)),
        }

    engine_stats = _engine.get_stats() if _engine else {}
    scheduler = _get_scheduler() if _engine else None

    # Differentiate status: "healthy" when model is loaded, "no_model" otherwise
    # Image models don't use _engine — they use _image_gen
    status = _health_status_value()

    # Include Metal GPU memory info when available
    memory_info = None
    try:
        import mlx.core as mx

        active = peak = cache = None
        if hasattr(mx, "get_active_memory"):
            active = mx.get_active_memory()
            peak = mx.get_peak_memory()
            cache = mx.get_cache_memory()
        elif hasattr(mx, "metal") and hasattr(mx.metal, "get_active_memory"):
            active = mx.metal.get_active_memory()
            peak = mx.metal.get_peak_memory()
            cache = mx.metal.get_cache_memory()
        if active is not None:
            memory_info = {
                "active_mb": round(active / (1024 * 1024), 1),
                "peak_mb": round(peak / (1024 * 1024), 1),
                "cache_mb": round(cache / (1024 * 1024), 1),
            }
    except Exception:
        pass

    # Include stored-KV cache quantization status for diagnostics. Pass the
    # TurboQuant status so an active storage codec is reported truthfully.
    kv_quant_info = _kv_cache_quantization_status(
        scheduler,
        _turboquant_kv_cache_status(_engine, scheduler)
        if _engine is not None
        else None,
    )

    # Include speculative decoding status
    spec_info = None
    try:
        from .speculative import get_spec_stats

        spec_info = get_spec_stats()
    except ImportError:
        pass

    if _model_type == "image":
        result = {
            "status": status,
            "model_loaded": _image_gen is not None and _image_gen.is_loaded,
            "model_name": _resolve_model_name(),
            "loaded_model_name": _model_name,
            "served_model_name": _served_model_name,
            "model_type": "image",
            "engine_type": "mflux",
            "last_request_time": _last_request_time if _last_request_time > 0 else None,
        }
        # What the loaded model actually accepts (negative prompt, strength,
        # mask, count), so clients and the app can show only effective controls.
        if _image_gen is not None and _image_gen.is_loaded:
            try:
                result["image"] = _image_gen.capabilities()
            except Exception as exc:  # never let a probe break /health
                result["image"] = {"loaded": True, "error": str(exc)[:200]}
    else:
        result = {
            "status": status,
            "model_loaded": _engine is not None,
            "model_name": _resolve_model_name(),
            "loaded_model_name": _model_name,
            "served_model_name": _served_model_name,
            "model_type": "mllm" if (_engine and _engine.is_mllm) else "llm",
            "engine_type": engine_stats.get("engine_type", "unknown"),
            "last_request_time": _last_request_time if _last_request_time > 0 else None,
            "mcp": mcp_info,
        }
    if _model_load_error:
        # Sanitize: strip absolute filesystem paths from error messages for security
        import re

        sanitized = re.sub(r"(/[^\s:]+)+", "<path>", _model_load_error)
        result["error"] = sanitized
    if memory_info:
        result["memory"] = memory_info
    if kv_quant_info:
        result["kv_cache_quantization"] = kv_quant_info
    if spec_info:
        result["speculative_decoding"] = spec_info.get(
            "speculative_decoding", spec_info
        )
    result["active_parsers"] = _active_parser_health_status()
    scheduler_stats: dict[str, Any] = {}
    if scheduler:
        try:
            scheduler_stats = scheduler.get_stats()
        except Exception:
            scheduler_stats = {}
        result["scheduler"] = {
            "num_waiting": scheduler_stats.get("num_waiting", 0),
            "num_running": scheduler_stats.get("num_running", 0),
            "engine_path": scheduler_stats.get("engine_path"),
            "batch_generator": scheduler_stats.get("batch_generator", {}),
            "single_active_decode": (
                scheduler_stats.get("batch_generator", {}) or {}
            ).get("single_active_decode", False),
            "ewma_ttft_seconds": scheduler_stats.get("ewma_ttft_seconds", 0),
            "cache_hit_requests": scheduler_stats.get("cache_hit_requests", 0),
            "cache_hit_tokens": scheduler_stats.get("cache_hit_tokens", 0),
            "cache_hit_tokens_by_detail": scheduler_stats.get(
                "cache_hit_tokens_by_detail", {}
            ),
            "hybrid_kv_without_ssm_hits": (
                scheduler_stats.get("batch_generator", {}) or {}
            ).get("hybrid_kv_without_ssm_hits", 0),
            "hybrid_kv_without_ssm_tokens": (
                scheduler_stats.get("batch_generator", {}) or {}
            ).get("hybrid_kv_without_ssm_tokens", 0),
            "last_hybrid_kv_without_ssm": (
                scheduler_stats.get("batch_generator", {}) or {}
            ).get("last_hybrid_kv_without_ssm"),
            "cache_reuse_skips": scheduler_stats.get("cache_reuse_skips", 0),
            "cache_reuse_skip_tokens": scheduler_stats.get(
                "cache_reuse_skip_tokens", 0
            ),
            "last_cache_reuse_skip": scheduler_stats.get("last_cache_reuse_skip"),
            "cache_reuse_partial_downgrades": scheduler_stats.get(
                "cache_reuse_partial_downgrades", 0
            ),
            "cache_reuse_partial_tokens": scheduler_stats.get(
                "cache_reuse_partial_tokens", 0
            ),
            "last_cache_reuse_partial": scheduler_stats.get(
                "last_cache_reuse_partial"
            ),
            "last_cache_selection": scheduler_stats.get("last_cache_selection"),
            "last_cache_execution": scheduler_stats.get("last_cache_execution"),
            "vision_cache": scheduler_stats.get("vision_cache"),
        }
        cache_snapshot = _cache_telemetry_snapshot(scheduler)
        if cache_snapshot:
            result["cache"] = cache_snapshot

    if _engine is not None:
        result["request_lifecycle"] = _request_lifecycle_health_snapshot(
            engine_stats,
            # Batched LLM and MLLM engines publish their scheduler IDs in the
            # same get_stats() snapshot as collector/cleanup state.  Reusing
            # that snapshot avoids a second scheduler read widening the normal
            # admission/terminal-cleanup observation skew.
            engine_stats,
        )

    # Smelt mode: report partial expert loading status
    if _smelt_enabled:
        result["smelt"] = {
            "enabled": True,
            "expert_percent": _smelt_experts,
        }

    # Distributed compute: report cluster status
    if _distributed_enabled:
        dist_info = {
            "enabled": True,
            "mode": _distributed_mode,
        }
        if _distributed_coordinator:
            dist_info.update(_distributed_coordinator.status)
            # Worker count and pipeline from coordinator (if we are coordinator)
            coord = _distributed_coordinator.coordinator
            if coord:
                dist_info["workers"] = len(coord.workers)
                dist_info["pipeline"] = [
                    a.to_dict() for a in coord.assignments
                ] if coord.assignments else []
        result["distributed"] = dist_info

    # Flash MoE: report SSD streaming status
    if _flash_moe_enabled and _flash_moe_loader is not None:
        result["flash_moe"] = _flash_moe_loader.stats()

    # JANG format: report cached quantization metadata (populated at load time)
    if _jang_metadata:
        result["quantization_format"] = _jang_metadata
    if _model_path or _model_name:
        bundle_key = _model_path or _model_name
        result["quantization"] = _model_quantization_status(bundle_key)
        result["acceleration"] = _model_acceleration_status(bundle_key)
        result["mtp"] = _model_mtp_status_with_loaded_runtime(bundle_key)
        generation_status = _model_effective_defaults_status(bundle_key)
        result["sampling_defaults"] = generation_status["sampling_defaults"]
        result["effective_defaults"] = generation_status["effective_defaults"]
        routing_status = _model_routing_status(bundle_key)
        if routing_status:
            result["routing"] = routing_status

    if _max_prompt_tokens > 0:
        result["max_prompt_tokens"] = _max_prompt_tokens

    # Nemotron-3-Nano-Omni multimodal: surface bundle status + active backend.
    # Lets the UI show "Vision/Audio: Native MLX (fast)" vs "PyTorch bridge".
    try:
        from .omni_multimodal import (
            OmniMultimodalDispatcher,
            omni_multimodal_component_status,
        )
        _omni_path = _model_path or _model_name
        _omni_status = (
            omni_multimodal_component_status(_omni_path) if _omni_path else {}
        )
        if _omni_status.get("bundle_compatible"):
            result["omni_multimodal"] = {
                "bundle_compatible": True,
                "backend": OmniMultimodalDispatcher._pick_backend(),
                "modalities": _omni_status.get("modalities")
                or ["text", "audio", "image"],
                "components": {
                    "radio": bool(_omni_status.get("has_radio_weights")),
                    "parakeet": bool(_omni_status.get("has_parakeet_weights")),
                    "media_projector": bool(_omni_status.get("has_media_projector")),
                },
                "session_l2": OmniMultimodalDispatcher.session_l2_status_for(
                    _omni_path,
                    enabled=_loaded_block_disk_cache_enabled(),
                ),
            }
    except Exception:
        pass

    if _engine is not None:
        scheduler = _get_scheduler()
        result["turboquant_kv_cache"] = _turboquant_kv_cache_status(
            _engine, scheduler
        )
        _mc = _current_model_config()
        native_cache = _native_cache_status(
            scheduler,
            family=getattr(_mc, "family_name", None),
            cfg=_mc,
            turboquant_status=result["turboquant_kv_cache"],
        )
        if native_cache:
            result["native_cache"] = native_cache

    # Volatile codec counters must not participate in the stable cache-topology
    # fingerprint. Keep them as a separate runtime observation surface.
    result["cache_storage_runtime_telemetry"] = (
        _cache_storage_runtime_telemetry()
    )
    result["wake_in_progress"] = _wake_in_progress
    result["load_progress"] = _lifecycle_progress.snapshot()

    model_loaded = bool(result.get("model_loaded"))
    model_bundle_provenance = _bundle_configuration_attestation(
        _model_path,
        model_loaded=model_loaded,
    )
    cache_topology_provenance = _cache_topology_attestation(
        _cache_topology_configuration(scheduler, result)
    )
    # Keep top-level path-free attestations for live gate harnesses while
    # retaining the nested copies in runtime_provenance for existing clients.
    result["model_bundle_provenance"] = model_bundle_provenance
    result["cache_topology_provenance"] = cache_topology_provenance
    result["runtime_provenance"] = {
        **_RUNTIME_PROVENANCE,
        "pid": os.getpid(),
        "model_bundle_provenance": model_bundle_provenance,
        "cache_topology_provenance": cache_topology_provenance,
    }
    try:
        import copy as _copy

        _health_snapshot_cache["result"] = _copy.deepcopy(result)
    except Exception:
        _health_snapshot_cache["result"] = None
    return result


@app.get("/health.mtp")
async def health_mtp():
    """Native MTP status endpoint used by the app and release gates."""
    return _model_mtp_status_with_loaded_runtime(_model_path or _model_name)


def _get_scheduler():
    """Get the scheduler from the engine, or None if not available."""
    if _engine is None:
        return None
    # MLLM path: scheduler is directly on the engine
    mllm_sched = getattr(_engine, "_mllm_scheduler", None)
    if mllm_sched is not None:
        return mllm_sched
    # LLM path: BatchedEngine._engine is AsyncEngineCore, which has .engine (EngineCore)
    # EngineCore has .scheduler
    async_core = getattr(_engine, "_engine", None)
    if async_core is not None:
        engine_core = getattr(async_core, "engine", None)
        if engine_core is not None:
            return getattr(engine_core, "scheduler", None)
    return None


async def _post_async_engine_teardown_mlx_cleanup(reason: str) -> None:
    """Run MLX cleanup after awaited engine-teardown frames can release.

    The deep-sleep path awaits nested async stop coroutines. CPython can keep a
    completed coroutine frame/traceback alive until the event loop advances once;
    for BatchedEngine that frame contains ``EngineCore.self`` which owns the
    Scheduler -> wrapper -> model chain. Clearing MLX memory before that tick
    leaves a model-sized active allocation that the next wake can duplicate.
    """
    try:
        await asyncio.sleep(0)
    except Exception:
        pass
    try:
        import gc as _gc
        import mlx.core as _mx

        _gc.collect()
        clear_mlx_memory_cache(log=logger)
        sync = getattr(_mx, "synchronize", None)
        if callable(sync):
            sync()
        _gc.collect()
        clear_mlx_memory_cache(log=logger)
    except Exception as exc:
        logger.debug("Post-teardown MLX cleanup failed after %s: %s", reason, exc)


# ── Admin: Sleep / Wake ──


def _scheduler_busy_counts() -> tuple[int, int]:
    """Return (num_running, num_waiting) from the live scheduler, 0s if unavailable."""
    scheduler = _get_scheduler()
    if scheduler is None:
        return (0, 0)
    try:
        stats = scheduler.get_stats()
        return (
            int(stats.get("num_running", 0) or 0),
            int(stats.get("num_waiting", 0) or 0),
        )
    except Exception:
        return (0, 0)


def _sleep_busy_response(depth: str):
    """409 guard: sleep must never tear down caches under a live request.

    A deep_reset() while a request is decoding destroys its KV state and the
    stream stalls silently until the client times out (observed live: 10min
    idle-from-submission soft sleep killed a long DSV4 reasoning turn).
    """
    from starlette.responses import JSONResponse

    num_running, num_waiting = _scheduler_busy_counts()
    if num_running > 0 or num_waiting > 0:
        logger.warning(
            "Refusing %s sleep: scheduler busy (num_running=%d, num_waiting=%d)",
            depth,
            num_running,
            num_waiting,
        )
        return JSONResponse(
            status_code=409,
            content={
                "error": "busy",
                "detail": f"{num_running} running / {num_waiting} waiting requests; retry when idle",
                "num_running": num_running,
                "num_waiting": num_waiting,
            },
        )
    return None


@app.post("/admin/soft-sleep", dependencies=[Depends(verify_api_key)])
async def admin_soft_sleep():
    """Enter soft sleep: clear all caches, reduce Metal cache limit. Model stays loaded."""
    global _standby_state, _pre_sleep_cache_limit, _wake_lock
    from starlette.responses import JSONResponse

    if _wake_lock is None:
        _wake_lock = asyncio.Lock()

    async with _wake_lock:
        if _standby_state == "deep":
            return JSONResponse(
                status_code=409, content={"error": "Already in deep sleep"}
            )
        if _standby_state == "soft":
            return {"status": "already_soft"}

        busy = _sleep_busy_response("soft")
        if busy is not None:
            return busy

        try:
            import mlx.core as mx

            scheduler = _get_scheduler()
            if scheduler is not None:
                if hasattr(scheduler, "deep_reset"):
                    scheduler.deep_reset()
                elif hasattr(scheduler, "_prefix_cache") and scheduler._prefix_cache:
                    scheduler._prefix_cache.clear()

            _set_cache = getattr(mx, "set_cache_limit", None) or getattr(
                mx.metal, "set_cache_limit", None
            )
            if _set_cache:
                _pre_sleep_cache_limit = _set_cache(512 * 1024 * 1024)

            clear_mlx_memory_cache(log=logger)

            _standby_state = "soft"
            _lifecycle_progress.report_standby("soft")
            logger.info("Entered soft sleep — caches cleared, model loaded")
            return {"status": "soft_sleep"}

        except Exception as e:
            logger.error(f"Failed to enter soft sleep: {e}")
            return {"error": str(e)}


@app.post("/admin/deep-sleep", dependencies=[Depends(verify_api_key)])
async def admin_deep_sleep():
    """Enter deep sleep: unload model entirely. Process stays alive, port stays allocated."""
    global _engine, _standby_state, _pre_sleep_cache_limit, _wake_lock
    global _flash_moe_loader, _distributed_coordinator
    from starlette.responses import JSONResponse

    if _wake_lock is None:
        _wake_lock = asyncio.Lock()

    async with _wake_lock:
        if _standby_state == "deep":
            return JSONResponse(
                status_code=409, content={"error": "Already in deep sleep"}
            )

        busy = _sleep_busy_response("deep")
        if busy is not None:
            return busy

        try:
            import mlx.core as mx
            import gc

            # Save Metal cache limit before deep sleep (if not already saved by soft sleep)
            if _pre_sleep_cache_limit is None:
                _set_cache = getattr(mx, "set_cache_limit", None) or getattr(
                    mx.metal, "set_cache_limit", None
                )
                if _set_cache:
                    _pre_sleep_cache_limit = _set_cache(512 * 1024 * 1024)

            # Generic mx.compile closures capture the model callable. Detach
            # them on the MLX-owning worker before clearing scheduler/engine
            # references, otherwise an in-process wake can retain the old JIT
            # graph while loading a second copy of the model.
            if _engine is not None:
                await _run_on_model_executor(_remove_jit_compilation)

            scheduler = _get_scheduler()
            if scheduler is not None:
                if hasattr(scheduler, "deep_reset"):
                    scheduler.deep_reset()

            if _model_type == "image" and _image_gen is not None:
                await _run_image_gen_call(_image_gen.unload)
            elif _engine is not None:
                if hasattr(_engine, "stop"):
                    try:
                        await _engine.stop()
                    except Exception:
                        pass
                _engine = None
                _reset_mllm_generation_streams()
                await _post_async_engine_teardown_mlx_cleanup("admin_deep_sleep_engine_stop")

            # Clear stale Flash MoE loader — the FlashMoEExpertLoader holds
            # references to the now-freed model's ExpertIndex and thread pool.
            # Leaving this set would cause /health to report stale stats and
            # would leak the I/O worker threads across the sleep cycle.
            if _flash_moe_loader is not None:
                try:
                    _flash_moe_loader.shutdown()
                except Exception as e:
                    logger.debug(f"Flash MoE loader shutdown during deep sleep: {e}")
                _flash_moe_loader = None

            # Tear down the distributed mesh so worker TCP connections close
            # cleanly and the coordinator doesn't keep heartbeating a model
            # that no longer exists. admin_wake() rebuilds from _cli_args.
            if _distributed_coordinator is not None:
                try:
                    shutdown = getattr(_distributed_coordinator, "shutdown", None) \
                        or getattr(_distributed_coordinator, "stop", None)
                    if shutdown is not None:
                        result = shutdown()
                        if asyncio.iscoroutine(result):
                            await result
                    logger.info("Distributed mesh coordinator shut down for deep sleep")
                except Exception as e:
                    logger.warning(f"Distributed shutdown during deep sleep failed: {e}")
                _distributed_coordinator = None

            # Unload speculative draft model to free GPU memory
            try:
                from .speculative import unload_draft_model

                unload_draft_model()
            except Exception as e:
                logger.debug(f"Draft model unload during deep sleep: {e}")

            gc.collect()
            clear_mlx_memory_cache(log=logger)

            _standby_state = "deep"
            _lifecycle_progress.report_standby("deep")
            try:
                asyncio.create_task(
                    _post_async_engine_teardown_mlx_cleanup("admin_deep_sleep_deferred")
                )
            except Exception:
                pass
            logger.info("Entered deep sleep — model unloaded, process alive")
            return {"status": "deep_sleep"}

        except Exception as e:
            logger.error(f"Failed to enter deep sleep: {e}")
            return {"error": str(e)}


async def _admin_wake_impl():
    """Reload from standby while the caller owns ``_wake_lock``."""
    global _engine, _standby_state, _pre_sleep_cache_limit, _model_load_error

    if _standby_state is None:
        return {"status": "already_active"}

    try:
        import mlx.core as mx

        if _standby_state == "soft":
            # Soft sleep: model is still loaded, just restore cache limit
            _set_cache = getattr(mx, "set_cache_limit", None) or getattr(
                mx.metal, "set_cache_limit", None
            )
            if _set_cache and _pre_sleep_cache_limit is not None:
                _set_cache(_pre_sleep_cache_limit)
            _standby_state = None
            _pre_sleep_cache_limit = None
            logger.info("Woke from soft sleep — cache limit restored")
            return {"status": "active"}

        elif _standby_state == "deep":
            # Deep sleep: need to reload model
            # Restore cache limit first
            _set_cache = getattr(mx, "set_cache_limit", None) or getattr(
                mx.metal, "set_cache_limit", None
            )
            if _set_cache and _pre_sleep_cache_limit is not None:
                _set_cache(_pre_sleep_cache_limit)
            _pre_sleep_cache_limit = None

            if _model_type == "image" and _image_gen is not None:
                # Reload image model on the same dedicated worker used for
                # generation. MLX streams are thread-local; reloading on the
                # default executor and generating elsewhere reopens the
                # Stream(gpu,N) crash class.
                await _run_image_gen_call(
                    _image_gen.load,
                    _model_name,
                    quantize=getattr(_image_gen, "_quantize", None),
                    model_path=getattr(_image_gen, "_model_path", None),
                    mflux_class=getattr(_image_gen, "_mflux_class", None),
                    lora_paths=_image_lora_paths,
                    lora_scales=_image_lora_scales,
                )
                _standby_state = None
                logger.info(
                    f"Woke from deep sleep — image model {_model_name} reloaded"
                )
                return {"status": "active"}
            elif _model_path or _model_name:
                await _post_async_engine_teardown_mlx_cleanup("admin_wake_before_deep_reload")
                _lifecycle_progress.report(
                    phase=_lifecycle_progress.PHASE_LOADING_WEIGHTS
                )
                # Reload text model — run in thread to avoid blocking event loop
                # (loading large models takes 10-60s; _wake_lock prevents concurrent
                # access to the globals that load_model modifies)
                await asyncio.to_thread(
                    load_model,
                    _model_path or _model_name,
                    use_batching=_cli_args.get("use_batching", False),
                    scheduler_config=_cli_args.get("scheduler_config"),
                    stream_interval=_cli_args.get("stream_interval", 1),
                    max_tokens=_cli_args.get("max_tokens", _FALLBACK_MAX_OUTPUT_TOKENS),
                    max_tokens_explicit=_cli_args.get("max_tokens_explicit", False),
                    max_prompt_tokens=_cli_args.get("max_prompt_tokens"),
                    force_mllm=_cli_args.get("force_mllm", False),
                    served_model_name=_cli_args.get("served_model_name"),
                    smelt=_cli_args.get("smelt", False),
                    smelt_experts=_cli_args.get("smelt_experts", 50),
                    flash_moe=_cli_args.get("flash_moe", False),
                    flash_moe_slot_bank=_cli_args.get("flash_moe_slot_bank", 64),
                    flash_moe_prefetch=_cli_args.get("flash_moe_prefetch", "none"),
                    flash_moe_io_split=_cli_args.get("flash_moe_io_split", 4),
                    distributed=_cli_args.get("distributed", False),
                    distributed_mode=_cli_args.get("distributed_mode", "pipeline"),
                    cluster_secret=_cli_args.get("cluster_secret", ""),
                    worker_nodes=_cli_args.get("worker_nodes"),
                )
                # Start engine after wake. Both SimpleEngine and BatchedEngine
                # expose `_loaded` — start() is idempotent for SimpleEngine and
                # required for BatchedEngine (lifespan usually handles this,
                # but wake bypasses lifespan).
                if (
                    _engine is not None
                    and hasattr(_engine, "_loaded")
                    and not _engine._loaded
                ):
                    await _engine.start()
                    if hasattr(_engine, "_needs_async_start"):
                        _engine._needs_async_start = False
                _lifecycle_progress.report(
                    phase=_lifecycle_progress.PHASE_RESTORING_ACCELERATION,
                    model_loaded=True,
                )
                # Re-apply Flash MoE after wake (load_model skipped it because
                # _engine._loaded was False when called inside event loop)
                if _flash_moe_enabled and _engine is not None:
                    await _run_on_model_executor(_apply_flash_moe_patching)
                # Re-apply JIT compilation after deep wake (load_model skips it
                # because _engine._loaded is False at check time inside event loop)
                if _enable_jit and _engine is not None:
                    await _run_on_model_executor(_apply_jit_compilation)
                # Reload speculative draft model if configured
                _spec_model = _cli_args.get("speculative_model")
                if _spec_model:
                    try:
                        from .speculative import SpeculativeConfig, load_draft_model

                        _spec_cfg = SpeculativeConfig(
                            model=_spec_model,
                            num_tokens=_cli_args.get("num_draft_tokens", 3),
                        )
                        # issue #200: reload draft model on the model worker
                        # thread to avoid a Metal eval race with generation.
                        await _run_on_model_executor(load_draft_model, _spec_cfg)
                        logger.info(f"Draft model reloaded: {_spec_model}")
                    except Exception as e:
                        logger.warning(f"Failed to reload draft model on wake: {e}")
                # Measure after the optional speculative draft is resident so
                # deep-wake prompt limits use the same total memory ownership
                # as initial startup.
                _record_metal_ws_model_baseline("admin_wake_post_acceleration")
                _refresh_loaded_max_prompt_tokens("admin_wake_engine_start")
                _standby_state = None
                logger.info(f"Woke from deep sleep — model {_model_name} reloaded")
                return {"status": "active"}
            else:
                return {"error": "No model name saved — cannot reload"}

    except Exception as e:
        logger.error(f"Failed to wake from sleep: {e}")
        # Clear standby state to prevent infinite JIT wake retry loop.
        # Server stays alive but reports error via /health.
        _standby_state = None
        _model_load_error = f"Wake failed: {e}"
        return {"error": str(e)}


async def _wake_with_lock_held():
    """Run one wake under the already-held shared transition lock.

    Both the JIT middleware and the public admin endpoint converge here.  The
    second waiter re-checks standby after acquiring the lock and therefore
    observes ``already_active`` instead of allocating a second model copy.
    """
    global _wake_in_progress

    if _standby_state is None:
        return {"status": "already_active"}

    _wake_in_progress = True
    _lifecycle_progress.begin_attempt(_lifecycle_progress.PHASE_STARTING)
    try:
        result = await _admin_wake_impl()
        if isinstance(result, dict) and result.get("status") in ("active", "already_active"):
            _lifecycle_progress.report(model_loaded=True, ready=True)
        else:
            _lifecycle_progress.report(phase=_lifecycle_progress.PHASE_IDLE, ready=False)
        return result
    finally:
        _wake_in_progress = False


@app.post("/admin/wake", dependencies=[Depends(verify_api_key)])
async def admin_wake():
    """Wake from sleep through the same mutex used by JIT/API wake."""
    global _wake_lock

    if _wake_lock is None:
        _wake_lock = asyncio.Lock()
    async with _wake_lock:
        return await _wake_with_lock_held()


@app.get("/v1/cache/stats", dependencies=[Depends(verify_api_key)])
async def cache_stats():
    """Get cache statistics for debugging and monitoring."""
    result = {}

    # Scheduler-level prefix cache stats
    if _engine:
        scheduler_cache = _engine.get_cache_stats()
        if scheduler_cache:
            result["scheduler_cache"] = scheduler_cache

    # Scheduler-level overall stats (includes cache stats + request stats)
    scheduler = _get_scheduler()
    if scheduler:
        stats = scheduler.get_stats()
        result["scheduler_stats"] = {
            "num_waiting": stats.get("num_waiting", 0),
            "num_running": stats.get("num_running", 0),
            "engine_path": stats.get("engine_path"),
            "batch_generator": stats.get("batch_generator", {}),
            "single_active_decode": (
                stats.get("batch_generator", {}) or {}
            ).get("single_active_decode", False),
            "num_requests_processed": stats.get("num_requests_processed", 0),
            "total_prompt_tokens": stats.get("total_prompt_tokens", 0),
            "total_completion_tokens": stats.get("total_completion_tokens", 0),
            "ewma_ttft_seconds": stats.get("ewma_ttft_seconds", 0),
            "cache_hit_requests": stats.get("cache_hit_requests", 0),
            "cache_hit_tokens": stats.get("cache_hit_tokens", 0),
            "cache_hit_tokens_by_detail": stats.get("cache_hit_tokens_by_detail", {}),
            "hybrid_kv_without_ssm_hits": (
                stats.get("batch_generator", {}) or {}
            ).get("hybrid_kv_without_ssm_hits", 0),
            "hybrid_kv_without_ssm_tokens": (
                stats.get("batch_generator", {}) or {}
            ).get("hybrid_kv_without_ssm_tokens", 0),
            "last_hybrid_kv_without_ssm": (
                stats.get("batch_generator", {}) or {}
            ).get("last_hybrid_kv_without_ssm"),
            "cache_reuse_skips": stats.get("cache_reuse_skips", 0),
            "cache_reuse_skip_tokens": stats.get("cache_reuse_skip_tokens", 0),
            "last_cache_reuse_skip": stats.get("last_cache_reuse_skip"),
            "cache_reuse_partial_downgrades": stats.get(
                "cache_reuse_partial_downgrades", 0
            ),
            "cache_reuse_partial_tokens": stats.get(
                "cache_reuse_partial_tokens", 0
            ),
            "last_cache_reuse_partial": stats.get("last_cache_reuse_partial"),
            "last_cache_selection": stats.get("last_cache_selection"),
            "last_cache_execution": stats.get("last_cache_execution"),
            "vision_cache": stats.get("vision_cache"),
        }
        # TurboQuant KV cache status (separate path from generic
        # kv_cache_quantization). Use the same recursive detector as /health
        # so source and packaged app expose the actual patched make_cache path.
        # Computed first so the kv_cache_quantization summary below can report
        # an active storage codec truthfully.
        result["turboquant_kv_cache"] = _turboquant_kv_cache_status(
            _engine, scheduler
        )
        # Stored-KV cache quantization info. Normalize disabled state so the
        # panel never renders raw bits=0 as a fake "0-bit" codec.
        kv_quant = _kv_cache_quantization_status(
            scheduler, result["turboquant_kv_cache"]
        )
        if kv_quant:
            result["kv_cache_quantization"] = kv_quant
        _mc = _current_model_config()
        native_cache = _native_cache_status(
            scheduler,
            family=getattr(_mc, "family_name", None),
            cfg=_mc,
            turboquant_status=result["turboquant_kv_cache"],
        )
        if native_cache:
            result["native_cache"] = native_cache

    # Disk cache (L2) stats — prompt-level
    if scheduler and getattr(scheduler, "disk_cache", None) is not None:
        result["disk_cache"] = scheduler.disk_cache.stats()

    # Block disk store (L2) stats — paged cache blocks
    paged_mgr = getattr(scheduler, "paged_cache_manager", None) if scheduler else None
    block_store = getattr(paged_mgr, "_disk_store", None) if paged_mgr else None
    if block_store is not None and hasattr(block_store, "get_stats"):
        result["block_disk_cache"] = block_store.get_stats()

    cache_snapshot = _cache_telemetry_snapshot(scheduler)
    if cache_snapshot.get("totals"):
        result["cache_totals"] = cache_snapshot["totals"]

    # MLLM-specific cache stats
    try:
        from mlx_vlm.utils import (
            get_multimodal_kv_cache_stats,
            get_pil_cache_stats,
            get_pixel_values_cache_stats,
        )

        result["multimodal_kv_cache"] = get_multimodal_kv_cache_stats()
        result["pixel_values_cache"] = get_pixel_values_cache_stats()
        result["pil_image_cache"] = get_pil_cache_stats()
    except ImportError:
        pass

    # TurboQuant status
    if _engine:
        model = getattr(_engine, "_model", None) or getattr(_engine, "model", None)
        if model and hasattr(model, "make_cache"):
            _tq_active = is_turboquant_make_cache(model.make_cache)
            if _tq_active:
                result["turbo_quant"] = {"enabled": True}

    # SSM companion cache stats (hybrid models only). Use the same helper as
    # /health so the panel sees disk token totals and IO counters on both
    # polling surfaces.
    ssm_snapshot = cache_snapshot.get("ssm_companion")
    if ssm_snapshot:
        result["ssm_companion"] = ssm_snapshot

    # Metal GPU memory info
    try:
        import mlx.core as mx

        active = peak = cache_mem = None
        if hasattr(mx, "get_active_memory"):
            active = mx.get_active_memory()
            peak = mx.get_peak_memory()
            cache_mem = mx.get_cache_memory()
        elif hasattr(mx, "metal") and hasattr(mx.metal, "get_active_memory"):
            active = mx.metal.get_active_memory()
            peak = mx.metal.get_peak_memory()
            cache_mem = mx.metal.get_cache_memory()
        if active is not None:
            result["memory"] = {
                "active_mb": round(active / (1024 * 1024), 1),
                "peak_mb": round(peak / (1024 * 1024), 1),
                "cache_mb": round(cache_mem / (1024 * 1024), 1),
            }
    except Exception:
        pass

    if not result:
        return {"error": "No cache stats available"}
    return result


@app.get("/v1/cache/entries", dependencies=[Depends(verify_api_key)])
async def cache_entries():
    """List cached prefix entries with metadata."""
    scheduler = _get_scheduler()
    if scheduler is None:
        return {"error": "Scheduler not available (SimpleEngine mode)"}

    entries = []
    cache_type = "none"

    if getattr(scheduler, "memory_aware_cache", None) is not None:
        cache_type = "memory_aware"
        from .memory_cache import _BYTES_PER_MB

        for tokens_key, entry in scheduler.memory_aware_cache._entries.items():
            entries.append(
                {
                    "tokens_count": len(tokens_key),
                    "memory_bytes": entry.memory_bytes,
                    "memory_mb": round(entry.memory_bytes / _BYTES_PER_MB, 2),
                    "cache_type": "memory_aware",
                }
            )
    elif getattr(scheduler, "block_aware_cache", None) is not None:
        cache_type = "paged"
        for (
            block_id,
            block,
        ) in scheduler.block_aware_cache.paged_cache.allocated_blocks.items():
            entries.append(
                {
                    "block_id": block_id,
                    "tokens_count": block.token_count,
                    "ref_count": block.ref_count,
                    "has_data": block.cache_data is not None,
                    "cache_type": "paged",
                }
            )
    elif getattr(scheduler, "prefix_cache", None) is not None:
        cache_type = "legacy"
        for _, tokens_tuple in scheduler.prefix_cache._lru:
            entries.append(
                {
                    "tokens_count": len(tokens_tuple),
                    "cache_type": "legacy",
                }
            )

    return {
        "cache_type": cache_type,
        "count": len(entries),
        "entries": entries,
    }


def _get_model_owner_executor():
    """Return the single-thread executor that owns MLX model eval, or None.

    Issue #200: background MLX work (cache-warm prefill, draft-model reload)
    must run on the SAME thread as scheduler.step()/model load. Using
    asyncio.to_thread()/run_in_executor(None, ...) picks arbitrary default-
    pool threads; concurrent Metal kernel/library cache population then races
    the model worker thread and crashes (objc_retain / newFunctionWithName).
    All three engine shapes expose a single-thread step/model executor.
    """
    eng = _engine
    if eng is None:
        return None
    # SimpleEngine (direct / no continuous-batching)
    ex = getattr(eng, "_model_executor", None)
    if ex is not None:
        return ex
    _ensure = getattr(eng, "_ensure_model_executor", None)
    if callable(_ensure):
        try:
            return _ensure()
        except Exception:
            pass
    # BatchedEngine (MLLM) — scheduler owns the step executor
    ex = getattr(getattr(eng, "_mllm_scheduler", None), "_step_executor", None)
    if ex is not None:
        return ex
    # BatchedEngine owns the loader/step executor directly for both its LLM
    # and MLLM construction paths. Missing this attribute sent wake-time JIT
    # and speculative-draft work to asyncio's arbitrary default pool.
    ex = getattr(eng, "_step_executor", None)
    if ex is not None:
        return ex
    # BatchedEngine (LLM) — EngineCore.scheduler._step_executor
    for _attr in ("_engine_core", "engine_core", "_core", "scheduler", "_scheduler"):
        obj = getattr(eng, _attr, None)
        if obj is None:
            continue
        ex = getattr(obj, "_step_executor", None)
        if ex is not None:
            return ex
        ex = getattr(getattr(obj, "scheduler", None), "_step_executor", None)
        if ex is not None:
            return ex
    return None


async def _run_on_model_executor(fn, /, *args, **kwargs):
    """Run a blocking MLX call on the model-owner thread (issue #200).

    Falls back to asyncio.to_thread only when no model executor is
    discoverable (e.g. between deep-sleep teardown and reload).
    """
    ex = _get_model_owner_executor()
    if ex is not None:
        loop = asyncio.get_running_loop()
        call = functools.partial(fn, *args, **kwargs)
        return await loop.run_in_executor(ex, call)
    return await asyncio.to_thread(fn, *args, **kwargs)


def _run_on_model_executor_blocking(fn, /, *args, **kwargs):
    """Run startup-time MLX mutation on the engine's owning worker.

    ``load_model`` is synchronous during CLI startup, so it cannot await the
    async helper. Its caller is the server/main thread, never the single model
    executor itself; submitting here keeps JIT/Flash model mutation on the same
    thread that loaded and evaluates the model.
    """
    ex = _get_model_owner_executor()
    call = functools.partial(fn, *args, **kwargs)
    if ex is not None:
        return ex.submit(call).result()
    return call()


@app.post("/v1/cache/warm", dependencies=[Depends(verify_api_key)])
async def cache_warm(request: dict):
    """
    Warm the prefix cache by pre-computing KV states for given prompts.

    Request body: {"prompts": ["system prompt text", ...]}
    """
    scheduler = _get_scheduler()
    if scheduler is None:
        return {"error": "Scheduler not available (SimpleEngine mode)"}

    prompts = request.get("prompts", [])
    if not prompts:
        return {"error": "No prompts provided"}

    def _encode_prompt_for_warm(_scheduler, _prompt: str):
        tokenizer = getattr(_scheduler, "_actual_tokenizer", None)
        if tokenizer is None:
            tokenizer = getattr(_scheduler, "tokenizer", None)
        if tokenizer is None:
            processor = getattr(_scheduler, "processor", None)
            tokenizer = getattr(processor, "tokenizer", processor)
        if tokenizer is None or not hasattr(tokenizer, "encode"):
            raise AttributeError("scheduler has no tokenizer/processor tokenizer")
        return tokenizer.encode(_prompt)

    def _do_warm():
        """Run prefill warming in a thread to avoid blocking the event loop."""
        warmed = 0
        token_counts = []
        errors = []

        for i, prompt in enumerate(prompts):
            try:
                tokens = _encode_prompt_for_warm(scheduler, prompt)

                if not tokens:
                    errors.append(f"Prompt {i}: empty after tokenization")
                    continue

                cache_tokens = tokens[:-1]
                if not cache_tokens:
                    errors.append(f"Prompt {i}: too short (1 token)")
                    continue

                cache = scheduler._prefill_for_prompt_only_cache(cache_tokens)
                if cache is None:
                    errors.append(f"Prompt {i}: prefill failed")
                    continue

                stored = False
                if getattr(scheduler, "memory_aware_cache", None) is not None:
                    stored = scheduler.memory_aware_cache.store(tokens, cache)
                elif getattr(scheduler, "block_aware_cache", None) is not None:
                    extracted = scheduler._extract_cache_states(cache)
                    if extracted:
                        result = scheduler.block_aware_cache.store_cache(
                            f"warm-{i}-{uuid.uuid4().hex[:8]}", tokens, extracted
                        )
                        stored = result is not None
                elif getattr(scheduler, "prefix_cache", None) is not None:
                    scheduler.prefix_cache.store_cache(tokens, cache)
                    stored = True
                else:
                    errors.append(f"Prompt {i}: no cache backend enabled")
                    continue

                if stored:
                    warmed += 1
                    token_counts.append(len(tokens))
                else:
                    errors.append(
                        f"Prompt {i}: cache store rejected (too large or full)"
                    )
            except Exception as e:
                errors.append(f"Prompt {i}: {type(e).__name__}: {e}")

        return {
            "warmed": warmed,
            "token_counts": token_counts,
            "errors": errors if errors else None,
        }

    # issue #200: serialize warm prefill on the model worker thread, not
    # an arbitrary default-pool thread (would race scheduler.step()).
    _warm_executor = getattr(scheduler, "_step_executor", None) or _get_model_owner_executor()
    if _warm_executor is not None:
        loop = asyncio.get_running_loop()
        return await loop.run_in_executor(_warm_executor, _do_warm)
    return await asyncio.to_thread(_do_warm)


def _cache_token_contract_request_sha256(payload: Any) -> str:
    return hashlib.sha256(
        json.dumps(
            payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode()
    ).hexdigest()


def _cache_contract_lcp(left: list[int], right: list[int]) -> int:
    count = 0
    for a_token, b_token in zip(left, right, strict=False):
        if a_token != b_token:
            break
        count += 1
    return count


def _cache_contract_tokenizer(engine: Any):
    scheduler = _get_scheduler()
    candidates = (
        getattr(engine, "_tokenizer", None),
        getattr(engine, "tokenizer", None),
        getattr(scheduler, "_actual_tokenizer", None),
        getattr(scheduler, "tokenizer", None),
        getattr(getattr(engine, "tokenizer", None), "tokenizer", None),
        getattr(getattr(engine, "_processor", None), "tokenizer", None),
        getattr(engine, "_processor", None),
    )
    seen: set[int] = set()
    for candidate in candidates:
        if candidate is None:
            continue
        ident = id(candidate)
        if ident in seen:
            continue
        seen.add(ident)
        if hasattr(candidate, "encode"):
            return candidate
    return None


def _cache_contract_encode(tokenizer: Any, prompt: str) -> list[int]:
    try:
        return list(tokenizer.encode(prompt, add_special_tokens=False))
    except TypeError:
        return list(tokenizer.encode(prompt))


_CACHE_CONTRACT_FORBIDDEN_SIDE_KEY_FIELDS = frozenset(
    {
        "_cache_extra_keys",
        "cache_extra_keys",
        "cache_salt",
        "media_salt",
        "request_salt",
        "skip_prefix_cache",
        "images",
        "videos",
        "audio",
        "audios",
        "input_image",
        "input_video",
        "input_audio",
    }
)


def _cache_contract_reject_side_keys(
    payload: dict[str, Any],
    request_controls: dict[str, Any],
) -> None:
    """Reject caller-supplied cache/media identity on the text-only contract."""
    for scope, values in (
        ("request", payload),
        ("request_controls", request_controls),
    ):
        forbidden = sorted(
            key
            for key in _CACHE_CONTRACT_FORBIDDEN_SIDE_KEY_FIELDS
            if key in values
        )
        if forbidden:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"{scope} cannot supply cache/media side keys to the "
                    f"text-only contract: {', '.join(forbidden)}"
                ),
            )


def _cache_contract_render_and_tokenize(
    *,
    engine: Any,
    prompt: str,
    model: str,
    request_controls: dict[str, Any],
) -> tuple[dict[str, Any], list[int], dict[str, str] | None]:
    """Dry-render one Responses prompt through the loaded engine cache path.

    This endpoint is intentionally no-generation and no-cache-lookup.  It is
    used by the live cache hierarchy gate to independently bind observed
    prompt/cache telemetry to the model's final Responses render path.  It
    returns only path-free counts and digests, never prompt text or token IDs.
    """
    if not isinstance(prompt, str):
        raise HTTPException(status_code=400, detail="inputs values must be strings")

    enable_thinking = request_controls.get("enable_thinking")
    if enable_thinking is not None and not isinstance(enable_thinking, bool):
        raise HTTPException(
            status_code=400,
            detail="request_controls.enable_thinking must be true, false, or null",
        )
    instructions = request_controls.get("instructions")
    if instructions is not None and not isinstance(instructions, str):
        raise HTTPException(
            status_code=400,
            detail="request_controls.instructions must be a string or null",
        )
    tools = request_controls.get("tools")
    if tools is None:
        tools = []
    if not isinstance(tools, list) or any(
        not isinstance(tool, dict) for tool in tools
    ):
        raise HTTPException(
            status_code=400,
            detail="request_controls.tools must be an array of tool objects",
        )
    if len(tools) > 64:
        raise HTTPException(
            status_code=400,
            detail="request_controls.tools exceeds the bounded limit of 64",
        )
    tool_choice = request_controls.get("tool_choice")
    if tool_choice is not None and not isinstance(tool_choice, (str, dict)):
        raise HTTPException(
            status_code=400,
            detail="request_controls.tool_choice must be a string, object, or null",
        )
    raw_ct_kwargs = request_controls.get("chat_template_kwargs")
    if raw_ct_kwargs is not None and not isinstance(raw_ct_kwargs, dict):
        raise HTTPException(
            status_code=400,
            detail="request_controls.chat_template_kwargs must be an object or null",
        )

    dry_request = ResponsesRequest(
        model=model,
        input=prompt,
        instructions=instructions,
        enable_thinking=enable_thinking,
        chat_template_kwargs=raw_ct_kwargs,
        tools=tools,
        tool_choice=tool_choice,
    )
    effective_tools = _request_tools_for_generation_prompt(dry_request)
    template_tools = convert_tools_for_template(effective_tools) or []
    messages = _responses_input_to_messages(
        dry_request.input,
        dry_request.instructions,
        preserve_multimodal=False,
    )
    messages = _normalize_leading_system_messages(
        messages,
        preserve_native_order=_is_loaded_dsv4_model(model),
    )
    ct_kwargs = _merge_ct_kwargs(
        dry_request.chat_template_kwargs,
        getattr(dry_request, "reasoning_effort", None),
    )
    resolved_thinking = _resolve_enable_thinking(
        request_value=dry_request.enable_thinking,
        ct_kwargs=ct_kwargs,
        tools_present=bool(template_tools),
        model_key=_model_path or _model_name or model,
        engine=engine,
        auto_detect=True,
        reasoning_effort=dry_request.reasoning_effort,
    )
    if resolved_thinking is not None:
        dry_request.enable_thinking = resolved_thinking
        ct_kwargs["enable_thinking"] = resolved_thinking
    if dry_request.max_thinking_tokens is not None and dry_request.enable_thinking is not False:
        ct_kwargs["thinking_budget"] = int(dry_request.max_thinking_tokens)

    _normalize_minimax_m3_thinking_mode(
        ct_kwargs,
        dry_request,
        _model_path or _model_name or model,
    )
    _normalize_openpangu_thinking(
        ct_kwargs,
        dry_request,
        _model_path or _model_name or model,
    )

    thinking_enabled = True if dry_request.enable_thinking is None else bool(
        dry_request.enable_thinking
    )
    token_ids: list[int]
    gen_prompt_len = 0
    cache_extra_keys: dict[str, str] | None = None
    tokenizer_source: str | None = None
    tokenizer_class: str | None = None
    production_cache_key_token_ids: list[int] | None = None
    cache_key_boundary = "full_cache_prompt"
    identity_builder = getattr(engine, "build_cache_contract_prompt_identity", None)
    if callable(identity_builder):
        try:
            identity = identity_builder(
                messages,
                template_tools,
                enable_thinking=thinking_enabled,
                extra_template_kwargs=ct_kwargs,
                skip_generation_prompt=False,
            )
            raw_token_ids = identity.get("token_ids")
            if not isinstance(raw_token_ids, list) or any(
                not isinstance(token, int) for token in raw_token_ids
            ):
                raise ValueError("cache contract helper returned invalid token ids")
            token_ids = list(raw_token_ids)
            raw_production_ids = identity.get("production_cache_key_token_ids")
            if raw_production_ids is not None:
                if not isinstance(raw_production_ids, list) or any(
                    not isinstance(token, int) for token in raw_production_ids
                ):
                    raise ValueError(
                        "cache contract helper returned invalid production key ids"
                    )
                production_cache_key_token_ids = list(raw_production_ids)
            raw_boundary = identity.get("cache_key_boundary")
            if raw_boundary is not None:
                cache_key_boundary = str(raw_boundary)
            gen_prompt_len = max(
                0,
                min(
                    int(identity.get("generation_prompt_suffix_tokens") or 0),
                    len(token_ids),
                ),
            )
            computed_extra_keys = identity.get("cache_extra_keys")
            tokenizer_source = (
                str(identity.get("tokenizer_source"))
                if identity.get("tokenizer_source") is not None
                else None
            )
            tokenizer_class = (
                str(identity.get("tokenizer_class"))
                if identity.get("tokenizer_class") is not None
                else None
            )
            if computed_extra_keys is not None:
                if (
                    not isinstance(computed_extra_keys, dict)
                    or set(computed_extra_keys) != {"generation_prompt"}
                    or not isinstance(
                        computed_extra_keys.get("generation_prompt"),
                        str,
                    )
                    or not computed_extra_keys["generation_prompt"]
                ):
                    raise ValueError(
                        "text-only cache contract received non-generation "
                        "cache side keys"
                    )
                cache_extra_keys = {
                    "generation_prompt": computed_extra_keys["generation_prompt"]
                }
        except Exception as exc:
            logger.debug("cache token-contract production identity failed: %s", exc)
            raise RuntimeError("cache token-contract production identity failed") from exc
    else:
        renderer = getattr(engine, "_apply_chat_template", None)
        if not callable(renderer):
            raise HTTPException(
                status_code=501,
                detail="loaded engine does not expose dry chat-template rendering",
            )
        rendered = renderer(
            messages,
            template_tools,
            num_images=0,
            num_videos=0,
            num_audio=0,
            enable_thinking=thinking_enabled,
            extra_template_kwargs=ct_kwargs,
            skip_generation_prompt=False,
        )

        tokenizer = _cache_contract_tokenizer(engine)
        if tokenizer is None:
            raise HTTPException(
                status_code=501,
                detail="loaded engine does not expose a prompt tokenizer",
            )
        tokenizer_source = "server_fallback"
        tokenizer_class = type(tokenizer).__name__
        token_ids = _cache_contract_encode(tokenizer, rendered)
        compute_gen_prompt = getattr(engine, "_compute_gen_prompt_cache_context", None)
        if callable(compute_gen_prompt):
            try:
                computed_len, computed_extra_keys = compute_gen_prompt(
                    messages,
                    template_tools,
                    0,
                    thinking_enabled,
                    ct_kwargs,
                    rendered,
                    num_videos=0,
                    num_audio=0,
                )
                gen_prompt_len = max(0, min(int(computed_len or 0), len(token_ids)))
                if computed_extra_keys is not None:
                    if (
                        not isinstance(computed_extra_keys, dict)
                        or set(computed_extra_keys) != {"generation_prompt"}
                        or not isinstance(
                            computed_extra_keys.get("generation_prompt"),
                            str,
                        )
                        or not computed_extra_keys["generation_prompt"]
                    ):
                        raise ValueError(
                            "text-only cache contract received non-generation "
                            "cache side keys"
                        )
                    cache_extra_keys = {
                        "generation_prompt": computed_extra_keys["generation_prompt"]
                    }
            except Exception as exc:
                logger.debug("cache token-contract gen-prompt derivation failed: %s", exc)
                raise RuntimeError(
                    "cache generation-prompt discriminator is unavailable"
                ) from exc
        elif rendered:
            raise RuntimeError(
                "loaded engine does not expose generation-prompt cache context"
            )
    if gen_prompt_len <= 0 and cache_extra_keys is not None:
        raise RuntimeError(
            "generation-prompt discriminator exists without a stripped suffix"
        )
    if gen_prompt_len > 0 and cache_extra_keys is None:
        raise RuntimeError(
            "stripped generation prompt has no production cache discriminator"
        )
    cache_prompt_token_ids = (
        token_ids[:-gen_prompt_len] if gen_prompt_len > 0 else token_ids
    )
    full_cache_prompt_token_ids = list(cache_prompt_token_ids)
    if production_cache_key_token_ids is None:
        production_cache_key_token_ids = list(cache_prompt_token_ids)
        if (
            bool(getattr(engine, "is_mllm", False) or getattr(engine, "_is_mllm", False))
            and len(production_cache_key_token_ids) > 1
        ):
            production_cache_key_token_ids = production_cache_key_token_ids[:-1]
            cache_key_boundary = "mllm_re_feed_n_minus_one"
    if len(production_cache_key_token_ids) > len(full_cache_prompt_token_ids):
        raise RuntimeError("production cache-key boundary exceeds rendered prompt")
    token_digest = hashlib.sha256(
        json.dumps(
            production_cache_key_token_ids,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode()
    ).hexdigest()
    full_token_digest = hashlib.sha256(
        json.dumps(
            full_cache_prompt_token_ids,
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode()
    ).hexdigest()
    return {
        "input_sha256": hashlib.sha256(prompt.encode()).hexdigest(),
        "cache_prompt_token_count": len(production_cache_key_token_ids),
        "cache_prompt_token_ids_sha256": token_digest,
        "full_cache_prompt_token_count": len(full_cache_prompt_token_ids),
        "full_cache_prompt_token_ids_sha256": full_token_digest,
        "cache_key_boundary": cache_key_boundary,
        "cache_key_boundary_removed_tokens": max(
            0,
            len(full_cache_prompt_token_ids) - len(production_cache_key_token_ids),
        ),
        "generation_prompt_suffix_tokens": gen_prompt_len,
        "generation_prompt_discriminator_present": cache_extra_keys is not None,
        "generation_prompt_discriminator_sha256": (
            hashlib.sha256(
                cache_extra_keys["generation_prompt"].encode(
                    "utf-8",
                    "surrogatepass",
                )
            ).hexdigest()
            if cache_extra_keys is not None
            else None
        ),
        "prompt_identity_source": (
            "engine_production_helper" if callable(identity_builder) else "server_fallback"
        ),
        "tokenizer_source": tokenizer_source,
        "tokenizer_class": tokenizer_class,
    }, production_cache_key_token_ids, cache_extra_keys


def _cache_prefix_chain_hashes(
    token_ids: list[int],
    block_size: int,
    cache_extra_keys: Any = None,
) -> list[bytes]:
    """Derive the production PagedCache chain for one rendered text prefix."""
    if block_size <= 0:
        raise ValueError("block_size must be positive")
    from .paged_cache import compute_block_hash

    hashes: list[bytes] = []
    parent_hash = None
    reusable_tokens = (len(token_ids) // block_size) * block_size
    for start in range(0, reusable_tokens, block_size):
        parent_hash = compute_block_hash(
            parent_hash,
            token_ids[start : start + block_size],
            extra_keys=cache_extra_keys,
        )
        hashes.append(bytes(parent_hash))
    return hashes


def _cache_prefix_chain_fingerprint(block_hashes: list[bytes]) -> str:
    hasher = hashlib.sha256()
    hasher.update(b"vmlx-cache-prefix-chain-v1\0")
    for block_hash in block_hashes:
        hasher.update(len(block_hash).to_bytes(2, "big"))
        hasher.update(block_hash)
    return hasher.hexdigest()


def _cache_prefix_terminal_fingerprint(block_hashes: list[bytes]) -> str:
    if not block_hashes:
        return ""
    return hashlib.sha256(
        b"vmlx-cache-prefix-terminal-v1\0" + block_hashes[-1]
    ).hexdigest()


class _CachePrefixAttestationBudgetExceeded(ValueError):
    """Raised inside the model executor when a rendered proof exceeds bounds."""


def _cache_prefix_safe_label(value: Any) -> str:
    label = str(value)
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,63}", label):
        raise HTTPException(
            status_code=400,
            detail="cache prefix labels must be 1-64 safe identifier characters",
        )
    return label


def _cache_prefix_l1_snapshot(
    paged_manager: Any,
    block_hashes: list[bytes],
) -> dict[str, Any]:
    """Read path-free L1 metadata/payload state without touching its LRU."""
    rows: list[dict[str, Any]] = []
    lock = getattr(paged_manager, "_lock", None)
    if lock is None:
        raise RuntimeError("paged cache manager has no synchronization lock")
    hash_map = getattr(paged_manager, "cached_block_hash_to_block", None)
    if hash_map is None or not hasattr(hash_map, "get_block"):
        raise RuntimeError("paged cache manager has no chain-hash index")
    with lock:
        for ordinal, block_hash in enumerate(block_hashes):
            block = hash_map.get_block(block_hash)
            metadata_present = bool(
                block is not None
                and bytes(getattr(block, "block_hash", b"") or b"")
                == block_hash
            )
            payload_present = bool(
                metadata_present and getattr(block, "cache_data", None) is not None
            )
            rows.append(
                {
                    "ordinal": ordinal,
                    "metadata_present": metadata_present,
                    "resident_payload_present": payload_present,
                    "resident_bytes": (
                        max(0, int(getattr(block, "resident_bytes", 0) or 0))
                        if payload_present
                        else 0
                    ),
                    "payload_from_disk": bool(
                        payload_present
                        and getattr(block, "cache_data_from_disk", False)
                    ),
                }
            )

    def _contiguous(field: str) -> int:
        count = 0
        for row in rows:
            if row[field] is not True:
                break
            count += 1
        return count

    terminal = rows[-1] if rows else {}
    disk_only = bool(getattr(paged_manager, "disk_only", False))
    return {
        "schema": "vmlx-cache-prefix-l1-snapshot-v1",
        "access_metadata_mutated": False,
        "backend_mode": "block_disk_only" if disk_only else "paged",
        "paged_ram_enabled": not disk_only,
        "disk_only": disk_only,
        "expected_blocks": len(rows),
        "metadata_blocks_present": sum(
            1 for row in rows if row["metadata_present"]
        ),
        "contiguous_metadata_blocks": _contiguous("metadata_present"),
        "resident_payload_blocks_present": sum(
            1 for row in rows if row["resident_payload_present"]
        ),
        "contiguous_resident_payload_blocks": _contiguous(
            "resident_payload_present"
        ),
        "metadata_only_blocks": sum(
            1
            for row in rows
            if row["metadata_present"] and not row["resident_payload_present"]
        ),
        "resident_payload_bytes": sum(
            int(row["resident_bytes"]) for row in rows
        ),
        "payloads_promoted_from_disk": sum(
            1 for row in rows if row["payload_from_disk"]
        ),
        "terminal_metadata_present": bool(
            terminal.get("metadata_present", False)
        ),
        "terminal_resident_payload_present": bool(
            terminal.get("resident_payload_present", False)
        ),
        "terminal_payload_from_disk": bool(
            terminal.get("payload_from_disk", False)
        ),
    }


def _cache_prefix_l2_snapshot(
    disk_store: Any,
    block_hashes: list[bytes],
) -> dict[str, Any]:
    """Aggregate a BlockDiskStore no-touch inspection without exposing hashes."""
    inspect = getattr(disk_store, "inspect_block_chain", None)
    if not callable(inspect):
        raise RuntimeError("block disk store has no read-only chain inspector")
    observed = inspect(block_hashes)
    if (
        not isinstance(observed, dict)
        or observed.get("schema") != "vmlx-block-disk-chain-inspection-v1"
        or observed.get("access_metadata_mutated") is not False
    ):
        raise RuntimeError("block disk store returned an invalid chain inspection")
    rows = observed.get("blocks")
    if not isinstance(rows, list) or len(rows) != len(block_hashes):
        raise RuntimeError("block disk chain inspection is incomplete")
    for ordinal, row in enumerate(rows):
        if not isinstance(row, dict) or row.get("ordinal") != ordinal:
            raise RuntimeError("block disk chain inspection order is invalid")

    def _contiguous(field: str) -> int:
        count = 0
        for row in rows:
            if row.get(field) is not True:
                break
            count += 1
        return count

    indexed_rows = [row for row in rows if row.get("indexed") is True]
    readable_rows = [row for row in rows if row.get("readable") is True]
    access_times = [
        max(0, int(row.get("last_accessed_ns") or 0))
        for row in readable_rows
        if int(row.get("last_accessed_ns") or 0) > 0
    ]
    terminal = rows[-1] if rows else {}
    return {
        "schema": "vmlx-cache-prefix-l2-snapshot-v1",
        "access_metadata_mutated": False,
        "expected_blocks": len(rows),
        "indexed_blocks": len(indexed_rows),
        "readable_blocks": len(readable_rows),
        "contiguous_indexed_blocks": _contiguous("indexed"),
        "contiguous_readable_blocks": _contiguous("readable"),
        "stale_index_blocks": sum(
            1
            for row in rows
            if row.get("indexed") is True and row.get("readable") is not True
        ),
        "matched_file_size_bytes": sum(
            max(0, int(row.get("file_size_bytes") or 0))
            for row in readable_rows
        ),
        "total_access_count": sum(
            max(0, int(row.get("access_count") or 0))
            for row in readable_rows
        ),
        "oldest_last_accessed_ns": min(access_times) if access_times else 0,
        "newest_last_accessed_ns": max(access_times) if access_times else 0,
        "terminal_indexed": bool(terminal.get("indexed", False)),
        "terminal_readable": bool(terminal.get("readable", False)),
        "terminal_num_tokens": max(
            0,
            int(terminal.get("num_tokens") or 0),
        ),
        "terminal_last_accessed_ns": max(
            0,
            int(terminal.get("last_accessed_ns") or 0),
        ),
        "terminal_access_count": max(
            0,
            int(terminal.get("access_count") or 0),
        ),
        "store_total_entries": max(
            0,
            int(observed.get("store_total_entries") or 0),
        ),
        "store_total_size_bytes": max(
            0,
            int(observed.get("store_total_size_bytes") or 0),
        ),
        "store_max_size_bytes": max(
            0,
            int(observed.get("store_max_size_bytes") or 0),
        ),
    }


@app.post(
    "/v1/cache/prefix-attestation",
    dependencies=[Depends(verify_private_cache_attestation)],
    include_in_schema=False,
)
async def cache_prefix_attestation(request: dict):
    """Return a read-only, path-free identity/state attestation for prompt pairs.

    Each named pair is dry-rendered through the loaded Responses path.  Only
    the longest block-aligned shared prefix is inspected, matching the paged
    chain-hash lookup contract.  Raw prompts and token IDs remain request-local;
    the response contains only SHA-256 fingerprints, counts, and timestamps.
    """
    if _engine is None:
        raise HTTPException(status_code=409, detail="model is not loaded")
    if not isinstance(request, dict):
        raise HTTPException(status_code=400, detail="request body must be an object")
    initial_controls = request.get("request_controls")
    _cache_contract_reject_side_keys(
        request,
        initial_controls if isinstance(initial_controls, dict) else {},
    )
    allowed_request_fields = {
        "contract_version",
        "surface",
        "model",
        "inputs",
        "prefix_pairs",
        "request_controls",
        "touch",
    }
    unknown_request_fields = sorted(set(request) - allowed_request_fields)
    if unknown_request_fields:
        raise HTTPException(
            status_code=400,
            detail="prefix attestation request contains unsupported fields",
        )
    if request.get("contract_version") != 1:
        raise HTTPException(status_code=400, detail="contract_version must be 1")
    if request.get("surface") != "responses":
        raise HTTPException(status_code=400, detail="surface must be responses")
    if request.get("touch") not in (None, False):
        raise HTTPException(
            status_code=400,
            detail="prefix attestation is read-only; use a real cache hit to touch LRU",
        )
    inputs = request.get("inputs")
    if (
        not isinstance(inputs, dict)
        or not 2 <= len(inputs) <= _PRIVATE_CACHE_ATTESTATION_MAX_INPUTS
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "inputs must contain between 2 and "
                f"{_PRIVATE_CACHE_ATTESTATION_MAX_INPUTS} named prompts"
            ),
        )
    normalized_inputs: dict[str, str] = {}
    total_prompt_bytes = 0
    for raw_label, prompt in inputs.items():
        label = _cache_prefix_safe_label(raw_label)
        if label in normalized_inputs:
            raise HTTPException(
                status_code=400,
                detail="input labels must be unique after normalization",
            )
        if not isinstance(prompt, str):
            raise HTTPException(
                status_code=400,
                detail="inputs values must be strings",
            )
        prompt_bytes = len(prompt.encode("utf-8", "surrogatepass"))
        if prompt_bytes > _PRIVATE_CACHE_ATTESTATION_MAX_PROMPT_BYTES:
            raise HTTPException(
                status_code=413,
                detail="one prefix attestation prompt exceeds the byte budget",
            )
        total_prompt_bytes += prompt_bytes
        if total_prompt_bytes > _PRIVATE_CACHE_ATTESTATION_MAX_TOTAL_PROMPT_BYTES:
            raise HTTPException(
                status_code=413,
                detail="prefix attestation prompts exceed the aggregate byte budget",
            )
        normalized_inputs[label] = prompt
    inputs = normalized_inputs
    prefix_pairs = request.get("prefix_pairs")
    if (
        not isinstance(prefix_pairs, dict)
        or not 1 <= len(prefix_pairs) <= _PRIVATE_CACHE_ATTESTATION_MAX_PAIRS
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "prefix_pairs must contain between 1 and "
                f"{_PRIVATE_CACHE_ATTESTATION_MAX_PAIRS} pairs"
            ),
        )
    normalized_pairs: dict[str, tuple[str, str]] = {}
    for pair_name, labels in prefix_pairs.items():
        normalized_name = _cache_prefix_safe_label(pair_name)
        if normalized_name in normalized_pairs:
            raise HTTPException(
                status_code=400,
                detail="prefix pair names must be unique after normalization",
            )
        if (
            not normalized_name
            or not isinstance(labels, list)
            or len(labels) != 2
            or any(not isinstance(label, str) for label in labels)
            or labels[0] == labels[1]
            or any(label not in inputs for label in labels)
        ):
            raise HTTPException(
                status_code=400,
                detail=f"prefix pair {normalized_name!r} is invalid",
            )
        normalized_pairs[normalized_name] = (labels[0], labels[1])
    model = str(request.get("model") or _model_name or "")
    if not model:
        raise HTTPException(status_code=400, detail="model is required")
    if len(model.encode("utf-8", "surrogatepass")) > 1024:
        raise HTTPException(status_code=413, detail="model identifier is too large")
    request_controls = request.get("request_controls") or {}
    if not isinstance(request_controls, dict):
        raise HTTPException(
            status_code=400,
            detail="request_controls must be an object when provided",
        )
    allowed_control_fields = {
        "enable_thinking",
        "instructions",
        "tools",
        "tool_choice",
        "chat_template_kwargs",
    }
    if set(request_controls) - allowed_control_fields:
        raise HTTPException(
            status_code=400,
            detail="request_controls contains unsupported fields",
        )
    _cache_contract_reject_side_keys(request, request_controls)
    try:
        request_controls_bytes = len(
            json.dumps(
                request_controls,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                allow_nan=False,
            ).encode("utf-8")
        )
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=400,
            detail="request_controls must contain JSON-compatible values",
        ) from exc
    if (
        request_controls_bytes
        > _PRIVATE_CACHE_ATTESTATION_MAX_REQUEST_CONTROLS_BYTES
    ):
        raise HTTPException(
            status_code=413,
            detail="request_controls exceeds the private proof byte budget",
        )

    scheduler = _get_scheduler()
    paged_manager = (
        getattr(scheduler, "paged_cache_manager", None)
        if scheduler is not None
        else None
    )
    disk_store = (
        getattr(paged_manager, "_disk_store", None)
        if paged_manager is not None
        else None
    )
    block_size = (
        int(getattr(paged_manager, "block_size", 0) or 0)
        if paged_manager is not None
        else 0
    )
    if paged_manager is None or disk_store is None or block_size <= 0:
        raise HTTPException(
            status_code=409,
            detail="paged prefix metadata and block-disk L2 must be active",
        )

    health_snapshot = await health()
    model_bundle_provenance = health_snapshot.get("model_bundle_provenance")
    if not isinstance(model_bundle_provenance, dict):
        model_bundle_provenance = (
            health_snapshot.get("runtime_provenance", {}) or {}
        ).get("model_bundle_provenance")
    cache_topology_provenance = health_snapshot.get("cache_topology_provenance")
    if not isinstance(cache_topology_provenance, dict):
        cache_topology_provenance = (
            health_snapshot.get("runtime_provenance", {}) or {}
        ).get("cache_topology_provenance")
    if not isinstance(model_bundle_provenance, dict) or not isinstance(
        cache_topology_provenance,
        dict,
    ):
        raise HTTPException(
            status_code=503,
            detail="health provenance attestations are unavailable",
        )

    def _build_attestation():
        prompt_rows: dict[str, dict[str, Any]] = {}
        prompt_vectors: dict[str, list[int]] = {}
        prompt_cache_extra_keys: dict[str, dict[str, str] | None] = {}
        total_rendered_tokens = 0
        for label in sorted(inputs):
            row, token_vector, cache_extra_keys = _cache_contract_render_and_tokenize(
                engine=_engine,
                prompt=inputs[label],
                model=model,
                request_controls=request_controls,
            )
            rendered_tokens = len(token_vector) + max(
                0,
                int(row.get("generation_prompt_suffix_tokens") or 0),
            )
            if rendered_tokens > _PRIVATE_CACHE_ATTESTATION_MAX_TOKENS_PER_PROMPT:
                raise _CachePrefixAttestationBudgetExceeded(
                    "one rendered prefix attestation prompt exceeds its token budget"
                )
            total_rendered_tokens += rendered_tokens
            if total_rendered_tokens > _PRIVATE_CACHE_ATTESTATION_MAX_TOTAL_TOKENS:
                raise _CachePrefixAttestationBudgetExceeded(
                    "rendered prefix attestation prompts exceed the token budget"
                )
            prompt_rows[str(label)] = row
            prompt_vectors[str(label)] = token_vector
            prompt_cache_extra_keys[str(label)] = cache_extra_keys

        prefix_rows: dict[str, dict[str, Any]] = {}
        total_pair_prefix_tokens = 0
        for pair_name in sorted(normalized_pairs):
            left_label, right_label = normalized_pairs[pair_name]
            left = prompt_vectors[left_label]
            right = prompt_vectors[right_label]
            left_cache_extra_keys = prompt_cache_extra_keys[left_label]
            right_cache_extra_keys = prompt_cache_extra_keys[right_label]
            if left_cache_extra_keys != right_cache_extra_keys:
                raise ValueError(
                    f"prefix pair {pair_name!r} has different production "
                    "generation-prompt discriminators"
                )
            lcp_tokens = _cache_contract_lcp(left, right)
            reusable_tokens = (lcp_tokens // block_size) * block_size
            total_pair_prefix_tokens += reusable_tokens
            if (
                total_pair_prefix_tokens
                > _PRIVATE_CACHE_ATTESTATION_MAX_PAIR_PREFIX_TOKENS
            ):
                raise _CachePrefixAttestationBudgetExceeded(
                    "prefix attestation pairs exceed the comparison token budget"
                )
            prefix_vector = left[:reusable_tokens]
            block_hashes = _cache_prefix_chain_hashes(
                prefix_vector,
                block_size,
                cache_extra_keys=left_cache_extra_keys,
            )
            prefix_rows[pair_name] = {
                "labels": [left_label, right_label],
                "longest_common_prefix_tokens": lcp_tokens,
                "reusable_prefix_tokens": reusable_tokens,
                "uncached_left_tokens": len(left) - reusable_tokens,
                "uncached_right_tokens": len(right) - reusable_tokens,
                "expected_blocks": len(block_hashes),
                "prefix_token_vector_sha256": hashlib.sha256(
                    json.dumps(
                        prefix_vector,
                        separators=(",", ":"),
                        ensure_ascii=True,
                    ).encode()
                ).hexdigest(),
                "block_chain_fingerprint_sha256": (
                    _cache_prefix_chain_fingerprint(block_hashes)
                ),
                "terminal_block_fingerprint_sha256": (
                    _cache_prefix_terminal_fingerprint(block_hashes)
                ),
                "generation_prompt_discriminator_present": (
                    left_cache_extra_keys is not None
                ),
                "generation_prompt_discriminator_sha256": prompt_rows[
                    left_label
                ].get("generation_prompt_discriminator_sha256"),
                "l1": _cache_prefix_l1_snapshot(
                    paged_manager,
                    block_hashes,
                ),
                "l2": _cache_prefix_l2_snapshot(
                    disk_store,
                    block_hashes,
                ),
            }
        return prompt_rows, prefix_rows

    try:
        prompt_rows, prefix_rows = await _run_on_model_executor(
            _build_attestation
        )
    except _CachePrefixAttestationBudgetExceeded as exc:
        raise HTTPException(status_code=413, detail=str(exc)) from exc
    except (RuntimeError, TypeError, ValueError) as exc:
        logger.warning("Cache prefix attestation failed: %s", exc)
        raise HTTPException(
            status_code=503,
            detail="cache prefix attestation unavailable",
        ) from exc

    return {
        "contract_version": 1,
        "method": "final-render-tokenize-cache-prefix-identity-readonly",
        "surface": "responses",
        "cache_extra_keys_contract": "generation-prompt-only-text-render-v1",
        "caller_cache_or_media_side_keys": "rejected",
        "cache_lookup_bypassed": True,
        "access_metadata_mutated": False,
        "request_sha256": _cache_token_contract_request_sha256(request),
        "model_bundle_fingerprint_sha256": str(
            model_bundle_provenance.get("fingerprint_sha256")
            or model_bundle_provenance.get("aggregate_sha256")
            or ""
        ),
        "cache_topology_fingerprint_sha256": str(
            cache_topology_provenance.get("fingerprint_sha256")
            or cache_topology_provenance.get("canonical_sha256")
            or ""
        ),
        "block_size": block_size,
        "snapshot_wall_time_ns": time.time_ns(),
        "prompts": prompt_rows,
        "prefixes": prefix_rows,
    }


@app.post(
    "/v1/cache/token-contract",
    dependencies=[Depends(verify_private_cache_attestation)],
    include_in_schema=False,
)
async def cache_token_contract(request: dict):
    """Return path-free final-render token/LCP attestations for cache gates."""
    if _engine is None:
        raise HTTPException(status_code=409, detail="model is not loaded")
    if not isinstance(request, dict):
        raise HTTPException(status_code=400, detail="request body must be an object")
    initial_controls = request.get("request_controls")
    _cache_contract_reject_side_keys(
        request,
        initial_controls if isinstance(initial_controls, dict) else {},
    )
    allowed_request_fields = {
        "contract_version",
        "surface",
        "model",
        "inputs",
        "request_controls",
    }
    if set(request) - allowed_request_fields:
        raise HTTPException(
            status_code=400,
            detail="cache token contract contains unsupported fields",
        )
    if request.get("contract_version") != 1:
        raise HTTPException(status_code=400, detail="contract_version must be 1")
    if request.get("surface") != "responses":
        raise HTTPException(status_code=400, detail="surface must be responses")
    inputs = request.get("inputs")
    if (
        not isinstance(inputs, dict)
        or not 1 <= len(inputs) <= _PRIVATE_CACHE_ATTESTATION_MAX_INPUTS
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "inputs must contain between 1 and "
                f"{_PRIVATE_CACHE_ATTESTATION_MAX_INPUTS} named prompts"
            ),
        )
    normalized_inputs: dict[str, str] = {}
    total_prompt_bytes = 0
    for raw_label, prompt in inputs.items():
        label = _cache_prefix_safe_label(raw_label)
        if label in normalized_inputs:
            raise HTTPException(
                status_code=400,
                detail="input labels must be unique after normalization",
            )
        if not isinstance(prompt, str):
            raise HTTPException(
                status_code=400,
                detail="inputs values must be strings",
            )
        prompt_bytes = len(prompt.encode("utf-8", "surrogatepass"))
        if prompt_bytes > _PRIVATE_CACHE_ATTESTATION_MAX_PROMPT_BYTES:
            raise HTTPException(
                status_code=413,
                detail="one cache token-contract prompt exceeds the byte budget",
            )
        total_prompt_bytes += prompt_bytes
        if total_prompt_bytes > _PRIVATE_CACHE_ATTESTATION_MAX_TOTAL_PROMPT_BYTES:
            raise HTTPException(
                status_code=413,
                detail="cache token-contract prompts exceed the byte budget",
            )
        normalized_inputs[label] = prompt
    inputs = normalized_inputs
    model = str(request.get("model") or _model_name or "")
    if not model:
        raise HTTPException(status_code=400, detail="model is required")
    if len(model.encode("utf-8", "surrogatepass")) > 1024:
        raise HTTPException(status_code=413, detail="model identifier is too large")
    request_controls = request.get("request_controls") or {}
    if not isinstance(request_controls, dict):
        raise HTTPException(
            status_code=400,
            detail="request_controls must be an object when provided",
        )
    allowed_control_fields = {
        "enable_thinking",
        "instructions",
        "tools",
        "tool_choice",
        "chat_template_kwargs",
    }
    if set(request_controls) - allowed_control_fields:
        raise HTTPException(
            status_code=400,
            detail="request_controls contains unsupported fields",
        )
    _cache_contract_reject_side_keys(request, request_controls)
    try:
        request_controls_bytes = len(
            json.dumps(
                request_controls,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                allow_nan=False,
            ).encode("utf-8")
        )
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=400,
            detail="request_controls must contain JSON-compatible values",
        ) from exc
    if (
        request_controls_bytes
        > _PRIVATE_CACHE_ATTESTATION_MAX_REQUEST_CONTROLS_BYTES
    ):
        raise HTTPException(
            status_code=413,
            detail="request_controls exceeds the private proof byte budget",
        )

    health_snapshot = await health()
    model_bundle_provenance = health_snapshot.get("model_bundle_provenance")
    if not isinstance(model_bundle_provenance, dict):
        model_bundle_provenance = (
            health_snapshot.get("runtime_provenance", {}) or {}
        ).get("model_bundle_provenance")
    cache_topology_provenance = health_snapshot.get("cache_topology_provenance")
    if not isinstance(cache_topology_provenance, dict):
        cache_topology_provenance = (
            health_snapshot.get("runtime_provenance", {}) or {}
        ).get("cache_topology_provenance")
    if not isinstance(model_bundle_provenance, dict) or not isinstance(
        cache_topology_provenance,
        dict,
    ):
        raise HTTPException(
            status_code=503,
            detail="health provenance attestations are unavailable",
        )

    def _build_contract():
        prompt_rows: dict[str, dict[str, Any]] = {}
        prompt_token_vectors: dict[str, list[int]] = {}
        total_rendered_tokens = 0
        for label in sorted(inputs):
            prompt = inputs[label]
            row, token_vector, _cache_extra_keys = (
                _cache_contract_render_and_tokenize(
                    engine=_engine,
                    prompt=prompt,
                    model=model,
                    request_controls=request_controls,
                )
            )
            rendered_tokens = len(token_vector) + max(
                0,
                int(row.get("generation_prompt_suffix_tokens") or 0),
            )
            if rendered_tokens > _PRIVATE_CACHE_ATTESTATION_MAX_TOKENS_PER_PROMPT:
                raise _CachePrefixAttestationBudgetExceeded(
                    "one rendered cache token-contract prompt exceeds its token budget"
                )
            total_rendered_tokens += rendered_tokens
            if total_rendered_tokens > _PRIVATE_CACHE_ATTESTATION_MAX_TOTAL_TOKENS:
                raise _CachePrefixAttestationBudgetExceeded(
                    "rendered cache token-contract prompts exceed the token budget"
                )
            prompt_rows[str(label)] = row
            prompt_token_vectors[str(label)] = token_vector
        lcp_rows: dict[str, int] = {}
        total_pair_prefix_tokens = 0
        for left in sorted(prompt_token_vectors):
            for right in sorted(prompt_token_vectors):
                lcp_tokens = _cache_contract_lcp(
                    prompt_token_vectors[left],
                    prompt_token_vectors[right],
                )
                total_pair_prefix_tokens += lcp_tokens
                if (
                    total_pair_prefix_tokens
                    > _PRIVATE_CACHE_ATTESTATION_MAX_PAIR_PREFIX_TOKENS
                ):
                    raise _CachePrefixAttestationBudgetExceeded(
                        "cache token-contract comparisons exceed the token budget"
                    )
                lcp_rows[f"{left}:{right}"] = lcp_tokens
        return prompt_rows, lcp_rows

    try:
        prompt_rows, lcp_rows = await _run_on_model_executor(_build_contract)
    except _CachePrefixAttestationBudgetExceeded as exc:
        raise HTTPException(status_code=413, detail=str(exc)) from exc
    bundle_fingerprint = str(
        model_bundle_provenance.get("fingerprint_sha256")
        or model_bundle_provenance.get("aggregate_sha256")
        or ""
    )
    cache_fingerprint = str(
        cache_topology_provenance.get("fingerprint_sha256")
        or cache_topology_provenance.get("canonical_sha256")
        or ""
    )
    return {
        "contract_version": 1,
        "method": "final-render-tokenize-no-cache",
        "surface": "responses",
        "cache_lookup_bypassed": True,
        "request_sha256": _cache_token_contract_request_sha256(request),
        "model_bundle_fingerprint_sha256": bundle_fingerprint,
        "cache_topology_fingerprint_sha256": cache_fingerprint,
        "prompts": prompt_rows,
        "longest_common_prefix_tokens": lcp_rows,
    }


@app.delete("/v1/cache", dependencies=[Depends(verify_api_key)])
async def clear_cache(
    cache_type: str = Query("all", alias="type"),
    expected_root: str | None = None,
    expected_pid: int | None = None,
):
    """
    Clear caches.

    Query params:
        type: "ram" | "prefix" | "multimodal" | "all" | "ssd_pool"

        ``ram`` drops only resident/indexed prefix state and preserves every
        disk-backed L2 store. ``prefix`` clears both RAM prefix state and its
        prompt/block/SSM disk companions. Keeping these operations distinct is
        important for validating and operating restart/L2 restore paths.
    """
    if cache_type == "ssd_pool":
        import sqlite3

        # Do not use cached /health data as an idle assertion. This synchronous
        # handler does not yield to new ASGI admissions before the operation.
        scheduler = _get_scheduler()
        if _engine is None or scheduler is None:
            raise HTTPException(status_code=409, detail="SSD cache engine is unavailable")
        lifecycle = _request_lifecycle_health_snapshot(
            _engine.get_stats(), scheduler.get_stats()
        )
        if (lifecycle.get("available") is not True
                or lifecycle.get("active_request_count") != 0
                or lifecycle.get("terminal_cleanup_pending") is not False):
            raise HTTPException(status_code=409, detail="Wait for requests and cache persistence to finish before clearing SSD cache")
        manager = getattr(scheduler, "paged_cache_manager", None)
        store = getattr(manager, "_disk_store", None)
        budget = getattr(store, "global_budget", None)
        if budget is None:
            raise HTTPException(status_code=409, detail="No managed SSD pool is available")
        if expected_pid != os.getpid() or expected_root != str(budget.root):
            raise HTTPException(status_code=409, detail="SSD pool or engine identity changed; refresh before clearing")
        try:
            result = budget.clear_eligible()
        except BlockingIOError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        except (OSError, sqlite3.Error) as exc:
            logger.exception("SSD pool clear could not finish")
            raise HTTPException(status_code=503, detail="SSD clear did not finish; refresh cache status before retrying") from exc
        block_cache = getattr(scheduler, "block_aware_cache", None)
        retired_hints = (
            block_cache.retire_missing_disk_hints()
            if block_cache is not None else 0
        )
        return {
            "status": "eligible_cleared", "cache_type": cache_type,
            "root": str(budget.root), "freed_bytes": result.evicted_bytes,
            "removed_entries": result.evicted_entries,
            "remaining_bytes": result.bytes_after,
            "effective_cap_bytes": result.max_size_bytes,
            "protected_temp_files": result.protected_temp_files,
            "protected_recent_orphans": result.protected_recent_orphans,
            "resident_cache_preserved": True,
            "retired_disk_hints": retired_hints,
        }

    cleared = []
    # Tiers that were deliberately NOT cleared, so the caller can tell "nothing
    # to do" apart from "refused because it was busy" instead of being told the
    # cache is gone when it is not.
    skipped: list[str] = []

    clear_resident_prefix = cache_type in ("ram", "prefix", "all")
    clear_prefix_l2 = cache_type in ("prefix", "all")

    # Clear resident prefix cache. The underlying PagedCacheManager.clear()
    # resets its RAM block pool but deliberately leaves _disk_store intact.
    if clear_resident_prefix:
        scheduler = _get_scheduler()
        if scheduler is not None:
            if getattr(scheduler, "memory_aware_cache", None) is not None:
                scheduler.memory_aware_cache.clear()
                cleared.append("memory_aware_prefix")
            if getattr(scheduler, "block_aware_cache", None) is not None:
                # Unforced: this endpoint is reachable mid-generation (async
                # handler, no idle gate), and rebuilding the pool under a live
                # request recycles its block ids into another request's table.
                if scheduler.block_aware_cache.clear():
                    cleared.append("paged_prefix")
                else:
                    skipped.append("paged_prefix:blocks_in_use")
            if getattr(scheduler, "prefix_cache", None) is not None:
                scheduler.prefix_cache.clear()
                cleared.append("legacy_prefix")
            if clear_prefix_l2 and getattr(scheduler, "disk_cache", None) is not None:
                scheduler.disk_cache.clear()
                cleared.append("disk_cache")
            # Also clear L2 paged block disk store (separate from legacy disk_cache)
            paged_mgr = getattr(scheduler, "paged_cache_manager", None)
            if clear_prefix_l2 and paged_mgr is not None:
                disk_store = getattr(paged_mgr, "_disk_store", None)
                if disk_store is not None:
                    disk_store.clear()
                    cleared.append("block_disk_store")
            # Hybrid SSM state is a prefix-cache companion with its own
            # bounded resident L1 and nested disk L2. Clearing only KV/paged
            # stores leaves SSM entries reusable after the UI says "Clear All".
            ssm_caches = []
            scheduler_ssm = getattr(scheduler, "_ssm_state_cache", None)
            generator = getattr(scheduler, "batch_generator", None)
            generator_ssm = getattr(generator, "_ssm_state_cache", None)
            for candidate in (scheduler_ssm, generator_ssm):
                if candidate is not None and all(
                    candidate is not existing for existing in ssm_caches
                ):
                    ssm_caches.append(candidate)
            ssm_disks = []
            if clear_prefix_l2:
                scheduler_ssm_disk = getattr(
                    scheduler, "_ssm_companion_disk_store", None
                )
                if scheduler_ssm_disk is not None:
                    ssm_disks.append(scheduler_ssm_disk)
            ssm_l1_cleared = False
            ssm_l2_cleared = False
            for ssm_cache in ssm_caches:
                clear_ssm = getattr(ssm_cache, "clear", None)
                if callable(clear_ssm):
                    clear_ssm()
                    ssm_l1_cleared = True
                if clear_prefix_l2:
                    ssm_disk = getattr(ssm_cache, "_disk", None)
                    if ssm_disk is not None and all(
                        ssm_disk is not existing for existing in ssm_disks
                    ):
                        ssm_disks.append(ssm_disk)
            for ssm_disk in ssm_disks:
                clear_ssm_disk = getattr(ssm_disk, "clear", None)
                if callable(clear_ssm_disk):
                    clear_ssm_disk()
                    ssm_l2_cleared = True
            if ssm_l1_cleared:
                cleared.append("ssm_companion")
            if ssm_l2_cleared:
                cleared.append("ssm_companion_disk")
            try:
                import gc as _gc

                _gc.collect()
                if clear_mlx_memory_cache(log=logger):
                    cleared.append("mlx_cache")
            except Exception:
                pass

    # Clear multimodal caches
    if cache_type in ("multimodal", "all"):
        try:
            from mlx_vlm.utils import (
                clear_multimodal_kv_cache,
                clear_pixel_values_cache,
            )

            clear_multimodal_kv_cache()
            clear_pixel_values_cache()
            cleared.append("multimodal_kv")
            cleared.append("pixel_values")
        except ImportError:
            pass

    if not cleared:
        if skipped:
            return {
                "status": "busy",
                "cache_type": cache_type,
                "skipped": skipped,
                "detail": "cache tiers are in use by live requests; retry when idle",
            }
        return {"status": "no_caches_found", "cache_type": cache_type}
    result = {"status": "cleared", "caches": cleared, "cache_type": cache_type}
    if skipped:
        result["skipped"] = skipped
    return result


# ── Distributed Cluster Endpoints ──


@app.get("/v1/cluster/status", dependencies=[Depends(verify_api_key)])
async def cluster_status():
    """Get distributed cluster status."""
    if not _distributed_enabled or not _distributed_coordinator:
        return {"enabled": False}
    return {
        "enabled": True,
        **_distributed_coordinator.status,
    }


@app.get("/v1/cluster/nodes", dependencies=[Depends(verify_api_key)])
async def cluster_nodes():
    """Get list of nodes in the distributed mesh."""
    if not _distributed_enabled or not _distributed_coordinator:
        return {"nodes": []}

    nodes = []
    for peer in _distributed_coordinator.topology.peers.values():
        node_info = {
            "node_id": peer.node_id,
            "hostname": peer.hostname,
            "address": peer.address,
            "port": peer.port,
            "chip": peer.chip,
            "ram_gb": peer.ram_gb,
            "gpu_cores": peer.gpu_cores,
            "available_gb": peer.available_gb,
            "capability_score": peer.capability_score,
            "state": peer.state,
            "is_coordinator": peer.is_coordinator,
            "assigned_layers": peer.assigned_layers,
            "is_alive": peer.is_alive,
        }
        # Add link info if available
        local_id = _distributed_coordinator.node.node_id
        link = _distributed_coordinator.topology.get_link(local_id, peer.node_id)
        if link:
            node_info["link_type"] = link.link_type.value
            node_info["bandwidth_mbps"] = link.bandwidth_mbps
            node_info["latency_ms"] = link.latency_ms
        nodes.append(node_info)

    return {"nodes": nodes}


@app.post("/v1/cluster/nodes", dependencies=[Depends(verify_api_key)])
async def cluster_add_node(request: dict):
    """Add a worker node manually by IP:port."""
    if not _distributed_enabled or not _distributed_coordinator:
        raise HTTPException(status_code=400, detail="Distributed mode not enabled")

    address = request.get("address")
    port = request.get("port", 9100)
    if not address:
        raise HTTPException(status_code=400, detail="address is required")

    coord = _distributed_coordinator.coordinator
    if not coord:
        raise HTTPException(status_code=400, detail="This node is not the coordinator")

    node = await coord.add_node_manual(address, port)
    if node:
        return {"success": True, "node": node.to_dict()}
    raise HTTPException(status_code=502, detail=f"Failed to connect to worker at {address}:{port}")


@app.delete("/v1/cluster/nodes/{node_id}", dependencies=[Depends(verify_api_key)])
async def cluster_remove_node(node_id: str):
    """Remove a node from the mesh."""
    if not _distributed_enabled or not _distributed_coordinator:
        raise HTTPException(status_code=400, detail="Distributed mode not enabled")

    coord = _distributed_coordinator.coordinator
    if coord and node_id in coord.workers:
        wc = coord.workers[node_id]
        await wc.disconnect()
        del coord.workers[node_id]
    _distributed_coordinator.topology.remove_peer(node_id)
    return {"success": True}


@app.post("/v1/cluster/scan", dependencies=[Depends(verify_api_key)])
async def cluster_scan():
    """Trigger node discovery scan."""
    if not _distributed_enabled or not _distributed_coordinator:
        raise HTTPException(status_code=400, detail="Distributed mode not enabled")

    coord = _distributed_coordinator.coordinator
    if not coord:
        raise HTTPException(status_code=400, detail="This node is not the coordinator")

    discovered = await coord.discover_nodes(timeout=5.0)
    nodes = [n.to_dict() for n in discovered]
    return {"nodes": nodes, "count": len(nodes)}


@app.post(
    "/v1/chat/completions/{request_id}/cancel", dependencies=[Depends(verify_api_key)]
)
async def cancel_chat_completion(request_id: str):
    """
    Cancel an ongoing chat completion request.

    Stops token generation immediately and marks the request as aborted.
    Any tokens generated so far are preserved in the partial response.

    Args:
        request_id: The request ID from the response (e.g., chatcmpl-abc123)

    Returns:
        Success message or 404 if request not found

    Example:
        ```bash
        curl -X POST http://localhost:8092/v1/chat/completions/chatcmpl-abc123/cancel \\
          -H "Authorization: Bearer your-api-key"
        ```
    """
    if _engine is None:
        raise HTTPException(
            status_code=404, detail="No model loaded — no active requests to cancel"
        )

    # Abort the request (returns True if found, False if not found/already finished)
    success = await _engine.abort_request(request_id)

    if success:
        logger.info(f"Request {request_id} cancelled via API")
        return {"success": True, "message": f"Request {request_id} cancelled"}
    else:
        raise HTTPException(
            status_code=404,
            detail=f"Request {request_id} not found or already finished",
        )


