@app.post(
    "/v1/completions",
    dependencies=[
        Depends(verify_api_key),
        Depends(check_rate_limit),
        Depends(check_memory_pressure),  # mlxstudio#63
        Depends(check_metal_working_set_pressure),  # mlxstudio#78
    ],
)
async def create_completion(request: CompletionRequest):
    """Create a text completion."""
    engine = get_engine()
    _reject_unsupported_logprobs_request(
        endpoint="Completions",
        requested=request.logprobs is not None,
        stream=bool(request.stream),
        is_mllm=bool(getattr(engine, "is_mllm", False)),
    )

    # Normalize model name (consistent with chat/responses endpoints)
    resolved_name = _resolve_model_name()
    request.model = resolved_name

    # Handle single prompt or list of prompts
    prompts = request.prompt if isinstance(request.prompt, list) else [request.prompt]

    _completion_max_prompt_tokens = _effective_max_prompt_tokens(request)

    if request.stream:
        return StreamingResponse(
            stream_completions_multi(engine, prompts, request),
            media_type="text/event-stream",
        )

    # Non-streaming response with timing and timeout
    start_time = time.perf_counter()
    timeout = request.timeout if request.timeout is not None else _default_timeout
    choices = []
    total_completion_tokens = 0
    total_prompt_tokens = 0
    total_cached_tokens = 0
    cache_detail: str | None = None

    for i, prompt in enumerate(prompts):
        try:
            gen_kwargs = {
                "prompt": prompt,
                "max_tokens": _resolve_max_tokens(request.max_tokens, getattr(request, "model", "")),
                "temperature": _resolve_temperature(request.temperature, request.model),
                "top_p": _resolve_top_p(request.top_p, request.model),
                "stop": request.stop,
                "max_prompt_tokens": _completion_max_prompt_tokens,
            }
            if request.seed is not None:
                gen_kwargs["seed"] = request.seed
            _set_resolved_top_k(gen_kwargs, request.top_k, request.model)
            _normalize_deterministic_sampling_filters(
                gen_kwargs,
                request_top_p=request.top_p,
                request_top_k=request.top_k,
            )
            _set_resolved_min_p(gen_kwargs, request.min_p, request.model)
            _rp = _resolve_repetition_penalty(request.repetition_penalty, request.model)
            if _rp is not None:
                gen_kwargs["repetition_penalty"] = _rp
            _forward_openai_token_controls(gen_kwargs, request)
            if _compute_bypass_prefix_cache(request):
                gen_kwargs["_bypass_prefix_cache"] = True
            if request.logprobs is not None:
                gen_kwargs["logprobs"] = True
                gen_kwargs["top_logprobs"] = request.logprobs
            if request.reasoning_effort is not None:
                gen_kwargs["reasoning_effort"] = request.reasoning_effort
            if request.enable_thinking is not None:
                gen_kwargs["enable_thinking"] = request.enable_thinking
            if _is_loaded_dsv4_model(request.model):
                chat_prompt = _dsv4_completion_prompt_for_chat_rail(prompt, request)
                chat_kwargs = {
                    key: value
                    for key, value in gen_kwargs.items()
                    if key != "prompt"
                }
                chat_kwargs["max_tokens"] = _dsv4_completion_internal_max_tokens(
                    chat_kwargs["max_tokens"],
                    request,
                )
                decision = _resolve_dsv4_thinking_policy(
                    requested_enable_thinking=True,
                    effort_requested=False,
                    tools_present=False,
                    tool_choice=None,
                    default_mode=_jang_chat_default_mode(
                        _model_path or _model_name or request.model or ""
                    ),
                )
                chat_kwargs["enable_thinking"] = decision.enable_thinking
                _set_resolved_repetition_penalty(
                    chat_kwargs,
                    request.repetition_penalty,
                    request.model,
                    enable_thinking=decision.enable_thinking,
                )
                output = await asyncio.wait_for(
                    engine.chat(
                        messages=[{"role": "user", "content": chat_prompt}],
                        **chat_kwargs,
                    ),
                    timeout=timeout,
                )
            elif _is_loaded_mimo_v2_model(request.model) or bool(
                getattr(engine, "is_mllm", False)
                or getattr(engine, "_is_mllm", False)
            ):
                # Loaded MLLM (any modality/quant): the raw /v1/completions
                # rail feeds engine.generate() an unframed string, but the
                # MLLM text-only preprocessor tokenizes with
                # add_special_tokens=False on the contract that the prompt
                # already passed through apply_chat_template(). Raw completion
                # violates that -> no BOS / no instruct turn framing ->
                # malformed prefill -> constant-token degeneration (W1-3).
                # Wrap the completion string as one user message so the
                # engine's native chat template builds valid input, exactly
                # as the DSV4 and MiMo-V2 completion rails already do.
                chat_kwargs = _completion_gen_kwargs_to_chat_kwargs(
                    gen_kwargs,
                    bundle_path=_model_path or _model_name or request.model or "",
                )
                output = await asyncio.wait_for(
                    engine.chat(
                        messages=[{"role": "user", "content": prompt}],
                        **chat_kwargs,
                    ),
                    timeout=timeout,
                )
            else:
                output = await asyncio.wait_for(
                    engine.generate(**gen_kwargs),
                    timeout=timeout,
                )
        except asyncio.TimeoutError:
            raise HTTPException(
                status_code=504, detail=f"Request timed out after {timeout:.1f} seconds"
            )
        except PromptTooLongError as e:
            return _prompt_too_long_response_from_error(e)
        except PrefillAdmissionError as e:
            return _prefill_admission_declined_response(e)
        except VLMImagePrefillBudgetError as e:
            return _vlm_image_prefill_budget_response_from_error(e)
        except MediaInputError as e:
            return _media_input_error_response_from_error(e)
        except MediaControlsUnmeetableError as e:
            return _media_controls_unmeetable_response_from_error(e)
        except UnsupportedMediaModalityError as e:
            return _unsupported_media_modality_response_from_error(e)
        except Exception as e:
            logger.error(f"Completion failed: {e}", exc_info=True)
            raise HTTPException(
                status_code=500,
                detail=f"Generation failed: {type(e).__name__}: {e}",
            )

        completion_text = (
            _visible_text_for_dsv4_completion(output, engine, request)
            if _is_loaded_dsv4_model(request.model)
            else output.text
        )

        choices.append(
            CompletionChoice(
                index=i,
                text=completion_text,
                logprobs=_format_completion_logprobs(
                    getattr(output, "logprobs", None),
                    engine.tokenizer,
                )
                if request.logprobs is not None
                else None,
                finish_reason=output.finish_reason,
            )
        )
        total_completion_tokens += output.completion_tokens
        total_prompt_tokens += (
            output.prompt_tokens if hasattr(output, "prompt_tokens") else 0
        )
        total_cached_tokens += int(getattr(output, "cached_tokens", 0) or 0)
        _detail = getattr(output, "cache_detail", "") or None
        if _detail:
            cache_detail = _detail

    elapsed = time.perf_counter() - start_time
    tokens_per_sec = total_completion_tokens / elapsed if elapsed > 0 else 0
    logger.info(
        f"Completion: {total_prompt_tokens} prompt + {total_completion_tokens} completion tokens in {elapsed:.2f}s ({tokens_per_sec:.1f} tok/s end-to-end incl. prefill) therm={thermal_state_name()}"
    )

    return CompletionResponse(
        model=request.model,
        choices=choices,
        usage=Usage(
            prompt_tokens=total_prompt_tokens,
            completion_tokens=total_completion_tokens,
            total_tokens=total_prompt_tokens + total_completion_tokens,
            prompt_tokens_details=PromptTokensDetails(
                cached_tokens=total_cached_tokens,
                cache_detail=cache_detail,
            )
            if total_cached_tokens > 0 or cache_detail
            else None,
        ),
    )


def _log_inbound_request_fields(endpoint: str, request: Any) -> None:
    """Log the settings a request actually arrived with, when asked.

    UI-vs-API parity is otherwise unobservable from either end: the app sends
    chat requests over its Electron IPC bridge from the MAIN process, so hooking
    the renderer's fetch and XMLHttpRequest captures nothing, and the server had
    no way to report what it received. That left "the UI toggle does nothing"
    indistinguishable from "the value never reached the engine".

    Off unless VMLX_LOG_REQUEST_FIELDS is set. Logs only settings-bearing
    fields, never message content -- prompts can carry private data and this is
    meant to be safe to switch on against a real session.

    Set it to a PATH to append there as well as to the logger. An engine started
    by the desktop app has its stdout piped into Electron, so the log line only
    reaches an in-app panel that is awkward to read back; a file makes the
    UI-versus-API comparison readable from anywhere.
    """
    sink = os.environ.get("VMLX_LOG_REQUEST_FIELDS", "").strip()
    if not sink:
        return
    fields = (
        "model", "stream", "temperature", "top_p", "top_k", "min_p",
        "max_tokens", "max_completion_tokens", "repetition_penalty",
        "reasoning_effort", "reasoning_strength", "enable_thinking",
        "thinking", "tool_choice", "seed", "stop", "logprobs", "top_logprobs",
        # Responses-API spellings. This list was written for the chat
        # completions shape, but the app talks to /v1/responses, where the
        # cap is `max_output_tokens` and reasoning may arrive NESTED as
        # `reasoning={"effort": ...}` rather than flat `reasoning_effort`.
        # Omitting them made a request that carried an effort log as though it
        # carried none -- a parity probe that under-reports on the endpoint it
        # exists to observe is worse than no probe, because it reads as proof
        # the UI sent nothing.
        "reasoning", "max_output_tokens", "max_thinking_tokens",
        "thinking_mode", "frequency_penalty", "presence_penalty", "logit_bias",
    )
    present = {}
    for name in fields:
        value = getattr(request, name, None)
        if value is not None:
            present[name] = value
    try:
        tool_count = len(getattr(request, "tools", None) or [])
        message_count = len(getattr(request, "messages", None) or [])
    except TypeError:
        tool_count = message_count = -1
    summary = (
        " ".join(f"{k}={v!r}" for k, v in sorted(present.items())) or "<none set>"
    )
    logger.info(
        "Inbound %s fields: %s (messages=%d tools=%d)",
        endpoint,
        summary,
        message_count,
        tool_count,
    )
    if os.sep in sink or sink.endswith(".log"):
        try:
            with open(sink, "a", encoding="utf-8") as handle:
                handle.write(
                    "Inbound %s fields: %s (messages=%d tools=%d)\n"
                    % (endpoint, summary, message_count, tool_count)
                )
        except OSError as exc:
            # A bad path must not take the request down; this is diagnostics.
            logger.warning("Could not append request fields to %r: %s", sink, exc)


@app.post(
    "/v1/chat/completions",
    dependencies=[
        Depends(verify_api_key),
        Depends(check_rate_limit),
        Depends(check_memory_pressure),  # mlxstudio#63
        Depends(check_metal_working_set_pressure),  # mlxstudio#78
    ],
    response_model_exclude_none=True,
)
async def create_chat_completion(
    request: ChatCompletionRequest,
    fastapi_request: Request,
):
    """
    Create a chat completion (supports multimodal content for VLM models).

    OpenAI-compatible multimodal format for images:
    ```json
    messages=[{
        "role": "user",
        "content": [
            {"type": "text", "text": "What's in this image?"},
            {"type": "image_url", "image_url": {"url": "https://..."}}
        ]
    }]
    ```

    Video support:
    ```json
    messages=[{
        "role": "user",
        "content": [
            {"type": "text", "text": "What happens in this video?"},
            {"type": "video_url", "video_url": {"url": "https://example.com/video.mp4"}}
        ]
    }]
    ```

    Structured output (JSON mode):
    ```json
    response_format={"type": "json_object"}
    ```

    Structured output (JSON Schema):
    ```json
    response_format={
        "type": "json_schema",
        "json_schema": {
            "name": "my_schema",
            "schema": {"type": "object", "properties": {...}}
        }
    }
    ```
    """
    _attach_tool_choice_fulfilled_marker(request, fastapi_request)
    _log_inbound_request_fields("chat.completions", request)
    # Model name validation: accept served name, actual name, or any name (permissive)
    resolved_name = _resolve_model_name()
    if (
        request.model
        and request.model != resolved_name
        and request.model != _model_name
    ):
        # v1.3.67 mlxstudio#79: log INFO once per distinct pair (not
        # DEBUG-after-first). Claude Code sends model="claude-3-5-sonnet"
        # or similar; operators need to see the substitution in logs to
        # diagnose "why did my claude-3-5-sonnet request return MiniMax
        # output". Silently demoting to DEBUG after one warning hid the
        # bug from operators.
        _pair = (str(request.model), str(resolved_name))
        if _pair not in _model_name_mismatch_seen:
            _model_name_mismatch_seen.add(_pair)
            logger.info(
                f"Request model '{request.model}' differs from served model "
                f"'{resolved_name}' — using loaded model (single-model server). "
                f"This is expected when routing tools like Claude Code, opencode, "
                f"or CCSwitch at vMLX — they send their own model alias."
            )
    # Normalize response model field to the resolved name
    request.model = resolved_name
    _log_multimodal_request_shape(
        "/v1/chat/completions",
        _model_path or _model_name or request.model,
        _messages_multimodal_summary(request.messages),
    )

    _chat_max_prompt_tokens = _effective_max_prompt_tokens(request)

    if request.logprobs:
        _logprobs_engine = get_engine()
        _reject_unsupported_logprobs_request(
            endpoint="Chat Completions",
            requested=True,
            stream=request.stream,
            is_mllm=bool(getattr(_logprobs_engine, "is_mllm", False)),
        )

    # Nemotron-3-Nano-Omni multimodal dispatch (Stage-1 PyTorch+MLX bridge).
    # If the loaded bundle is a nemotron_h Omni bundle (has config_omni.json
    # + vision_model.* weights) AND the request includes any image/audio/
    # video content parts, route through `OmniMultimodalDispatcher` which
    # wraps `jang_tools.nemotron_omni_session.OmniSession`. Text-only
    # requests fall through to the standard chat path (already verified
    # working at full LLM speed). See research/NEMOTRON-OMNI-MULTIMODAL-2026-04-28.md.
    try:
        from .omni_multimodal import (
            is_omni_multimodal_bundle,
            request_has_multimodal,
            dispatch_omni_chat_completion,
        )

        _omni_path = _model_path or _model_name
        if (
            _omni_path
            and is_omni_multimodal_bundle(_omni_path)
            and request_has_multimodal(
                [m.model_dump(exclude_none=True) if hasattr(m, "model_dump") else m
                 for m in (request.messages or [])]
            )
        ):
            return await dispatch_omni_chat_completion(
                request,
                _omni_path,
                disk_cache_enabled=_loaded_block_disk_cache_enabled(),
                effective_max_tokens=_resolve_max_tokens(
                    request.max_tokens, request.model
                ),
                effective_temperature=_resolve_temperature(
                    request.temperature, request.model
                ),
                effective_top_p=_resolve_top_p(request.top_p, request.model),
            )
    except HTTPException:
        raise
    except Exception as _omni_route_err:  # pragma: no cover
        logger.warning(
            "Omni multimodal dispatch failed (%s); falling back to standard path",
            _omni_route_err,
        )

    # Reject empty prompts with a clear 400 instead of letting mlx-vlm
    # crash inside stream_generate with ValueError:
    # "[reshape] Cannot infer the shape of an empty array".
    # A message with content="" contributes zero tokens — the model has
    # nothing to decode. Covers str content, content parts list with
    # no non-empty text, and messages arrays that are empty after role
    # filtering. iter 26 added: caught live on Qwen3.6-JANGTQ2.
    def _has_non_empty_content(msg) -> bool:
        c = getattr(msg, "content", None)
        if c is None:
            # assistant with tool_calls only is valid even if content is None
            if getattr(msg, "tool_calls", None):
                return True
            return False
        if isinstance(c, str):
            return c.strip() != ""
        if isinstance(c, list):
            # content parts — at least one text/image/video part with a value
            for p in c:
                t = getattr(p, "type", None) or (p.get("type") if isinstance(p, dict) else None)
                if t == "text":
                    txt = getattr(p, "text", None) or (p.get("text") if isinstance(p, dict) else None)
                    if txt and str(txt).strip():
                        return True
                elif t in _MULTIMODAL_CONTENT_TYPES:
                    return True
            return False
        return bool(c)

    if request.messages:
        _user_msgs = [m for m in request.messages if getattr(m, "role", None) == "user"]
        # Two bugs gated by this check:
        # (iter 26) user message with empty content → 500 reshape crash
        # (iter 27) NO user messages at all (only system) → same 500 crash
        # Both resolve to "the engine will have 0 prompt tokens to work with".
        if not _user_msgs:
            raise HTTPException(
                status_code=400,
                detail="No user message — at least one message with role='user' "
                       "and non-empty content is required. (System-only prompts "
                       "cannot generate output.)"
            )
        if not any(_has_non_empty_content(m) for m in _user_msgs):
            raise HTTPException(
                status_code=400,
                detail="Empty user content — at least one user message must have "
                       "non-empty text, image, video, or audio content."
            )

    engine = get_engine()
    _chat_requested_modalities = _messages_requested_modalities(request.messages)
    if _chat_requested_modalities and _m3_vl_media_ok(engine):
        # M3 VL media is served by the text-routed M3 path.
        _chat_requested_modalities = {
            m for m in _chat_requested_modalities
            if str(m).lower() not in ("image", "vision", "video")
        }
    if _chat_requested_modalities:
        _reject_unsupported_multimodal(
            "/v1/chat/completions",
            _chat_requested_modalities,
        )

    # For MLLM models, keep original messages with embedded images
    # (MLLM.chat() extracts images from message content internally)
    if engine.is_mllm:
        # Convert Pydantic messages to dicts, excluding None fields.
        # CRITICAL: model_dump() without exclude_none includes ALL optional fields
        # (e.g. image_url=None on text items). The Jinja2 chat template checks
        # 'image_url' in item (key existence), so None-valued fields cause text items
        # to be misdetected as images, producing duplicate <|image_pad|> tokens.
        messages = []
        for msg in request.messages:
            if hasattr(msg, "model_dump"):
                msg_dict = msg.model_dump(exclude_none=True)
            else:
                msg_dict = dict(msg)
            # Map "developer" role to "system" (OpenAI API compatibility)
            if msg_dict.get("role") == "developer":
                msg_dict["role"] = "system"
            messages.append(msg_dict)
        images, videos = [], []  # MLLM extracts these from messages
        logger.debug(f"MLLM: Processing {len(messages)} messages")
    else:
        # For LLM, extract text, images, and videos separately
        messages, images, videos = extract_multimodal_content(
            request.messages,
            preserve_native_format=engine.preserve_native_tool_format,
        )

    # An assistant turn may legitimately carry NO content: a reply that spent its
    # whole budget on reasoning finishes with `length` and an empty answer, and
    # the never-empty contract permits that. When a client replays such a turn,
    # `model_dump(exclude_none=True)` above drops the `content` key entirely, so
    # the chat template sees an assistant message with neither content nor tool
    # calls -- Mistral's then raises TemplateError("Assistant message must have a
    # string or a list of chunks in content or a list of tool calls") and the
    # caller gets a 500 for echoing back the turn we handed them.
    #
    # DROP the turn rather than filling it. Setting content to "" does NOT work:
    # Mistral's template rejects the empty string exactly as it rejects a missing
    # key (verified by rendering both shapes through the real tokenizer). A turn
    # that produced neither text nor a tool call carries no information, so
    # dropping it is also the honest repair -- injecting a placeholder would put
    # words in the assistant's mouth. Verified that the resulting consecutive
    # user turns still render on Mistral, Qwen3.8, Nanbeige and Muse.
    #
    # A tool-call-only assistant turn is left alone: it is valid without content.
    messages = _drop_contentless_assistant_turns(messages)

    # Include audio in the media check: extract_multimodal_content returns only
    # images+videos, so an audio-only request that reached this text path
    # (omni dispatch declined or a non-omni model) used to be answered
    # text-only with the audio silently dropped. _chat_requested_modalities is
    # computed from the full message summary and does see audio. The reject
    # call stays arg-free on purpose: it raises 503 for an omni bundle whose
    # dispatch did not complete (never silently proceed) and 400 for a genuine
    # text-only runtime — passing the modality set would instead let an omni
    # runtime that advertises audio return silently and drop the media.
    has_media = bool(images or videos) or bool(_chat_requested_modalities)
    if has_media and not engine.is_mllm and not _m3_vl_media_ok(engine):
        _reject_unsupported_multimodal("/v1/chat/completions")

    # Handle response_format - inject system prompt if needed
    response_format = request.response_format
    if response_format:
        json_instruction = build_json_system_prompt(response_format)
        if json_instruction:
            # Inject JSON instruction into messages
            messages = _inject_json_instruction(messages, json_instruction)
    if engine.is_mllm and _should_coerce_zaya_vl_tool_history(request.model):
        messages = _coerce_zaya_vl_tool_history_for_template(messages)
    messages = _normalize_leading_system_messages(
        messages,
        preserve_native_order=_is_loaded_dsv4_model(request.model),
    )

    # When thinking is explicitly disabled, strip <think> blocks from prior assistant
    # messages in the conversation history. Without this, the model sees prior thinking
    # in context and mimics the pattern, producing reasoning even when the generation
    # prompt doesn't inject <think>. This is the root cause of "thinking OFF but model
    # still thinks on 2nd message" bugs.
    _ct_kwargs = _merge_ct_kwargs(
        request.chat_template_kwargs,
        getattr(request, "reasoning_effort", None),
    )
    _explicit_thinking_off = request.enable_thinking is False or (
        _ct_kwargs.get("enable_thinking") is False
    )
    if _explicit_thinking_off and messages:
        messages = _strip_prior_reasoning_for_thinking_off(messages)

    # Prepare kwargs. Preserve explicit zero for validation/error paths:
    # request.max_tokens if request.max_tokens is not None else None
    # feeds `_resolve_max_tokens()` without using a falsy `or` fallback.
    _request_max_tokens = request.max_tokens if request.max_tokens is not None else None
    chat_kwargs = {
        "max_tokens": _resolve_max_tokens(_request_max_tokens, request.model),
        "temperature": _resolve_temperature(request.temperature, request.model),
        "top_p": _resolve_top_p(request.top_p, request.model),
        "max_prompt_tokens": _chat_max_prompt_tokens,
    }
    if request.seed is not None:
        chat_kwargs["seed"] = request.seed
    if response_format:
        chat_kwargs["_vmlx_response_format"] = (
            response_format.model_dump(exclude_none=True, by_alias=True)
            if hasattr(response_format, "model_dump")
            else response_format
        )
    # Forward stop sequences from request to engine
    if request.stop:
        chat_kwargs["stop"] = request.stop
    # Extended sampling params (only pass if explicitly set)
    _set_resolved_top_k(chat_kwargs, request.top_k, request.model)
    _normalize_deterministic_sampling_filters(
        chat_kwargs,
        request_top_p=request.top_p,
        request_top_k=request.top_k,
    )
    _set_resolved_min_p(chat_kwargs, request.min_p, request.model)
    _rp = _resolve_repetition_penalty(request.repetition_penalty, request.model)
    if _rp is not None:
        chat_kwargs["repetition_penalty"] = _rp
    _forward_openai_token_controls(chat_kwargs, request)
    if _compute_bypass_prefix_cache(request):
        chat_kwargs["_bypass_prefix_cache"] = True
    if request.logprobs:
        chat_kwargs["logprobs"] = True
        chat_kwargs["top_logprobs"] = request.top_logprobs or 0

    # Pass enable_thinking to engine
    # Priority: top-level field > chat_template_kwargs > server default > auto-detect
    _et = _resolve_enable_thinking(
        request_value=request.enable_thinking,
        ct_kwargs=_ct_kwargs,
        tools_present=bool(request.tools),
        model_key=_model_path or _model_name or request.model,
        engine=engine,
        auto_detect=True,
        reasoning_effort=request.reasoning_effort,
    )
    if _et is not None:
        chat_kwargs["enable_thinking"] = _et
        request.enable_thinking = _et
        _ct_kwargs["enable_thinking"] = _et

    _forward_reasoning_effort_kwargs(
        chat_kwargs, _ct_kwargs, request.reasoning_effort
    )
    if getattr(request, "max_thinking_tokens", None) is not None and request.enable_thinking is not False:
        _ct_kwargs["thinking_budget"] = int(request.max_thinking_tokens)

    # Auto-map enable_thinking → reasoning_effort for Mistral 4.
    # Mistral 4's template uses reasoning_effort ("none"/"high"), not enable_thinking.
    # When the user toggles thinking ON in the UI, set reasoning_effort="high" if not already set.
    # Original Mistral 4 reasoning integration by Jinho Jang (eric@jangq.ai) — vMLX.
    # This approach (auto-mapping enable_thinking to reasoning_effort for models that
    # use [MODEL_SETTINGS] blocks) was developed through extensive trial and error.
    # If you adapt this pattern, please credit the original author.
    if (
        _reasoning_parser
        and type(_reasoning_parser).__name__ == "MistralReasoningParser"
    ):
        if request.enable_thinking is True and "reasoning_effort" not in _ct_kwargs:
            _ct_kwargs["reasoning_effort"] = "high"
            chat_kwargs["reasoning_effort"] = "high"
        elif request.enable_thinking is False and "reasoning_effort" not in _ct_kwargs:
            _ct_kwargs["reasoning_effort"] = "none"

    _apply_hy3_reasoning_policy(
        chat_kwargs,
        _ct_kwargs,
        model_key=_model_path or _model_name or request.model,
        enable_thinking=request.enable_thinking,
    )
    # Mint the response id BEFORE the stamped-effort policy so a coercion is
    # recorded under the id the finalize sites pop. Only the policy itself
    # knows a substitution happened — a request-vs-effective diff at mint
    # time would false-positive on the hy3/enable_thinking mappings.
    response_id = f"chatcmpl-{uuid.uuid4().hex[:8]}"
    _note_request_diagnostics_id(response_id)
    _apply_stamped_effort_policy(
        chat_kwargs,
        _ct_kwargs,
        model_key=_model_path or _model_name or request.model,
        request_id=response_id,
    )

    # DeepSeek V4 bundle-owned encoder: thinking_mode=chat|thinking plus an
    # optional effort accepted by that exact encoder revision. Auto-map only
    # the public on/off toggle; never alias explicit effort tiers.
    try:
        from .model_config_registry import get_model_config_registry
        _model_family_key = _model_path or _model_name or getattr(request, "model", "") or ""
        _mc_for_dsv4 = get_model_config_registry().lookup(_model_family_key)
        _is_dsv4 = getattr(_mc_for_dsv4, "family_name", "") == "deepseek_v4"
    except Exception:
        _is_dsv4 = False
    if _is_dsv4:
        # DSV4 uses its versioned Python encoder rather than a Jinja template.
        # Keep `thinking_mode` out of generic kwargs and pass only the resolved
        # enable flag plus a bundle-validated explicit effort.
        _cur_effort = _dsv4_requested_reasoning_effort(
            request,
            _ct_kwargs,
        )
        # Strip stale fields from any prior path so the final kwargs are clean.
        _ct_kwargs.pop("thinking_mode", None)

        _dsv4_thinking = _resolve_dsv4_thinking_policy(
            requested_enable_thinking=request.enable_thinking,
            effort_requested=bool(_cur_effort),
            tools_present=bool(getattr(request, "tools", None)),
            tool_choice=getattr(request, "tool_choice", None),
            default_mode=_jang_chat_default_mode(
                _model_path or _model_name or request.model or ""
            ),
        )
        if (
            not _dsv4_thinking.enable_thinking
            and (request.enable_thinking is True or _cur_effort)
        ):
            logger.info(
                "DSV4: using direct rail because %s.",
                _dsv4_thinking.reason,
            )
        request.enable_thinking = _dsv4_thinking.enable_thinking
        chat_kwargs["enable_thinking"] = _dsv4_thinking.enable_thinking
        _ct_kwargs["enable_thinking"] = _dsv4_thinking.enable_thinking
        _set_resolved_repetition_penalty(
            chat_kwargs,
            request.repetition_penalty,
            request.model,
            enable_thinking=chat_kwargs.get("enable_thinking"),
        )
        _stable_effort = (
            _normalize_dsv4_reasoning_effort(
                _cur_effort,
                _model_path or _model_name or request.model or "",
            )
            if _dsv4_thinking.reasoning_effort_allowed
            else None
        )
        if _stable_effort:
            _ct_kwargs["reasoning_effort"] = _stable_effort
        else:
            _ct_kwargs.pop("reasoning_effort", None)

    _normalize_minimax_m3_thinking_mode(
        _ct_kwargs, request, _model_path or _model_name or request.model)
    _normalize_openpangu_thinking(
        _ct_kwargs, request, _model_path or _model_name or request.model)
    # Resolve the render-relevant tool_choice before snapshotting
    # chat_template_kwargs. Native fallback renderers (notably LFM2) need a
    # required/specific current-request contract, while `none`/`auto` remain
    # scheduler controls and must not perturb arbitrary model templates.
    _tool_choice = request.tool_choice
    if _tool_choice is not None:
        chat_kwargs["tool_choice"] = _tool_choice
    _qwen4_specific_tool_name = _specific_tool_choice_name(_tool_choice)
    _qwen4_stable_tool_catalog = bool(
        _qwen4_specific_tool_name
        and _is_loaded_qwen4_exp_model(request.model or "")
    )
    if _is_required_tool_choice(_tool_choice) and not _qwen4_stable_tool_catalog:
        # The official top-level API contract overrides any conflicting nested
        # template value.
        _ct_kwargs["tool_choice"] = _tool_choice
    else:
        _ct_kwargs.pop("tool_choice", None)

    # Forward the resolved template kwargs to the engine.  Keep the resolved
    # enable_thinking value mirrored here as well as the top-level engine kwarg:
    # build_chat_template_kwargs() treats the top-level flag as authoritative,
    # while renderer/processor wrappers that inspect the raw template kwargs see
    # the same effective On/Off value instead of stale caller input.
    if _ct_kwargs:
        extra_ct = dict(_ct_kwargs)
        if extra_ct:
            chat_kwargs["chat_template_kwargs"] = extra_ct

    _log_resolved_sampling_kwargs(
        "/v1/chat/completions",
        request.model or _resolve_model_name(),
        chat_kwargs,
        proof_request_id=_request_header_value(
            fastapi_request,
            "x-vmlx-proof-request-id",
        ),
        request_id=_request_header_value(fastapi_request, "x-vmlx-request-id"),
        message_id=_request_header_value(fastapi_request, "x-vmlx-message-id"),
    )

    # Add multimodal content
    if has_media:
        chat_kwargs["images"] = images if images else None
        chat_kwargs["videos"] = videos if videos else None
    if request.image_token_budget:
        chat_kwargs["image_token_budget"] = request.image_token_budget
    # Video controls — passed regardless of has_media since MLLM models
    # extract media from messages internally (has_media is always False for them)
    # Video controls: every SET field (0 is invalid and rejected at the model,
    # so no truthiness filter is needed), plus the normalized object.
    chat_kwargs.update(video_control_kwargs(request))

    _suppress_tools = _tool_choice == "none"

    # response_format = json_object / json_schema implies the output IS the
    # structured data — not a tool call. The generic tool-call parser runs
    # on any JSON-ish output and is happy to interpret `{"name":"alice",
    # "age":30}` as a tool call `alice()`. Suppress the tool parser when
    # the client asked for JSON output and didn't pass tools themselves.
    # If both tools AND response_format are present, tool parsing still
    # runs (structured tool-call arguments are allowed).
    if not request.tools and not _suppress_tools:
        _rf = request.response_format
        _rf_type = None
        if isinstance(_rf, dict):
            _rf_type = _rf.get("type")
        elif _rf is not None and hasattr(_rf, "type"):
            _rf_type = getattr(_rf, "type", None)
        if _rf_type in ("json_object", "json_schema"):
            _suppress_tools = True

    # Merge MCP tools with user-provided tools
    all_tools = []

    if not _suppress_tools:
        # Add MCP tools if available
        if _mcp_manager is not None:
            mcp_tools = _mcp_manager.get_all_tools_openai(policy=_mcp_policy)
            mcp_tools = _drop_colliding_mcp_tools(mcp_tools, request.tools)
            if not _qwen4_stable_tool_catalog:
                mcp_tools = _filter_tools_for_specific_choice(mcp_tools, _tool_choice)
            all_tools.extend(mcp_tools)
            if mcp_tools:
                logger.debug(f"Added {len(mcp_tools)} MCP tools")

        # Add user-provided tools
        if request.tools:
            # If tool_choice is a specific tool dict, filter to only that tool
            if isinstance(_tool_choice, dict) and not _qwen4_stable_tool_catalog:
                target_name = _tool_choice.get("function", {}).get(
                    "name"
                ) or _tool_choice.get("name")
                if target_name:
                    # request.tools are ToolDefinition Pydantic models (type + function dict)
                    filtered = [
                        t
                        for t in request.tools
                        if t.function.get("name") == target_name
                    ]
                    # A specific choice is an authorization boundary. Falling
                    # back to every request tool when the name is unavailable
                    # lets the model call a function the client did not choose
                    # and diverges from the Responses path. Leave the set empty;
                    # the shared no-tools guard below returns an explicit 400.
                    all_tools.extend(filtered)
                else:
                    all_tools.extend(request.tools)
            else:
                all_tools.extend(request.tools)
            logger.debug(f"Added {len(all_tools)} tools (tool_choice={_tool_choice})")

    parser_tools = (
        _filter_tools_for_specific_choice(all_tools, _tool_choice)
        if _qwen4_stable_tool_catalog
        else all_tools
    )
    if not _suppress_tools:
        _suppress_tools = _suppress_tool_parsing_when_no_tools(
            parser_tools, _tool_choice, "Chat Completions"
        )
    _attach_effective_tools_for_tool_parsing(request, parser_tools)

    # Pass merged tools to engine (normalize all to template format)
    if all_tools:
        chat_kwargs["tools"] = convert_tools_for_template(all_tools)
        chat_kwargs["_vmlx_tools_present"] = True
        if _qwen4_stable_tool_catalog:
            chat_kwargs["_vmlx_qwen4_specific_tool_name"] = (
                _qwen4_specific_tool_name
            )

    # Inject Harmony analysis prefix for GPT-OSS models when thinking is enabled.
    # The suffix replaces the template's generation prompt (<|start|>assistant<|message|>)
    # with the analysis channel prefix to guide the model into reasoning mode.
    if isinstance(_reasoning_parser, GptOssReasoningParser):
        _think_val = chat_kwargs.get("enable_thinking")
        if _think_val is True:
            _analysis_hint = "<|start|>assistant<|channel|>analysis<|message|>"
            chat_kwargs["prompt_suffix"] = _analysis_hint
            # Skip template's generation prompt — suffix provides the full assistant prefix
            chat_kwargs["skip_generation_prompt"] = True
            _effort = chat_kwargs.get("reasoning_effort", "").lower()
            logger.info(
                f"[chat] Injecting Harmony analysis prefix for GPT-OSS model (effort={_effort or 'default'})"
            )
        # GPT-OSS/GLM Flash models sometimes generate <|im_end|> (ChatML format)
        # which is NOT a single token in the Harmony vocabulary — it shatters into
        # sub-tokens and leaks into output. Add it as a string stop sequence.
        _stop = chat_kwargs.get("stop") or []
        if "<|im_end|>" not in _stop:
            _stop = list(_stop) + ["<|im_end|>"]
            chat_kwargs["stop"] = _stop

    if request.stream:
        return StreamingResponse(
            _terminal_finish_guard(
                stream_chat_completion(
                    engine,
                    messages,
                    request,
                    fastapi_request=fastapi_request,
                    response_id=response_id,
                    **chat_kwargs,
                ),
                required_tool_call=_is_pending_required_tool_choice(request),
            ),
            media_type="text/event-stream",
        )

    # Non-streaming response with timing and timeout (response_id was minted
    # before the stamped-effort policy above).
    start_time = time.perf_counter()
    timeout = request.timeout if request.timeout is not None else _default_timeout

    # An explicit max_thinking_tokens may reserve part of the caller's output
    # cap for the existing direct-answer stage. Auto/On without an explicit
    # thinking cap always receives the full native generation budget.
    _ns_answer_pass_original_cap = None
    _ns_pre_mtt = getattr(request, "max_thinking_tokens", None)
    if _ns_pre_mtt is None:
        # DSV4 only — see _dsv4_answer_pass_thinking_cap.
        try:
            from .model_config_registry import get_model_config_registry as _ns_dsv4_mcr
            _ns_dsv4_family = getattr(
                _ns_dsv4_mcr().lookup(_model_path or _model_name or request.model),
                "family_name", None,
            )
        except Exception:
            _ns_dsv4_family = None
        _ns_pre_mtt = _dsv4_answer_pass_thinking_cap(
            _ns_dsv4_family,
            None if chat_kwargs.get("enable_thinking") is None
            else chat_kwargs.get("enable_thinking"),
            chat_kwargs.get("max_tokens"),
        )
        # The SOFT-cap flavor is DSV4-only (its engine rail implements the
        # lift-at-</think> kwarg). Nemotron's default reserve takes the plain
        # hard split below, exactly like an explicit max_thinking_tokens.
        _ns_dsv4_default_reserve = (
            _ns_pre_mtt is not None and _ns_dsv4_family == "deepseek_v4"
        )
    else:
        _ns_dsv4_default_reserve = False
    if (
        _ns_pre_mtt is not None
        and chat_kwargs.get("enable_thinking") is not False
        and getattr(request, "enable_thinking", None) is not False
        and (chat_kwargs.get("chat_template_kwargs") or {}).get("enable_thinking") is not False
    ):
        try:
            from .model_config_registry import get_model_config_registry as _ns_pre_mcr
            _ns_pre_family = getattr(
                _ns_pre_mcr().lookup(_model_path or _model_name or request.model),
                "family_name", None,
            )
        except Exception:
            _ns_pre_family = None
        _ns_pre_cap_family = (
            _ns_pre_family in _THINKING_BUDGET_CAP_FAMILIES
            or _ns_pre_family == "deepseek_v4"
            or _ns_pre_family in ("minimax_m3", "minimax_m3_vl")
            # A served alias is not necessarily a readable bundle path. The
            # configured native parser is still source-owned runtime evidence
            # for MiniMax-M3, matching the post-parse family fallback below.
            or _tool_call_parser == "minimax_m3"
        )
        if _ns_pre_cap_family:
            _ns_pre_orig = int(chat_kwargs.get("max_tokens") or 256)
            _ns_pre_capped = max(1, min(_ns_pre_orig, int(_ns_pre_mtt)))
            if _ns_pre_capped < _ns_pre_orig:
                _ns_answer_pass_original_cap = _ns_pre_orig
                chat_kwargs = dict(chat_kwargs)
                if _ns_dsv4_default_reserve:
                    # DSV4 default reserve: SOFT cap — lifts engine-side at
                    # </think> so the same pass spends the reserved answer
                    # budget instead of stranding it. Reasoning-only runs still
                    # finish=length at the cap and arm the answer pass below.
                    chat_kwargs["dsv4_thinking_soft_cap"] = _ns_pre_capped
                else:
                    chat_kwargs["max_tokens"] = _ns_pre_capped

    try:
        _note_request_diagnostics_id(response_id)
        output = await _await_chat_with_disconnect_abort(
            engine,
            messages=messages,
            chat_kwargs=chat_kwargs,
            timeout=timeout,
            fastapi_request=fastapi_request,
            request_id=response_id,
            endpoint="Chat Completions",
            hard_timeout=request.timeout is not None,
        )
    except asyncio.TimeoutError:
        raise HTTPException(
            status_code=504, detail=f"Request timed out after {timeout:.1f} seconds"
        )
    except PromptTooLongError as e:
        return _prompt_too_long_response_from_error(e)
    except PrefillAdmissionError as e:
        return _prefill_admission_declined_response(e)
    except VLMImagePrefillBudgetError as e:
        return _vlm_image_prefill_budget_response_from_error(e)
    except MediaInputError as e:
        return _media_input_error_response_from_error(e)
    except MediaControlsUnmeetableError as e:
        return _media_controls_unmeetable_response_from_error(e)
    except UnsupportedMediaModalityError as e:
        return _unsupported_media_modality_response_from_error(e)
    except ValueError as e:
        conv1d_detail = _grouped_conv1d_layout_error_detail(e)
        if conv1d_detail:
            logger.error("Chat completion failed with grouped Conv1d layout error: %s", e)
            raise HTTPException(status_code=503, detail=conv1d_detail)
        logger.warning(f"Chat completion rejected: {e}")
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        logger.error(f"Chat completion failed: {e}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail=_generation_error_detail(e),
        )

    elapsed = time.perf_counter() - start_time
    tokens_per_sec = output.completion_tokens / elapsed if elapsed > 0 else 0
    logger.info(
        f"Chat completion: {output.completion_tokens} tokens in {elapsed:.2f}s ({tokens_per_sec:.1f} tok/s end-to-end incl. prefill) therm={thermal_state_name()}"
    )

    # Extract reasoning content FIRST from raw output (before stripping tags).
    # Must happen before tool call parsing since that strips <think> blocks.
    reasoning_text = None
    _private_tool_candidate = None
    content_for_parsing = output.text
    if _reasoning_parser:
        # Clone parser per-request to avoid shared state across concurrent requests
        request_parser = _reasoning_parser.__class__()
        # Initialize parser state (harmony_active, etc.) — same as streaming path
        # NOTE: non-stream extract_reasoning() parses the COMPLETE text and finds
        # the harmony final marker on its own, so it never needs the harmony_active
        # hint (and forcing it True here alters channel parsing enough to drop
        # gpt_oss tool calls — the streaming-only leak fix must NOT touch this path).
        _harmony_prefix_active = "prompt_suffix" in chat_kwargs and chat_kwargs.get(
            "prompt_suffix", ""
        ).startswith("<|start|>assistant<|channel|>analysis")

        # Compute think_in_prompt the same way the streaming path does at
        # ~line 5840. MiniMax and other "always-thinks" templates inject
        # <think>\n in the generation prompt, so model output starts in
        # reasoning mode. Without think_in_prompt=True, `extract_reasoning`
        # falls through to "no tags → pure content" and the reasoning prose
        # shows up raw in content (§15 regression).
        try:
            from .model_config_registry import get_model_config_registry as _mcr
            _mc_nonstream = _mcr().lookup(_model_path or _model_name or request.model)
            _think_in_prompt_ns = _mc_nonstream.think_in_template
            _think_in_prompt_ns = _apply_tokenizer_thinking_vocab_fallback(
                _think_in_prompt_ns,
                reasoning_parser=_reasoning_parser,
                tokenizer=engine.tokenizer,
                model_config=_mc_nonstream,
            )
            if _think_in_prompt_ns and _template_completes_thinking(
                engine.tokenizer, _model_name or request.model
            ):
                _think_in_prompt_ns = False
            _eff_thinking_ns = chat_kwargs.get("enable_thinking")
            _prompt_enable_ns = (
                True if _eff_thinking_ns is None else bool(_eff_thinking_ns)
            )
            _tools_present_ns = _tools_available_for_generation(
                request, chat_kwargs.get("tools")
            )
            if _engine_prompt_starts_in_reasoning(
                engine.tokenizer,
                model_name=_model_name or request.model,
                enable_thinking=_prompt_enable_ns,
                family_name=getattr(_mc_nonstream, "family_name", None),
                tools_present=_tools_present_ns,
            ):
                _think_in_prompt_ns = True
            else:
                _think_in_prompt_ns = False
            if _hy3_prompt_starts_in_reasoning(
                model_key=_model_path or _model_name or request.model,
                enable_thinking=_eff_thinking_ns,
                ct_kwargs=chat_kwargs.get("chat_template_kwargs") or _ct_kwargs,
            ):
                _think_in_prompt_ns = True
            if _synthetic_mllm_think_prompt_starts(
                model_key=_model_path or _model_name or request.model,
                enable_thinking=_eff_thinking_ns,
                engine=engine,
            ):
                _think_in_prompt_ns = True
            # MiniMax-M3 thinking_mode="enabled" prompt-opens <mm:think> in the
            # generation prompt, so assistant output starts INSIDE reasoning with
            # no opening tag in the OUTPUT. Seed the parser's implicit-reasoning
            # mode so the reasoning isn't misclassified as visible content.
            if (chat_kwargs.get("chat_template_kwargs") or _ct_kwargs or {}).get(
                "thinking_mode"
            ) == "enabled":
                _think_in_prompt_ns = True
        except Exception as _tpe:
            logger.debug(f"think_in_prompt derivation failed non-stream: {_tpe}")
            _think_in_prompt_ns = False

        request_parser.reset_state(
            think_in_prompt=_think_in_prompt_ns,
            harmony_active=_harmony_prefix_active,
        )
        # Prefer raw_text (pre-clean) when the engine tracked it — reasoning
        # parsers (esp. Gemma 4 channel markers, Qwen 3.6 think tags) need the
        # special tokens that clean_output_text strips for display.
        _raw_for_parse = getattr(output, "raw_text", "") or output.text
        reasoning_text, remaining_text = request_parser.extract_reasoning(_raw_for_parse)
        if _is_dsv4:
            token_reasoning, token_content = _dsv4_split_reasoning_from_token_ids(
                _output_token_ids_for_reasoning(output),
                engine.tokenizer,
            )
            if token_content:
                reasoning_text = token_reasoning
                remaining_text = token_content
        if remaining_text is not None:
            content_for_parsing = remaining_text
        elif reasoning_text is not None:
            # Truncated reasoning (e.g., max_tokens hit during <think> phase):
            # reasoning extracted but no content after it — don't leak raw <think> tags
            content_for_parsing = ""
        # Suppress reasoning when thinking is disabled (check resolved value from chat_kwargs,
        # not just raw request — covers --default-enable-thinking and auto-detect paths)
        _resolved = chat_kwargs.get("enable_thinking")
        _suppress = _resolved is False or request.enable_thinking is False
        if not _suppress:
            _suppress = _ct_kwargs.get("enable_thinking") is False
        reasoning_text, content_for_parsing, _private_tool_candidate = (
            _apply_reasoning_visibility(
                reasoning_text,
                content_for_parsing,
                suppress=_suppress,
            )
        )

        # Post-parse cleaning: the parser operates on raw_text which carries
        # special markers (Gemma 4 `<|channel>`/`<channel|>`/`<turn|>`, Qwen
        # `<|im_end|>`, etc.). Markers that survive the parser's split (e.g. a
        # second `<channel|>` embedded in content, or `thought\n` degraded
        # form) must not leak into the user-visible content field. Apply the
        # same cleaner that the engine applies to `output.text` for display,
        # but AFTER the parser has done its structural extraction.
        if content_for_parsing:
            content_for_parsing = clean_output_text(content_for_parsing)
        if reasoning_text:
            reasoning_text = clean_output_text(reasoning_text)

    _ns_visible_answer_finish_reason: str | None = None

    # Reasoning-runaway backstop (non-streaming chat completions): mirror the
    # streaming bounded thinking-off answer pass. Degraded reasoners
    # (qwen3.5/3.6 MXFP4-CRACK, gemma4, MiniMax-M3) can fill the thinking
    # block without closing it, leaving content empty; re-run thinking-off
    # (coherent for these families) so non-streaming clients still get an
    # answer. No-op for healthy reasoners (only fires on reasoning + no
    # content) and for non-reasoning models (reasoning_text is None).
    try:
        from .model_config_registry import get_model_config_registry as _ns_mcr
        _ns_family = getattr(
            _ns_mcr().lookup(_model_path or _model_name or request.model),
            "family_name", None,
        )
    except Exception:
        _ns_family = None
    # The loaded runtime can expose a public/served model name that is not a
    # readable bundle path.  In that case the registry intentionally fails
    # closed to ``unknown``, but the configured native parser remains the
    # authoritative runtime contract.  Do not suppress M3's bounded answer
    # pass merely because this late non-stream lookup cannot reopen config.json.
    _ns_is_m3 = (
        _ns_family in ("minimax_m3", "minimax_m3_vl")
        or _tool_call_parser == "minimax_m3"
    )
    _ns_tools_available = _tools_available_for_generation(
        request, chat_kwargs.get("tools")
    )
    _ns_m3_valid_tool_call = (
        _ns_is_m3
        and not _suppress_tools
        and _has_schema_valid_tool_call_candidate(
            content_for_parsing,
            reasoning_text,
            request,
        )
    )
    _ns_thinking_off = (
        chat_kwargs.get("enable_thinking") is False
        or getattr(request, "enable_thinking", None) is False
        or (chat_kwargs.get("chat_template_kwargs") or {}).get("enable_thinking") is False
    )
    _ns_native_tool_recovery = _native_reasoning_tool_recovery_allowed(
        _ns_family,
        request,
        tools_available=_ns_tools_available,
        effective_thinking=False if _ns_thinking_off else True,
    )
    _ns_native_valid_tool_call = (
        _ns_native_tool_recovery
        and _has_schema_valid_tool_call_candidate(
            content_for_parsing,
            reasoning_text,
            request,
        )
    )
    _ns_explicit_tool_fallback = (
        _ns_answer_pass_original_cap is not None
        and _ns_tools_available
        and not _request_explicitly_requests_tool_use(request)
        and _ns_family in _REASONING_ANSWER_PASS_FAMILIES
        and not _has_schema_valid_tool_call_candidate(
            content_for_parsing,
            reasoning_text,
            request,
        )
    )
    _ns_visible_content_for_answer_gate = content_for_parsing
    if _ns_native_tool_recovery and not _ns_native_valid_tool_call:
        _ns_visible_content_for_answer_gate = (
            _visible_prefix_before_unparsed_tool_markup(
                _strip_think_for_tool_parse(
                    _ns_visible_content_for_answer_gate or ""
                )
            )
        )
    if _suppress_tools and _ns_visible_content_for_answer_gate:
        _ns_visible_content_for_answer_gate = (
            _clean_suppressed_tool_markup_for_display(
                _strip_think_for_tool_parse(_ns_visible_content_for_answer_gate),
                request,
            )
        )
    if (
        not _ns_visible_content_for_answer_gate
        and reasoning_text
        and not _ns_thinking_off
        and _ns_answer_pass_original_cap is not None
        and (
            not _ns_tools_available
            or (_ns_is_m3 and not _ns_m3_valid_tool_call)
            or (_ns_native_tool_recovery and not _ns_native_valid_tool_call)
            or _ns_explicit_tool_fallback
        )
        and _remaining_answer_pass_budget(
            _ns_answer_pass_original_cap,
            getattr(output, "completion_tokens", 0),
        ) > 0
    ):
        if (
            _ns_family in _REASONING_ANSWER_PASS_FAMILIES
            or _ns_is_m3
            or _ns_native_tool_recovery
        ):
            _ns_cap = int(_ns_answer_pass_original_cap)
            _ns_used = int(getattr(output, "completion_tokens", 0) or 0)
            _ns_budget = _remaining_answer_pass_budget(_ns_cap, _ns_used)
            logger.info(
                "%s non-stream chat produced no visible content; running "
                "bounded %s answer pass (reasoning_chars=%d, "
                "cap=%d, used=%d, answer_budget=%d)",
                _ns_family,
                "native tools-free" if _ns_native_tool_recovery else "thinking-off",
                len(reasoning_text or ""), _ns_cap, _ns_used,
                _ns_budget,
            )
            _ns_kwargs = dict(chat_kwargs)
            if not _ns_native_tool_recovery:
                _force_answer_pass_direct_rail(
                    _ns_kwargs,
                    family_name=_ns_family,
                )
            _ns_kwargs["max_tokens"] = _ns_budget
            _ns_ct = dict(_ns_kwargs.get("chat_template_kwargs") or {})
            if not _ns_native_tool_recovery:
                if _ns_is_m3:
                    _ns_ct["thinking_mode"] = "disabled"
                if _ns_family == "openpangu_v2":
                    _ns_ct["thinking"] = False
                _ns_ct.pop("enable_thinking", None)
            _ns_kwargs["chat_template_kwargs"] = _ns_ct
            _ns_kwargs.pop("dsv4_thinking_soft_cap", None)
            _ns_kwargs.pop("tools", None)
            _ns_kwargs.pop("_vmlx_tools_present", None)
            _ns_kwargs.pop("_vmlx_template_tools", None)
            try:
                _ns_out = await _await_chat_with_disconnect_abort(
                    engine,
                    messages=_answer_pass_messages(
                        messages, _ns_family, reasoning_text
                    ),
                    chat_kwargs=_ns_kwargs,
                    timeout=timeout,
                    fastapi_request=fastapi_request,
                    request_id=f"{response_id}:visible-answer",
                    endpoint="Chat Completions visible answer pass (non-stream)",
                    hard_timeout=request.timeout is not None,
                )
                _ns_text, _ = _answer_pass_visible_delta(
                    getattr(_ns_out, "text", "") or "",
                    "",
                    request,
                    True,
                    think_in_prompt=_ns_native_tool_recovery,
                )
                # For qwen3.5/3.6 ONLY, adopt the salvage when it actually
                # COMPLETED. A salvage that itself hit the bounded budget
                # (finish_reason="length") is an incomplete fragment: a
                # length-truncated reasoning re-continues as planning prose, so
                # surfacing that fragment leaks internal planning as the visible
                # answer (W2-1, live-proven: the model closes reasoning and
                # answers cleanly once max_tokens is large enough — the leak is
                # a symptom of a too-small output budget). Keeping the honest
                # finish_reason="length" result makes the client raise
                # max_tokens. Scoped to qwen3_5* because other families
                # (gemma4/M3/openpangu/minimax_m2/Hy3) emit a coherent worked
                # answer here — an incomplete salvage is a legitimate partial
                # answer, not a leak, and must still be surfaced (live-proven:
                # MiniMax-M2.7 truncates its visible worked solution honestly,
                # no planning leak). See streaming gate for the matching scope.
                _ns_qwen_scope = _ns_family in _ANSWER_PASS_LEAK_GUARD_FAMILIES
                # 2026-07-12 parity fix (streaming siblings): a length-truncated
                # qwen3_5* salvage is a CLEAN cut-off answer, not a planning-prose
                # leak — the direct-rail thinking-off pass does not emit <think>.
                # Discarding it left the turn EMPTY and stalled agentic loops.
                # Adopt the truncated answer; reject ONLY a genuine <think>
                # re-entry (clean_output_text does not strip <think>, so the
                # raw-text check is load-bearing).
                _ns_reasoning_leak = _ns_qwen_scope and _answer_pass_thinking_reentry(
                    getattr(_ns_out, "text", "") or ""
                )
                _ns_answer_complete = not _ns_reasoning_leak
                if _ns_text and _ns_answer_complete:
                    content_for_parsing = _ns_text
                    _ns_visible_answer_finish_reason = getattr(
                        _ns_out, "finish_reason", None
                    )
                    try:
                        output.completion_tokens += int(getattr(_ns_out, "completion_tokens", 0) or 0)
                    except Exception:
                        pass
            except Exception as _nse:
                logger.error("non-stream chat visible answer pass failed: %s", _nse)

    _cc_parse_text = _strip_think_for_tool_parse(content_for_parsing)

    # Parse tool calls from output using configured parser (skip when tool_choice="none").
    # Capture dropped-call / schema-validation diagnostics so the JSON reply
    # carries the same `warnings` the stream does (a warning that only reaches
    # the server log is not a warning the caller can act on).
    _begin_tool_call_drop_capture()
    cleaned_text, tool_calls = (
        _parse_tool_calls_with_parser(_cc_parse_text, request)
        if not _suppress_tools
        else (
            _clean_suppressed_tool_markup_for_display(
                _cc_parse_text or content_for_parsing or "",
                request,
            ),
            None,
        )
    )

    if (
        not tool_calls
        and _private_tool_candidate
        and not _suppress_tools
        and _private_reasoning_has_tool_syntax(_private_tool_candidate)
    ):
        logger.info(
            "Private reasoning contained native tool markers; parsing a "
            "structured Chat Completions call without exposing private prose"
        )
        _private_calls = _parse_private_reasoning_tool_calls(
            _private_tool_candidate, request
        )
        if _private_calls:
            tool_calls = _private_calls
            cleaned_text = ""

    structured_output_warnings: list[str] | None = None

    # Process response_format if specified
    _xml_response_config = _xml_response_format_config(response_format)
    if _xml_response_config and not tool_calls:
        _structured_report = repair_xml_output(
            cleaned_text or content_for_parsing,
            root_tag=_xml_response_config.get("root_tag"),
            required_fields=_xml_response_config.get("required_fields") or (),
        )
        if not _structured_report.get("is_valid"):
            _retry_output, _retry_report = await _retry_structured_output_xml_once(
                engine=engine,
                messages=messages,
                chat_kwargs=chat_kwargs,
                response_format=response_format,
                invalid_text=cleaned_text or content_for_parsing or "",
                error=_structured_report.get("error"),
                timeout=timeout,
                fastapi_request=fastapi_request,
                request_id=f"{response_id}-xml-retry",
                endpoint="Chat Completions",
                hard_timeout=request.timeout is not None,
            )
            if _retry_output is not None and _retry_report.get("is_valid"):
                output = _retry_output
                reasoning_text = None
                content_for_parsing = _retry_output.text
                cleaned_text = _retry_output.text
                _structured_report = _retry_report
        repaired_xml = _structured_report.get("xml")
        is_valid = bool(_structured_report.get("is_valid"))
        error = _structured_report.get("error")
        structured_output_warnings = _structured_output_repair_warning(
            _structured_report
        )
        if repaired_xml is not None:
            cleaned_text = str(repaired_xml)
        if not is_valid:
            if _xml_response_config.get("strict"):
                raise HTTPException(
                    status_code=400, detail=f"response_format strict mode: {error}"
                )
            logger.warning(f"XML validation failed: {error}")
    elif response_format and not tool_calls:
        _structured_report = repair_json_output(
            cleaned_text or content_for_parsing, response_format
        )
        if not _structured_report.get("is_valid"):
            _retry_output, _retry_report = await _retry_structured_output_json_once(
                engine=engine,
                messages=messages,
                chat_kwargs=chat_kwargs,
                response_format=response_format,
                invalid_text=cleaned_text or content_for_parsing or "",
                error=_structured_report.get("error"),
                timeout=timeout,
                fastapi_request=fastapi_request,
                request_id=f"{response_id}-json-retry",
                endpoint="Chat Completions",
                hard_timeout=request.timeout is not None,
            )
            if _retry_output is not None and _retry_report.get("is_valid"):
                output = _retry_output
                reasoning_text = None
                content_for_parsing = _retry_output.text
                cleaned_text = _retry_output.text
                _structured_report = _retry_report
        parsed_json = _structured_report.get("parsed")
        is_valid = bool(_structured_report.get("is_valid"))
        error = _structured_report.get("error")
        structured_output_warnings = _structured_output_repair_warning(
            _structured_report
        )
        if parsed_json is not None:
            # Return JSON as string
            cleaned_text = json.dumps(parsed_json)
        if not is_valid:
            # Check if strict mode is enabled — return 400 error instead of a warning
            _rf_strict = False
            if isinstance(response_format, dict):
                _rf_strict = response_format.get("json_schema", {}).get("strict", False)
            elif (
                hasattr(response_format, "json_schema") and response_format.json_schema
            ):
                _rf_strict = getattr(response_format.json_schema, "strict", False)
            if _rf_strict:
                raise HTTPException(
                    status_code=400, detail=f"response_format strict mode: {error}"
                )
            logger.warning(f"JSON validation failed: {error}")

    # Enforce tool_choice="required": model MUST produce at least one tool call
    if _is_pending_required_tool_choice(request) and not tool_calls:
        tool_required_preview = (_cc_parse_text or content_for_parsing or "")
        tool_required_preview = tool_required_preview.replace("\n", "\\n")[:500]
        logger.warning(
            f"tool_choice='required' but model produced no tool calls. "
            f"Returning error to client. raw_preview={tool_required_preview!r}"
        )
        raise HTTPException(
            status_code=400,
            detail={
                "message": (
                    f"{_describe_required_tool_choice(_tool_choice)} was set but the model did not "
                    "produce any tool calls. Try rephrasing your prompt or using a "
                    "model with better tool-calling support."
                ),
                "raw_preview": tool_required_preview,
            },
        )

    # Determine finish reason
    finish_reason = (
        "tool_calls"
        if tool_calls
        else (_ns_visible_answer_finish_reason or output.finish_reason)
    )
    response_content = clean_output_text(cleaned_text) if cleaned_text else None
    if response_content:
        response_content = _finalize_visible_text_for_request(response_content, request, minimum_partial=4)
    response_content = _drop_tool_visible_channel_marker(response_content, tool_calls)
    response_warnings = _merge_responses_warnings(
        _chat_completion_warnings_for_reasoning_only(
            response_content,
            reasoning_text,
            tool_calls,
            finish_reason,
        ),
        structured_output_warnings,
        _take_tool_call_drop_diagnostics() or None,
    )
    if (
        response_warnings
        and not response_content
        and reasoning_text
        and not tool_calls
        and _normalize_responses_finish_reason(finish_reason) != "length"
    ):
        raise HTTPException(
            status_code=502,
            detail=_reasoning_only_chat_error_payload(response_id)["error"],
        )

    # Attach the context-clamp record when the admission clamp bound this
    # request (pop regardless of outcome so the registry never leaks).
    from vmlx_engine.context_limits import (
        pop_context_clamp,
        pop_effort_substitution,
    )

    _effort_record = pop_effort_substitution(str(response_id))
    if _effort_record:
        response_warnings = list(response_warnings or []) + [
            "reasoning_effort "
            f"{_effort_record['requested_effort']!r} is not in this bundle's "
            f"stamped set {_effort_record['stamped_levels']}; ran at "
            f"{_effort_record['effective_effort']!r}"
        ]

    _clamp_record = pop_context_clamp(str(response_id))
    _context_exhaustion = None
    if _clamp_record:
        _usage_for_clamp = get_usage(output)
        _exhausted = (
            _normalize_responses_finish_reason(finish_reason) == "length"
            and int(getattr(_usage_for_clamp, "completion_tokens", 0) or 0)
            >= int(_clamp_record["clamped_max_tokens"])
        )
        _context_exhaustion = {**_clamp_record, "exhausted": _exhausted}
        _notice = (
            "output budget clamped to the model's declared context "
            f"({_clamp_record['prompt_tokens']} prompt + "
            f"{_clamp_record['requested_max_tokens']} requested > "
            f"{_clamp_record['declared_context_tokens']} declared); "
            + (
                "generation ran to the context ceiling - CONTEXT EXHAUSTED"
                if _exhausted
                else f"generating at most {_clamp_record['clamped_max_tokens']} tokens"
            )
        )
        response_warnings = list(response_warnings or []) + [_notice]

    response = ChatCompletionResponse(
        id=response_id,
        model=request.model,
        choices=[
            ChatCompletionChoice(
                message=AssistantMessage(
                    content=response_content,
                    reasoning=reasoning_text,
                    tool_calls=tool_calls,
                ),
                logprobs=_format_chat_logprobs(
                    getattr(output, "logprobs", None),
                    engine.tokenizer,
                )
                if request.logprobs
                else None,
                finish_reason=finish_reason,
            )
        ],
        usage=get_usage(output),
        warnings=response_warnings,
        context_exhaustion=_context_exhaustion,
    )

    # When tool_calls are present, serialize manually to ensure content:null is
    # included (response_model_exclude_none=True would drop it, but OpenAI
    # always includes content:null with tool_calls — required by many clients).
    if tool_calls:
        from starlette.responses import JSONResponse

        resp_dict = response.model_dump(exclude_none=True)
        # Force content:null back into the message
        for choice in resp_dict.get("choices", []):
            msg = choice.get("message", {})
            if "tool_calls" in msg and "content" not in msg:
                msg["content"] = None
        return JSONResponse(content=resp_dict)

    return response


# =============================================================================
# Responses API (OpenAI /v1/responses)
# =============================================================================


_RESPONSES_HISTORY_MAX = int(os.environ.get("VMLX_RESPONSES_HISTORY_MAX", "512"))
_responses_history: "OrderedDict[str, list[dict]]" = OrderedDict()
_responses_history_lock = threading.Lock()
# Marker set: response_ids whose stored output was reasoning-only (no visible
# text, no tool calls). Used to surface a non-fatal `warnings` field on chained
# responses. Evicted in lockstep with `_responses_history` capacity enforcement.
_responses_was_reasoning_only: set[str] = set()


def _clone_response_messages(messages: list[dict]) -> list[dict]:
    """JSON-deep-copy response history so later request mutation cannot leak."""
    try:
        return json.loads(json.dumps(messages))
    except Exception:
        return [dict(m) for m in messages if isinstance(m, dict)]


_RESPONSES_VISIBLE_PART_TYPES = {"output_text", "text"}
_RESPONSES_REASONING_ITEM_TYPES = {"reasoning", "reasoning_summary"}
_RESPONSES_REASONING_PART_TYPES = {
    "reasoning",
    "reasoning_text",
    "reasoning_summary_text",
    "summary_text",
}


def _responses_field(obj, name, default=None):
    if isinstance(obj, dict):
        return obj.get(name, default)
    return getattr(obj, name, default)


def _responses_part_text(part) -> str:
    text = _responses_field(part, "text")
    if text is None:
        text = _responses_field(part, "content")
    return text if isinstance(text, str) else ""


def _responses_reasoning_texts(item) -> list[str]:
    """Extract replayable reasoning text from a Responses reasoning item.

    vMLX returns local-model reasoning as plain text in ``content`` parts.  It
    is not merely UI metadata: native chat templates such as DeepSeek-V4 use
    prior ``reasoning_content`` when reconstructing tool-call conversations.
    Accept the standard summary/content envelopes plus the compact local form
    emitted by this server and the panel.
    """
    texts: list[str] = []
    direct = _responses_part_text(item)
    if direct:
        texts.append(direct)
    for key in ("content", "summary"):
        for part in _responses_field(item, key, []) or []:
            text = _responses_part_text(part)
            if text:
                texts.append(text)
    return texts


def _responses_output_has_reasoning(output_items: list) -> bool:
    for item in output_items or []:
        item_type = _responses_field(item, "type")
        if item_type in _RESPONSES_REASONING_ITEM_TYPES:
            return True
        for part in _responses_field(item, "content", []) or []:
            if _responses_field(part, "type") in _RESPONSES_REASONING_PART_TYPES:
                return True
    return False


def _responses_output_has_visible_or_tool(output_items: list) -> bool:
    for item in output_items or []:
        item_type = _responses_field(item, "type")
        if item_type == "function_call":
            return True
        if item_type in _RESPONSES_VISIBLE_PART_TYPES and _responses_part_text(item):
            return True
        for part in _responses_field(item, "content", []) or []:
            if (
                _responses_field(part, "type") in _RESPONSES_VISIBLE_PART_TYPES
                and _responses_part_text(part)
            ):
                return True
    return False


def _responses_output_is_reasoning_only(output_items: list) -> bool:
    return _responses_output_has_reasoning(
        output_items
    ) and not _responses_output_has_visible_or_tool(output_items)


def _stable_replayed_call_id(name: Any, arguments: Any, ordinal: int) -> str:
    """A tool-call id that is identical every time the SAME history is replayed.

    Responses replay rebuilds assistant turns from client-supplied `function_call`
    items. When such an item carries no `call_id`, minting a fresh uuid4 gave the
    call a DIFFERENT id on every request — and chat templates that render the id
    (gemma4's does) then produce different prompt bytes each turn, so the prefix
    cache goes cold from the first historical tool call onward for the rest of the
    conversation. Deriving the fallback from the call's own content keeps replay
    byte-stable; the ordinal disambiguates two identical calls in one turn.

    Only for REPLAYED history. A newly generated call still gets a random id.
    """
    payload = f"{ordinal}\x00{name}\x00{arguments}"
    return f"call_{hashlib.sha256(payload.encode('utf-8', 'replace')).hexdigest()[:8]}"


def _responses_tool_arguments_for_history(arguments: Any) -> dict:
    """Normalize Responses function arguments for native chat templates.

    Responses wire items carry ``arguments`` as a JSON string, while native
    templates (Qwen, Mistral, and others) iterate the historical argument
    mapping. Explicit replay already performs this conversion in
    ``_responses_input_to_messages``; local ``previous_response_id`` storage
    must use the identical shape or the two continuation paths tokenize
    differently.
    """
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except (json.JSONDecodeError, TypeError):
            return {}
    return arguments if isinstance(arguments, dict) else {}


def _responses_output_to_assistant_messages(output_items: list) -> list[dict]:
    """Convert a Responses output array back to chat-history assistant turns."""
    assistant_messages: list[dict] = []
    content_parts: list[str] = []
    tool_calls: list[dict] = []
    reasoning_parts: list[str] = []

    for item in output_items or []:
        item_type = _responses_field(item, "type")
        if item_type in _RESPONSES_REASONING_ITEM_TYPES:
            reasoning_parts.extend(_responses_reasoning_texts(item))
            continue
        if item_type == "function_call":
            name = _responses_field(item, "name", "")
            arguments = _responses_tool_arguments_for_history(
                _responses_field(item, "arguments", "{}")
            )
            call_id = _responses_field(item, "call_id") or _stable_replayed_call_id(
                name, arguments, len(tool_calls)
            )
            tool_calls.append(
                {
                    "id": call_id,
                    "type": "function",
                    "function": {"name": name, "arguments": arguments},
                }
            )
            continue
        content = _responses_field(item, "content") or []
        for part in content:
            ptype = _responses_field(part, "type")
            text = _responses_part_text(part)
            if ptype in _RESPONSES_VISIBLE_PART_TYPES and text:
                content_parts.append(text)
            elif ptype in _RESPONSES_REASONING_PART_TYPES:
                if text:
                    reasoning_parts.append(text)
    reasoning_text = "\n".join(reasoning_parts) if reasoning_parts else ""
    if tool_calls:
        # A Responses turn can contain visible assistant text and function_call
        # items. Store them on the same assistant turn so the next
        # function_call_output remains adjacent to assistant.tool_calls for
        # strict native chat templates.
        message = {
            "role": "assistant",
            "content": "\n".join(content_parts) if content_parts else "",
            "tool_calls": tool_calls,
        }
        if reasoning_text:
            message["reasoning_content"] = reasoning_text
        assistant_messages.append(message)
    elif content_parts:
        message = {"role": "assistant", "content": "\n".join(content_parts)}
        if reasoning_text:
            message["reasoning_content"] = reasoning_text
        assistant_messages.append(message)
    elif reasoning_text and not assistant_messages:
        # Reasoning-only output (no visible text, no tool calls): inject an
        # assistant turn so the STORE keeps the model's actual reasoning rail
        # (read by the reasoning-only chain warning and store introspection).
        # `_responses_get_history` drops this turn at replay time — no chat
        # template may receive a contentless assistant turn (strict templates
        # 500 on it), matching the drop every dialect applies to
        # client-provided input.
        assistant_messages.append(
            {
                "role": "assistant",
                "content": "",
                "reasoning_content": reasoning_text,
            }
        )
    return assistant_messages


def _responses_store_history(
    response_id: str,
    messages: list[dict],
    *,
    reasoning_only: bool = False,
) -> None:
    """Persist a Responses history slot keyed by response_id.

    Args:
        response_id: identifier returned in `ResponsesObject.id`.
        messages: the chat-history messages to store (input + replayed
            assistant turns from `_responses_output_to_assistant_messages`).
        reasoning_only: True when the response produced ONLY reasoning items
            (no visible text, no tool calls). Tracked in
            `_responses_was_reasoning_only` so chained turns can surface a
            warning to the client.
    """
    if not response_id:
        return
    with _responses_history_lock:
        _responses_history[response_id] = _clone_response_messages(messages)
        _responses_history.move_to_end(response_id)
        if reasoning_only:
            _responses_was_reasoning_only.add(response_id)
        else:
            _responses_was_reasoning_only.discard(response_id)
        # Capacity enforcement — also evict the matching reasoning-only
        # marker so the marker set never references a freed slot (would
        # otherwise give stale-warning false positives if a future
        # response_id collides via uuid prefix).
        while len(_responses_history) > _RESPONSES_HISTORY_MAX:
            evicted_id, _ = _responses_history.popitem(last=False)
            _responses_was_reasoning_only.discard(evicted_id)


def _chain_warnings_for_previous_response_id(
    previous_response_id: str | None,
) -> list[str] | None:
    """Return chain-warnings list when `previous_response_id` references a
    reasoning-only predecessor, else None.

    Used when constructing a new ResponsesObject for a chained turn so the
    client can surface coherence/cache-prefix risk without breaking the API
    contract. Always returns None for missing/unknown ids.
    """
    if not previous_response_id:
        return None
    with _responses_history_lock:
        if previous_response_id not in _responses_history:
            # The normal store path evicts marker+history in lockstep. Keep
            # the read side defensive too, so tests/admin cleanup paths that
            # clear history directly cannot leave a stale warning behind.
            _responses_was_reasoning_only.discard(previous_response_id)
            return None
        if previous_response_id not in _responses_was_reasoning_only:
            return None
    return [
        "previous_response_id chained a response that produced reasoning only "
        "(no visible message, no tool calls). Chat continuity may be impaired "
        "and prefix-cache reuse may be lower than expected. Inspect the prior "
        "response terminal status before deciding whether to retry it."
    ]


@dataclass(frozen=True)
class _ResponsesTerminalState:
    """One normalized Responses terminal contract shared by every adapter."""

    finish_reason: str | None
    response_status: str
    item_status: str
    event_type: str
    incomplete_details: dict[str, str] | None = None


def _normalize_responses_finish_reason(finish_reason: Any) -> str | None:
    """Normalize engine/adapter terminal aliases without inventing success."""

    raw = str(finish_reason or "").strip().lower()
    if not raw:
        return None
    if raw in {"abort", "aborted", "cancelled", "canceled"}:
        return "cancelled"
    if raw in {"stop", "length", "error"}:
        return raw
    return raw


def _responses_terminal_state(
    finish_reason: Any,
    *,
    cancelled: bool = False,
    failed: bool = False,
    reasoning_only_no_content: bool = False,
    request_id: str | None = None,
) -> _ResponsesTerminalState:
    """Return matching response/item status, details, and SSE terminal event."""

    normalized = _normalize_responses_finish_reason(finish_reason)
    if failed or normalized == "error":
        return _ResponsesTerminalState(
            finish_reason="error",
            response_status="failed",
            item_status="incomplete",
            event_type="response.failed",
        )
    if cancelled or normalized == "cancelled":
        return _ResponsesTerminalState(
            finish_reason="cancelled",
            response_status="incomplete",
            item_status="incomplete",
            event_type="response.incomplete",
            incomplete_details={"reason": "cancelled"},
        )
    if normalized == "length":
        # Keep the OpenAI-spec reason value; attach the context-clamp record
        # ADDITIVELY when the admission clamp bound this request so a
        # length-stop at the declared ceiling is machine-distinguishable
        # from an ordinary max_output_tokens stop (mirrors the chat
        # surfaces). Peek, not pop — this state derives more than once per
        # stream; the registry's FIFO bound handles expiry.
        _incomplete: dict[str, Any] = {"reason": "max_output_tokens"}
        if request_id:
            from vmlx_engine.context_limits import peek_context_clamp

            _clamp_record = peek_context_clamp(str(request_id))
            if _clamp_record:
                _incomplete["context_exhaustion"] = _clamp_record
        return _ResponsesTerminalState(
            finish_reason="length",
            response_status="incomplete",
            item_status="incomplete",
            event_type="response.incomplete",
            incomplete_details=_incomplete,
        )
    if reasoning_only_no_content:
        return _ResponsesTerminalState(
            finish_reason=normalized,
            response_status="incomplete",
            item_status="incomplete",
            event_type="response.incomplete",
            incomplete_details={"reason": "reasoning_only_no_content"},
        )
    return _ResponsesTerminalState(
        finish_reason=normalized,
        response_status="completed",
        item_status="completed",
        event_type="response.completed",
    )


def _current_response_warnings_for_reasoning_only(
    reasoning_only: bool,
    finish_reason: str | None = None,
) -> list[str] | None:
    if not reasoning_only:
        return None
    base = (
        "This response produced reasoning only (no visible message, no tool "
        "calls). The reasoning was preserved separately, but the visible answer "
        "is empty. "
    )
    normalized_finish = _normalize_responses_finish_reason(finish_reason)
    if normalized_finish == "length":
        detail = (
            "The maximum output-token limit was reached before a visible answer. "
            "Increase max_output_tokens or send a follow-up request to continue."
        )
    elif normalized_finish == "cancelled":
        detail = (
            "Generation ended early because the request was cancelled or aborted; "
            "this was not an output-token-limit completion."
        )
    elif normalized_finish == "stop":
        detail = (
            "The model ended normally while still in its reasoning phase; this was "
            "not output-token truncation."
        )
    elif normalized_finish == "error":
        detail = (
            "Generation reported an error while the response was still in its "
            "reasoning phase; this was not output-token truncation."
        )
    else:
        detail = (
            "The engine did not report a terminal cause, so output-token "
            "truncation must not be inferred."
        )
    return [base + detail]


def _chat_completion_warnings_for_reasoning_only(
    content: str | None,
    reasoning: str | None,
    tool_calls: list | None,
    finish_reason: str | None = None,
) -> list[str] | None:
    has_visible_content = bool((content or "").strip())
    has_reasoning = bool((reasoning or "").strip())
    has_tool_calls = bool(tool_calls)
    return _current_response_warnings_for_reasoning_only(
        has_reasoning and not has_visible_content and not has_tool_calls,
        finish_reason,
    )


def _reasoning_only_chat_error_payload(
    response_id: str,
    *,
    message: str | None = None,
) -> dict[str, Any]:
    return {
        "id": response_id,
        "object": "chat.completion.chunk",
        "error": {
            "message": message
            or (
                "The model produced reasoning_content but no visible answer and no "
                "tool call. This turn is incomplete; retry with a larger output "
                "budget or adjust the prompt/reasoning settings."
            ),
            "type": "invalid_response_error",
            "code": "reasoning_only_no_content",
        },
    }


def _merge_responses_warnings(*warning_lists: list[str] | None) -> list[str] | None:
    merged: list[str] = []
    seen: set[str] = set()
    for warnings in warning_lists:
        for warning in warnings or []:
            if not isinstance(warning, str):
                continue
            text = warning.strip()
            if not text or text in seen:
                continue
            seen.add(text)
            merged.append(text)
    return merged or None


def _plain_response_format_dict(response_format: Any) -> dict[str, Any] | None:
    if response_format is None:
        return None
    if isinstance(response_format, dict):
        return response_format
    if hasattr(response_format, "model_dump"):
        return response_format.model_dump(exclude_none=True)
    return None


def _structured_output_json_retry_instruction(
    response_format: Any,
    error: str | None,
) -> str | None:
    rf_dict = _plain_response_format_dict(response_format)
    if not isinstance(rf_dict, dict):
        return None
    rf_type = rf_dict.get("type")
    if rf_type not in {"json_object", "json_schema"}:
        return None

    lines = [
        "Please fix this JSON only.",
        "Your previous response failed structured JSON validation.",
        "Return exactly one valid JSON object or array.",
        "Do not include markdown fences, comments, explanations, or any prose.",
    ]
    if error:
        lines.append(f"Validation error: {error}")
    if rf_type == "json_schema":
        json_schema = rf_dict.get("json_schema")
        schema = (
            json_schema.get("schema")
            if isinstance(json_schema, dict)
            else None
        )
        if schema:
            lines.append("JSON Schema:")
            lines.append(json.dumps(schema, ensure_ascii=False, sort_keys=True))
    return "\n".join(lines)


def _xml_response_format_config(response_format: Any) -> dict[str, Any] | None:
    rf_dict = _plain_response_format_dict(response_format)
    if not isinstance(rf_dict, dict) or rf_dict.get("type") != "xml":
        return None
    required_fields = rf_dict.get("required_xml_fields", rf_dict.get("required_fields", ()))
    if isinstance(required_fields, str):
        required_fields = [required_fields]
    elif not isinstance(required_fields, (list, tuple)):
        required_fields = []
    return {
        "root_tag": rf_dict.get("xml_root_tag") or rf_dict.get("root_tag"),
        "required_fields": tuple(
            str(field).strip() for field in required_fields if str(field).strip()
        ),
        "strict": bool(rf_dict.get("strict", False)),
    }


def _structured_output_xml_retry_instruction(
    response_format: Any,
    error: str | None,
) -> str | None:
    config = _xml_response_format_config(response_format)
    if config is None:
        return None

    lines = [
        "Please fix this XML only.",
        "Your previous response failed structured XML validation.",
        "Return exactly one valid XML document.",
        "Do not include markdown fences, comments, explanations, or any prose.",
    ]
    root_tag = config.get("root_tag")
    if root_tag:
        lines.append(f"Root tag: {root_tag}")
    required_fields = config.get("required_fields") or ()
    if required_fields:
        lines.append(f"Required XML fields: {', '.join(required_fields)}")
    if error:
        lines.append(f"Validation error: {error}")
    return "\n".join(lines)


def _structured_retry_report(report: dict[str, Any]) -> dict[str, Any]:
    updated = dict(report)
    actions = [
        str(action)
        for action in updated.get("repair_actions", [])
        if str(action).strip()
    ]
    updated["repair_needed"] = True
    updated["repair_actions"] = list(
        dict.fromkeys(["model_retry_json_only"] + actions)
    )
    return updated


def _structured_xml_retry_report(report: dict[str, Any]) -> dict[str, Any]:
    updated = dict(report)
    actions = [
        str(action)
        for action in updated.get("repair_actions", [])
        if str(action).strip()
    ]
    updated["repair_needed"] = True
    updated["repair_actions"] = list(
        dict.fromkeys(["model_retry_xml_only"] + actions)
    )
    return updated


async def _retry_structured_output_json_once(
    *,
    engine: Any,
    messages: list[dict[str, Any]],
    chat_kwargs: dict[str, Any],
    response_format: Any,
    invalid_text: str,
    error: str | None,
    timeout: float,
    fastapi_request: Request | None,
    request_id: str,
    endpoint: str,
    hard_timeout: bool = False,
) -> tuple[GenerationOutput | None, dict[str, Any]]:
    instruction = _structured_output_json_retry_instruction(response_format, error)
    if not instruction:
        return None, {}

    retry_messages = list(messages or [])
    if invalid_text:
        retry_messages.append({"role": "assistant", "content": invalid_text})
    retry_messages.append({"role": "user", "content": instruction})

    retry_kwargs = dict(chat_kwargs)
    # The retry is a JSON-only correction pass. Keeping tool schemas in this
    # turn can make a model produce a tool call instead of the corrected object.
    retry_kwargs.pop("tools", None)
    retry_kwargs.pop("_vmlx_tools_present", None)
    retry_kwargs.pop("tool_choice", None)

    logger.info(
        "%s: retrying failed structured JSON output with JSON-only correction prompt",
        endpoint,
    )
    try:
        retry_output = await _await_chat_with_disconnect_abort(
            engine,
            messages=retry_messages,
            chat_kwargs=retry_kwargs,
            timeout=timeout,
            fastapi_request=fastapi_request,
            request_id=request_id,
            endpoint=f"{endpoint} structured JSON retry",
            hard_timeout=hard_timeout,
        )
    except Exception:
        logger.warning(
            "%s: structured JSON retry failed before producing output",
            endpoint,
            exc_info=True,
        )
        return None, {}

    retry_report = repair_json_output(retry_output.text, response_format)
    if retry_report.get("is_valid"):
        retry_report = _structured_retry_report(retry_report)
    return retry_output, retry_report


async def _retry_structured_output_xml_once(
    *,
    engine: Any,
    messages: list[dict[str, Any]],
    chat_kwargs: dict[str, Any],
    response_format: Any,
    invalid_text: str,
    error: str | None,
    timeout: float,
    fastapi_request: Request | None,
    request_id: str,
    endpoint: str,
    hard_timeout: bool = False,
) -> tuple[GenerationOutput | None, dict[str, Any]]:
    instruction = _structured_output_xml_retry_instruction(response_format, error)
    config = _xml_response_format_config(response_format)
    if not instruction or config is None:
        return None, {}

    retry_messages = list(messages or [])
    if invalid_text:
        retry_messages.append({"role": "assistant", "content": invalid_text})
    retry_messages.append({"role": "user", "content": instruction})

    retry_kwargs = dict(chat_kwargs)
    retry_kwargs.pop("tools", None)
    retry_kwargs.pop("_vmlx_tools_present", None)
    retry_kwargs.pop("tool_choice", None)

    logger.info(
        "%s: retrying failed structured XML output with XML-only correction prompt",
        endpoint,
    )
    try:
        retry_output = await _await_chat_with_disconnect_abort(
            engine,
            messages=retry_messages,
            chat_kwargs=retry_kwargs,
            timeout=timeout,
            fastapi_request=fastapi_request,
            request_id=request_id,
            endpoint=f"{endpoint} structured XML retry",
            hard_timeout=hard_timeout,
        )
    except Exception:
        logger.warning(
            "%s: structured XML retry failed before producing output",
            endpoint,
            exc_info=True,
        )
        return None, {}

    retry_report = repair_xml_output(
        retry_output.text,
        root_tag=config.get("root_tag"),
        required_fields=config.get("required_fields") or (),
    )
    if retry_report.get("is_valid"):
        retry_report = _structured_xml_retry_report(retry_report)
    return retry_output, retry_report


def _structured_output_repair_warning(report: dict | None) -> list[str] | None:
    if not isinstance(report, dict) or report.get("repair_needed") is not True:
        return None
    actions = [
        str(action)
        for action in report.get("repair_actions", [])
        if str(action).strip()
    ]
    action_text = ", ".join(actions) if actions else "unknown"
    format_name = "XML" if "xml" in report else "JSON"
    return [
        f"structured output {format_name} was repaired after generation "
        f"before returning it to the client; repair_actions={action_text}. "
        "This is post-generation repair, not guided or constrained decoding."
    ]


def _responses_get_history(response_id: str | None) -> list[dict]:
    """Return template-safe replayable history for a chained turn.

    The STORE keeps the reasoning-only assistant turn for fidelity (the
    reasoning-only chain warning and store introspection read it), but no
    template path may receive it: every dialect drops contentless assistant
    turns from request-provided input, and the server's own store must not
    reintroduce through `previous_response_id` the exact 500 that drop fixes
    (Mistral-class templates refuse an assistant turn with neither text nor
    tool calls). Dropping here, at the single replay boundary, keeps chained
    and client-replayed histories byte-consistent.
    """
    if not response_id:
        return []
    with _responses_history_lock:
        history = _responses_history.get(response_id)
        if history is None:
            return []
        _responses_history.move_to_end(response_id)
        history = _clone_response_messages(history)
    return _drop_contentless_assistant_turns(history)


def _responses_scrub_multimodal_history_for_text_followup(messages: list[dict]) -> list[dict]:
    """Drop replayed media payloads when a chained Responses turn is text-only.

    `previous_response_id` history is prepended to the new turn. If an earlier
    user turn contained image/video/audio parts, a later text-only follow-up
    would otherwise replay those media parts and can re-trigger VLM prefill
    budget rejection even though the user did not attach media to the new turn.
    Preserve textual context and tool/assistant turns; do not use this for
    media-bearing follow-ups.
    """
    scrubbed: list[dict] = []
    for message in messages or []:
        if not isinstance(message, dict):
            scrubbed.append(message)
            continue
        content = message.get("content")
        if isinstance(content, list) and _content_has_multimodal(content):
            replacement = dict(message)
            replacement["content"] = _extract_text_from_content(content)
            scrubbed.append(replacement)
        else:
            scrubbed.append(message)
    return scrubbed


def _responses_should_scrub_multimodal_history_for_followup(
    input_data: str | list,
    *,
    current_request_has_media: bool,
) -> bool:
    """Decide whether a chained text request may discard prior media payloads.

    A normal text-only follow-up should not re-run old image/video/audio
    encoders. A ``function_call_output`` request is different: it is the
    continuation of the same assistant turn that consumed the media. Scrubbing
    at that boundary makes the model forget media-derived facts between its
    tool call and final answer. Keep prior media for that one logical tool loop;
    later ordinary text turns retain the existing scrub behavior.
    """
    if current_request_has_media:
        return False
    if not isinstance(input_data, list):
        return True
    return not any(
        _responses_field(item, "type") == "function_call_output"
        for item in input_data
    )


def _extract_text_from_content(content) -> str:
    """Extract plain text from a content field that may be a string or list of parts."""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        # Content parts: [{"type": "input_text", "text": "..."}, ...]
        parts = []
        for part in content:
            if isinstance(part, dict):
                parts.append(part.get("text", part.get("content", "")))
            elif isinstance(part, str):
                parts.append(part)
        return "\n".join(p for p in parts if p)
    return str(content) if content else ""


def _normalize_leading_system_messages(
    messages: list[dict],
    *,
    preserve_native_order: bool = False,
) -> list[dict]:
    """Merge all system/developer messages into one leading system message.

    Some tokenizer templates, including Qwen-family templates, reject a system
    message anywhere after the first user/assistant/tool turn. Responses
    follow-ups can create that shape when previous_response_id history is
    prepended before a new request with instructions. Treat system/developer
    content as global instructions and keep non-system turns in order.

    DeepSeek V4 is the explicit exception: its official Python encoder owns
    message order and has a distinct ``latest_reminder`` role for tail
    reminders.  Hoisting a later system message changes the beginning of the
    token sequence and destroys an otherwise reusable prompt prefix.  Callers
    must opt into native ordering only after resolving the loaded family; this
    helper never rewrites ``system`` into ``latest_reminder``.
    """
    if not messages:
        return messages
    if preserve_native_order:
        return list(messages)

    system_template: dict | None = None
    system_parts: list[str] = []
    seen_system_parts: set[str] = set()
    non_system: list[dict] = []

    for msg in messages:
        role = msg.get("role") if isinstance(msg, dict) else getattr(msg, "role", None)
        if role in ("system", "developer"):
            if system_template is None:
                system_template = dict(msg) if isinstance(msg, dict) else {
                    "role": "system",
                    "content": getattr(msg, "content", ""),
                }
            text = _extract_text_from_content(
                msg.get("content") if isinstance(msg, dict) else getattr(msg, "content", "")
            ).strip()
            if text and text not in seen_system_parts:
                system_parts.append(text)
                seen_system_parts.add(text)
            continue
        non_system.append(msg)

    if system_template is None:
        return list(messages)

    merged_system = dict(system_template)
    merged_system["role"] = "system"
    merged_system["content"] = "\n\n".join(system_parts)
    return [merged_system] + non_system


def _responses_input_to_messages(
    input_data: str | list,
    instructions: str | None = None,
    preserve_multimodal: bool = False,
) -> list[dict]:
    """Convert Responses API input to chat messages format.

    Handles all Responses API input item types:
    - {"role": "user/assistant/system", "content": "..."} → standard messages
    - {"type": "message", "role": "...", "content": [...]} → message with content parts
    - {"type": "function_call", "name": "...", "call_id": "...", "arguments": "..."} → tool call
    - {"type": "function_call_output", "call_id": "...", "output": "..."} → tool result

    Args:
        preserve_multimodal: When True (MLLM models), preserve content arrays with
            image_url/video_url parts instead of extracting text only. MLLM engines
            extract images from message content internally.
    """

    def _drop_none_fields(value):
        """Recursively drop absent optional fields before MLLM templating.

        Multimodal chat templates commonly test key presence (for example
        ``'image_url' in item``) before reading nested values. Pydantic content
        parts can carry optional keys with ``None`` values, which makes text
        parts look like image/audio/video parts. Preserve the user-provided
        media/text structure, but remove absent optional fields at every level
        before the tokenizer sees Responses history.
        """
        if hasattr(value, "model_dump"):
            return value.model_dump(exclude_none=True)
        if isinstance(value, dict):
            return {
                key: _drop_none_fields(item)
                for key, item in value.items()
                if item is not None
            }
        if isinstance(value, list):
            return [_drop_none_fields(item) for item in value]
        return value

    def _resolve_content(raw_content):
        """Resolve content: preserve arrays for MLLM, extract text for LLM."""
        if preserve_multimodal and isinstance(raw_content, list):
            # Convert Pydantic content parts to clean dicts (exclude None fields)
            # to avoid template issues where 'image_url' in item returns True
            # for text items that have image_url=None as a model field.
            clean_parts = []
            for p in raw_content:
                clean_parts.append(_drop_none_fields(p))
            # OpenAI Responses API uses `input_image` / `input_video` /
            # `input_audio` as the canonical content-part types (with
            # `image_url` / `audio` etc. as sub-fields), distinct from
            # the chat-completions API's `image_url` / `video_url` types.
            # Both shapes must be detected as media-bearing AND normalized
            # so downstream multimodal extraction (`extract_media_from_messages`,
            # OmniMultimodalDispatcher) sees a uniform shape.
            # Live test 2026-04-30 with /v1/responses + input_image → empty
            # response (model never saw the image) was traced to this gap.
            _MEDIA_TYPES = {
                "image_url", "image", "video_url", "video", "input_audio",
                "input_image", "input_video",
            }
            has_media = any(
                isinstance(p, dict) and p.get("type") in _MEDIA_TYPES
                for p in clean_parts
            )
            if has_media:
                # Normalize Responses-API shapes → chat-completions shapes
                # so downstream code paths (which expect image_url +
                # video_url + input_audio) get a consistent envelope.
                normalized = []
                for p in clean_parts:
                    if not isinstance(p, dict):
                        normalized.append(p); continue
                    t = p.get("type")
                    if t == "input_image":
                        # `input_image: {image_url: "data:image/...;base64,..."}`
                        url = p.get("image_url")
                        if isinstance(url, dict):
                            url = url.get("url")
                        if url:
                            normalized.append({"type": "image_url",
                                               "image_url": _drop_none_fields({"url": url})})
                        else:
                            # a media-typed part with no readable source used
                            # to pass through and be ignored downstream (the
                            # request then succeeded text-only)
                            raise MediaInputError(
                                "input_image part has no readable source: expected "
                                "'image_url' (a URL, data: URL or local path); "
                                f"got keys {sorted(k for k in p if k != 'type')}"
                            )
                    elif t == "input_video":
                        url = p.get("video_url")
                        if isinstance(url, dict):
                            url = url.get("url")
                        if url:
                            normalized.append({"type": "video_url",
                                               "video_url": _drop_none_fields({"url": url})})
                        else:
                            raise MediaInputError(
                                "input_video part has no readable source: expected "
                                "'video_url' (a URL, data: URL or local path); "
                                f"got keys {sorted(k for k in p if k != 'type')}"
                            )
                    elif t == "input_text":
                        # OpenAI Responses uses input_text; chat completions
                        # uses just `text`. Re-tag for consistency.
                        normalized.append({"type": "text",
                                           "text": p.get("text", "")})
                    else:
                        normalized.append(p)
                return normalized
        return _extract_text_from_content(raw_content)

    messages = []

    # Add system/instructions message
    if instructions:
        messages.append({"role": "system", "content": instructions})

    # Handle string input (simple prompt)
    if isinstance(input_data, str):
        messages.append({"role": "user", "content": input_data})
        return messages

    # Handle list of input items
    # Each function_call becomes its own assistant message with a single tool_call
    # (many models only support single tool-calls per message)
    # function_call_output becomes a tool message

    def _normalize_role(role: str) -> str:
        """Map 'developer' role to 'system' (OpenAI API compatibility)."""
        return "system" if role == "developer" else role

    pending_reasoning_parts: list[str] = []
    pending_visible_assistant: dict | None = None

    def _take_pending_reasoning() -> str:
        text = "\n".join(pending_reasoning_parts)
        pending_reasoning_parts.clear()
        return text

    def _flush_pending_visible_assistant() -> None:
        nonlocal pending_visible_assistant
        if pending_visible_assistant is not None:
            messages.append(pending_visible_assistant)
            pending_visible_assistant = None

    # Ordinal disambiguates two identical replayed calls in one turn while
    # keeping the derived id stable across requests.
    _replayed_call_ordinal = [0]

    for item in input_data:
        if not isinstance(item, dict):
            if hasattr(item, "role"):
                role = _normalize_role(item.role)
                raw = item.content if hasattr(item, "content") else ""
                msg: dict = {"role": role, "content": _resolve_content(raw)}
                reasoning = getattr(item, "reasoning_content", None) or getattr(
                    item, "reasoning", None
                )
                if role == "assistant" and reasoning:
                    msg["reasoning_content"] = reasoning
                if hasattr(item, "tool_calls") and item.tool_calls:
                    msg["tool_calls"] = (
                        item.tool_calls
                        if isinstance(item.tool_calls, list)
                        else [item.tool_calls]
                    )
                    if msg.get("content") is None:
                        msg["content"] = ""
                if hasattr(item, "tool_call_id") and item.tool_call_id:
                    msg["tool_call_id"] = item.tool_call_id
                messages.append(msg)
            continue

        item_type = item.get("type", "")

        # Responses output reasoning items are valid multi-turn input.  Keep
        # their text pending until the following assistant function_call or
        # output_text item so native templates receive one correctly ordered
        # assistant turn with ``reasoning_content``.
        if item_type in _RESPONSES_REASONING_ITEM_TYPES:
            # A reasoning item after visible output begins a new assistant
            # generation. Commit the previous visible turn before collecting
            # reasoning for the next one.
            _flush_pending_visible_assistant()
            pending_reasoning_parts.extend(_responses_reasoning_texts(item))
            continue

        # function_call → assistant message with single tool_call
        if item_type == "function_call":
            call_id = item.get("call_id") or _stable_replayed_call_id(
                item.get("name", ""), item.get("arguments", "{}"), _replayed_call_ordinal[0]
            )
            _replayed_call_ordinal[0] += 1
            # Parse arguments to dict — chat templates (Qwen3, Llama, etc.)
            # call .items() on arguments, so they must be a mapping, not a string
            args_raw = item.get("arguments", "{}")
            if isinstance(args_raw, str):
                try:
                    args_parsed = json.loads(args_raw)
                except (json.JSONDecodeError, TypeError):
                    args_parsed = {}
            else:
                args_parsed = args_raw if args_raw else {}
            tool_call = {
                "id": call_id,
                "type": "function",
                "function": {
                    "name": item.get("name", ""),
                    "arguments": args_parsed,
                },
            }
            if pending_visible_assistant is not None:
                # Responses permits one assistant generation to contain both
                # output_text and function_call items. Electron emits those as
                # reasoning -> output_text -> function_call. Keep all three on
                # the same native assistant turn; splitting them creates an
                # empty <think></think> tool-call exemplar in templates such as
                # Laguna/Poolside and breaks tool-result adjacency.
                message = pending_visible_assistant
                pending_visible_assistant = None
                message["tool_calls"] = [tool_call]
                messages.append(message)
            elif (
                messages
                and isinstance(messages[-1], dict)
                and messages[-1].get("role") == "assistant"
                and messages[-1].get("tool_calls")
                and not pending_reasoning_parts
            ):
                # Parallel tool calls: one assistant generation emits several
                # function_call items back-to-back (nothing between them).
                # Chain replay via previous_response_id coalesces them into
                # ONE assistant turn (_responses_output_to_assistant_messages);
                # the explicit-replay path must build the identical shape or
                # the two continuation modes tokenize differently — splitting
                # the prompt prefix cache and producing consecutive assistant
                # turns that strict-alternation templates reject (dialect F3).
                messages[-1]["tool_calls"].append(tool_call)
            else:
                message = {
                    "role": "assistant",
                    # Tool-call-only assistant turns are valid Responses/OpenAI
                    # history anchors. Use an empty string instead of None:
                    # strict templates such as Mistral 4 accept the tool_calls
                    # but later evaluate `message['content'] | length`, which
                    # crashes on None.
                    "content": "",
                    "tool_calls": [tool_call],
                }
                reasoning = _take_pending_reasoning()
                if reasoning:
                    message["reasoning_content"] = reasoning
                messages.append(message)
            continue

        # function_call_output → tool message with result
        if item_type == "function_call_output":
            _flush_pending_visible_assistant()
            messages.append(
                {
                    "role": "tool",
                    "tool_call_id": item.get("call_id", ""),
                    "content": item.get("output", ""),
                }
            )
            continue

        # output_text is how the panel preserves assistant text between
        # Responses API follow-up calls (including tool auto-continue). Treat
        # it as an assistant message when converting back to Chat Completions
        # history; skipping it makes continuation forget the model's previous
        # answer/context after a tool round.
        if item_type == "output_text":
            text = item.get("text", "")
            reasoning = _take_pending_reasoning()
            if text or reasoning:
                message = {"role": "assistant", "content": text}
                if reasoning:
                    message["reasoning_content"] = reasoning
                # Delay emission by one item so a following function_call from
                # the same Responses generation can be attached to this turn.
                _flush_pending_visible_assistant()
                pending_visible_assistant = message
            continue

        # message type with content parts
        if item_type == "message":
            _flush_pending_visible_assistant()
            role = _normalize_role(item.get("role", "user"))
            content = _resolve_content(item.get("content", ""))
            message = {"role": role, "content": content}
            if role == "assistant":
                reasoning = (
                    item.get("reasoning_content")
                    or item.get("reasoning")
                    or _take_pending_reasoning()
                )
                if reasoning:
                    message["reasoning_content"] = reasoning
            messages.append(message)
        # Standard role-based message (no type field, or type is not a special one)
        elif "role" in item:
            _flush_pending_visible_assistant()
            role = _normalize_role(item.get("role", "user"))
            # Preserve tool messages with tool_call_id (Chat Completions format)
            if role == "tool" and "tool_call_id" in item:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": item["tool_call_id"],
                        "content": _extract_text_from_content(item.get("content", "")),
                    }
                )
            # Preserve assistant messages with tool_calls (Chat Completions format)
            elif role == "assistant" and "tool_calls" in item:
                _assistant_content = item.get("content")
                if _assistant_content is None:
                    _assistant_content = ""
                message = {
                    "role": "assistant",
                    "content": _assistant_content,
                    "tool_calls": item["tool_calls"],
                }
                reasoning = (
                    item.get("reasoning_content")
                    or item.get("reasoning")
                    or _take_pending_reasoning()
                )
                if reasoning:
                    message["reasoning_content"] = reasoning
                messages.append(message)
            else:
                content = _resolve_content(item.get("content", ""))
                message = {"role": role, "content": content}
                if role == "assistant":
                    reasoning = (
                        item.get("reasoning_content")
                        or item.get("reasoning")
                        or _take_pending_reasoning()
                    )
                    if reasoning:
                        message["reasoning_content"] = reasoning
                messages.append(message)
        # Skip unknown item types (e.g. reasoning, web_search_call, etc.)

    _flush_pending_visible_assistant()

    if pending_reasoning_parts:
        # Preserve a trailing reasoning-only input item as a completed
        # assistant turn instead of silently collapsing user→user history.
        messages.append(
            {
                "role": "assistant",
                "content": "",
                "reasoning_content": _take_pending_reasoning(),
            }
        )

    # Responses clients may send a previous response as function_call /
    # function_call_output items without also replaying the original user
    # prompt that caused the call. Native chat templates still need a valid
    # user→assistant ordering anchor before assistant tool_calls. DSV4 is
    # especially sensitive here: a leading assistant DSML block after system
    # prompt can produce only "<think></think>" on continuation. Insert a
    # neutral user anchor before a leading assistant tool-call turn; models
    # still see the actual tool result and the real follow-up user message.
    first_non_system = next(
        (
            idx
            for idx, msg in enumerate(messages)
            if msg.get("role") not in ("system", "developer")
        ),
        None,
    )
    if first_non_system is not None:
        first_msg = messages[first_non_system]
        if first_msg.get("role") == "assistant" and first_msg.get("tool_calls"):
            messages.insert(
                first_non_system,
                {
                    "role": "user",
                    "content": "Previous assistant tool-call history follows.",
                },
            )

    # Drop assistant turns that carry neither text nor a tool call. A reply that
    # spends its whole budget on reasoning finishes with `length` and an empty
    # answer -- the never-empty contract permits that -- and replaying it hands
    # the chat template an assistant message it refuses to render: Mistral's
    # raises TemplateError("Assistant message must have a string or a list of
    # chunks in content or a list of tool calls"), so the caller gets a 500 for
    # echoing back the turn we gave them.
    #
    # This mirrors the same drop on the chat-completions path. It has to exist
    # in BOTH: /v1/responses builds its messages here, not there, and the app
    # talks to /v1/responses -- fixing only the other one would leave the
    # surface users actually hit still broken.
    #
    # Filling with "" is NOT a fix: Mistral's template rejects the empty string
    # exactly as it rejects a missing key (verified against the real tokenizer).
    messages = _drop_contentless_assistant_turns(messages)

    return messages


def _coerce_orphan_tool_messages_for_template(messages: list[dict]) -> list[dict]:
    """Preserve orphan tool outputs as text instead of native tool messages.

    Strict native templates such as Gemma4 render a ``role=tool`` message by
    looking backward for a matching assistant ``tool_calls[].id``. Responses
    history from UI/tool auto-continue can contain a tool result without that
    native anchor. Passing it through as ``role=tool`` makes the template's
    tool name ``None`` and crashes during rendering. Do not fabricate a missing
    tool call; keep the output in context as visible history text.
    """
    active_tool_call_ids: set[str] = set()
    coerced: list[dict] = []
    for msg in messages:
        role = msg.get("role") if isinstance(msg, dict) else None
        if role == "assistant":
            active_tool_call_ids = set()
            for tc in msg.get("tool_calls") or []:
                if not isinstance(tc, dict):
                    continue
                tc_id = tc.get("id")
                if isinstance(tc_id, str) and tc_id:
                    active_tool_call_ids.add(tc_id)
        if role == "tool":
            tool_call_id = msg.get("tool_call_id")
            if not isinstance(tool_call_id, str) or tool_call_id not in active_tool_call_ids:
                content = _extract_text_from_content(msg.get("content", ""))
                label = tool_call_id if isinstance(tool_call_id, str) and tool_call_id else "unknown"
                coerced.append(
                    {
                        "role": "user",
                        "content": f"Tool result ({label}):\n{content}",
                    }
                )
                continue
        elif role not in ("assistant", "system", "developer"):
            # Responses request-scoped instructions are normalized to the
            # leading system slot after this pass. They do not break native
            # adjacency between a restored assistant tool call and the current
            # function_call_output. Reset only on an actual conversation turn.
            active_tool_call_ids = set()
        coerced.append(msg)
    return coerced


def _zaya_vl_text_part(text: str) -> list[dict[str, str]]:
    return [{"type": "text", "text": text}]


def _render_zaya_tool_call_history(tool_calls: list) -> str:
    blocks: list[str] = []
    for tc in tool_calls or []:
        if hasattr(tc, "model_dump"):
            tc = tc.model_dump()
        elif hasattr(tc, "dict"):
            tc = tc.dict()
        if not isinstance(tc, dict):
            continue
        fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
        name = fn.get("name") or ""
        if not name:
            continue
        args = fn.get("arguments") or {}
        if isinstance(args, str):
            try:
                args = json.loads(args)
            except Exception:
                args = {}
        lines = ["<zyphra_tool_call>", f"<function={name}>"]
        if isinstance(args, dict):
            for key, value in args.items():
                if not isinstance(value, str):
                    value = json.dumps(value, ensure_ascii=False)
                lines.extend([f"<parameter={key}>", value, "</parameter>"])
        lines.extend(["</function>", "</zyphra_tool_call>"])
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks)


def _render_zaya_tool_response_text(msg: dict) -> str:
    content = _extract_text_from_content(msg.get("content", ""))
    tool_name = str(msg.get("name") or "tool").strip() or "tool"
    try:
        parsed = json.loads(content)
    except Exception:
        parsed = None
    if isinstance(parsed, dict):
        stored = parsed.get("stored")
        if isinstance(stored, str) and stored:
            if tool_name == "record_fact":
                return f"STORED {stored}"
            return f"{tool_name} result: {stored}"
    return content


def _zaya_vl_text_from_part_list(content: Any) -> str | None:
    if isinstance(content, list):
        parts: list[str] = []
        for item in content:
            if not isinstance(item, dict) or item.get("type") != "text":
                return None
            text = item.get("text")
            if isinstance(text, str):
                parts.append(text)
        return "\n".join(parts)
    if isinstance(content, str):
        return content
    return None


def _merge_zaya_vl_adjacent_user_text(messages: list[dict]) -> list[dict]:
    merged: list[dict] = []
    for msg in messages:
        if (
            merged
            and isinstance(msg, dict)
            and isinstance(merged[-1], dict)
            and msg.get("role") == "user"
            and merged[-1].get("role") == "user"
        ):
            previous_text = _zaya_vl_text_from_part_list(merged[-1].get("content"))
            current_text = _zaya_vl_text_from_part_list(msg.get("content"))
            if previous_text is not None and current_text is not None:
                merged[-1] = {
                    **merged[-1],
                    "content": _zaya_vl_text_part(
                        previous_text.rstrip() + "\n\n" + current_text.lstrip()
                    ),
                }
                continue
        merged.append(msg)
    return merged


def _coerce_zaya_vl_tool_history_for_template(messages: list[dict]) -> list[dict]:
    """Render ZAYA-VL tool history as text parts instead of role=tool turns.

    ZAYA-VL's template is multimodal/list-content aware, but it does not have a
    native role="tool" contract. Preserving OpenAI tool messages renders
    ``<|im_start|>tool`` and live runs showed the model continuing in visual
    grounding tokens (``<|point_start|>tool``). Keep zaya_xml output parsing
    native, but serialize prior calls/results as ordinary text parts.
    """
    coerced: list[dict] = []
    for msg in messages or []:
        if not isinstance(msg, dict):
            coerced.append(msg)
            continue
        role = msg.get("role")
        if role == "assistant" and msg.get("tool_calls"):
            rendered = _render_zaya_tool_call_history(msg.get("tool_calls") or [])
            if rendered:
                coerced.append(
                    {
                        "role": "user",
                        "content": _zaya_vl_text_part(
                            "Previous assistant tool call:\n" + rendered
                        ),
                    }
                )
            else:
                coerced.append(msg)
            continue
        if role == "tool":
            content = _render_zaya_tool_response_text(msg)
            coerced.append(
                {
                    "role": "user",
                    "content": _zaya_vl_text_part("Tool response: " + content),
                }
            )
            continue
        if role in {"user", "assistant", "system"} and isinstance(msg.get("content"), str):
            coerced.append({**msg, "content": _zaya_vl_text_part(msg.get("content", ""))})
            continue
        coerced.append(msg)
    return _merge_zaya_vl_adjacent_user_text(coerced)


def _should_coerce_zaya_vl_tool_history(model_hint: str | None = None) -> bool:
    try:
        from .model_config_registry import get_model_config_registry

        cfg = get_model_config_registry().lookup(
            _model_path or _model_name or model_hint or ""
        )
        return cfg.family_name == "zaya1_vl"
    except Exception:
        return False


def _synthesize_tools_from_message_tool_calls(messages: list[dict]) -> list[dict]:
    """Build minimal tool schemas from assistant tool-call history.

    Responses follow-up requests can replay prior ``function_call`` and
    ``function_call_output`` items without including the original ``tools``
    array. Some native templates (notably DSV4 DSML) need tool definitions on
    the system prompt to render tool-call conversations correctly, even when
    the current request is not allowed to call tools. Infer a conservative
    schema from historical arguments so the prompt has the missing context.
    """
    by_name: dict[str, dict] = {}
    for msg in messages or []:
        if not isinstance(msg, dict) or msg.get("role") != "assistant":
            continue
        for tc in msg.get("tool_calls") or []:
            if not isinstance(tc, dict):
                continue
            fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
            name = fn.get("name")
            if not isinstance(name, str) or not name:
                continue
            args = fn.get("arguments") or {}
            if isinstance(args, str):
                try:
                    args = json.loads(args)
                except Exception:
                    args = {}
            props = {}
            required = []
            if isinstance(args, dict):
                for key, value in args.items():
                    if not isinstance(key, str) or not key:
                        continue
                    if isinstance(value, bool):
                        typ = "boolean"
                    elif isinstance(value, int):
                        typ = "integer"
                    elif isinstance(value, float):
                        typ = "number"
                    elif isinstance(value, list):
                        typ = "array"
                    elif isinstance(value, dict):
                        typ = "object"
                    else:
                        typ = "string"
                    props[key] = {"type": typ}
                    required.append(key)
            by_name.setdefault(
                name,
                {
                    "type": "function",
                    "function": {
                        "name": name,
                        "description": (
                            "Previously available tool from conversation history."
                        ),
                        "parameters": {
                            "type": "object",
                            "properties": props,
                            "required": required,
                        },
                    },
                },
            )
    return list(by_name.values())


def _adapt_omni_chat_completion_to_responses_payload(
    chat_completion: dict,
    model: str,
) -> dict:
    """Translate a completed Omni Chat response without collapsing reasoning.

    The Omni runtime speaks Chat Completions internally.  Responses clients
    still require reasoning to be a distinct ``reasoning`` output item; putting
    it in the message or dropping it makes non-stream and stream behavior
    disagree and breaks continuation clients that replay the output array.
    """
    choice = (chat_completion.get("choices") or [{}])[0]
    message = choice.get("message") or {}
    visible_text = message.get("content") or ""
    reasoning_text = message.get("reasoning_content") or ""
    finish_reason = choice.get("finish_reason")
    terminal = _responses_terminal_state(
        finish_reason,
        reasoning_only_no_content=bool(reasoning_text and not visible_text),
    )
    usage = chat_completion.get("usage") or {}

    output: list[dict] = []
    if reasoning_text:
        output.append(
            {
                "id": f"rs_{uuid.uuid4().hex[:12]}",
                "type": "reasoning",
                "status": terminal.item_status,
                "summary": [
                    {"type": "summary_text", "text": reasoning_text}
                ],
                "content": [],
            }
        )
    if visible_text or not reasoning_text:
        output.append(
            {
                "type": "message",
                "id": f"msg_{uuid.uuid4().hex[:12]}",
                "status": terminal.item_status,
                "role": "assistant",
                "content": [
                    {
                        "type": "output_text",
                        "text": visible_text,
                        "annotations": [],
                    }
                ],
            }
        )

    payload = {
        "id": f"resp_{uuid.uuid4().hex[:12]}",
        "object": "response",
        "created_at": chat_completion.get("created", int(time.time())),
        "model": model,
        "status": terminal.response_status,
        "output_text": visible_text,
        "output": output,
        "usage": {
            "input_tokens": usage.get("prompt_tokens", 0),
            "output_tokens": usage.get("completion_tokens", 0),
            "total_tokens": usage.get("total_tokens", 0),
        },
    }
    if terminal.incomplete_details:
        payload["incomplete_details"] = terminal.incomplete_details
    reasoning_only_warnings = _current_response_warnings_for_reasoning_only(
        bool(reasoning_text and not visible_text),
        finish_reason,
    )
    if reasoning_only_warnings:
        payload["warnings"] = reasoning_only_warnings
    return payload


async def _adapt_omni_chat_stream_to_responses(
    chat_stream: StreamingResponse,
    request: ResponsesRequest,
    *,
    history_messages: list[dict] | None = None,
) -> AsyncIterator[str]:
    """Translate a live Omni Chat SSE stream into native Responses events."""
    response_id = f"resp_{uuid.uuid4().hex[:12]}"
    msg_id = f"item_{uuid.uuid4().hex[:12]}"
    reasoning_item_id = f"rs_{uuid.uuid4().hex[:12]}"
    next_output_index = 0
    message_output_index: int | None = None
    reasoning_output_index: int | None = None
    message_item_started = False
    reasoning_item_started = False
    reasoning_item_finished = False
    reasoning_item: dict | None = None
    output_items_by_index: dict[int, dict] = {}
    created_at = int(time.time())
    seq = 0

    def _sse(event_type: str, data: dict) -> str:
        nonlocal seq
        data["sequence_number"] = seq
        seq += 1
        return (
            f"event: {event_type}\n"
            f"data: {json.dumps(data, ensure_ascii=True)}\n\n"
        )

    def _start_reasoning_item_events() -> list[str]:
        nonlocal reasoning_item_started, reasoning_output_index, next_output_index
        if reasoning_item_started:
            return []
        reasoning_item_started = True
        reasoning_output_index = next_output_index
        next_output_index += 1
        return [
            _sse(
                "response.output_item.added",
                {
                    "type": "response.output_item.added",
                    "output_index": reasoning_output_index,
                    "item": {
                        "id": reasoning_item_id,
                        "type": "reasoning",
                        "status": "in_progress",
                        "summary": [],
                        "content": [],
                    },
                },
            ),
            _sse(
                "response.reasoning_summary_part.added",
                {
                    "type": "response.reasoning_summary_part.added",
                    "item_id": reasoning_item_id,
                    "output_index": reasoning_output_index,
                    "summary_index": 0,
                    "part": {"type": "summary_text", "text": ""},
                },
            ),
        ]

    def _start_message_item_events() -> list[str]:
        nonlocal message_item_started, message_output_index, next_output_index
        if message_item_started:
            return []
        message_item_started = True
        message_output_index = next_output_index
        next_output_index += 1
        return [
            _sse(
                "response.output_item.added",
                {
                    "type": "response.output_item.added",
                    "output_index": message_output_index,
                    "item": {
                        "id": msg_id,
                        "type": "message",
                        "status": "in_progress",
                        "role": "assistant",
                        "content": [],
                    },
                },
            ),
            _sse(
                "response.content_part.added",
                {
                    "type": "response.content_part.added",
                    "item_id": msg_id,
                    "output_index": message_output_index,
                    "content_index": 0,
                    "part": {
                        "type": "output_text",
                        "text": "",
                        "annotations": [],
                    },
                },
            ),
        ]

    def _finish_reasoning_item_events(
        text: str,
        *,
        status: str = "completed",
    ) -> list[str]:
        nonlocal reasoning_item_finished, reasoning_item
        if reasoning_item_finished or not text:
            return []
        events = _start_reasoning_item_events()
        reasoning_item_finished = True
        summary_part = {"type": "summary_text", "text": text}
        reasoning_item = {
            "id": reasoning_item_id,
            "type": "reasoning",
            "status": status,
            "summary": [summary_part],
            "content": [],
        }
        events.extend(
            [
                _sse(
                    "response.reasoning_summary_text.done",
                    {
                        "type": "response.reasoning_summary_text.done",
                        "item_id": reasoning_item_id,
                        "output_index": reasoning_output_index,
                        "summary_index": 0,
                        "text": text,
                    },
                ),
                _sse(
                    "response.reasoning_summary_part.done",
                    {
                        "type": "response.reasoning_summary_part.done",
                        "item_id": reasoning_item_id,
                        "output_index": reasoning_output_index,
                        "summary_index": 0,
                        "part": summary_part,
                    },
                ),
                _sse(
                    "response.output_item.done",
                    {
                        "type": "response.output_item.done",
                        "output_index": reasoning_output_index,
                        "item": reasoning_item,
                    },
                ),
            ]
        )
        if reasoning_output_index is None:
            raise RuntimeError("Omni reasoning item finalized before allocation")
        output_items_by_index[reasoning_output_index] = reasoning_item
        return events

    yield _sse(
        "response.created",
        {
            "type": "response.created",
            "response": {
                "id": response_id,
                "object": "response",
                "created_at": created_at,
                "status": "in_progress",
                "model": request.model,
                "output": [],
            },
        },
    )
    reasoning_text = ""
    content_text = ""
    finish_reason = None
    usage = {"input_tokens": 0, "output_tokens": 0, "total_tokens": 0}
    raw_buffer = ""
    stream_failed = False

    async def _handle_payload(payload: dict) -> AsyncIterator[str]:
        nonlocal reasoning_text, content_text, finish_reason, usage, stream_failed
        if isinstance(payload.get("error"), dict):
            stream_failed = True
            error = payload["error"]
            yield _sse(
                "error",
                {
                    "type": "error",
                    "error": {
                        "type": error.get("type", "server_error"),
                        "message": error.get(
                            "message", "Omni multimodal generation failed"
                        ),
                        **({"code": error["code"]} if error.get("code") else {}),
                    },
                },
            )
            return
        choices = payload.get("choices") or []
        if choices:
            choice = choices[0] or {}
            delta = choice.get("delta") or {}
            reasoning_delta = delta.get("reasoning_content") or ""
            content_delta = delta.get("content") or ""
            if reasoning_delta:
                reasoning_text += reasoning_delta
                for event in _start_reasoning_item_events():
                    yield event
                yield _sse(
                    "response.reasoning_summary_text.delta",
                    {
                        "type": "response.reasoning_summary_text.delta",
                        "item_id": reasoning_item_id,
                        "output_index": reasoning_output_index,
                        "summary_index": 0,
                        "delta": reasoning_delta,
                    },
                )
            if content_delta:
                if reasoning_item_started and not reasoning_item_finished:
                    for event in _finish_reasoning_item_events(reasoning_text):
                        yield event
                for event in _start_message_item_events():
                    yield event
                content_text += content_delta
                yield _sse(
                    "response.output_text.delta",
                    {
                        "type": "response.output_text.delta",
                        "item_id": msg_id,
                        "output_index": message_output_index,
                        "content_index": 0,
                        "delta": content_delta,
                    },
                )
            if choice.get("finish_reason"):
                finish_reason = str(choice["finish_reason"])
        chat_usage = payload.get("usage")
        if isinstance(chat_usage, dict):
            prompt_tokens = int(chat_usage.get("prompt_tokens") or 0)
            completion_tokens = int(chat_usage.get("completion_tokens") or 0)
            usage = {
                "input_tokens": prompt_tokens,
                "output_tokens": completion_tokens,
                "total_tokens": int(
                    chat_usage.get("total_tokens")
                    or prompt_tokens + completion_tokens
                ),
            }

    async for raw in chat_stream.body_iterator:
        raw_buffer += raw.decode("utf-8") if isinstance(raw, bytes) else str(raw)
        while "\n\n" in raw_buffer:
            event_text, raw_buffer = raw_buffer.split("\n\n", 1)
            for line in event_text.splitlines():
                if not line.startswith("data: "):
                    continue
                data_text = line[6:]
                if data_text == "[DONE]":
                    continue
                try:
                    payload = json.loads(data_text)
                except json.JSONDecodeError:
                    continue
                async for event in _handle_payload(payload):
                    yield event
            if stream_failed:
                break
        if stream_failed:
            break

    if stream_failed:
        yield _sse(
            "response.failed",
            {
                "type": "response.failed",
                "response": {
                    "id": response_id,
                    "object": "response",
                    "created_at": created_at,
                    "status": "failed",
                    "model": request.model,
                    "output": [],
                    "usage": usage,
                },
            },
        )
        return

    reasoning_text = reasoning_text.strip()
    content_text = content_text.strip()
    if reasoning_text and not content_text:
        reasoning_only_warning = _current_response_warnings_for_reasoning_only(
            True,
            finish_reason,
        )
        yield _sse(
            "response.warning",
            {
                "type": "response.warning",
                "code": "reasoning_only_response",
                "message": reasoning_only_warning[0],
            },
        )

    terminal = _responses_terminal_state(
        finish_reason,
        reasoning_only_no_content=bool(reasoning_text and not content_text),
    )
    if reasoning_text:
        for event in _finish_reasoning_item_events(
            reasoning_text,
            status=terminal.item_status,
        ):
            yield event
    if content_text or not reasoning_text:
        for event in _start_message_item_events():
            yield event
        message_item = {
            "id": msg_id,
            "type": "message",
            "status": terminal.item_status,
            "role": "assistant",
            "content": [{
                "type": "output_text",
                "text": content_text,
                "annotations": [],
            }],
        }
        yield _sse(
            "response.output_text.done",
            {
                "type": "response.output_text.done",
                "item_id": msg_id,
                "output_index": message_output_index,
                "content_index": 0,
                "text": content_text,
            },
        )
        yield _sse(
            "response.content_part.done",
            {
                "type": "response.content_part.done",
                "item_id": msg_id,
                "output_index": message_output_index,
                "content_index": 0,
                "part": {
                    "type": "output_text",
                    "text": content_text,
                    "annotations": [],
                },
            },
        )
        yield _sse(
            "response.output_item.done",
            {
                "type": "response.output_item.done",
                "output_index": message_output_index,
                "item": message_item,
            },
        )
        if message_output_index is None:
            raise RuntimeError("Omni message item finalized before allocation")
        output_items_by_index[message_output_index] = message_item

    output_items = [
        output_items_by_index[index] for index in sorted(output_items_by_index)
    ]
    for item in output_items:
        if "status" in item:
            item["status"] = terminal.item_status
    completed_response = {
        "id": response_id,
        "object": "response",
        "created_at": created_at,
        "status": terminal.response_status,
        "model": request.model,
        "output_text": content_text,
        "output": output_items,
        "usage": usage,
    }
    if terminal.incomplete_details:
        completed_response["incomplete_details"] = terminal.incomplete_details
    if terminal.response_status == "completed":
        _responses_store_history(
            response_id,
            (history_messages or [])
            + _responses_output_to_assistant_messages(output_items),
            reasoning_only=bool(reasoning_text and not content_text),
        )
    yield _sse(
        terminal.event_type,
        {
            "type": terminal.event_type,
            "response": completed_response,
        },
    )


@app.post(
    "/v1/responses",
    dependencies=[
        Depends(verify_api_key),
        Depends(check_rate_limit),
        Depends(check_memory_pressure),  # mlxstudio#63
        Depends(check_metal_working_set_pressure),  # mlxstudio#78
    ],
)
async def create_response(
    request: ResponsesRequest,
    fastapi_request: Request,
):
    """
    Create a response using the OpenAI Responses API format.

    This endpoint provides compatibility with the newer OpenAI Responses API
    (POST /v1/responses) while using the same underlying engine as
    /v1/chat/completions.

    Request format:
    ```json
    {
      "model": "model-name",
      "input": "What is the meaning of life?",
      "instructions": "You are a helpful assistant.",
      "stream": false
    }
    ```

    Or with message list:
    ```json
    {
      "model": "model-name",
      "input": [
        {"role": "user", "content": "Hello!"}
      ]
    }
    ```
    """
    _attach_tool_choice_fulfilled_marker(request, fastapi_request)
    # The vMLX app talks to THIS endpoint, not /v1/chat/completions -- the Chat
    # Settings panel shows its API URL as /v1/responses. Logging only the chat
    # endpoint left every UI request invisible.
    _log_inbound_request_fields("responses", request)
    # Model name validation (same as chat completions)
    resolved_name = _resolve_model_name()
    if (
        request.model
        and request.model != resolved_name
        and request.model != _model_name
    ):
        # v1.3.67 mlxstudio#79: INFO log once per distinct pair (see
        # create_chat_completion for full rationale).
        _pair = (str(request.model), str(resolved_name))
        if _pair not in _model_name_mismatch_seen:
            _model_name_mismatch_seen.add(_pair)
            logger.info(
                f"Request model '{request.model}' differs from served model "
                f"'{resolved_name}' — using loaded model (single-model server). "
                f"This is expected when routing tools like Claude Code, opencode, "
                f"or CCSwitch at vMLX — they send their own model alias."
            )
    request.model = resolved_name

    engine = get_engine()
    _responses_has_media = _responses_input_has_multimodal(request.input)
    _responses_requested_modalities = _responses_input_requested_modalities(request.input)
    _log_multimodal_request_shape(
        "/v1/responses",
        _model_path or _model_name or request.model,
        _responses_input_multimodal_summary(request.input),
    )
    # M3 VL is intentionally loaded through the text-routed M3 engine
    # (VMLX_M3_VL=1) because the upstream mlx-vlm wrapper is not published.
    # Chat Completions, Anthropic, and Ollama allow M3 image/video requests
    # through this path; Responses is the UI default and must preserve the
    # same media arrays instead of rejecting or flattening them as text-only.
    _responses_requested_modalities = (
        _responses_modalities_unsupported_after_m3_vl_carveout(
            engine,
            _responses_requested_modalities,
        )
    )
    if _responses_requested_modalities:
        _reject_unsupported_multimodal(
            "/v1/responses",
            _responses_requested_modalities,
        )
    if (
        _responses_has_media
        and not engine.is_mllm
        and _loaded_omni_modalities() is None
        and not _m3_vl_response_media_supported(
            engine,
            _responses_input_requested_modalities(request.input),
        )
    ):
        _reject_unsupported_multimodal("/v1/responses")

    # Convert Responses API input to chat messages
    # For MLLM models, preserve content arrays with image/video parts — MLLM engines
    # extract images from message content internally (same as Chat Completions path).
    # Nemotron-Omni is loaded as an LLM (engine.is_mllm=False) but the omni dispatcher
    # picks up multimodal content at request time — so we must preserve the array
    # for omni bundles too, otherwise input_image gets collapsed to text and the
    # encoder never sees the image.
    _preserve_mm = bool(engine.is_mllm)
    if not _preserve_mm:
        _resp_modalities_for_preserve = _responses_input_requested_modalities(request.input)
        if _m3_vl_response_media_supported(engine, _resp_modalities_for_preserve):
            _preserve_mm = True
    if not _preserve_mm:
        try:
            from .omni_multimodal import is_omni_multimodal_bundle
            _omni_path_resp = _model_path or _model_name
            if _omni_path_resp and is_omni_multimodal_bundle(_omni_path_resp):
                _preserve_mm = True
        except Exception:
            pass
    # Responses ``instructions`` are request-scoped. OpenAI's chaining
    # contract explicitly does not carry them through ``previous_response_id``.
    # Keep a second, instruction-free transcript for the local history store;
    # otherwise a tool-result follow-up can inherit contradictory first-turn
    # instructions such as "call this tool exactly once".
    history_messages = _responses_input_to_messages(
        request.input,
        None,
        preserve_multimodal=_preserve_mm,
    )
    messages = _responses_input_to_messages(
        request.input,
        request.instructions,
        preserve_multimodal=_preserve_mm,
    )
    if request.previous_response_id:
        previous_messages = _responses_get_history(request.previous_response_id)
        if previous_messages and _responses_should_scrub_multimodal_history_for_followup(
            request.input,
            current_request_has_media=_responses_has_media,
        ):
            previous_messages = _responses_scrub_multimodal_history_for_text_followup(
                previous_messages
            )
        if previous_messages:
            messages = previous_messages + messages
            history_messages = previous_messages + history_messages
            logger.debug(
                "Responses API restored %d history message(s) from %s",
                len(previous_messages),
                request.previous_response_id,
            )
        else:
            logger.info(
                "Responses API previous_response_id=%s not found in local history; "
                "continuing with request input only",
                request.previous_response_id,
            )
    if _preserve_mm:
        messages = _coerce_orphan_tool_messages_for_template(messages)
    if engine.is_mllm and _should_coerce_zaya_vl_tool_history(request.model):
        messages = _coerce_zaya_vl_tool_history_for_template(messages)

    # Re-detect DSV4 for the Responses rail policy below. This is cheap
    # (cached registry lookup) and does not mutate caller messages.
    try:
        from .model_config_registry import get_model_config_registry
        _mc_dsv4_resp_msgs = get_model_config_registry().lookup(
            _model_path or _model_name or getattr(request, "model", "") or ""
        )
        _is_dsv4_resp_msgs = getattr(_mc_dsv4_resp_msgs, "family_name", "") == "deepseek_v4"
    except Exception:
        _is_dsv4_resp_msgs = False

    # Handle text format (json_object / json_schema) — translate to response_format
    if (
        request.text
        and isinstance(request.text, dict)
        and request.text.get("type") != "text"
    ):
        # Convert Responses API text format to Chat Completions response_format
        json_instruction = build_json_system_prompt(request.text)
        if json_instruction:
            messages = _inject_json_instruction(messages, json_instruction)
    elif hasattr(request.text, "type") and request.text.type != "text":
        text_dict = (
            request.text.model_dump(exclude_none=True)
            if hasattr(request.text, "model_dump")
            else {"type": request.text.type}
        )
        json_instruction = build_json_system_prompt(text_dict)
        if json_instruction:
            messages = _inject_json_instruction(messages, json_instruction)
    messages = _normalize_leading_system_messages(
        messages,
        preserve_native_order=_is_dsv4_resp_msgs,
    )
    # Persist only explicit input system/developer messages. Template-only
    # coercions and request-scoped instructions remain generation-local.
    history_messages = _normalize_leading_system_messages(
        history_messages,
        preserve_native_order=_is_dsv4_resp_msgs,
    )
    _responses_max_prompt_tokens = _effective_max_prompt_tokens(request)

    # Strip <think> blocks from history when thinking is OFF (same as Chat Completions path)
    _ct_kwargs = _merge_ct_kwargs(
        request.chat_template_kwargs,
        getattr(request, "reasoning_effort", None),
    )
    _explicit_thinking_off = request.enable_thinking is False or (
        _ct_kwargs.get("enable_thinking") is False
    )
    if _explicit_thinking_off and messages:
        messages = _strip_prior_reasoning_for_thinking_off(messages)

    # Build kwargs
    chat_kwargs = {
        "max_tokens": _resolve_max_tokens(request.max_output_tokens, request.model),
        "temperature": _resolve_temperature(request.temperature, request.model),
        "top_p": _resolve_top_p(request.top_p, request.model),
        "max_prompt_tokens": _responses_max_prompt_tokens,
    }
    if request.seed is not None:
        chat_kwargs["seed"] = request.seed
    _response_text_format = None
    if request.text and isinstance(request.text, dict):
        _response_text_format = request.text
    elif request.text and hasattr(request.text, "model_dump"):
        _response_text_format = request.text.model_dump(exclude_none=True)
    if (
        isinstance(_response_text_format, dict)
        and _response_text_format.get("type") not in (None, "text")
    ):
        chat_kwargs["_vmlx_response_format"] = _response_text_format
    # Forward stop sequences from request to engine
    if request.stop:
        chat_kwargs["stop"] = request.stop
    # Extended sampling params (only pass if explicitly set)
    _set_resolved_top_k(chat_kwargs, request.top_k, request.model)
    _normalize_deterministic_sampling_filters(
        chat_kwargs,
        request_top_p=request.top_p,
        request_top_k=request.top_k,
    )
    _set_resolved_min_p(chat_kwargs, request.min_p, request.model)
    _rp = _resolve_repetition_penalty(request.repetition_penalty, request.model)
    if _rp is not None:
        chat_kwargs["repetition_penalty"] = _rp
    _forward_openai_token_controls(chat_kwargs, request)
    if _compute_bypass_prefix_cache(request):
        chat_kwargs["_bypass_prefix_cache"] = True

    # Pass enable_thinking to engine
    # Priority: top-level field > chat_template_kwargs > server default > auto-detect
    _et = _resolve_enable_thinking(
        request_value=request.enable_thinking,
        ct_kwargs=_ct_kwargs,
        tools_present=bool(request.tools),
        model_key=_model_path or _model_name or request.model,
        engine=engine,
        auto_detect=True,
        reasoning_effort=request.reasoning_effort,
    )
    if _et is not None:
        chat_kwargs["enable_thinking"] = _et
        request.enable_thinking = _et
        _ct_kwargs["enable_thinking"] = _et

    _forward_reasoning_effort_kwargs(
        chat_kwargs, _ct_kwargs, request.reasoning_effort
    )
    if getattr(request, "max_thinking_tokens", None) is not None and request.enable_thinking is not False:
        _ct_kwargs["thinking_budget"] = int(request.max_thinking_tokens)

    # Auto-map enable_thinking → reasoning_effort for Mistral 4 (Responses API path).
    if (
        _reasoning_parser
        and type(_reasoning_parser).__name__ == "MistralReasoningParser"
    ):
        _resp_thinking = chat_kwargs.get("enable_thinking")
        if _resp_thinking is True and "reasoning_effort" not in _ct_kwargs:
            _ct_kwargs["reasoning_effort"] = "high"
            chat_kwargs["reasoning_effort"] = "high"
        elif _resp_thinking is False and "reasoning_effort" not in _ct_kwargs:
            _ct_kwargs["reasoning_effort"] = "none"

    _apply_hy3_reasoning_policy(
        chat_kwargs,
        _ct_kwargs,
        model_key=_model_path or _model_name or request.model,
        enable_thinking=request.enable_thinking,
    )
    # Mint the response id BEFORE the effort policy (mirrors the chat route):
    # only the policy knows whether a coercion happened, and the finalize
    # surfaces (non-stream ResponsesObject / stream terminal snapshot) pop the
    # substitution record by this id. Both branches below reuse this id.
    response_id = f"resp_{uuid.uuid4().hex[:12]}"
    _note_request_diagnostics_id(response_id)
    _apply_stamped_effort_policy(
        chat_kwargs,
        _ct_kwargs,
        model_key=_model_path or _model_name or request.model,
        request_id=response_id,
    )

    # DSV4 rail-policy + reasoning_effort handling — REAL /v1/responses path.
    # This is the actual route the panel uses; the earlier DSV4 block in this
    # function only sets the default system prompt. Without this block,
    # /v1/responses would skip the same direct/reasoning policy used by chat
    # completions and could drift back into stale bare-thinking behavior.
    if _is_dsv4_resp_msgs:
        _dsv4_thinking_resp = _resolve_dsv4_thinking_policy(
            requested_enable_thinking=request.enable_thinking,
            effort_requested=bool(
                getattr(request, "reasoning_effort", None)
                or _ct_kwargs.get("reasoning_effort")
            ),
            tools_present=bool(getattr(request, "tools", None)),
            tool_choice=getattr(request, "tool_choice", None),
            default_mode=_jang_chat_default_mode(
                _model_path or _model_name or request.model or ""
            ),
        )
        if (
            not _dsv4_thinking_resp.enable_thinking
            and (
                request.enable_thinking is True
                or getattr(request, "reasoning_effort", None)
                or _ct_kwargs.get("reasoning_effort")
            )
        ):
            logger.info(
                "DSV4 (/v1/responses): using direct rail because %s.",
                _dsv4_thinking_resp.reason,
            )
        request.enable_thinking = _dsv4_thinking_resp.enable_thinking
        chat_kwargs["enable_thinking"] = _dsv4_thinking_resp.enable_thinking
        _ct_kwargs["enable_thinking"] = _dsv4_thinking_resp.enable_thinking
        _set_resolved_repetition_penalty(
            chat_kwargs,
            request.repetition_penalty,
            request.model,
            enable_thinking=chat_kwargs.get("enable_thinking"),
        )

        # (b) Preserve a supported explicit bundle effort. Generic
        #     `thinking_mode=reasoning` selects the bundle-native default;
        #     unsupported explicit tiers fail with a clear 400.
        _cur_resp_effort = _dsv4_requested_reasoning_effort(
            request,
            _ct_kwargs,
        )
        _ct_kwargs.pop("thinking_mode", None)
        _stable_resp_effort = (
            _normalize_dsv4_reasoning_effort(
                _cur_resp_effort,
                _model_path or _model_name or request.model or "",
            )
            if _dsv4_thinking_resp.reasoning_effort_allowed
            else None
        )
        if _stable_resp_effort:
            _ct_kwargs["reasoning_effort"] = _stable_resp_effort
        else:
            _ct_kwargs.pop("reasoning_effort", None)

        # (c) Diagnostic log so we can verify what actually goes to the
        #     encoder. Keep explicit logs of effective values.
        logger.info(
            f"DSV4 (/v1/responses) effective: enable_thinking="
            f"{chat_kwargs.get('enable_thinking')}, reasoning_effort="
            f"{_ct_kwargs.get('reasoning_effort')}, "
            f"messages={len(messages) if messages else 0}"
        )

    _normalize_minimax_m3_thinking_mode(
        _ct_kwargs, request, _model_path or _model_name or request.model)
    _normalize_openpangu_thinking(
        _ct_kwargs, request, _model_path or _model_name or request.model)
    # Resolve the render-relevant tool_choice before snapshotting
    # chat_template_kwargs. Native fallback renderers (notably LFM2) need a
    # required/specific current-request contract, while `none`/`auto` remain
    # scheduler controls and must not perturb arbitrary model templates.
    _tool_choice = request.tool_choice
    if _tool_choice is not None:
        chat_kwargs["tool_choice"] = _tool_choice
    _qwen4_specific_tool_name = _specific_tool_choice_name(_tool_choice)
    _qwen4_stable_tool_catalog = bool(
        _qwen4_specific_tool_name
        and _is_loaded_qwen4_exp_model(request.model or "")
    )
    if _is_required_tool_choice(_tool_choice) and not _qwen4_stable_tool_catalog:
        # The official top-level API contract overrides any conflicting nested
        # template value.
        _ct_kwargs["tool_choice"] = _tool_choice
    else:
        _ct_kwargs.pop("tool_choice", None)

    # Forward the resolved template kwargs to the engine.  Keep the resolved
    # enable_thinking value mirrored here as well as the top-level engine kwarg:
    # build_chat_template_kwargs() treats the top-level flag as authoritative,
    # while renderer/processor wrappers that inspect the raw template kwargs see
    # the same effective On/Off value instead of stale caller input.
    if _ct_kwargs:
        extra_ct = dict(_ct_kwargs)
        if extra_ct:
            chat_kwargs["chat_template_kwargs"] = extra_ct

    _log_resolved_sampling_kwargs(
        "/v1/responses",
        request.model or _resolve_model_name(),
        chat_kwargs,
        proof_request_id=_request_header_value(
            fastapi_request,
            "x-vmlx-proof-request-id",
        ),
        request_id=_request_header_value(fastapi_request, "x-vmlx-request-id"),
        message_id=_request_header_value(fastapi_request, "x-vmlx-message-id"),
    )

    # Video processing controls (MLLM models)
    if request.image_token_budget:
        chat_kwargs["image_token_budget"] = request.image_token_budget
    # Video controls: every SET field (0 is invalid and rejected at the model,
    # so no truthiness filter is needed), plus the normalized object.
    chat_kwargs.update(video_control_kwargs(request))

    _suppress_tools = _tool_choice == "none"

    # response_format = json_object / json_schema implies the output IS the
    # structured data — not a tool call. The generic tool-call parser runs
    # on any JSON-ish output and is happy to interpret `{"name":"alice",
    # "age":30}` as a tool call `alice()`. Suppress the tool parser when
    # the client asked for JSON output and didn't pass tools themselves.
    # Responses API exposes the format signal on request.text.format
    # (ResponsesTextFormat); ResponsesRequest has no response_format field,
    # so getattr avoids AttributeError. Accept either shape.
    if not request.tools and not _suppress_tools:
        _rf = getattr(request, "response_format", None) or getattr(request, "text", None)
        _rf_type = None
        if isinstance(_rf, dict):
            _rf_type = _rf.get("type")
            if _rf_type is None:
                _fmt = _rf.get("format")
                if isinstance(_fmt, dict):
                    _rf_type = _fmt.get("type")
        elif _rf is not None:
            _rf_type = getattr(_rf, "type", None)
            if _rf_type is None:
                _fmt = getattr(_rf, "format", None)
                if isinstance(_fmt, dict):
                    _rf_type = _fmt.get("type")
                elif _fmt is not None:
                    _rf_type = getattr(_fmt, "type", None)
        if _rf_type in ("json_object", "json_schema"):
            _suppress_tools = True

    # Merge MCP tools with user-provided tools
    all_tools = []

    if not _suppress_tools:
        # Add MCP tools if available
        if _mcp_manager is not None:
            mcp_tools = _mcp_manager.get_all_tools_openai(policy=_mcp_policy)
            mcp_tools = _drop_colliding_mcp_tools(mcp_tools, request.tools)
            if not _qwen4_stable_tool_catalog:
                mcp_tools = _filter_tools_for_specific_choice(mcp_tools, _tool_choice)
            all_tools.extend(mcp_tools)
            if mcp_tools:
                logger.debug(f"Added {len(mcp_tools)} MCP tools")

        # Add user-provided tools — convert from Responses API flat format to Chat Completions nested format
        if request.tools:
            # If tool_choice is a specific tool dict, filter to only that tool
            if isinstance(_tool_choice, dict):
                target_name = _tool_choice.get("function", {}).get(
                    "name"
                ) or _tool_choice.get("name")
            else:
                target_name = None

            for tool in request.tools:
                tool_type = tool.get("type", "")
                # Skip built-in Responses API tools (web_search, code_interpreter, file_search, etc.)
                if (
                    tool_type != "function"
                    and "function" not in tool
                    and "name" not in tool
                ):
                    continue
                # Chat Completions nested format: {"type": "function", "function": {...}}
                if "function" in tool:
                    td = ToolDefinition(**tool)
                    # Filter to specific tool if tool_choice is a dict
                    if (
                        target_name
                        and not _qwen4_stable_tool_catalog
                        and td.function.get("name") != target_name
                    ):
                        continue
                    all_tools.append(td)
                # Responses API flat format: {"type": "function", "name": "...", "parameters": {...}}
                elif "name" in tool:
                    # Filter to specific tool if tool_choice is a dict
                    if (
                        target_name
                        and not _qwen4_stable_tool_catalog
                        and tool.get("name") != target_name
                    ):
                        continue
                    flat = ResponsesToolDefinition(**tool)
                    all_tools.append(
                        ToolDefinition(**flat.to_chat_completions_format())
                    )
            logger.debug(f"Added {len(all_tools)} tools (tool_choice={_tool_choice})")

    parser_tools = (
        _filter_tools_for_specific_choice(all_tools, _tool_choice)
        if _qwen4_stable_tool_catalog
        else all_tools
    )
    if not _suppress_tools:
        _suppress_tools = _suppress_tool_parsing_when_no_tools(
            parser_tools, _tool_choice, "Responses API"
        )
    _attach_effective_tools_for_tool_parsing(request, parser_tools)

    # Pass merged tools to engine
    if all_tools:
        chat_kwargs["tools"] = convert_tools_for_template(all_tools)
        chat_kwargs["_vmlx_tools_present"] = True
        if _qwen4_stable_tool_catalog:
            chat_kwargs["_vmlx_qwen4_specific_tool_name"] = (
                _qwen4_specific_tool_name
            )
    elif not _suppress_tools and _is_dsv4_resp_msgs and any(
        isinstance(m, dict) and m.get("role") == "tool" for m in messages
    ):
        historical_tools = _synthesize_tools_from_message_tool_calls(messages)
        if historical_tools:
            chat_kwargs["tools"] = historical_tools
            chat_kwargs["_vmlx_tools_present"] = True
            logger.info(
                "DSV4 (Responses): synthesized %d historical tool schema(s) "
                "for tool-result continuation prompt context",
                len(historical_tools),
            )

    # Inject Harmony analysis prefix for GPT-OSS models (same as Chat Completions path)
    if isinstance(_reasoning_parser, GptOssReasoningParser):
        _think_val = chat_kwargs.get("enable_thinking")
        if _think_val is True:
            _analysis_hint = "<|start|>assistant<|channel|>analysis<|message|>"
            chat_kwargs["prompt_suffix"] = _analysis_hint
            chat_kwargs["skip_generation_prompt"] = True
            _effort = chat_kwargs.get("reasoning_effort", "").lower()
            logger.info(
                f"[responses] Injecting Harmony analysis prefix for GPT-OSS model (effort={_effort or 'default'})"
            )
        # GPT-OSS/GLM Flash: add <|im_end|> as string stop sequence (see Chat Completions path)
        _stop = chat_kwargs.get("stop") or []
        if "<|im_end|>" not in _stop:
            _stop = list(_stop) + ["<|im_end|>"]
            chat_kwargs["stop"] = _stop

    # Nemotron-Omni multimodal dispatch (Responses API parity with
    # /v1/chat/completions + /v1/messages). Without this hook, input_image /
    # input_video / input_audio reach the engine but engine.chat() is the
    # text-only path — image+audio encoders never run. Live test 2026-04-30
    # T6 surfaced this gap: T6 returned "Could you clarify what you'd like a
    # brief description of?" because the model never saw the image. Mirrors
    # /v1/messages dispatch at server.py:3189-3224.
    try:
        from .omni_multimodal import (
            is_omni_multimodal_bundle as _is_omni_resp,
            request_has_multimodal as _has_mm_resp,
            dispatch_omni_chat_completion as _omni_dispatch_resp,
        )
        _omni_path_dispatch = _model_path or _model_name
        if (
            _omni_path_dispatch
            and _is_omni_resp(_omni_path_dispatch)
            and _has_mm_resp(messages)
        ):
            from .api.models import ChatCompletionRequest as _CCR
            from starlette.responses import JSONResponse as _JR2
            _cc_req = _CCR(
                model=resolved_name,
                messages=messages,  # already preserved-multimodal above
                temperature=chat_kwargs["temperature"],
                top_p=chat_kwargs["top_p"],
                max_tokens=chat_kwargs["max_tokens"],
                stream=bool(request.stream),
                enable_thinking=request.enable_thinking,
                reasoning_effort=request.reasoning_effort,
            )
            cc = await _omni_dispatch_resp(
                _cc_req,
                _omni_path_dispatch,
                disk_cache_enabled=_loaded_block_disk_cache_enabled(),
                effective_max_tokens=chat_kwargs["max_tokens"],
                effective_temperature=chat_kwargs["temperature"],
                effective_top_p=chat_kwargs["top_p"],
            )
            if isinstance(cc, StreamingResponse) and request.stream:
                return StreamingResponse(
                    _adapt_omni_chat_stream_to_responses(
                        cc,
                        request,
                        history_messages=(
                            history_messages
                            if history_messages is not None
                            else messages
                        ),
                    ),
                    media_type="text/event-stream",
                )
            cc_dict = None
            if isinstance(cc, _JR2):
                cc_dict = json.loads(cc.body.decode("utf-8")) if cc.body else {}
                if int(getattr(cc, "status_code", 200) or 200) >= 400 and isinstance(cc_dict.get("error"), dict):
                    # a typed rejection keeps its status and code on the
                    # Responses door (live: a strict media-control rejection
                    # became a 200 "incomplete" response)
                    _e = cc_dict["error"]
                    return _JR2(
                        status_code=int(cc.status_code),
                        content={
                            "error": {
                                "type": _e.get("type") or "invalid_request_error",
                                "message": _e.get("message") or "request rejected",
                                **({"code": _e["code"]} if _e.get("code") else {}),
                            }
                        },
                    )
            elif isinstance(cc, dict):
                cc_dict = cc
            if cc_dict is not None:
                _resp_payload = _adapt_omni_chat_completion_to_responses_payload(
                    cc_dict,
                    resolved_name,
                )
                return _JR2(content=_resp_payload)
            return cc
    except HTTPException:
        raise
    except Exception as _omni_resp_err:  # pragma: no cover
        logger.warning(
            "Omni dispatch failed in /v1/responses (%s); "
            "falling back to text-only LLM path.",
            _omni_resp_err,
        )

    if request.stream:
        return StreamingResponse(
            stream_responses_api(
                engine,
                messages,
                request,
                fastapi_request,
                history_messages=history_messages,
                response_id=response_id,
                **chat_kwargs,
            ),
            media_type="text/event-stream",
        )

    # Non-streaming response (response_id was minted before the effort policy)
    start_time = time.perf_counter()
    timeout = request.timeout if request.timeout is not None else _default_timeout

    # Responses parity with Chat: only an explicit max_thinking_tokens may
    # reserve output for the direct-answer stage.
    _ns_answer_pass_original_cap = None
    _ns_visible_answer_finish_reason: str | None = None
    _ns_pre_mtt = getattr(request, "max_thinking_tokens", None)
    if _ns_pre_mtt is None:
        # DSV4 only — see _dsv4_answer_pass_thinking_cap.
        try:
            from .model_config_registry import get_model_config_registry as _ns_dsv4_mcr
            _ns_dsv4_family = getattr(
                _ns_dsv4_mcr().lookup(_model_path or _model_name or request.model),
                "family_name", None,
            )
        except Exception:
            _ns_dsv4_family = None
        _ns_pre_mtt = _dsv4_answer_pass_thinking_cap(
            _ns_dsv4_family,
            None if chat_kwargs.get("enable_thinking") is None
            else chat_kwargs.get("enable_thinking"),
            chat_kwargs.get("max_tokens"),
        )
        # The SOFT-cap flavor is DSV4-only (its engine rail implements the
        # lift-at-</think> kwarg). Nemotron's default reserve takes the plain
        # hard split below, exactly like an explicit max_thinking_tokens.
        _ns_dsv4_default_reserve = (
            _ns_pre_mtt is not None and _ns_dsv4_family == "deepseek_v4"
        )
    else:
        _ns_dsv4_default_reserve = False
    if (
        _ns_pre_mtt is not None
        and chat_kwargs.get("enable_thinking") is not False
        and getattr(request, "enable_thinking", None) is not False
        and (chat_kwargs.get("chat_template_kwargs") or {}).get("enable_thinking") is not False
    ):
        try:
            from .model_config_registry import get_model_config_registry as _ns_pre_mcr
            _ns_pre_family = getattr(
                _ns_pre_mcr().lookup(_model_path or _model_name or request.model),
                "family_name", None,
            )
        except Exception:
            _ns_pre_family = None
        _ns_pre_cap_family = (
            _ns_pre_family in _THINKING_BUDGET_CAP_FAMILIES
            or _ns_pre_family == "deepseek_v4"
            or _ns_pre_family in ("minimax_m3", "minimax_m3_vl")
            or _tool_call_parser == "minimax_m3"
        )
        if _ns_pre_cap_family:
            _ns_pre_orig = int(chat_kwargs.get("max_tokens") or 256)
            _ns_pre_capped = max(1, min(_ns_pre_orig, int(_ns_pre_mtt)))
            if _ns_pre_capped < _ns_pre_orig:
                _ns_answer_pass_original_cap = _ns_pre_orig
                chat_kwargs = dict(chat_kwargs)
                if _ns_dsv4_default_reserve:
                    # DSV4 default reserve: SOFT cap — lifts engine-side at
                    # </think> so the same pass spends the reserved answer
                    # budget instead of stranding it. Reasoning-only runs still
                    # finish=length at the cap and arm the answer pass below.
                    chat_kwargs["dsv4_thinking_soft_cap"] = _ns_pre_capped
                else:
                    chat_kwargs["max_tokens"] = _ns_pre_capped

    try:
        _note_request_diagnostics_id(response_id)
        output = await _await_chat_with_disconnect_abort(
            engine,
            messages=messages,
            chat_kwargs=chat_kwargs,
            timeout=timeout,
            fastapi_request=fastapi_request,
            request_id=response_id,
            endpoint="Responses API",
            hard_timeout=request.timeout is not None,
        )
    except asyncio.TimeoutError:
        raise HTTPException(
            status_code=504, detail=f"Request timed out after {timeout:.1f} seconds"
        )
    except PromptTooLongError as e:
        return _prompt_too_long_response_from_error(e)
    except PrefillAdmissionError as e:
        return _prefill_admission_declined_response(e)
    except VLMImagePrefillBudgetError as e:
        return _vlm_image_prefill_budget_response_from_error(e)
    except MediaInputError as e:
        return _media_input_error_response_from_error(e)
    except MediaControlsUnmeetableError as e:
        return _media_controls_unmeetable_response_from_error(e)
    except UnsupportedMediaModalityError as e:
        return _unsupported_media_modality_response_from_error(e)
    except Exception as e:
        logger.error(f"Response generation failed: {e}", exc_info=True)
        raise HTTPException(
            status_code=500,
            detail=f"Generation failed: {type(e).__name__}: {e}",
        )

    elapsed = time.perf_counter() - start_time
    tokens_per_sec = output.completion_tokens / elapsed if elapsed > 0 else 0
    logger.info(
        f"Response: {output.completion_tokens} tokens in {elapsed:.2f}s ({tokens_per_sec:.1f} tok/s end-to-end incl. prefill) therm={thermal_state_name()}"
    )

    # Extract reasoning content FIRST from raw output (before stripping tags).
    # Must happen before tool call parsing since that strips <think> blocks.
    reasoning_text = None
    _private_tool_candidate = None
    content_for_parsing = output.text
    if _reasoning_parser:
        # Clone parser per-request to avoid shared state across concurrent requests
        request_parser = _reasoning_parser.__class__()
        # Initialize parser state (harmony_active, etc.) — same as streaming path
        # NOTE: non-stream extract_reasoning() parses the COMPLETE text and finds
        # the harmony final marker on its own, so it never needs the harmony_active
        # hint (and forcing it True here alters channel parsing enough to drop
        # gpt_oss tool calls — the streaming-only leak fix must NOT touch this path).
        _harmony_prefix_active = "prompt_suffix" in chat_kwargs and chat_kwargs.get(
            "prompt_suffix", ""
        ).startswith("<|start|>assistant<|channel|>analysis")

        # Compute think_in_prompt the same way the streaming path does at
        # ~line 5840. MiniMax and other "always-thinks" templates inject
        # <think>\n in the generation prompt, so model output starts in
        # reasoning mode. Without think_in_prompt=True, `extract_reasoning`
        # falls through to "no tags → pure content" and the reasoning prose
        # shows up raw in content (§15 regression).
        try:
            from .model_config_registry import get_model_config_registry as _mcr
            _mc_nonstream = _mcr().lookup(_model_path or _model_name or request.model)
            _think_in_prompt_ns = _mc_nonstream.think_in_template
            _think_in_prompt_ns = _apply_tokenizer_thinking_vocab_fallback(
                _think_in_prompt_ns,
                reasoning_parser=_reasoning_parser,
                tokenizer=engine.tokenizer,
                model_config=_mc_nonstream,
            )
            if _think_in_prompt_ns and _template_completes_thinking(
                engine.tokenizer, _model_name or request.model
            ):
                _think_in_prompt_ns = False
            _eff_thinking_ns = chat_kwargs.get("enable_thinking")
            _prompt_enable_ns = (
                True if _eff_thinking_ns is None else bool(_eff_thinking_ns)
            )
            _tools_present_ns = _tools_available_for_generation(
                request, chat_kwargs.get("tools")
            )
            if _engine_prompt_starts_in_reasoning(
                engine.tokenizer,
                model_name=_model_name or request.model,
                enable_thinking=_prompt_enable_ns,
                family_name=getattr(_mc_nonstream, "family_name", None),
                tools_present=_tools_present_ns,
            ):
                _think_in_prompt_ns = True
            else:
                _think_in_prompt_ns = False
            if _hy3_prompt_starts_in_reasoning(
                model_key=_model_path or _model_name or request.model,
                enable_thinking=_eff_thinking_ns,
                ct_kwargs=chat_kwargs.get("chat_template_kwargs") or _ct_kwargs,
            ):
                _think_in_prompt_ns = True
            if _synthetic_mllm_think_prompt_starts(
                model_key=_model_path or _model_name or request.model,
                enable_thinking=_eff_thinking_ns,
                engine=engine,
            ):
                _think_in_prompt_ns = True
            # MiniMax-M3 thinking_mode="enabled" prompt-opens <mm:think> in the
            # generation prompt, so assistant output starts INSIDE reasoning with
            # no opening tag in the OUTPUT. Seed the parser's implicit-reasoning
            # mode so the reasoning isn't misclassified as visible content.
            if (chat_kwargs.get("chat_template_kwargs") or _ct_kwargs or {}).get(
                "thinking_mode"
            ) == "enabled":
                _think_in_prompt_ns = True
        except Exception as _tpe:
            logger.debug(f"think_in_prompt derivation failed non-stream: {_tpe}")
            _think_in_prompt_ns = False

        request_parser.reset_state(
            think_in_prompt=_think_in_prompt_ns,
            harmony_active=_harmony_prefix_active,
        )
        # Prefer raw_text (pre-clean) when the engine tracked it — reasoning
        # parsers (esp. Gemma 4 channel markers, Qwen 3.6 think tags) need the
        # special tokens that clean_output_text strips for display.
        _raw_for_parse = getattr(output, "raw_text", "") or output.text
        # DSV4 /v1/responses debug instrumentation:
        # log raw model output to confirm whether parser is failing or
        # model emitted </think> immediately, etc.
        if _is_dsv4_resp_msgs:
            _raw_len = len(_raw_for_parse) if _raw_for_parse else 0
            _has_open = "<think>" in (_raw_for_parse or "")
            _has_close = "</think>" in (_raw_for_parse or "")
            logger.info(
                f"DSV4 (/v1/responses) raw_output: len={_raw_len}, "
                f"has_<think>={_has_open}, has_</think>={_has_close}, "
                f"think_in_prompt={_think_in_prompt_ns}, "
                f"head={(_raw_for_parse or '')[:200]!r}, "
                f"tail={(_raw_for_parse or '')[-200:]!r}"
            )
        reasoning_text, remaining_text = request_parser.extract_reasoning(_raw_for_parse)
        if _is_dsv4_resp_msgs:
            logger.info(
                f"DSV4 (/v1/responses) parser: reasoning_len="
                f"{len(reasoning_text or '')}, remaining_len="
                f"{len(remaining_text or '')}"
            )
        if _is_dsv4_resp_msgs:
            token_reasoning, token_content = _dsv4_split_reasoning_from_token_ids(
                _output_token_ids_for_reasoning(output),
                engine.tokenizer,
            )
            if token_content:
                reasoning_text = token_reasoning
                remaining_text = token_content
                logger.info(
                    "DSV4 (/v1/responses) token split: reasoning_len=%s, content_len=%s",
                    len(reasoning_text or ""),
                    len(remaining_text or ""),
                )
        if remaining_text is not None:
            content_for_parsing = remaining_text
        elif reasoning_text is not None:
            # Truncated reasoning (e.g., max_tokens hit during <think> phase):
            # reasoning extracted but no content after it — don't leak raw <think> tags
            content_for_parsing = ""
        # Suppress reasoning when thinking is disabled (check resolved value from chat_kwargs,
        # not just raw request — covers --default-enable-thinking and auto-detect paths)
        _resolved = chat_kwargs.get("enable_thinking")
        _suppress = _resolved is False or request.enable_thinking is False
        if not _suppress:
            _suppress = _ct_kwargs.get("enable_thinking") is False
        reasoning_text, content_for_parsing, _private_tool_candidate = (
            _apply_reasoning_visibility(
                reasoning_text,
                content_for_parsing,
                suppress=_suppress,
            )
        )

        # Post-parse cleaning — matches the chat_completions path so content
        # emitted by /v1/responses is stripped of residual `<channel|>`,
        # `thought\n`, `<turn|>` etc. that survive the parser's structural
        # split. Applied AFTER extract_reasoning so parser still sees the
        # special tokens it needs for detection.
        if content_for_parsing:
            content_for_parsing = clean_output_text(content_for_parsing)
        if reasoning_text:
            reasoning_text = clean_output_text(reasoning_text)

    # Reasoning-runaway backstop (non-streaming responses): mirror the
    # streaming bounded thinking-off answer pass for degraded reasoners.
    try:
        from .model_config_registry import get_model_config_registry as _ns_mcr
        _ns_family = getattr(
            _ns_mcr().lookup(_model_path or _model_name or request.model),
            "family_name", None,
        )
    except Exception:
        _ns_family = None
    # Match the Chat Completions path: a served model alias may not resolve to
    # a local bundle during this late lookup, while the configured native tool
    # parser still proves which runtime contract is active.
    _ns_is_m3 = (
        _ns_family in ("minimax_m3", "minimax_m3_vl")
        or _tool_call_parser == "minimax_m3"
    )
    _ns_tools_available = _tools_available_for_generation(
        request, chat_kwargs.get("tools")
    )
    _ns_m3_valid_tool_call = (
        _ns_is_m3
        and not _suppress_tools
        and _has_schema_valid_tool_call_candidate(
            content_for_parsing,
            reasoning_text,
            request,
        )
    )
    _ns_thinking_off = (
        chat_kwargs.get("enable_thinking") is False
        or getattr(request, "enable_thinking", None) is False
        or (chat_kwargs.get("chat_template_kwargs") or {}).get("enable_thinking") is False
    )
    _ns_native_tool_recovery = _native_reasoning_tool_recovery_allowed(
        _ns_family,
        request,
        tools_available=_ns_tools_available,
        effective_thinking=False if _ns_thinking_off else True,
    )
    _ns_native_valid_tool_call = (
        _ns_native_tool_recovery
        and _has_schema_valid_tool_call_candidate(
            content_for_parsing,
            reasoning_text,
            request,
        )
    )
    _ns_explicit_tool_fallback = (
        _ns_answer_pass_original_cap is not None
        and _ns_tools_available
        and not _request_explicitly_requests_tool_use(request)
        and _ns_family in _REASONING_ANSWER_PASS_FAMILIES
        and not _has_schema_valid_tool_call_candidate(
            content_for_parsing,
            reasoning_text,
            request,
        )
    )
    _ns_visible_content_for_answer_gate = content_for_parsing
    if _ns_native_tool_recovery and not _ns_native_valid_tool_call:
        _ns_visible_content_for_answer_gate = (
            _visible_prefix_before_unparsed_tool_markup(
                _strip_think_for_tool_parse(
                    _ns_visible_content_for_answer_gate or ""
                )
            )
        )
    if _suppress_tools and _ns_visible_content_for_answer_gate:
        _ns_visible_content_for_answer_gate = (
            _clean_suppressed_tool_markup_for_display(
                _strip_think_for_tool_parse(_ns_visible_content_for_answer_gate),
                request,
            )
        )
    if (
        not _ns_visible_content_for_answer_gate
        and reasoning_text
        and not _ns_thinking_off
        and _ns_answer_pass_original_cap is not None
        and (
            not _ns_tools_available
            or (_ns_is_m3 and not _ns_m3_valid_tool_call)
            or (_ns_native_tool_recovery and not _ns_native_valid_tool_call)
            or _ns_explicit_tool_fallback
        )
        and _remaining_answer_pass_budget(
            _ns_answer_pass_original_cap,
            getattr(output, "completion_tokens", 0),
        ) > 0
    ):
        if (
            _ns_family in _REASONING_ANSWER_PASS_FAMILIES
            or _ns_is_m3
            or _ns_native_tool_recovery
        ):
            _ns_cap = int(_ns_answer_pass_original_cap)
            _ns_used = int(getattr(output, "completion_tokens", 0) or 0)
            _ns_budget = _remaining_answer_pass_budget(_ns_cap, _ns_used)
            logger.info(
                "%s non-stream responses produced no visible content; running "
                "bounded %s answer pass (reasoning_chars=%d, "
                "cap=%d, used=%d, answer_budget=%d)",
                _ns_family,
                "native tools-free" if _ns_native_tool_recovery else "thinking-off",
                len(reasoning_text or ""), _ns_cap, _ns_used,
                _ns_budget,
            )
            _ns_kwargs = dict(chat_kwargs)
            if not _ns_native_tool_recovery:
                _force_answer_pass_direct_rail(
                    _ns_kwargs,
                    family_name=_ns_family,
                )
            _ns_kwargs["max_tokens"] = _ns_budget
            _ns_ct = dict(_ns_kwargs.get("chat_template_kwargs") or {})
            if not _ns_native_tool_recovery:
                if _ns_is_m3:
                    _ns_ct["thinking_mode"] = "disabled"
                if _ns_family == "openpangu_v2":
                    _ns_ct["thinking"] = False
                _ns_ct.pop("enable_thinking", None)
            _ns_kwargs["chat_template_kwargs"] = _ns_ct
            _ns_kwargs.pop("dsv4_thinking_soft_cap", None)
            _ns_kwargs.pop("tools", None)
            _ns_kwargs.pop("_vmlx_tools_present", None)
            _ns_kwargs.pop("_vmlx_template_tools", None)
            try:
                _ns_out = await _await_chat_with_disconnect_abort(
                    engine,
                    messages=_answer_pass_messages(
                        messages, _ns_family, reasoning_text
                    ),
                    chat_kwargs=_ns_kwargs,
                    timeout=timeout,
                    fastapi_request=fastapi_request,
                    request_id=f"{response_id}:visible-answer",
                    endpoint="Responses visible answer pass (non-stream)",
                    hard_timeout=request.timeout is not None,
                )
                _ns_text, _ = _answer_pass_visible_delta(
                    getattr(_ns_out, "text", "") or "",
                    "",
                    request,
                    True,
                    think_in_prompt=_ns_native_tool_recovery,
                )
                # For qwen3.5/3.6 ONLY, adopt the salvage when it actually
                # COMPLETED. A salvage that itself hit the bounded budget
                # (finish_reason="length") is an incomplete fragment: a
                # length-truncated reasoning re-continues as planning prose, so
                # surfacing that fragment leaks internal planning as the visible
                # answer (W2-1, live-proven: the model closes reasoning and
                # answers cleanly once max_tokens is large enough — the leak is
                # a symptom of a too-small output budget). Keeping the honest
                # finish_reason="length" result makes the client raise
                # max_tokens. Scoped to qwen3_5* because other families
                # (gemma4/M3/openpangu/minimax_m2/Hy3) emit a coherent worked
                # answer here — an incomplete salvage is a legitimate partial
                # answer, not a leak, and must still be surfaced (live-proven:
                # MiniMax-M2.7 truncates its visible worked solution honestly,
                # no planning leak). See streaming gate for the matching scope.
                _ns_qwen_scope = _ns_family in _ANSWER_PASS_LEAK_GUARD_FAMILIES
                # 2026-07-12 parity fix (streaming siblings): a length-truncated
                # qwen3_5* salvage is a CLEAN cut-off answer, not a planning-prose
                # leak — the direct-rail thinking-off pass does not emit <think>.
                # Discarding it left the turn EMPTY and stalled agentic loops.
                # Adopt the truncated answer; reject ONLY a genuine <think>
                # re-entry (clean_output_text does not strip <think>, so the
                # raw-text check is load-bearing).
                _ns_reasoning_leak = _ns_qwen_scope and _answer_pass_thinking_reentry(
                    getattr(_ns_out, "text", "") or ""
                )
                _ns_answer_complete = not _ns_reasoning_leak
                if _ns_text and _ns_answer_complete:
                    content_for_parsing = _ns_text
                    _ns_visible_answer_finish_reason = getattr(
                        _ns_out, "finish_reason", None
                    )
                    try:
                        output.completion_tokens += int(getattr(_ns_out, "completion_tokens", 0) or 0)
                    except Exception:
                        pass
            except Exception as _nse:
                logger.error("non-stream responses visible answer pass failed: %s", _nse)

    parse_text = _strip_think_for_tool_parse(content_for_parsing)

    # Parse tool calls (skip when tool_choice="none"); capture dropped-call /
    # schema-validation diagnostics for the response `warnings` field.
    _begin_tool_call_drop_capture()
    cleaned_text, tool_calls = (
        _parse_tool_calls_with_parser(parse_text, request)
        if not _suppress_tools
        else (
            _clean_suppressed_tool_markup_for_display(
                parse_text or content_for_parsing or "",
                request,
            ),
            None,
        )
    )

    _reasoning_tool_candidate = reasoning_text or _private_tool_candidate
    if (
        not tool_calls
        and _reasoning_tool_candidate
        and not _suppress_tools
        and _private_reasoning_has_tool_syntax(_reasoning_tool_candidate)
    ):
        logger.info(
            f"Request {response_id}: tool markers in reasoning — "
            "extracting before Responses API finalization"
        )
        _tc_calls = _parse_private_reasoning_tool_calls(
            _reasoning_tool_candidate, request
        )
        if _tc_calls:
            tool_calls = _tc_calls
            cleaned_text = ""

    structured_output_warnings: list[str] | None = None

    # Process text format (json_schema with strict) if specified — mirrors Chat Completions behavior
    _text_format = request.text if hasattr(request, "text") else None
    if _text_format and hasattr(_text_format, "model_dump"):
        _text_format = _text_format.model_dump(exclude_none=True)
    if (
        _text_format
        and isinstance(_text_format, dict)
        and _text_format.get("type") == "xml"
        and not tool_calls
    ):
        _xml_response_config = _xml_response_format_config(_text_format)
        if _xml_response_config:
            _out_text = cleaned_text or content_for_parsing
            _structured_report = repair_xml_output(
                _out_text,
                root_tag=_xml_response_config.get("root_tag"),
                required_fields=_xml_response_config.get("required_fields") or (),
            )
            if not _structured_report.get("is_valid"):
                _retry_output, _retry_report = await _retry_structured_output_xml_once(
                    engine=engine,
                    messages=messages,
                    chat_kwargs=chat_kwargs,
                    response_format=_text_format,
                    invalid_text=_out_text or "",
                    error=_structured_report.get("error"),
                    timeout=timeout,
                    fastapi_request=fastapi_request,
                    request_id=f"{response_id}-xml-retry",
                    endpoint="Responses API",
                    hard_timeout=request.timeout is not None,
                )
                if _retry_output is not None and _retry_report.get("is_valid"):
                    output = _retry_output
                    _ns_visible_answer_finish_reason = getattr(
                        _retry_output, "finish_reason", None
                    )
                    reasoning_text = None
                    content_for_parsing = _retry_output.text
                    cleaned_text = _retry_output.text
                    _structured_report = _retry_report
            repaired_xml = _structured_report.get("xml")
            is_valid = bool(_structured_report.get("is_valid"))
            error = _structured_report.get("error")
            structured_output_warnings = _structured_output_repair_warning(
                _structured_report
            )
            if repaired_xml is not None:
                cleaned_text = str(repaired_xml)
            if not is_valid:
                if _xml_response_config.get("strict"):
                    raise HTTPException(
                        status_code=400, detail=f"response_format strict mode: {error}"
                    )
                logger.warning(f"[responses] XML validation failed: {error}")
    elif (
        _text_format
        and isinstance(_text_format, dict)
        and _text_format.get("type") not in (None, "text")
        and not tool_calls
    ):
        # Build a response_format-compatible dict for parse_json_output
        _rf_type = _text_format.get("type", "")
        if _rf_type in ("json_schema", "json_object"):
            response_format = _text_format
            _out_text = cleaned_text or content_for_parsing
            _structured_report = repair_json_output(
                _out_text, response_format
            )
            if not _structured_report.get("is_valid"):
                _retry_output, _retry_report = await _retry_structured_output_json_once(
                    engine=engine,
                    messages=messages,
                    chat_kwargs=chat_kwargs,
                    response_format=response_format,
                    invalid_text=_out_text or "",
                    error=_structured_report.get("error"),
                    timeout=timeout,
                    fastapi_request=fastapi_request,
                    request_id=f"{response_id}-json-retry",
                    endpoint="Responses API",
                    hard_timeout=request.timeout is not None,
                )
                if _retry_output is not None and _retry_report.get("is_valid"):
                    output = _retry_output
                    _ns_visible_answer_finish_reason = getattr(
                        _retry_output, "finish_reason", None
                    )
                    reasoning_text = None
                    content_for_parsing = _retry_output.text
                    cleaned_text = _retry_output.text
                    _structured_report = _retry_report
            parsed_json = _structured_report.get("parsed")
            is_valid = bool(_structured_report.get("is_valid"))
            error = _structured_report.get("error")
            structured_output_warnings = _structured_output_repair_warning(
                _structured_report
            )
            if parsed_json is not None:
                cleaned_text = json.dumps(parsed_json)
            if not is_valid:
                _rf_strict = _text_format.get("json_schema", {}).get("strict", False)
                if _rf_strict:
                    raise HTTPException(
                        status_code=400, detail=f"response_format strict mode: {error}"
                    )
                logger.warning(f"[responses] JSON validation failed: {error}")

    # Enforce tool_choice="required": model MUST produce at least one tool call
    _resp_tool_choice = getattr(request, "tool_choice", None)
    if _is_pending_required_tool_choice(request) and not tool_calls:
        tool_required_preview = (parse_text or content_for_parsing or "")
        tool_required_preview = tool_required_preview.replace("\n", "\\n")[:500]
        logger.warning(
            f"tool_choice='required' but model produced no tool calls. "
            f"Returning error to client. raw_preview={tool_required_preview!r}"
        )
        raise HTTPException(
            status_code=400,
            detail={
                "message": (
                    f"{_describe_required_tool_choice(_resp_tool_choice)} was set but the model did not "
                    "produce any tool calls. Try rephrasing your prompt or using a "
                    "model with better tool-calling support."
                ),
                "raw_preview": tool_required_preview,
            },
        )

    _response_finish = (
        _ns_visible_answer_finish_reason
        if _ns_visible_answer_finish_reason is not None
        else getattr(output, "finish_reason", None)
    )
    _note_request_diagnostics_id(response_id)
    _response_terminal = _responses_terminal_state(
        _response_finish, request_id=response_id
    )

    # Build output array
    output_items = []

    # Add reasoning output if present
    if reasoning_text:
        output_items.append(
            ResponsesReasoningItem(
                status=_response_terminal.item_status,
                summary=[ResponsesReasoningSummaryText(text=reasoning_text)],
            )
        )

    # Add main message (use cleaned text if tool calls were extracted, otherwise raw text)
    final_text = _select_responses_visible_text(
        cleaned_text=cleaned_text,
        raw_text=content_for_parsing,
        tool_calls=tool_calls,
        suppress_tools=_suppress_tools,
    )
    if final_text:
        final_text = _finalize_visible_text_for_request(final_text, request, minimum_partial=4)
    final_text = _drop_tool_visible_channel_marker(final_text, tool_calls) or ""
    if final_text:
        output_items.append(
            ResponsesOutputMessage(
                status=_response_terminal.item_status,
                role="assistant",
                content=[ResponsesOutputText(text=final_text)],
            )
        )

    # Add tool calls as separate function_call output items (Responses API format)
    if tool_calls:
        for tc in tool_calls:
            func = tc.function if hasattr(tc, "function") else tc
            # Forward tc.id from parser so stateful tool-use loops can correlate results
            tc_call_id = tc.id if hasattr(tc, "id") and tc.id else None
            fc_kwargs = dict(
                name=func.name if hasattr(func, "name") else func.get("name", ""),
                arguments=func.arguments
                if hasattr(func, "arguments")
                else func.get("arguments", ""),
            )
            if tc_call_id:
                fc_kwargs["call_id"] = tc_call_id
            output_items.append(
                ResponsesFunctionCall(
                    status=_response_terminal.item_status,
                    **fc_kwargs,
                )
            )

    # Detect reasoning-only output: any reasoning items present, no visible
    # message text, no tool/function calls. Empty streaming-style message
    # shells do not count as visible output. Tracked so chained turns surface
    # a warning.
    _reasoning_only = _responses_output_is_reasoning_only(output_items)
    if _reasoning_only:
        _note_request_diagnostics_id(response_id)
        _response_terminal = _responses_terminal_state(
            _response_finish,
            reasoning_only_no_content=True,
            request_id=response_id,
        )
        for _item in output_items:
            if hasattr(_item, "status"):
                _item.status = _response_terminal.item_status

    # Pop the effort-substitution record minted by the pre-policy route id
    # (additive field; None when no coercion happened for this request).
    from vmlx_engine.context_limits import pop_effort_substitution as _ns_pop_effort

    response_obj = ResponsesObject(
        id=response_id,
        model=request.model,
        status=_response_terminal.response_status,
        output=output_items,
        usage=_get_responses_usage(output),
        previous_response_id=request.previous_response_id,
        incomplete_details=_response_terminal.incomplete_details,
        effort_substitution=_ns_pop_effort(str(response_id)),
        warnings=_merge_responses_warnings(
            _chain_warnings_for_previous_response_id(request.previous_response_id),
            _current_response_warnings_for_reasoning_only(
                _reasoning_only,
                _response_finish,
            ),
            structured_output_warnings,
            _take_tool_call_drop_diagnostics() or None,
        ),
    )
    if _response_terminal.finish_reason not in {"cancelled", "error"}:
        _responses_store_history(
            response_obj.id,
            history_messages + _responses_output_to_assistant_messages(output_items),
            reasoning_only=_reasoning_only,
        )
    return response_obj


def _inject_json_instruction(messages: list, instruction: str) -> list:
    """
    Inject JSON instruction into messages.

    If a system message exists, append to it. Otherwise, prepend a new system message.
    """
    messages = list(messages)  # Make a copy

    # Find existing system message
    system_idx = None
    for i, msg in enumerate(messages):
        role = msg.get("role") if isinstance(msg, dict) else getattr(msg, "role", None)
        if role == "system":
            system_idx = i
            break

    if system_idx is not None:
        # Append to existing system message
        msg = messages[system_idx]
        if isinstance(msg, dict):
            existing = msg.get("content", "")
            msg["content"] = f"{existing}\n\n{instruction}"
        else:
            existing = getattr(msg, "content", "") or ""
            msg.content = f"{existing}\n\n{instruction}"
    else:
        # Prepend new system message
        messages.insert(0, {"role": "system", "content": instruction})

    return messages


# =============================================================================
# Streaming Helpers
# =============================================================================


async def stream_completions_multi(
    engine: BaseEngine,
    prompts: list[str],
    request: CompletionRequest,
) -> AsyncIterator[str]:
    """Stream completion responses for one or more prompts.

    Each prompt gets its own choice index in the streaming chunks.
    A single [DONE] sentinel is sent after all prompts complete.
    """
    response_id = f"cmpl-{uuid.uuid4().hex[:8]}"
    created = int(time.time())

    # Use per-request timeout if provided, otherwise server default
    _stream_timeout = (
        request.timeout if request.timeout is not None else _default_timeout
    )

    for prompt_index, prompt in enumerate(prompts):
        # Per-prompt request_id so abort targets the correct engine request
        prompt_request_id = f"{response_id}-{prompt_index}"
        try:
            gen_kwargs: dict = {
                "prompt": prompt,
                "max_tokens": _resolve_max_tokens(request.max_tokens, getattr(request, "model", "")),
                "temperature": _resolve_temperature(request.temperature, request.model),
                "top_p": _resolve_top_p(request.top_p, request.model),
                "stop": request.stop,
                "request_id": prompt_request_id,
                "max_prompt_tokens": _effective_max_prompt_tokens(request),
            }
            if request.seed is not None:
                gen_kwargs["seed"] = request.seed
            _set_resolved_top_k(gen_kwargs, request.top_k, request.model)
            _normalize_deterministic_sampling_filters(
                gen_kwargs,
                request_top_p=request.top_p,
                request_top_k=request.top_k,
            )
            _set_resolved_min_p(gen_kwargs, request.min_p, request.model)
            _rp = _resolve_repetition_penalty(request.repetition_penalty, request.model)
            if _rp is not None:
                gen_kwargs["repetition_penalty"] = _rp
            _forward_openai_token_controls(gen_kwargs, request)
            if _compute_bypass_prefix_cache(request):
                gen_kwargs["_bypass_prefix_cache"] = True
            if request.logprobs is not None:
                gen_kwargs["logprobs"] = True
                gen_kwargs["top_logprobs"] = request.logprobs
            if request.reasoning_effort is not None:
                gen_kwargs["reasoning_effort"] = request.reasoning_effort
            if request.enable_thinking is not None:
                gen_kwargs["enable_thinking"] = request.enable_thinking
            if _is_loaded_dsv4_model(request.model):
                # DSV4 on the streaming /v1/completions rail: the generic path
                # below streams raw `<think>RC</think>content` deltas. The
                # canonical DSV4 template glues reasoning to content with no
                # separator, so raw-text consumers that fence-match code
                # (HumanEval-style harnesses) see `</think>```python` and
                # fail. Route through engine.chat() and emit one aggregate
                # chunk carrying only the visible text — exact parity with the
                # non-stream DSV4 completion branch.
                chat_prompt = _dsv4_completion_prompt_for_chat_rail(
                    prompt, request
                )
                chat_kwargs = {
                    key: value
                    for key, value in gen_kwargs.items()
                    if key != "prompt"
                }
                chat_kwargs["max_tokens"] = _dsv4_completion_internal_max_tokens(
                    chat_kwargs["max_tokens"],
                    request,
                )
                decision = _resolve_dsv4_thinking_policy(
                    requested_enable_thinking=True,
                    effort_requested=False,
                    tools_present=False,
                    tool_choice=None,
                    default_mode=_jang_chat_default_mode(
                        _model_path or _model_name or request.model or ""
                    ),
                )
                chat_kwargs["enable_thinking"] = decision.enable_thinking
                _set_resolved_repetition_penalty(
                    chat_kwargs,
                    request.repetition_penalty,
                    request.model,
                    enable_thinking=decision.enable_thinking,
                )
                output = await asyncio.wait_for(
                    engine.chat(
                        messages=[{"role": "user", "content": chat_prompt}],
                        **chat_kwargs,
                    ),
                    timeout=_stream_timeout,
                )
                data = {
                    "id": response_id,
                    "object": "text_completion",
                    "created": created,
                    "model": request.model,
                    "choices": [
                        {
                            "index": prompt_index,
                            "text": _visible_text_for_dsv4_completion(
                                output, engine, request
                            ),
                            "finish_reason": output.finish_reason,
                        }
                    ],
                    "usage": get_usage(output).model_dump(exclude_none=True),
                }
                yield f"data: {json.dumps(data, ensure_ascii=True)}\n\n"
                continue
            if _is_loaded_mimo_v2_model(request.model) or bool(
                getattr(engine, "is_mllm", False)
                or getattr(engine, "_is_mllm", False)
            ):
                # Loaded MLLM on the streaming /v1/completions rail: same W1-3
                # degeneration as the non-stream branch (raw prompt bypasses
                # the native chat template -> malformed MLLM prefill). Route
                # through engine.chat() and emit one aggregate completion
                # chunk, matching the existing MiMo-V2 completion behavior.
                chat_kwargs = _completion_gen_kwargs_to_chat_kwargs(
                    gen_kwargs,
                    bundle_path=_model_path or _model_name or request.model or "",
                )
                output = await asyncio.wait_for(
                    engine.chat(
                        messages=[{"role": "user", "content": prompt}],
                        **chat_kwargs,
                    ),
                    timeout=_stream_timeout,
                )
                data = {
                    "id": response_id,
                    "object": "text_completion",
                    "created": created,
                    "model": request.model,
                    "choices": [
                        {
                            "index": prompt_index,
                            "text": output.text,
                            "finish_reason": output.finish_reason,
                        }
                    ],
                    "usage": get_usage(output).model_dump(exclude_none=True),
                }
                yield f"data: {json.dumps(data, ensure_ascii=True)}\n\n"
                continue
            stream_logprob_offset = 0
            async for output in _stream_with_keepalive(
                engine.stream_generate(**gen_kwargs),
                total_timeout=_stream_timeout,
                progress_probe=(
                    None
                    if request.timeout is not None
                    else lambda rid=prompt_request_id: _engine_request_progress(
                        engine, rid
                    )
                ),
            ):
                if output is None:
                    yield ": keep-alive\n\n"
                    continue
                raw_logprobs = getattr(output, "logprobs", None) or []
                choice = {
                    "index": prompt_index,
                    "text": output.new_text,
                    "finish_reason": output.finish_reason
                    if output.finished
                    else None,
                }
                if request.logprobs is not None:
                    delta_logprobs = raw_logprobs[stream_logprob_offset:]
                    stream_logprob_offset = len(raw_logprobs)
                    choice["logprobs"] = _format_completion_logprobs(
                        delta_logprobs,
                        engine.tokenizer,
                    )
                data = {
                    "id": response_id,
                    "object": "text_completion",
                    "created": created,
                    "model": request.model,
                    "choices": [choice],
                }
                if output.finished:
                    data["usage"] = get_usage(output).model_dump(exclude_none=True)
                yield f"data: {json.dumps(data, ensure_ascii=True)}\n\n"
        # PrefillAdmissionError rides along: same class of client error (the
        # device cannot serve this context), and the body below uses only
        # str(e), so it needs no PromptTooLongError-specific fields.
        except (MediaControlsUnmeetableError, MediaInputError) as e:
            if hasattr(engine, "abort_request"):
                await engine.abort_request(prompt_request_id)
            error_data = {
                "id": response_id,
                "object": "text_completion",
                "error": {
                    "message": str(e),
                    "type": "invalid_request_error",
                    "code": type(e).code,
                },
            }
            yield f"data: {json.dumps(error_data)}\n\n"
        except (PromptTooLongError, PrefillAdmissionError) as e:
            if hasattr(engine, "abort_request"):
                await engine.abort_request(prompt_request_id)
            error_data = {
                "id": response_id,
                "object": "text_completion",
                "error": {
                    "message": str(e),
                    "type": "invalid_request_error",
                    "code": "prompt_too_long",
                },
            }
            yield f"data: {json.dumps(error_data)}\n\n"
        except VLMImagePrefillBudgetError as e:
            if hasattr(engine, "abort_request"):
                await engine.abort_request(prompt_request_id)
            error_data = {
                "id": response_id,
                "object": "text_completion",
                "error": {
                    "message": str(e),
                    "type": "invalid_request_error",
                    "code": VLMImagePrefillBudgetError.code,
                },
            }
            yield f"data: {json.dumps(error_data)}\n\n"
        except UnsupportedMediaModalityError as e:
            if hasattr(engine, "abort_request"):
                await engine.abort_request(prompt_request_id)
            error_data = {
                "id": response_id,
                "object": "text_completion",
                "error": {
                    "message": str(e),
                    "type": "invalid_request_error",
                    "code": UnsupportedMediaModalityError.code,
                },
            }
            yield f"data: {json.dumps(error_data)}\n\n"
        except Exception as e:
            logger.error(f"Stream error for {response_id}: {e}", exc_info=True)
            if hasattr(engine, "abort_request"):
                await engine.abort_request(prompt_request_id)
            error_data = {
                "id": response_id,
                "object": "text_completion",
                "error": {
                    "message": f"Stream generation failed: {e}",
                    "type": "server_error",
                    "code": "internal_error",
                },
            }
            yield f"data: {json.dumps(error_data)}\n\n"

    yield "data: [DONE]\n\n"


def _dump_sse_json(obj) -> str:
    """Serialize Pydantic model to ASCII-safe JSON for SSE streaming.

    Uses ensure_ascii=True so emoji and other multi-byte UTF-8 characters
    are encoded as \\uXXXX escape sequences. This prevents corruption when
    HTTP chunk boundaries split raw UTF-8 bytes.
    Uses exclude_none=True so fields like reasoning_content don't appear
    when they have no value (cleaner streaming output).
    """
    return json.dumps(obj.model_dump(exclude_none=True), ensure_ascii=True)


# ─── SSE keep-alive helper ──────────────────────────────────────────────
# During long prefills (VLMs, large contexts), no tokens are emitted for
# many seconds. Clients, proxies, and load balancers may treat the silence
# as a stalled connection and drop it. This wrapper yields None sentinels
# when no item arrives within `interval` seconds, which the streaming
# generators convert to SSE comments (`: keep-alive\n\n`).

_SSE_KEEPALIVE_INTERVAL = 15.0  # seconds

# How many extra timeout windows to spend when the engine cannot report progress
# at all. A probe returning None means "unknown", not "stalled", and from outside
# the engine a 250k-token prefill is indistinguishable from a wedged request. Two
# extra windows is enough for a prefill that overran its window to land (the
# DSV4-Flash turn that motivated this needed 903s against 900s) while still
# bounding how long a genuinely wedged request can hold the engine.
_UNKNOWN_PROGRESS_GRACE_WINDOWS = 2


async def _stream_with_keepalive(
    async_gen,
    interval: float = _SSE_KEEPALIVE_INTERVAL,
    total_timeout: float | None = None,
    progress_probe=None,
):
    """Yield items from async generator, inserting None sentinels on timeout.
    If total_timeout is set, raises TimeoutError after that many seconds of total streaming.

    When progress_probe is provided (server-default timeout, not an explicit
    per-request one), the timeout is progress-aware: if the engine reports the
    request advanced tokens since the last window, the window resets instead of
    killing a healthy long prefill/decode. Only a request with zero progress
    across a full window is treated as wedged.

    Uses asyncio.wait() which does NOT cancel the pending future on timeout —
    critical because cancelling an async generator's __anext__() finalizes it.
    asyncio.wait_for() MUST NOT be used here: it cancels on timeout, which
    kills the stream during long prefills or tool call generation.
    """
    it = async_gen.__aiter__()
    pending = asyncio.ensure_future(it.__anext__())
    start = time.monotonic()
    last_progress: int | None = None
    # A probe means this is the SERVER-DEFAULT timeout, which is documented as a
    # stall detector. An explicit per-request timeout passes no probe and is
    # documented as wall-clock, so it must keep firing even while output flows.
    progress_aware = progress_probe is not None
    unknown_progress_windows = 0
    try:
        while True:
            if total_timeout and (time.monotonic() - start) > total_timeout:
                # An item already sitting in `pending` is the strongest possible
                # evidence of progress — stronger than any out-of-band probe —
                # and discarding it throws away work already paid for.
                #
                # LIVE: DSV4-Flash turn 4 of the 400k benchmark, a 332k prompt
                # with 249k reused and 83k fresh, was killed at wall=903.3s
                # against the 900s window. Its first token landed as the window
                # expired, the probe happened to report nothing, and ~15 minutes
                # of completed prefill was thrown away as "wedged".
                if progress_aware and pending.done():
                    start = time.monotonic()
                else:
                    progress = None
                    if progress_probe is not None:
                        try:
                            progress = progress_probe()
                        except Exception:
                            progress = None
                    if progress is not None and progress > 0 and (
                        last_progress is None or progress > last_progress
                    ):
                        logger.info(
                            "Stream still progressing (%d tokens, +%d this "
                            "window) — extending %.1fs timeout window",
                            progress,
                            progress - (last_progress or 0),
                            total_timeout,
                        )
                        last_progress = progress
                        # Real evidence clears the ambiguity budget, so a later
                        # unreadable stretch gets the full grace again.
                        unknown_progress_windows = 0
                        start = time.monotonic()
                    elif (
                        progress_aware
                        and not progress  # None OR 0 — see below
                        and unknown_progress_windows < _UNKNOWN_PROGRESS_GRACE_WINDOWS
                    ):
                        # ZERO IS ALSO "UNKNOWN", and this is the case that
                        # actually happens for generic text generators.
                        # `Scheduler.request_progress` returns lifetime output
                        # tokens there, so nothing advances it during prefill.
                        # DSV4 and MLLM expose real chunk progress and normally
                        # avoid this ambiguity branch.
                        # (It used to sum `num_computed_tokens +
                        # total_output_tokens`, which double-counted and went
                        # backwards across a recovery retry; the observation
                        # this comment records was what exposed that.)
                        #
                        # Gating this grace on `progress is None` alone left the
                        # 900s kill exactly as it was for every prefill, which is
                        # the only phase long enough to hit it: `0 > 0` fails the
                        # branch above, `0 is not None` failed this one, and the
                        # request died at the first window. The DSV4-Flash turn
                        # this was written for would have died identically.
                        #
                        # So treat "no positive evidence" as ambiguous however it
                        # is spelled. A wedged request still dies, just after a
                        # bounded number of windows instead of one.
                        unknown_progress_windows += 1
                        logger.warning(
                            "Stream %.1fs window elapsed with no engine progress "
                            "reading — cannot distinguish a long prefill from a "
                            "wedged request; extending (%d/%d)",
                            total_timeout,
                            unknown_progress_windows,
                            _UNKNOWN_PROGRESS_GRACE_WINDOWS,
                        )
                        start = time.monotonic()
                    else:
                        raise TimeoutError(
                            f"Streaming exceeded {total_timeout}s timeout"
                        )
            done, _ = await asyncio.wait({pending}, timeout=interval)
            if done:
                try:
                    item = pending.result()
                except StopAsyncIteration:
                    return
                except Exception as e:
                    logger.error(f"Stream generator error: {e}")
                    raise
                # Output produced means not stalled. Reset the window here too,
                # so a stream that keeps delivering is never killed for having
                # run a long time — that is what `total_timeout` means under the
                # server default, per this function's own docstring.
                if progress_aware:
                    start = time.monotonic()
                yield item
                pending = asyncio.ensure_future(it.__anext__())
            else:
                yield None  # keep-alive sentinel
    finally:
        if not pending.done():
            pending.cancel()


async def _terminal_finish_guard(
    sse_stream: AsyncIterator[str],
    *,
    required_tool_call: bool = False,
) -> AsyncIterator[str]:
    """OpenAI terminal-contract guard for chat-completion SSE streams.

    ``stream_chat_completion`` attaches ``finish_reason`` only inside
    conditional branches (tool finish, flush-remainder, answer pass,
    diagnostics, ...). Natural completion — content fully streamed, model
    stops on EOS — hits none of them, so the stream ended ``…content →
    [DONE]`` with NO chunk carrying ``finish_reason``. Strict OpenAI
    clients (langchain, Claude Code/litellm) wait for a non-null
    ``finish_reason`` before closing and hang or mark the response
    incomplete (docs/STREAMING-FINISH-REASON-FINDINGS-2026-07-02.md;
    GitHub #226 item 4). If no chunk carried a non-null finish_reason by
    ``[DONE]``, inject exactly one terminal ``finish_reason:"stop"`` chunk.

    Detection relies on ``_dump_sse_json``'s ``exclude_none=True`` (the
    key only appears when non-null) and the raw ``json.dumps`` sites'
    explicit ``: null`` form. Applied at the SSE route call sites so the
    generator itself stays the single source for source-inspection
    contract tests.
    """
    finish_seen = False
    required_tool_finish_seen = False
    error_seen = False
    first_chunk_meta = None
    usage_field_seen = False

    def _synthetic_terminal() -> dict | None:
        if first_chunk_meta is None:
            return None
        terminal = {
            "id": first_chunk_meta["id"],
            "object": "chat.completion.chunk",
            "created": first_chunk_meta["created"],
            "model": first_chunk_meta["model"],
            "choices": [
                {
                    "index": 0,
                    "delta": {},
                    "finish_reason": "stop",
                }
            ],
        }
        if usage_field_seen:
            terminal["usage"] = None
        return terminal

    async for sse in sse_stream:
        suppress_frame = False
        if sse.startswith("data: ") and not sse.startswith("data: [DONE]"):
            try:
                _p = json.loads(sse[6:].strip())
            except Exception:
                _p = None
            if isinstance(_p, dict) and _p.get("error") is not None:
                # A structured SSE error is already the terminal contract.
                # Never append a synthetic successful `stop` after it: doing
                # so made guarded VLM prefill failures look like empty normal
                # completions to clients that key off finish_reason.
                error_seen = True
            if isinstance(_p, dict) and "usage" in _p:
                usage_field_seen = True
            if first_chunk_meta is None and '"chat.completion.chunk"' in sse:
                try:
                    if not isinstance(_p, dict):
                        raise ValueError("invalid SSE payload")
                    first_chunk_meta = {
                        "id": _p.get("id"),
                        "created": _p.get("created"),
                        "model": _p.get("model"),
                    }
                except Exception:
                    pass
            _finish_reasons = []
            if isinstance(_p, dict):
                _finish_reasons = [
                    choice.get("finish_reason")
                    for choice in (_p.get("choices") or [])
                    if choice.get("finish_reason") is not None
                ]
            if _finish_reasons:
                if "tool_calls" in _finish_reasons:
                    required_tool_finish_seen = True
                    finish_seen = True
                elif required_tool_call and not error_seen:
                    # A required-tool stream is unresolved until a schema-valid
                    # call is emitted or the final parser emits its structured
                    # error.  Engine ``stop``/``length`` terminals are
                    # provisional and must not precede that decision: strict
                    # clients stop at the first non-null finish_reason and would
                    # otherwise miss the later tool_calls_required error.
                    suppress_frame = True
                else:
                    finish_seen = True
            # include_usage's choices-empty total must remain the last JSON
            # chunk before [DONE]. If the generator omitted finish_reason,
            # insert the guard chunk *before* that usage tail, not at [DONE]
            # after it. Strict clients consume finish -> usage -> [DONE].
            if (
                not finish_seen
                and not error_seen
                and not required_tool_call
                and isinstance(_p, dict)
                and _p.get("choices") == []
                and _p.get("usage") is not None
            ):
                terminal = _synthetic_terminal()
                if terminal is not None:
                    yield f"data: {json.dumps(terminal, ensure_ascii=True)}\n\n"
                    finish_seen = True
        elif (
            sse.startswith("data: [DONE]")
            and not finish_seen
            and not error_seen
        ):
            if required_tool_call and not required_tool_finish_seen:
                # Defensive fail-closed fallback. stream_chat_completion normally
                # emits this error itself after final parsing, but the route guard
                # must never synthesize a successful stop if a future branch exits
                # before that enforcement point.
                meta = first_chunk_meta or {}
                error = {
                    "id": meta.get("id"),
                    "object": "chat.completion.chunk",
                    "error": {
                        "message": (
                            "tool_choice='required' was set but the model did not "
                            "produce any tool calls."
                        ),
                        "type": "invalid_request_error",
                        "code": "tool_calls_required",
                    },
                }
                yield f"data: {json.dumps(error, ensure_ascii=True)}\n\n"
                error_seen = True
            else:
                terminal = _synthetic_terminal()
                if terminal is not None:
                    yield f"data: {json.dumps(terminal, ensure_ascii=True)}\n\n"
                    finish_seen = True
        if not suppress_frame:
            yield sse


async def _request_tool_parser_graceful_stop(engine: Any, request_id: str) -> bool:
    """Stop a parsed tool turn through the engine's cacheable finish path.

    Returning ``False`` tells the caller to retain the legacy abort fallback.
    The supported MLLM path emits one final internal decode step, publishes a
    real finished object, persists KV/native companion/SSD state, and releases
    that object through the existing terminal durability barrier.
    """
    stop = getattr(engine, "request_graceful_stop", None)
    if not callable(stop):
        return False
    try:
        return bool(await stop(request_id))
    except Exception:
        logger.warning(
            "Graceful parser stop failed for %s; falling back to abort",
            request_id,
            exc_info=True,
        )
        return False


async def stream_chat_completion(
    engine: BaseEngine,
    messages: list,
    request: ChatCompletionRequest,
    fastapi_request: Request | None = None,
    response_id: str | None = None,
    **kwargs,
) -> AsyncIterator[str]:
    """Stream chat completion with auto-detection of closed connections."""
    # The chat route mints its id BEFORE the stamped-effort policy and passes
    # it here so policy-recorded notices pop under the id the terminal
    # chunk serializes; adapters that call this generator directly still get
    # a fresh id.
    response_id = response_id or f"chatcmpl-{uuid.uuid4().hex[:8]}"

    # Some adapters (notably Anthropic stream=false) consume this streaming
    # generator inside a non-streaming HTTP handler so they can reuse its
    # reasoning and tool parsing. Starlette does not own a StreamingResponse in
    # that shape, and lazy is_disconnected() polling can miss http.disconnect
    # after the request body has already been consumed. Actively drain receive
    # only for that non-streaming-consumer shape; real StreamingResponse routes
    # retain Starlette's single receive owner.
    _nonstream_disconnect_event = asyncio.Event()
    _nonstream_disconnect_drain: asyncio.Task | None = None
    if (
        fastapi_request is not None
        and request.stream is False
        and hasattr(fastapi_request, "receive")
    ):
        async def _drain_nonstream_disconnect() -> None:
            try:
                while not _nonstream_disconnect_event.is_set():
                    message = await fastapi_request.receive()
                    if (
                        isinstance(message, dict)
                        and message.get("type") == "http.disconnect"
                    ):
                        _nonstream_disconnect_event.set()
                        return
            except asyncio.CancelledError:
                raise
            except Exception:
                _nonstream_disconnect_event.set()

        _nonstream_disconnect_drain = asyncio.create_task(
            _drain_nonstream_disconnect()
        )

    def _stop_nonstream_disconnect_drain() -> None:
        if (
            _nonstream_disconnect_drain is not None
            and not _nonstream_disconnect_drain.done()
        ):
            _nonstream_disconnect_drain.cancel()

    # Pass response_id as request_id to engine for unified tracking
    kwargs["request_id"] = response_id

    # Check if we should include usage in the final chunk
    include_usage = request.stream_options and request.stream_options.include_usage

    def _dump_chat_chunk(obj, *, terminal_usage: bool = False) -> str:
        """Serialize one Chat SSE chunk with OpenAI-compatible usage shape.

        ``include_usage`` requests exactly one non-null, choices-empty usage
        chunk immediately before ``[DONE]``. Ordinary chunks carry
        ``usage:null``; they must never expose the engine's growing counters.
        The Electron client derives live TPS from real reasoning/content
        deltas and consumes the authoritative total from the terminal chunk.
        """
        if hasattr(obj, "model_dump"):
            payload = obj.model_dump(exclude_none=True)
        else:
            payload = dict(obj)
        if include_usage and not terminal_usage:
            payload["usage"] = None
        if terminal_usage:
            # Attach the context-clamp record on the one terminal usage
            # chunk (mirrors the non-stream surface; pops so the registry
            # never leaks). `exhausted` = the clamped budget was consumed.
            from vmlx_engine.context_limits import pop_context_clamp

            _clamp_record = pop_context_clamp(str(response_id))
            if _clamp_record:
                _completion = int(
                    ((payload.get("usage") or {}).get("completion_tokens"))
                    or 0
                )
                payload["context_exhaustion"] = {
                    **_clamp_record,
                    "exhausted": _completion
                    >= int(_clamp_record["clamped_max_tokens"]),
                }
            from vmlx_engine.context_limits import pop_effort_substitution

            _effort_record = pop_effort_substitution(str(response_id))
            if _effort_record:
                payload["effort_substitution"] = _effort_record
        return json.dumps(payload, ensure_ascii=True)

    # Stable timestamp for all chunks in this stream (OpenAI spec compliance)
    _created_ts = int(time.time())

    # First chunk with role
    first_chunk = ChatCompletionChunk(
        id=response_id,
        created=_created_ts,
        model=request.model,
        choices=[
            ChatCompletionChunkChoice(
                delta=ChatCompletionChunkDelta(role="assistant"),
            )
        ],
    )
    yield f"data: {_dump_chat_chunk(first_chunk)}\n\n"

    # Resolve effective enable_thinking:
    # Priority: top-level field > chat_template_kwargs > server default > auto-detect
    # (None = fall through to template/tokenizer auto-detect below — this site
    # drives SSE parser behavior, not engine kwargs, so no Gemma4+tools override.)
    _ct_kwargs = _merge_ct_kwargs(
        request.chat_template_kwargs,
        getattr(request, "reasoning_effort", None),
    )
    _effective_thinking = _resolve_enable_thinking(
        request_value=request.enable_thinking,
        ct_kwargs=_ct_kwargs,
        tools_present=bool(getattr(request, "tools", None)),
        model_key=_model_path or _model_name or request.model,
        engine=engine,
        auto_detect=True,
        reasoning_effort=request.reasoning_effort,
    )
    if _effective_thinking is not None:
        kwargs["enable_thinking"] = _effective_thinking
        request.enable_thinking = _effective_thinking
        _ct_kwargs["enable_thinking"] = _effective_thinking
        kwargs["chat_template_kwargs"] = dict(
            kwargs.get("chat_template_kwargs") or {}, **_ct_kwargs
        )

    # Check if model's chat template injects <think> in the assistant prefix
    # Use _model_name (actual model path) not request.model (which may be "default")
    from .model_config_registry import get_model_config_registry

    _model_config = get_model_config_registry().lookup(
        _model_path or _model_name or request.model
    )
    _family_name = getattr(_model_config, "family_name", None)
    _is_minimax_m3 = getattr(_model_config, "family_name", None) in (
        "minimax_m3",
        "minimax_m3_vl",
    )
    _m3_thinking_mode = (
        (kwargs.get("chat_template_kwargs") or _ct_kwargs or {}).get("thinking_mode")
        if _is_minimax_m3
        else None
    )
    think_in_template = _model_config.think_in_template

    # Fallback only for unknown configs. Known families may expose thinking
    # tokens in vocab without opening a reasoning rail in the rendered prompt.
    think_in_template = _apply_tokenizer_thinking_vocab_fallback(
        think_in_template,
        reasoning_parser=_reasoning_parser,
        tokenizer=engine.tokenizer,
        model_config=_model_config,
    )

    # S5 seed detection: some templates (e.g., Nemotron CRACK) complete the
    # thinking block in the generation prompt (<think>\nOK.\n</think>\n).
    # The model output is plain text — think_in_template must be False so
    # the parser doesn't misclassify all output as reasoning.
    _template_completed_thinking = False
    if think_in_template:
        if _template_completes_thinking(engine.tokenizer, _model_name or request.model):
            _template_completed_thinking = True
            think_in_template = False

    # When user explicitly disables thinking, check if template actually respects it.
    # This is only a raw-template precheck. The parser seed below uses the
    # engine's final prompt contract, including MiniMax's closed no-thinking
    # sentinel for no-tool direct-chat requests.
    if _effective_thinking is False and think_in_template:
        if not _template_always_thinks(engine.tokenizer, _model_name or request.model):
            think_in_template = False

    _reasoning_seed_probe_needed = bool(
        _reasoning_parser
        or getattr(_model_config, "reasoning_parser", None)
        or getattr(_model_config, "think_in_template", False)
    )
    if _reasoning_seed_probe_needed:
        _prompt_enable = True if _effective_thinking is None else bool(_effective_thinking)
        _tools_present_for_prompt = _tools_available_for_generation(
            request, kwargs.get("tools")
        )
        if _engine_prompt_starts_in_reasoning(
            engine.tokenizer,
            model_name=_model_name or request.model,
            enable_thinking=_prompt_enable,
            family_name=getattr(_model_config, "family_name", None),
            tools_present=_tools_present_for_prompt,
        ):
            think_in_template = True
        else:
            think_in_template = False

    if _stamped_think_template_requires_reasoning_seed(
        _model_config,
        _effective_thinking,
        template_completed_thinking=_template_completed_thinking,
    ):
        think_in_template = True

    if _hy3_prompt_starts_in_reasoning(
        model_key=_model_path or _model_name or request.model,
        enable_thinking=_effective_thinking,
        ct_kwargs=kwargs.get("chat_template_kwargs") or _ct_kwargs,
    ):
        think_in_template = True

    if _synthetic_mllm_think_prompt_starts(
        model_key=_model_path or _model_name or request.model,
        enable_thinking=_effective_thinking,
        engine=engine,
    ):
        think_in_template = True

    # MiniMax-M3's enabled mode prompt-opens <mm:think> in the rendered
    # generation prompt, so streamed output starts inside reasoning without
    # emitting an opening tag. Seed the streaming parser the same way the
    # non-streaming parser is seeded, otherwise internal reasoning is emitted
    # as visible content on /v1/chat/completions stream=true.
    # Adaptive emits no template prefix: the model may either open an
    # <mm:think> block or answer directly.  Pre-seeding adaptive as implicit
    # reasoning misroutes a valid tagless direct answer to reasoning_content.
    if _m3_thinking_mode == "enabled":
        think_in_template = True

    # The parser seed must match the final prompt the engine renders. Tool
    # requests may intentionally leave reasoning open; no-tool thinking-off
    # requests may close it before decode.
    effective_think_in_template = think_in_template

    # Suppress reasoning output when user explicitly disabled thinking.
    # The parser still runs (to strip <think> tags from content), but reasoning
    # chunks are dropped so the user never sees them.
    suppress_reasoning = _effective_thinking is False

    # Create a per-request parser instance to avoid mutable-state conflicts
    # when multiple requests stream concurrently.
    # Check if Harmony analysis prefix was injected (set by chat endpoint above)
    _harmony_prefix_active = (
        "prompt_suffix" in kwargs
        and kwargs.get("prompt_suffix", "").startswith(
            "<|start|>assistant<|channel|>analysis"
        )
    ) or _reasoning_parser_is_harmony(_reasoning_parser)
    request_parser = _new_request_reasoning_parser(
        configured_parser=_reasoning_parser,
        model_config=_model_config,
        effective_think_in_template=effective_think_in_template,
        harmony_active=_harmony_prefix_active,
        stream_surface="chat",
        adaptive_mode=bool(_is_minimax_m3 and _m3_thinking_mode == "adaptive"),
    )
    if request_parser is None:
        logger.debug("[chat] No reasoning parser active for this request")

    # Track accumulated text for reasoning parser and tool call detection
    accumulated_text = ""
    accumulated_reasoning = ""  # Track reasoning text for fallback
    accumulated_content = ""  # Track content-only text for tool call marker detection
    _early_stopped_tool_text: str | None = None
    _draining_tool_parser_stop = False
    streamed_content = (
        ""  # Track content actually yielded to client (for post-stream dedup)
    )
    streamed_reasoning_content = ""
    content_was_emitted = False  # Whether any content chunk was actually sent
    reasoning_was_streamed = False  # Whether any reasoning_content chunk was sent

    # Start per-request capture of dropped-tool-call diagnostics so that, when
    # the parser drops a parsed call (missing required args, unavailable name),
    # the stream's terminal warnings array carries an explanation back to the
    # client instead of returning an empty response with no signal (Bug 5).
    _begin_tool_call_drop_capture()

    # Tool call buffering: when we detect a tool call marker in the stream,
    # we stop emitting content and buffer the rest. At end of stream, we parse
    # the buffer for tool calls and emit them as proper tool_calls chunks.
    tool_call_buffering = False  # Are we currently buffering for tool calls?
    tool_call_buffering_notified = False  # Have we sent the buffering signal?
    tool_calls_emitted = False  # Were actual tool calls parsed and emitted?
    # #219 follow-up: the START tool_calls delta emitted at first buffer tick
    # generates its own random id. Cache it here so the final arguments delta
    # can continue index 0 without emitting a second id fragment. OpenAI SDKs
    # concatenate string fields across deltas; repeating the full id would
    # reconstruct ``call_abccall_abc`` instead of one call identifier.
    _stream_tool_call_start_id: str | None = None
    _suppress_tools = getattr(request, "tool_choice", None) == "none"
    # Auto-enable tool call detection when client sends tools in request (#46),
    # even if server wasn't started with --enable-auto-tool-choice
    _request_has_tools = bool(_effective_tools_for_tool_parsing(request))
    _stream_tools_available = _tools_available_for_generation(
        request, kwargs.get("tools")
    )
    # Streaming ``_suppress_tools`` only records tool_choice=="none".  The
    # non-stream handlers additionally flip it via
    # _suppress_tool_parsing_when_no_tools when the request carries no tool
    # schema at all; mirror that union for every visible-display decision so
    # native tool markup never streams as content on a no-tools request.
    _suppress_markup_display = _suppress_tools or not _stream_tools_available
    tool_call_active = (
        _stream_tools_available
        and not _suppress_tools
        and not _tool_call_parser_disabled_explicitly
    )
    # An explicit single-call contract has no legitimate visible prose before
    # the first function call. Responses already buffers that selection turn
    # from token one; Chat must do the same or native/off-template call
    # scaffolding can leak as content before final parsing converts it into
    # structured tool_calls. After a real tool result is in history, stream the
    # answer normally and only re-buffer if a new marker appears.
    _exact_once_requested = _request_explicitly_requires_one_tool_once(request)
    _has_post_user_tool_result = _responses_messages_have_tool_result_after_latest_user(
        messages
    )
    _exact_once_tool_contract = bool(
        tool_call_active
        and _exact_once_requested
        and not _has_post_user_tool_result
    )
    _stream_speculative_tool_start_allowed = False
    if tool_call_active and _exact_once_requested:
        logger.info(
            "Chat exact-once tool gate: initial_selection=%s "
            "post_user_tool_result=%s message_shapes=%s",
            _exact_once_tool_contract,
            _has_post_user_tool_result,
            [
                (message.get("role"), message.get("type"))
                for message in messages
                if isinstance(message, dict)
            ],
        )
    tool_call_buffering = _exact_once_tool_contract
    # Early-stop after a complete tool-call turn (opt-in per tool parser via
    # STREAM_STOPS_AFTER_COMPLETE_CALL). Live-proven need: degraded 2-bit
    # openPangu keeps narrating after <|tool_call_end|> instead of emitting
    # EOS, so the stream runs to max_tokens and ends with
    # finish_reason="length" even though a complete call was produced.
    _tc_stop_parser = (
        _stream_tool_call_early_stop_parser(request) if tool_call_active else None
    )
    _tc_stop_complete_chunks = 0
    m3_reasoning_only_answer_budget: int | None = None
    m3_reasoning_only_answer_enabled = False
    m3_tools_fallback_answer_budget: int | None = None
    reasoning_only_answer_budget: int | None = None
    reasoning_only_answer_enabled = False
    reasoning_only_answer_family = ""
    reasoning_tools_fallback_answer_budget: int | None = None
    _explicit_answer_pass_mtt = getattr(request, "max_thinking_tokens", None)
    _dsv4_default_reserve = False
    if _explicit_answer_pass_mtt is None:
        # Server-managed-budget families (DSV4, Nemotron): reserve answer
        # budget so the never-empty answer pass below can arm. No-op for
        # every other family. The SOFT-cap flag stays DSV4-only — its engine
        # rail implements the lift-at-</think> kwarg; Nemotron hard-splits.
        _explicit_answer_pass_mtt = _dsv4_answer_pass_thinking_cap(
            _family_name, _effective_thinking, kwargs.get("max_tokens")
        )
        _dsv4_default_reserve = (
            _explicit_answer_pass_mtt is not None
            and _family_name == "deepseek_v4"
        )
    if (
        _explicit_answer_pass_mtt is not None
        and _is_minimax_m3
        and (
            _m3_thinking_mode in ("enabled", "adaptive")
            or _effective_thinking is True
        )
    ):
        try:
            _requested_output_budget = int(kwargs.get("max_tokens") or 256)
            _requested_thinking_budget = max(1, int(_explicit_answer_pass_mtt))
            if _requested_thinking_budget < _requested_output_budget:
                kwargs = dict(kwargs)
                kwargs["max_tokens"] = _requested_thinking_budget
                if _stream_tools_available:
                    m3_tools_fallback_answer_budget = _requested_output_budget
                else:
                    m3_reasoning_only_answer_budget = _requested_output_budget
                    m3_reasoning_only_answer_enabled = True
        except Exception:
            m3_reasoning_only_answer_budget = None
            m3_reasoning_only_answer_enabled = False
            m3_tools_fallback_answer_budget = None
    if (
        _explicit_answer_pass_mtt is not None
        and _family_name == "gemma4"
        and _effective_thinking is not False
        and not _stream_tools_available
    ):
        try:
            _requested_output_budget = int(kwargs.get("max_tokens") or 256)
            _requested_thinking_budget = max(1, int(_explicit_answer_pass_mtt))
            if _requested_thinking_budget < _requested_output_budget:
                kwargs = dict(kwargs)
                kwargs["max_tokens"] = _requested_thinking_budget
                reasoning_only_answer_budget = _requested_output_budget
                reasoning_only_answer_enabled = True
                reasoning_only_answer_family = "Gemma4"
        except Exception:
            reasoning_only_answer_budget = None
            reasoning_only_answer_enabled = False
            reasoning_only_answer_family = ""
    if (
        not reasoning_only_answer_enabled
        and _explicit_answer_pass_mtt is not None
        and (
            _family_name in _THINKING_BUDGET_CAP_FAMILIES
            or _family_name == "deepseek_v4"
        )
        and _effective_thinking is not False
    ):
        # The two-stage path is an explicit API contract only. Auto/On without
        # max_thinking_tokens stays in one native decode and preserves its real
        # content and terminal instead of fabricating a fresh-context answer.
        try:
            _requested_output_budget = int(kwargs.get("max_tokens") or 256)
            _requested_thinking_budget = max(1, int(_explicit_answer_pass_mtt))
            if _requested_thinking_budget < _requested_output_budget:
                reasoning_only_answer_family = _reasoning_answer_pass_family_label(
                    _family_name
                )
                if _stream_tools_available:
                    reasoning_tools_fallback_answer_budget = _requested_output_budget
                else:
                    reasoning_only_answer_budget = _requested_output_budget
                    reasoning_only_answer_enabled = True
                kwargs = dict(kwargs)
                if _dsv4_default_reserve:
                    # DSV4 default reserve: SOFT cap enforced engine-side only
                    # while inside the thinking rail; lifts at </think> so the
                    # same pass spends the reserved answer budget instead of
                    # stranding it (v1.6.23 hard split truncated answers that
                    # started just before the cap). Reasoning-only runs still
                    # finish=length at the cap, so the answer pass below arms
                    # exactly as before. Explicit max_thinking_tokens keeps the
                    # hard split contract.
                    kwargs["dsv4_thinking_soft_cap"] = _requested_thinking_budget
                else:
                    kwargs["max_tokens"] = _requested_thinking_budget
        except Exception:
            reasoning_only_answer_budget = None
            reasoning_only_answer_enabled = False
            reasoning_only_answer_family = ""
            reasoning_tools_fallback_answer_budget = None

    # Track token counts for usage reporting
    prompt_tokens = 0
    completion_tokens = 0
    cached_tokens = 0
    cache_detail: str | None = None
    last_output = None
    stream_logprob_offset = 0
    _decode_first_ts: float | None = None
    _decode_first_count = 1
    _decode_last_ts = 0.0
    _decode_last_count = 0

    # Use per-request timeout if provided, otherwise server default
    _stream_timeout = (
        request.timeout if request.timeout is not None else _default_timeout
    )

    try:
        # Stream content (with SSE keep-alive during long prefills)
        async for output in _stream_with_keepalive(
            engine.stream_chat(messages=messages, **kwargs),
            interval=(
                0.25
                if _nonstream_disconnect_drain is not None
                else _SSE_KEEPALIVE_INTERVAL
            ),
            total_timeout=_stream_timeout,
            progress_probe=(
                None
                if request.timeout is not None
                else lambda: _engine_request_progress(engine, response_id)
            ),
        ):
            # Keep-alive sentinel — emit SSE comment to prevent connection timeout
            if output is None:
                if _nonstream_disconnect_event.is_set():
                    logger.info(
                        "Client disconnected from non-stream adapter, aborting %s",
                        response_id,
                    )
                    if hasattr(engine, "abort_request"):
                        await engine.abort_request(response_id)
                    return
                yield ": keep-alive\n\n"
                continue

            # Check if client disconnected
            if _nonstream_disconnect_event.is_set() or (
                fastapi_request
                and _nonstream_disconnect_drain is None
                and await fastapi_request.is_disconnected()
            ):
                logger.info(f"Client disconnected, aborting request {response_id}")
                if hasattr(engine, "abort_request"):
                    await engine.abort_request(response_id)
                return

            delta_text = output.new_text
            last_output = output

            # Track token counts from output (updated each chunk)
            if hasattr(output, "prompt_tokens") and output.prompt_tokens:
                prompt_tokens = output.prompt_tokens
            if hasattr(output, "completion_tokens") and output.completion_tokens:
                completion_tokens = output.completion_tokens
            if completion_tokens > _decode_last_count:
                _decode_last_ts = _decode_output_timestamp(output)
                if _decode_first_ts is None:
                    _decode_first_ts = _decode_last_ts
                    _decode_first_count = completion_tokens
                _decode_last_count = completion_tokens
            if hasattr(output, "cached_tokens") and output.cached_tokens:
                cached_tokens = output.cached_tokens
            _detail = getattr(output, "cache_detail", "") or None
            if _detail is not None:
                cache_detail = _detail
            if getattr(output, "error", None):
                raise RuntimeError(str(getattr(output, "error")))

            if _draining_tool_parser_stop:
                # The parsed native call is already frozen in
                # _early_stopped_tool_text.  Suppress the generator's internal
                # drain token(s), but do not leave the iterator until its real
                # terminal has crossed the cache-persistence barrier.
                if output.finished:
                    break
                continue
            chunk_logprobs = None
            if request.logprobs:
                raw_logprobs = getattr(output, "logprobs", None) or []
                delta_logprobs = raw_logprobs[stream_logprob_offset:]
                stream_logprob_offset = len(raw_logprobs)
                chunk_logprobs = _format_chat_logprobs(
                    delta_logprobs,
                    engine.tokenizer,
                )

            # Always accumulate full text (needed for both reasoning and tool call parsing)
            accumulated_text += delta_text if delta_text else ""

            # Stop generation once the tool-call turn is complete (opt-in per
            # parser). When the active parser declares the turn closed and the
            # model keeps generating past the grace window instead of emitting
            # EOS, abort the engine request and break; the post-stream
            # extraction below then emits the #46 tool_calls data + finish
            # chunks (finish_reason="tool_calls") exactly as if the model had
            # stopped on its own.
            if (
                _tc_stop_parser is not None
                and tool_call_buffering
                and delta_text
                and not output.finished
            ):
                if _tc_stop_parser.stream_tool_calls_complete(accumulated_text):
                    _tc_stop_complete_chunks += 1
                    _tc_stop_grace = int(
                        getattr(
                            _tc_stop_parser,
                            "_stream_stop_grace_chunks",
                            _STREAM_TOOL_CALL_STOP_GRACE_CHUNKS,
                        )
                    )
                    if _tc_stop_complete_chunks > _tc_stop_grace:
                        logger.info(
                            "Stream %s: complete tool call parsed but model kept "
                            "generating %d chunks past it — stopping generation "
                            "(parser=%s)",
                            response_id,
                            _tc_stop_complete_chunks,
                            type(_tc_stop_parser).__name__,
                        )
                        # Drop the post-call rambling so it neither leaks to
                        # the client as content nor steers the post-stream
                        # parse to the wrong channel.
                        accumulated_text = _tc_stop_parser.stream_tool_call_stop_truncate(
                            accumulated_text
                        )
                        _early_stopped_tool_text = accumulated_text
                        if _tc_stop_parser.stream_tool_calls_complete(
                            accumulated_content
                        ):
                            accumulated_content = (
                                _tc_stop_parser.stream_tool_call_stop_truncate(
                                    accumulated_content
                                )
                            )
                        elif _tc_stop_parser.stream_tool_calls_complete(
                            accumulated_reasoning
                        ):
                            # Call arrived mid-reasoning: any accumulated
                            # content came AFTER the call (post-</think>
                            # rambling, never streamed while buffering) and
                            # must not shadow the reasoning-channel parse.
                            accumulated_reasoning = (
                                _tc_stop_parser.stream_tool_call_stop_truncate(
                                    accumulated_reasoning
                                )
                            )
                            accumulated_content = ""
                        if await _request_tool_parser_graceful_stop(
                            engine, response_id
                        ):
                            _draining_tool_parser_stop = True
                            continue
                        if hasattr(engine, "abort_request"):
                            await engine.abort_request(response_id)
                        break
                else:
                    _tc_stop_complete_chunks = 0

            # Use reasoning parser if enabled
            if request_parser and (delta_text or output.finished):
                if delta_text:
                    previous_text = accumulated_text[: -len(delta_text)]
                    delta_msg = _extract_reasoning_stream_delta(
                        request_parser,
                        previous_text,
                        accumulated_text,
                        delta_text,
                        finished=bool(output.finished),
                    )
                else:
                    delta_msg = ChatCompletionChunkDelta()
                if delta_msg is None:
                    # Skip this chunk (e.g., <think> token itself)
                    if output.finished:
                        delta_msg = ChatCompletionChunkDelta()
                    else:
                        if suppress_reasoning:
                            logger.debug(
                                f"[reasoning-debug] parser returned None for delta={repr(delta_text[:50])}, suppress={suppress_reasoning}, think_in_prompt={effective_think_in_template}"
                            )
                        continue

                # Post-parse cleaning for streaming deltas — strip any
                # structural markers that survived the parser's split
                # (e.g. a second `<channel|>` embedded in content when
                # Gemma 4 emits nested channel frames). Must use the
                # DELTA-safe variant that preserves leading/trailing
                # whitespace — otherwise single-space deltas (" the")
                # lose their space, concatenating the entire stream into
                # "Itlooksliketypo" visible garbage (bug 2026-04-21).
                if delta_msg.content:
                    delta_msg.content = strip_marker_tokens_delta(delta_msg.content)
                if delta_msg.reasoning:
                    delta_msg.reasoning = strip_marker_tokens_delta(delta_msg.reasoning)

                # Debug: log parser output when suppress is active
                if suppress_reasoning and (delta_msg.content or delta_msg.reasoning):
                    logger.debug(
                        f"[reasoning-debug] content={repr((delta_msg.content or '')[:30])}, reasoning={repr((delta_msg.reasoning or '')[:30])}, suppress={suppress_reasoning}"
                    )

                # Accumulate for marker detection (before buffering check).
                # Suppressed reasoning stays internal and must not be mirrored
                # into accumulated_content or next-turn visible history.
                if delta_msg.content:
                    accumulated_content += delta_msg.content
                if delta_msg.reasoning:
                    accumulated_reasoning += delta_msg.reasoning

                # Check for tool call markers — separate logic for content vs reasoning:
                # - Content: check accumulated_content (markers can span deltas)
                # - Reasoning: check a trailing window of accumulated_reasoning
                #   (catches markers split across chunk boundaries, but avoids
                #   false positives from earlier reasoning that casually mentions
                #   tool formats like "<function=")
                if tool_call_active and not tool_call_buffering:
                    if delta_msg.content and accumulated_content:
                        tool_call_buffering = _has_tool_marker_or_partial_suffix(
                            accumulated_content
                        ) or _content_forms_raw_json_tool_call(accumulated_content)
                    if not tool_call_buffering and delta_msg.reasoning:
                        _reasoning_tail = (
                            accumulated_reasoning[-30:]
                            if len(accumulated_reasoning) > 30
                            else accumulated_reasoning
                        )
                        # #199-2A: buffer only when the reasoning tail is ACTIVELY
                        # emitting a tool marker (ends with a complete/partial
                        # marker) — a real reasoning-channel tool call is still
                        # captured, but reasoning prose that merely MENTIONS tool
                        # syntax earlier and continues does not stall output.
                        tool_call_buffering = _text_ends_with_tool_marker(
                            _reasoning_tail
                        )
                    # GPT-OSS/Harmony native tool format: to=<name> code{...}
                    # Uses regex for specificity (plain "to=" is too broad for markers list)
                    if not tool_call_buffering:
                        _tc_check = (
                            accumulated_content
                            or (
                                accumulated_reasoning[-30:]
                                if (
                                    accumulated_reasoning
                                    and _parser_routes_tools_via_reasoning_channel(
                                        request_parser, _harmony_prefix_active
                                    )
                                )
                                else ""
                            )
                            or ""
                        )
                        if re.search(r"\bto=\w[\w.]*\s+code\{", _tc_check):
                            tool_call_buffering = True

                if tool_call_buffering:
                    if (
                        _exact_once_tool_contract
                        and not suppress_reasoning
                        and delta_msg.reasoning
                    ):
                        # Exact-once selection turns buffer visible content from
                        # token one, but genuine reasoning should still stream on
                        # the reasoning rail. Stop the reasoning prefix at the
                        # first native tool marker so the structured call itself
                        # never leaks as reasoning text.
                        _safe_reasoning = _visible_prefix_before_unparsed_tool_markup(
                            accumulated_reasoning
                        )
                        if _safe_reasoning.startswith(streamed_reasoning_content):
                            _reasoning_delta = _safe_reasoning[
                                len(streamed_reasoning_content) :
                            ]
                        else:
                            _reasoning_delta = ""
                        if _reasoning_delta:
                            reasoning_was_streamed = True
                            streamed_reasoning_content += _reasoning_delta
                            reasoning_chunk = ChatCompletionChunk(
                                id=response_id,
                                created=_created_ts,
                                model=request.model,
                                choices=[
                                    ChatCompletionChunkChoice(
                                        delta=ChatCompletionChunkDelta(
                                            reasoning=_reasoning_delta
                                        ),
                                        finish_reason=None,
                                    )
                                ],
                            )
                            yield f"data: {_dump_chat_chunk(reasoning_chunk)}\n\n"
                    # Buffering is speculative until the final parser returns a
                    # schema-valid function call. Do not advertise an OpenAI
                    # tool_calls START delta here: malformed required-tool
                    # output and optional/post-tool native marker residue can
                    # false-trigger buffering, and strict coding harnesses will
                    # treat the empty delta as a real call. Valid calls still
                    # receive a START delta immediately before the final
                    # schema-valid call deltas are emitted below.
                    if (
                        not tool_call_buffering_notified
                        and _stream_speculative_tool_start_allowed
                    ):
                        tool_call_buffering_notified = True
                        if _stream_tool_call_start_id is None:
                            _stream_tool_call_start_id = generate_tool_id()
                        start_chunk = {
                            "id": response_id,
                            "object": "chat.completion.chunk",
                            "created": _created_ts,
                            "model": request.model,
                            "choices": [
                                {
                                    "index": 0,
                                    "delta": {
                                        "role": "assistant",
                                        "tool_calls": [
                                            {
                                                "index": 0,
                                                "id": _stream_tool_call_start_id,
                                                "type": "function",
                                                "function": {"name": "", "arguments": ""},
                                            }
                                        ],
                                    },
                                    "finish_reason": None,
                                }
                            ],
                        }
                        yield f"data: {_dump_chat_chunk(start_chunk)}\n\n"
                    elif not tool_call_buffering_notified:
                        tool_call_buffering_notified = True
                    # Subsequent ticks: spec-clean empty delta.
                    # No `tool_call_generating` field and no non-terminal usage.
                    buf_chunk = ChatCompletionChunk(
                        id=response_id,
                        created=_created_ts,
                        model=request.model,
                        choices=[
                            ChatCompletionChunkChoice(
                                delta=ChatCompletionChunkDelta(content=None),
                                finish_reason=None,
                            )
                        ],
                    )
                    yield f"data: {_dump_chat_chunk(buf_chunk)}\n\n"
                    continue

                # Suppressed reasoning is never redirected into visible content.
                # If a boundary delta carries both reasoning and content, only
                # the content half is user-visible.
                if suppress_reasoning:
                    emit_content = delta_msg.content
                    emit_reasoning = None
                    if not emit_content and not output.finished:
                        heartbeat = ChatCompletionChunk(
                            id=response_id,
                            created=_created_ts,
                            model=request.model,
                            choices=[
                                ChatCompletionChunkChoice(
                                    delta=ChatCompletionChunkDelta(content=None),
                                    finish_reason=None,
                                )
                            ],
                        )
                        yield f"data: {_dump_chat_chunk(heartbeat)}\n\n"
                        continue
                else:
                    emit_reasoning = delta_msg.reasoning
                    emit_content = delta_msg.content

                if tool_call_active and emit_reasoning:
                    safe_reasoning_prefix = _tool_safe_stream_prefix(
                        accumulated_reasoning,
                        finished=output.finished,
                    )
                    emit_reasoning = (
                        safe_reasoning_prefix[len(streamed_reasoning_content) :]
                        if safe_reasoning_prefix.startswith(streamed_reasoning_content)
                        else None
                    )

                # Tool-call-only streams often start with harmless whitespace
                # before the native marker (DSV4 commonly emits "\n\n<｜DSML｜…").
                # Do not send that whitespace as visible content until we know
                # the turn is not a tool call; otherwise clients see a blank
                # assistant message before the structured tool_calls delta.
                if (
                    tool_call_active
                    and not content_was_emitted
                    and emit_content
                    and not emit_content.strip()
                ):
                    if include_usage:
                        heartbeat = ChatCompletionChunk(
                            id=response_id,
                            created=_created_ts,
                            model=request.model,
                            choices=[
                                ChatCompletionChunkChoice(
                                    delta=ChatCompletionChunkDelta(content=None),
                                    finish_reason=None,
                                )
                            ],
                        )
                        yield f"data: {_dump_chat_chunk(heartbeat)}\n\n"
                    continue

                # Once the reasoning parser exposes content, it is real stream
                # output and must follow the same progressive contract as the
                # Responses API. The old family-wide deferral held every answer
                # token until finish, making clean Step/Bonsai/MiniMax turns look
                # frozen and converting decode into one synthetic terminal blob.
                # If the client cap is reached after visible content, preserve
                # the honest incremental prefix + finish_reason="length". The
                # bounded direct answer pass remains only for truly content-empty
                # reasoning runs, where nothing has been sent and replacement is
                # still possible without duplicate or unretractable output.
                if _suppress_markup_display and emit_content:
                    safe_content_prefix = (
                        _tool_safe_stream_prefix(
                            accumulated_content, finished=output.finished
                        )
                        if tool_call_active
                        else accumulated_content
                    )
                    emit_content = _suppressed_tool_display_delta(
                        safe_content_prefix,
                        streamed_content,
                        request,
                    )
                elif emit_content:
                    safe_content_prefix = (
                        _tool_safe_stream_prefix(
                            accumulated_content, finished=output.finished
                        )
                        if tool_call_active
                        else accumulated_content
                    )
                    emit_content = _visual_grounding_display_delta(
                        safe_content_prefix,
                        streamed_content,
                    )

                if output.finished and not tool_call_buffering:
                    terminal_suffix = _terminal_visible_stream_suffix(
                        getattr(output, "text", ""),
                        streamed_content + (emit_content or ""),
                        parser=request_parser,
                        request=request,
                        suppress_markup=_suppress_markup_display,
                        tools_active=tool_call_active,
                    )
                    if terminal_suffix:
                        emit_content = (emit_content or "") + terminal_suffix
                        accumulated_content += terminal_suffix

                # Skip chunks that have nothing to emit after conversion
                if not emit_content and not emit_reasoning and not output.finished:
                    continue

                if emit_reasoning:
                    reasoning_was_streamed = True
                    streamed_reasoning_content += emit_reasoning
                if emit_content:
                    content_was_emitted = True
                    streamed_content += emit_content

                # The first reasoning pass is an internal stage when a bounded
                # visible-answer continuation is armed.  Do not expose its
                # length/stop reason as the terminal reason for the whole API
                # stream; a standards-compliant client may stop immediately.
                _answer_pass_pending = bool(
                    m3_reasoning_only_answer_enabled
                    or reasoning_only_answer_enabled
                    or m3_tools_fallback_answer_budget is not None
                    or reasoning_tools_fallback_answer_budget is not None
                )

                chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[
                        ChatCompletionChunkChoice(
                            delta=ChatCompletionChunkDelta(
                                content=emit_content,
                                reasoning=emit_reasoning,
                            ),
                            logprobs=chunk_logprobs,
                            finish_reason=_main_pass_finish_reason(
                                output.finish_reason,
                                finished=bool(output.finished),
                                content_was_emitted=content_was_emitted,
                                accumulated_reasoning=accumulated_reasoning,
                                answer_pass_pending=_answer_pass_pending,
                            ),
                        )
                    ],
                )
                yield f"data: {_dump_chat_chunk(chunk)}\n\n"
            elif not request_parser:
                # Standard path without reasoning parsing (no parser configured)
                content = delta_text

                # Check for tool call markers — start buffering when detected
                if tool_call_active and not tool_call_buffering and content:
                    tool_call_buffering = _has_tool_marker_or_partial_suffix(
                        accumulated_text
                    )

                if tool_call_buffering:
                    # Same contract as the reasoning-parser branch: buffering
                    # emits only neutral heartbeats until a schema-valid tool
                    # call exists. Valid calls still get a START delta below.
                    if (
                        not tool_call_buffering_notified
                        and _stream_speculative_tool_start_allowed
                    ):
                        tool_call_buffering_notified = True
                        if _stream_tool_call_start_id is None:
                            _stream_tool_call_start_id = generate_tool_id()
                        start_chunk = {
                            "id": response_id,
                            "object": "chat.completion.chunk",
                            "created": _created_ts,
                            "model": request.model,
                            "choices": [
                                {
                                    "index": 0,
                                    "delta": {
                                        "role": "assistant",
                                        "tool_calls": [
                                            {
                                                "index": 0,
                                                "id": _stream_tool_call_start_id,
                                                "type": "function",
                                                "function": {"name": "", "arguments": ""},
                                            }
                                        ],
                                    },
                                    "finish_reason": None,
                                }
                            ],
                        }
                        yield f"data: {_dump_chat_chunk(start_chunk)}\n\n"
                    elif not tool_call_buffering_notified:
                        tool_call_buffering_notified = True
                    buf_chunk = ChatCompletionChunk(
                        id=response_id,
                        created=_created_ts,
                        model=request.model,
                        choices=[
                            ChatCompletionChunkChoice(
                                delta=ChatCompletionChunkDelta(content=None),
                                finish_reason=None,
                            )
                        ],
                    )
                    yield f"data: {_dump_chat_chunk(buf_chunk)}\n\n"
                    continue

                # Same leading-whitespace guard as the reasoning-parser path.
                if (
                    tool_call_active
                    and not content_was_emitted
                    and content
                    and not content.strip()
                ):
                    if include_usage:
                        heartbeat = ChatCompletionChunk(
                            id=response_id,
                            created=_created_ts,
                            model=request.model,
                            choices=[
                                ChatCompletionChunkChoice(
                                    delta=ChatCompletionChunkDelta(content=None),
                                    finish_reason=None,
                                )
                            ],
                        )
                        yield f"data: {_dump_chat_chunk(heartbeat)}\n\n"
                    continue

                if _suppress_markup_display and content:
                    safe_text_prefix = (
                        _tool_safe_stream_prefix(
                            accumulated_text, finished=output.finished
                        )
                        if tool_call_active
                        else accumulated_text
                    )
                    content = _suppressed_tool_display_delta(
                        safe_text_prefix,
                        streamed_content,
                        request,
                    )
                elif content:
                    safe_text_prefix = (
                        _tool_safe_stream_prefix(
                            accumulated_text, finished=output.finished
                        )
                        if tool_call_active
                        else accumulated_text
                    )
                    content = _visual_grounding_display_delta(
                        safe_text_prefix,
                        streamed_content,
                    )

                if output.finished and not tool_call_buffering:
                    terminal_suffix = _terminal_visible_stream_suffix(
                        getattr(output, "text", ""),
                        streamed_content + (content or ""),
                        request=request,
                        suppress_markup=_suppress_markup_display,
                        tools_active=tool_call_active,
                    )
                    if terminal_suffix:
                        content = (content or "") + terminal_suffix

                if content:
                    content_was_emitted = True
                    streamed_content += content

                chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[
                        ChatCompletionChunkChoice(
                            delta=ChatCompletionChunkDelta(
                                content=content if content else None
                            ),
                            logprobs=chunk_logprobs,
                            finish_reason=output.finish_reason
                            if output.finished
                            else None,
                        )
                    ],
                )
                yield f"data: {_dump_chat_chunk(chunk)}\n\n"
            else:
                # Reasoning parser is active but delta_text is empty/None
                # (progress-only engine chunk). Skip — don't emit empty delta.
                continue

    # PrefillAdmissionError rides along: same class of client error (the
    # device cannot serve this context), and the body below uses only
    # str(e), so it needs no PromptTooLongError-specific fields.
    except (MediaControlsUnmeetableError, MediaInputError) as e:
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        error_data = {
            "id": response_id,
            "object": "chat.completion.chunk",
            "error": {
                "message": str(e),
                "type": "invalid_request_error",
                "code": type(e).code,
            },
        }
        yield f"data: {json.dumps(error_data)}\n\n"
        yield "data: [DONE]\n\n"
        return
    except (PromptTooLongError, PrefillAdmissionError) as e:
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        error_data = {
            "id": response_id,
            "object": "chat.completion.chunk",
            "error": {
                "message": str(e),
                "type": "invalid_request_error",
                "code": "prompt_too_long",
            },
        }
        yield f"data: {json.dumps(error_data)}\n\n"
        yield "data: [DONE]\n\n"
        return
    except VLMImagePrefillBudgetError as e:
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        error_data = {
            "id": response_id,
            "object": "chat.completion.chunk",
            "error": {
                "message": str(e),
                "type": "invalid_request_error",
                "code": VLMImagePrefillBudgetError.code,
            },
        }
        yield f"data: {json.dumps(error_data)}\n\n"
        yield "data: [DONE]\n\n"
        return
    except UnsupportedMediaModalityError as e:
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        error_data = {
            "id": response_id,
            "object": "chat.completion.chunk",
            "error": {
                "message": str(e),
                "type": "invalid_request_error",
                "code": UnsupportedMediaModalityError.code,
            },
        }
        yield f"data: {json.dumps(error_data)}\n\n"
        yield "data: [DONE]\n\n"
        return
    except asyncio.CancelledError:
        logger.info("Chat Completions stream cancelled, aborting %s", response_id)
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        raise
    except Exception as e:
        # On any error, abort the request and emit an error SSE event
        # so the client knows what happened instead of a silent EOF.
        logger.error(f"Stream error for {response_id}: {e}", exc_info=True)
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        error_data = {
            "id": response_id,
            "object": "chat.completion.chunk",
            "error": {
                "message": _generation_error_detail(
                    e, prefix="Stream generation failed"
                ),
                "type": "server_error",
                "code": "internal_error",
            },
        }
        yield f"data: {json.dumps(error_data)}\n\n"
        # M8: Send usage even on error so client gets partial token counts
        if include_usage and (prompt_tokens > 0 or completion_tokens > 0):
            _err_usage = Usage(
                prompt_tokens=prompt_tokens,
                completion_tokens=completion_tokens,
                total_tokens=prompt_tokens + completion_tokens,
            )
            if cached_tokens > 0 or cache_detail:
                _err_usage.prompt_tokens_details = PromptTokensDetails(
                    cached_tokens=cached_tokens, cache_detail=cache_detail
                )
            err_usage_chunk = ChatCompletionChunk(
                id=response_id,
                created=_created_ts,
                model=request.model,
                choices=[],
                usage=_err_usage,
            )
            yield f"data: {_dump_chat_chunk(err_usage_chunk, terminal_usage=True)}\n\n"
        yield "data: [DONE]\n\n"
        return
    finally:
        _stop_nonstream_disconnect_drain()

    # ─── Post-stream: tool call extraction ───────────────────────────────
    # If we buffered text because of tool call markers, parse it now
    if tool_call_buffering and accumulated_text and not _suppress_tools:
        # Use content-only text when reasoning parser separated it (avoids losing
        # tool calls that appear inside <think> blocks during regex stripping).
        # If content is empty but reasoning has tool markers, check reasoning too
        # (model may emit tool calls in analysis channel instead of final channel).
        # Fall back to accumulated_text with think-tag stripping when no parser was active.
        if _early_stopped_tool_text:
            # Immediate exact-once stopping happens before the current close
            # marker is fed through the reasoning splitter. Parse the complete,
            # parser-truncated raw candidate instead of an incomplete content
            # accumulator; the exact-once branch below still suppresses any
            # pre-call meta prose from visible output.
            parse_text = _early_stopped_tool_text
        elif request_parser and accumulated_content.strip():
            parse_text = accumulated_content.strip()
        elif request_parser and accumulated_reasoning.strip():
            # Tool call markers were in reasoning — try parsing reasoning text
            parse_text = accumulated_reasoning.strip()
        else:
            parse_text = _strip_think_for_tool_parse(accumulated_text)
        cleaned_text, tool_calls = _parse_tool_calls_with_parser(
            parse_text or accumulated_text, request
        )
        if tool_calls:
            # Emit any remaining content text before the tool calls,
            # but ONLY the portion that wasn't already streamed.
            # streamed_content tracks what was ACTUALLY yielded to the client
            # (not just accumulated — content in the same delta as a tool marker
            # may be accumulated but never yielded due to buffering).
            unemitted_content = None
            if (
                not _exact_once_tool_contract
                and cleaned_text
                and cleaned_text.strip()
            ):
                already_sent = streamed_content.strip()
                candidate = cleaned_text.strip()
                if not already_sent:
                    # Nothing was streamed yet — emit all cleaned content
                    unemitted_content = candidate
                elif candidate.startswith(already_sent):
                    # Subtract the already-streamed portion. Leading whitespace
                    # of the remainder is INTERNAL to the full text (e.g. the
                    # \n\n paragraph separator before the flushed portion) —
                    # stripping it glued paragraphs together in clients.
                    remainder = candidate[len(already_sent) :]
                    unemitted_content = remainder if remainder.strip() else None
                else:
                    # Content doesn't overlap (rare: reasoning redirect, etc.)
                    # Emit the full candidate only if nothing was sent
                    unemitted_content = candidate if not content_was_emitted else None

            if unemitted_content:
                content_chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[
                        ChatCompletionChunkChoice(
                            delta=ChatCompletionChunkDelta(content=unemitted_content),
                            finish_reason=None,
                        )
                    ],
                )
                yield f"data: {_dump_chat_chunk(content_chunk)}\n\n"

            # Emit tool calls in OpenAI-compatible streaming format (#46):
            # Chunk 1: tool_calls data with finish_reason=null
            # Chunk 2: empty delta with finish_reason="tool_calls"
            # This split is required for CLI clients (Claude Code, OpenCode, etc.)
            #
            # #219 follow-up: when a START delta already introduced index 0's
            # id/type, the final data delta must omit those string fields and
            # carry only the remaining function name/arguments fragments.
            # Official SDK accumulation appends string deltas; repeating the
            # same full id corrupts it. Subsequent calls did not receive an
            # early START, so they still introduce their parser id/type here.
            if _stream_tool_call_start_id is None:
                _stream_tool_call_start_id = generate_tool_id()
                start_chunk = {
                    "id": response_id,
                    "object": "chat.completion.chunk",
                    "created": _created_ts,
                    "model": request.model,
                    "choices": [
                        {
                            "index": 0,
                            "delta": {
                                "role": "assistant",
                                "tool_calls": [
                                    {
                                        "index": 0,
                                        "id": _stream_tool_call_start_id,
                                        "type": "function",
                                        "function": {"name": "", "arguments": ""},
                                    }
                                ],
                            },
                            "finish_reason": None,
                        }
                    ],
                }
                yield f"data: {_dump_chat_chunk(start_chunk)}\n\n"
            tc_deltas = []
            for i, tc in enumerate(tool_calls):
                tc_delta = {
                    "index": i,
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                if not (i == 0 and _stream_tool_call_start_id is not None):
                    tc_delta["id"] = tc.id
                    tc_delta["type"] = "function"
                tc_deltas.append(tc_delta)
            # Build tool_calls chunk matching OpenAI's exact format (#46):
            # - role: "assistant" required for SDK message assembly
            # - content omitted (not null) — OpenAI omits it in tool_calls deltas
            tc_data_chunk = {
                "id": response_id,
                "object": "chat.completion.chunk",
                "created": _created_ts,
                "model": request.model,
                "choices": [
                    {
                        "index": 0,
                        "delta": (
                            {"tool_calls": tc_deltas}
                            if _stream_tool_call_start_id is not None
                            else {"role": "assistant", "tool_calls": tc_deltas}
                        ),
                        "finish_reason": None,
                    }
                ],
            }
            yield f"data: {_dump_chat_chunk(tc_data_chunk)}\n\n"
            # Finish chunk: empty delta with finish_reason="tool_calls"
            tc_finish_chunk = {
                "id": response_id,
                "object": "chat.completion.chunk",
                "created": _created_ts,
                "model": request.model,
                "choices": [
                    {
                        "index": 0,
                        "delta": {},
                        "finish_reason": "tool_calls",
                    }
                ],
            }
            yield f"data: {_dump_chat_chunk(tc_finish_chunk)}\n\n"
            # This path returns before the end-of-stream diagnostics block, so
            # deliver the recorded drop / schema warnings here (warn-mode
            # problems ride alongside the delivered call; a sibling call
            # dropped for an unavailable name is reported, not lost).
            _tc_diagnostics = _take_tool_call_drop_diagnostics()
            if _tc_diagnostics:
                _tc_warning_chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[],
                    warnings=_tc_diagnostics,
                )
                yield f"data: {_dump_chat_chunk(_tc_warning_chunk)}\n\n"
            # Skip normal end-of-stream handling — we already set finish_reason
            if include_usage:
                _tc_usage = Usage(
                    prompt_tokens=prompt_tokens,
                    completion_tokens=completion_tokens,
                    total_tokens=prompt_tokens + completion_tokens,
                )
                if cached_tokens > 0 or cache_detail:
                    _tc_usage.prompt_tokens_details = PromptTokensDetails(
                        cached_tokens=cached_tokens, cache_detail=cache_detail
                    )
                usage_chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[],
                    usage=_tc_usage,
                )
                yield f"data: {_dump_chat_chunk(usage_chunk, terminal_usage=True)}\n\n"
            tool_calls_emitted = True
            yield "data: [DONE]\n\n"
            return
        else:
            # No tool calls found despite markers — flush only the UN-STREAMED
            # portion. streamed_content tracks what was actually yielded to client;
            # the remainder needs flushing.
            # When reasoning parser is active, use accumulated_content (content-only)
            # instead of accumulated_text (which includes reasoning and would leak it).
            already_sent = streamed_content.strip()
            full = (
                accumulated_content.strip()
                if request_parser
                else accumulated_text.strip()
            )
            if already_sent and full.startswith(already_sent):
                # Leading whitespace of the remainder is INTERNAL to the full
                # text (paragraph separator before the flushed portion) — keep it.
                remainder = full[len(already_sent) :]
                if not remainder.strip():
                    remainder = ""
            else:
                remainder = full if not content_was_emitted else ""
            if _exact_once_tool_contract:
                # An explicit exact-one selection turn has no legitimate visible
                # prose before its required function call.  If the final parser
                # rejects the buffered candidate, keep all native/orphan control
                # fragments hidden and let the required-tool terminal below report
                # the failure truthfully.  Flushing here leaked Qwen-style
                # ``<parameter=path>...`` residue through Anthropic/Chat clients.
                remainder = ""
            elif remainder:
                # Mirror the non-streaming visible-answer gate: only prose that
                # safely precedes the first unparsed native marker is assistant
                # text. Residue-stripping the whole rejected candidate instead
                # surfaced bare parameter values (e.g. a lone "Paris") as the
                # visible answer while non-stream honestly returned nothing.
                remainder = _strip_tool_markup_residue_for_display(
                    _visible_prefix_before_unparsed_tool_markup(remainder)
                )
            if remainder:
                # Use the engine's actual finish_reason (e.g., "length" if max_tokens
                # was hit) instead of hardcoding "stop"
                _flush_reason = (
                    last_output.finish_reason
                    if last_output and last_output.finish_reason
                    else "stop"
                )
                flush_chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[
                        ChatCompletionChunkChoice(
                            delta=ChatCompletionChunkDelta(content=remainder),
                            finish_reason=_flush_reason,
                        )
                    ],
                )
                yield f"data: {_dump_chat_chunk(flush_chunk)}\n\n"
                # This chunk already carried visible content and the terminal
                # finish_reason. Without recording it, the answer-pass re-arm
                # and reasoning-only terminals below fire afterwards and append
                # a contradictory "no visible answer" warning + error to a
                # stream that just delivered content.
                content_was_emitted = True
                streamed_content += remainder

    if (
        not tool_calls_emitted
        and not content_was_emitted
        and not m3_reasoning_only_answer_enabled
        and m3_tools_fallback_answer_budget is not None
        and accumulated_reasoning.strip()
    ):
        # A tools-enabled M3 turn can finish after reasoning with only a false
        # or incomplete native-tool prefix. The real tool parser has now run
        # and found no function call, so a tools-free direct answer pass is safe.
        # Arming this only after parsing avoids deferring or shadowing genuine
        # tool-call streams.
        logger.info(
            "MiniMax-M3 tools-enabled stream produced no valid tool call or "
            "visible content; re-arming bounded thinking-off answer pass"
        )
        m3_reasoning_only_answer_budget = m3_tools_fallback_answer_budget
        m3_reasoning_only_answer_enabled = True

    if (
        not tool_calls_emitted
        and not content_was_emitted
        and not reasoning_only_answer_enabled
        and reasoning_tools_fallback_answer_budget is not None
        and accumulated_reasoning.strip()
        and not _request_explicitly_requests_tool_use(request)
    ):
        # Tool availability alone must not disable the never-empty contract.
        # The real parser has now found no function call, so the same bounded
        # direct rail used by tools-free requests is safe and cannot shadow a
        # genuine tool stream.
        logger.info(
            "%s tools-enabled stream produced no valid tool call or visible "
            "content; re-arming bounded %s answer pass",
            reasoning_only_answer_family or "reasoning model",
            (
                "native tools-free"
                if _family_name in _NATIVE_REASONING_TOOL_RECOVERY_FAMILIES
                else "thinking-off"
            ),
        )
        reasoning_only_answer_budget = reasoning_tools_fallback_answer_budget
        reasoning_only_answer_enabled = True

    # A parser may surface its full reasoning block only at stream finalization.
    # Emit that late block on the reasoning rail, never as visible content.
    if (
        request_parser
        and not content_was_emitted
        and accumulated_reasoning
        and not reasoning_was_streamed
        and not suppress_reasoning
        and not (m3_reasoning_only_answer_enabled or reasoning_only_answer_enabled)
    ):
        fallback_chunk = ChatCompletionChunk(
            id=response_id,
            created=_created_ts,
            model=request.model,
            choices=[
                ChatCompletionChunkChoice(
                    delta=ChatCompletionChunkDelta(
                        reasoning=accumulated_reasoning,
                    ),
                    finish_reason=None,
                )
            ],
        )
        yield f"data: {_dump_chat_chunk(fallback_chunk)}\n\n"
        reasoning_was_streamed = True

    if (
        not content_was_emitted
        and (m3_reasoning_only_answer_enabled or reasoning_only_answer_enabled)
        and accumulated_reasoning.strip()
        and not tool_calls_emitted
        and _remaining_answer_pass_budget(
            (
                m3_reasoning_only_answer_budget
                if m3_reasoning_only_answer_enabled
                else reasoning_only_answer_budget
            ) or 256,
            completion_tokens,
        ) > 0
    ):
        _answer_family = (
            "MiniMax-M3"
            if m3_reasoning_only_answer_enabled
            else (reasoning_only_answer_family or "reasoning model")
        )
        _answer_budget = (
            m3_reasoning_only_answer_budget
            if m3_reasoning_only_answer_enabled
            else reasoning_only_answer_budget
        )
        logger.info(
            "%s Chat Completions stream produced no visible content; "
            "running bounded %s answer pass "
            "(reasoning_chars=%d, answer_budget=%s)",
            _answer_family,
            (
                "native tools-free"
                if _family_name in _NATIVE_REASONING_TOOL_RECOVERY_FAMILIES
                else "thinking-off"
            ),
            len(accumulated_reasoning),
            _answer_budget,
        )
        _ap_prep_start = time.perf_counter()
        answer_messages = _answer_pass_messages(
            messages, _family_name, accumulated_reasoning
        )
        answer_kwargs = dict(kwargs)
        _native_reasoning_retry = (
            _family_name in _NATIVE_REASONING_TOOL_RECOVERY_FAMILIES
        )
        # Register the answer-pass stream under the id the disconnect handler
        # aborts (`{response_id}:visible-answer`); otherwise it inherits the main
        # request_id and abort_request() misses, leaking the answer-pass
        # generation on the GPU after the client disconnects mid-answer-pass.
        answer_kwargs["request_id"] = f"{response_id}:visible-answer"
        if not _native_reasoning_retry:
            _force_answer_pass_direct_rail(
                answer_kwargs,
                family_name=_family_name,
            )
        answer_kwargs["max_tokens"] = _remaining_answer_pass_budget(
            _answer_budget or 256,
            completion_tokens,
        )
        answer_ct_kwargs = dict(answer_kwargs.get("chat_template_kwargs") or {})
        if _native_reasoning_retry:
            pass
        elif _answer_family == "MiniMax-M3":
            answer_ct_kwargs["thinking_mode"] = "disabled"
        elif _answer_family == "openPangu":
            answer_ct_kwargs["thinking"] = False
        else:
            # Qwen3.5/3.6 VLM/MTP templates consume enable_thinking from
            # chat_template_kwargs; the top-level kwarg alone is not enough to
            # keep the bounded visible-answer retry on the direct rail.
            answer_ct_kwargs["enable_thinking"] = False
        answer_kwargs["chat_template_kwargs"] = answer_ct_kwargs
        answer_kwargs.pop("dsv4_thinking_soft_cap", None)
        answer_kwargs.pop("tools", None)
        answer_kwargs.pop("_vmlx_tools_present", None)
        answer_kwargs.pop("_vmlx_template_tools", None)
        try:
            # SSE comments are ignored by standard OpenAI clients but let the
            # local Electron panel distinguish a real second-generation prefill
            # from a stalled reasoning-to-content transition.  Do not encode
            # this as a JSON chunk: strict Chat clients must never see a
            # non-OpenAI object in the data stream.
            yield ": vmlx-answer-pass-start\n\n"
            # F6: STREAM the bounded answer pass token-by-token instead of
            # generating it in full and emitting it as one content delta. The
            # single-delta form made the whole answer land at once after a long
            # silent wait (a coding-harness / progressive-UI hazard whenever
            # reasoning exhausts the budget and this fallback fires). The MLLM
            # stream only assembles GenerationOutput.text at finished=True, so we
            # accumulate new_text ourselves and let _answer_pass_visible_delta
            # apply the same clean_output_text + </think> split the non-streaming
            # path used (marker-length holdback until finish) — the streamed text
            # is byte-identical to the old single chunk, just incremental.
            #
            # Families in _ANSWER_PASS_LEAK_GUARD_FAMILIES still buffer because
            # their thinking-off salvage can reopen a real thinking marker and a
            # streamed delta cannot be recalled. Qwen3.5/3.6 is intentionally not
            # in that set: its fresh-context direct rail removed the planning
            # continuation, so its visible answer must remain progressive.
            _buffer_answer_pass = _family_name in _ANSWER_PASS_LEAK_GUARD_FAMILIES
            _ans_budget_cap = int(answer_kwargs.get("max_tokens") or 0)
            _ans_raw = ""
            _ans_sent = ""
            _ans_ct = 0
            _ans_any = False
            _ans_last_out = None
            _ans_disconnected = False
            _ans_tool_calls = None
            _answer_pass_trace(
                "answer_pass_prep",
                _ap_prep_start,
                family=_family_name,
                budget=_ans_budget_cap,
            )
            _ap_stream_start = time.perf_counter()
            _ap_first_seen = False
            async for answer_output in _stream_with_keepalive(
                engine.stream_chat(messages=answer_messages, **answer_kwargs),
                total_timeout=_stream_timeout,
                progress_probe=(
                    None
                    if request.timeout is not None
                    else lambda: _engine_request_progress(
                        engine, f"{response_id}:visible-answer"
                    )
                ),
            ):
                if answer_output is None:
                    yield ": keep-alive\n\n"
                    continue
                if fastapi_request and await fastapi_request.is_disconnected():
                    logger.info(
                        "Client disconnected during %s answer pass, aborting %s",
                        _answer_family,
                        response_id,
                    )
                    if hasattr(engine, "abort_request"):
                        await engine.abort_request(f"{response_id}:visible-answer")
                    _ans_disconnected = True
                    break
                if not _ap_first_seen:
                    _ap_first_seen = True
                    _answer_pass_trace(
                        "answer_pass_to_first_output", _ap_stream_start
                    )
                _ans_last_out = answer_output
                # Keep the decode-window timestamps live through the answer
                # pass; otherwise the final decode tok/s line divides BOTH
                # passes' tokens by only the first pass's span and overreports.
                _decode_last_ts = _decode_output_timestamp(answer_output)
                if _decode_first_ts is None:
                    _decode_first_ts = _decode_last_ts
                _ans_ct = (
                    int(getattr(answer_output, "completion_tokens", 0) or 0) or _ans_ct
                )
                _ans_raw += getattr(answer_output, "new_text", "") or ""
                if _buffer_answer_pass:
                    # Accumulate only; emit after we confirm clean completion.
                    continue
                _delta, _ans_sent = _answer_pass_visible_delta(
                    _ans_raw,
                    _ans_sent,
                    request,
                    bool(getattr(answer_output, "finished", False)),
                    holdback=_answer_pass_stream_holdback(
                        _family_name,
                        buffer_answer_pass=_buffer_answer_pass,
                    ),
                    think_in_prompt=_native_reasoning_retry,
                    markup_guard=True,
                )
                if not _delta:
                    continue
                _ans_any = True
                answer_chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[
                        ChatCompletionChunkChoice(
                            delta=ChatCompletionChunkDelta(content=_delta),
                            finish_reason=None,
                        )
                    ],
                )
                yield f"data: {_dump_chat_chunk(answer_chunk)}\n\n"
            if _buffer_answer_pass:
                # Emit the buffered qwen3_5* answer as one delta, but ONLY if the
                # pass itself completed. A pass that hit its bounded budget
                # (finish_reason="length" or spent the whole cap) is the W2-1
                # planning-prose leak risk and is discarded → honest empty +
                # diagnostic, which tells the client to raise max_tokens.
                _ans_truncated = (
                    getattr(_ans_last_out, "finish_reason", None) == "length"
                    or (_ans_budget_cap and _ans_ct >= _ans_budget_cap)
                )
                _full_delta, _ans_sent = _answer_pass_visible_delta(
                    _ans_raw,
                    "",
                    request,
                    True,
                    holdback=0,
                    think_in_prompt=_native_reasoning_retry,
                )
                logger.debug(
                    "%s buffered Chat Completions answer pass result: "
                    "finish=%s ct=%d/%d raw_chars=%d visible_chars=%d "
                    "thinking_reentry=%s",
                    _answer_family,
                    getattr(_ans_last_out, "finish_reason", None),
                    _ans_ct,
                    _ans_budget_cap,
                    len(_ans_raw),
                    len(_full_delta),
                    _answer_pass_thinking_reentry(_ans_raw),
                )
                # 2026-07-12 (live-proven on Qwen3.6-27B-MXFP4-CRACK-MTP): the
                # W2-1 blanket discard-on-truncation threw away a CLEAN, usable
                # answer from an explicitly budgeted direct pass. The direct-rail
                # thinking-off pass emits a plain
                # answer with NO <think> block, so a length-truncated pass is a
                # cut-off answer, not the planning-prose leak W2-1 guarded against.
                # Emit it. Discard ONLY when the pass actually re-entered reasoning
                # (a <think> marker in the raw output) — clean_output_text does NOT
                # strip <think>, so this guard is load-bearing. Never-empty beats a
                # truncated-but-honest answer (Eric: output MUST stream after reasoning).
                _ans_reasoning_leak = _answer_pass_thinking_reentry(_ans_raw)
                if _full_delta and not _ans_reasoning_leak:
                    _ans_any = True
                    answer_chunk = ChatCompletionChunk(
                        id=response_id,
                        created=_created_ts,
                        model=request.model,
                        choices=[
                            ChatCompletionChunkChoice(
                                delta=ChatCompletionChunkDelta(content=_full_delta),
                                finish_reason=None,
                            )
                        ],
                    )
                    yield f"data: {_dump_chat_chunk(answer_chunk)}\n\n"
                elif _ans_reasoning_leak:
                    logger.info(
                        "%s streaming answer pass re-entered reasoning "
                        "(<think> leak, ct=%d/%d) — discarding to avoid "
                        "planning-prose leak; client should raise max_tokens",
                        _answer_family, _ans_ct, _ans_budget_cap,
                    )
                elif _ans_truncated:
                    logger.info(
                        "%s streaming answer pass truncated with no visible "
                        "content (ct=%d/%d) — client should raise max_tokens",
                        _answer_family, _ans_ct, _ans_budget_cap,
                    )
            if not _buffer_answer_pass and not _ans_disconnected and _ans_raw:
                # Terminal disposition for the progressive lane: the in-loop
                # markup guard held back everything from the first native tool
                # marker onward, so resolve that remainder here exactly like the
                # non-streaming answer pass — parse into structured tool_calls
                # when the original request offered tools, otherwise strip it
                # as suppressed control markup. Clean prose finalizes to the
                # already-streamed text and emits nothing new.
                _ans_final_text, _ans_tool_calls = _answer_pass_finalize_visible(
                    _ans_raw,
                    request,
                    think_in_prompt=_native_reasoning_retry,
                    suppress_tools=_suppress_markup_display,
                )
                if _ans_final_text and _ans_final_text.startswith(_ans_sent):
                    _ans_final_tail = _ans_final_text[len(_ans_sent):]
                    if _ans_final_tail:
                        _ans_any = True
                        _ans_sent = _ans_final_text
                        answer_chunk = ChatCompletionChunk(
                            id=response_id,
                            created=_created_ts,
                            model=request.model,
                            choices=[
                                ChatCompletionChunkChoice(
                                    delta=ChatCompletionChunkDelta(
                                        content=_ans_final_tail
                                    ),
                                    finish_reason=None,
                                )
                            ],
                        )
                        yield f"data: {_dump_chat_chunk(answer_chunk)}\n\n"
                if _ans_tool_calls:
                    logger.info(
                        "%s bounded answer pass re-emitted a schema-valid "
                        "native tool call; emitting structured tool_calls "
                        "instead of raw markup",
                        _answer_family,
                    )
                    _ans_tc_chunk = ChatCompletionChunk(
                        id=response_id,
                        created=_created_ts,
                        model=request.model,
                        choices=[
                            ChatCompletionChunkChoice(
                                delta=ChatCompletionChunkDelta(
                                    tool_calls=[
                                        {
                                            "index": i,
                                            "id": tc.id,
                                            "type": "function",
                                            "function": {
                                                "name": tc.function.name,
                                                "arguments": tc.function.arguments,
                                            },
                                        }
                                        for i, tc in enumerate(_ans_tool_calls)
                                    ],
                                ),
                                finish_reason="tool_calls",
                            )
                        ],
                    )
                    tool_calls_emitted = True
                    yield f"data: {_dump_chat_chunk(_ans_tc_chunk)}\n\n"
            _answer_pass_succeeded = _ans_any or bool(_ans_tool_calls)
            _ans_truncated_for_terminal = bool(
                getattr(_ans_last_out, "finish_reason", None) == "length"
                or (_ans_budget_cap and _ans_ct >= _ans_budget_cap)
            )
            if _answer_pass_succeeded:
                if _ans_any:
                    content_was_emitted = True
                    streamed_content += _ans_sent
                completion_tokens += int(_ans_ct or 0)
                # Terminal finish for the answer-pass stream satisfies the OpenAI
                # terminal-finish contract so strict clients do not hang.  Preserve
                # an honest length terminal when the bounded answer pass itself
                # truncated/spent its cap; otherwise Chat-derived adapters
                # (Anthropic/Ollama) report a cut-off visible answer as a normal
                # end_turn/stop.  A structured-tool-call disposition already
                # carried its own finish_reason="tool_calls" terminal.
                if not _ans_tool_calls:
                    _answer_finish_reason = (
                        "length"
                        if _ans_truncated_for_terminal
                        else (getattr(_ans_last_out, "finish_reason", None) or "stop")
                    )
                    answer_finish_chunk = ChatCompletionChunk(
                        id=response_id,
                        created=_created_ts,
                        model=request.model,
                        choices=[
                            ChatCompletionChunkChoice(
                                delta=ChatCompletionChunkDelta(),
                                finish_reason=_answer_finish_reason,
                            )
                        ],
                    )
                    yield f"data: {_dump_chat_chunk(answer_finish_chunk)}\n\n"
        except asyncio.CancelledError:
            logger.info(
                "%s Chat Completions visible answer pass cancelled, aborting %s",
                _answer_family,
                response_id,
            )
            if hasattr(engine, "abort_request"):
                await engine.abort_request(f"{response_id}:visible-answer")
                await engine.abort_request(response_id)
            raise
        except Exception as e:
            logger.error(
                "%s Chat Completions visible answer pass failed for %s: %s",
                _answer_family,
                response_id,
                e,
                exc_info=True,
            )

    # When reasoning is suppressed and the model produced ONLY reasoning (no content),
    # try to extract tool calls from reasoning before showing the diagnostic.
    # MiniMax M2.7 and similar models may emit tool calls inside <think> blocks
    # when reasoning OFF — the tool call parser needs to see the reasoning text.
    if (
        suppress_reasoning
        and not content_was_emitted
        and not tool_calls_emitted
        and accumulated_reasoning
    ):
        # Last-chance tool call extraction from reasoning text
        _has_tc_markers = _private_reasoning_has_tool_syntax(accumulated_reasoning)
        if _has_tc_markers and not _suppress_markup_display:
            logger.info(f"Request {response_id}: tool call markers found in suppressed reasoning — extracting")
            _tc_text = accumulated_reasoning.strip()
            _tc_calls = _parse_private_reasoning_tool_calls(_tc_text, request)
            if _tc_calls:
                # Emit tool calls as if they came from content
                tc_chunk = ChatCompletionChunk(
                    id=response_id, created=_created_ts, model=request.model,
                    choices=[ChatCompletionChunkChoice(
                        delta=ChatCompletionChunkDelta(
                            tool_calls=[{
                                "index": i, "id": tc.id, "type": "function",
                                "function": {"name": tc.function.name, "arguments": tc.function.arguments},
                            } for i, tc in enumerate(_tc_calls)],
                        ),
                        finish_reason="tool_calls",
                    )],
                )
                tool_calls_emitted = True
                yield f"data: {_dump_chat_chunk(tc_chunk)}\n\n"
            else:
                logger.info(
                    f"Request {response_id}: tool markers found in suppressed "
                    "reasoning but parsing failed — preserving hidden reasoning"
                )
        else:
            logger.info(
                f"Request {response_id}: model produced only reasoning ({len(accumulated_reasoning)} chars) — suppressed per user setting"
            )

    _stream_chat_warnings = None
    if (
        accumulated_reasoning
        and not content_was_emitted
        and not tool_calls_emitted
        and (suppress_reasoning or reasoning_was_streamed)
    ):
        _stream_chat_warnings = _chat_completion_warnings_for_reasoning_only(
            content=None,
            reasoning=accumulated_reasoning,
            tool_calls=None,
            finish_reason=(
                getattr(last_output, "finish_reason", None)
                if last_output is not None
                else None
            ),
        )
    # Bug 5: surface dropped-tool-call diagnostics to the client even when no
    # reasoning-only warning fired. A parser-dropped call leaves the stream
    # without a tool_calls delta; without this hook the client sees an empty
    # response with no signal as to why. Diagnostics are also delivered when a
    # call WAS emitted: under warn-mode schema validation the call is delivered
    # together with its problems, and a sibling call dropped for an unavailable
    # name must not vanish silently just because another call surfaced.
    _dropped_tc_diagnostics = _take_tool_call_drop_diagnostics()
    if _dropped_tc_diagnostics:
        if _stream_chat_warnings is None:
            _stream_chat_warnings = []
        _stream_chat_warnings.extend(_dropped_tc_diagnostics)
    if _stream_chat_warnings:
        warning_chunk = ChatCompletionChunk(
            id=response_id,
            created=_created_ts,
            model=request.model,
            choices=[],
            warnings=_stream_chat_warnings,
        )
        yield f"data: {_dump_chat_chunk(warning_chunk)}\n\n"
        if not content_was_emitted and not tool_calls_emitted:
            _warning_finish_reason = _normalize_responses_finish_reason(
                (
                    getattr(last_output, "finish_reason", None)
                    if last_output is not None
                    else None
                )
                or "stop"
            )
            if _warning_finish_reason == "length":
                warning_finish_chunk = ChatCompletionChunk(
                    id=response_id,
                    created=_created_ts,
                    model=request.model,
                    choices=[
                        ChatCompletionChunkChoice(
                            delta=ChatCompletionChunkDelta(),
                            finish_reason="length",
                        )
                    ],
                )
                yield f"data: {_dump_chat_chunk(warning_finish_chunk)}\n\n"
                # A reasoning-only turn that ran into max_tokens still did real
                # work: it read a prompt — often a fully reused prefix — and
                # spent completion tokens. Returning here skipped both the
                # terminal usage chunk and [DONE], so every client saw the turn
                # as zero tokens, and the Anthropic non-streaming route (which
                # rebuilds usage by collecting this very stream) reported
                # usage {input_tokens: 0, output_tokens: 0} with no
                # cache_read_input_tokens on a fully cached prefix.
                if include_usage:
                    _len_usage = Usage(
                        prompt_tokens=prompt_tokens,
                        completion_tokens=completion_tokens,
                        total_tokens=prompt_tokens + completion_tokens,
                    )
                    if cached_tokens > 0 or cache_detail:
                        _len_usage.prompt_tokens_details = PromptTokensDetails(
                            cached_tokens=cached_tokens, cache_detail=cache_detail
                        )
                    len_usage_chunk = ChatCompletionChunk(
                        id=response_id,
                        created=_created_ts,
                        model=request.model,
                        choices=[],
                        usage=_len_usage,
                    )
                    yield (
                        "data: "
                        f"{_dump_chat_chunk(len_usage_chunk, terminal_usage=True)}"
                        "\n\n"
                    )
                yield "data: [DONE]\n\n"
                return
            yield (
                "data: "
                + json.dumps(
                    _reasoning_only_chat_error_payload(response_id),
                    ensure_ascii=True,
                )
                + "\n\n"
            )
            yield "data: [DONE]\n\n"
            return

    # Safeguard: if model generated zero tokens (empty stream), finish the stream
    # without injecting diagnostic prose as assistant output. The warning belongs
    # in logs/diagnostics, not in next-turn model history.
    _zero_tokens = (last_output is None) or (
        not content_was_emitted
        and not accumulated_reasoning
        and getattr(last_output, "completion_tokens", 1) == 0
    )
    if _zero_tokens and not content_was_emitted and not accumulated_reasoning:
        logger.warning(f"Request {response_id}: model generated zero tokens")
        empty_chunk = ChatCompletionChunk(
            id=response_id,
            created=_created_ts,
            model=request.model,
            choices=[
                ChatCompletionChunkChoice(
                    delta=ChatCompletionChunkDelta(),
                    finish_reason="stop",
                )
            ],
        )
        yield f"data: {_dump_chat_chunk(empty_chunk)}\n\n"

    # Enforce tool_choice="required" in streaming: emit error SSE if no tool calls
    _stream_tool_choice = getattr(request, "tool_choice", None)
    if _is_pending_required_tool_choice(request) and not tool_calls_emitted:
        # tool_calls_emitted is set True only when tool calls were actually parsed and yielded.
        # tool_call_buffering can be True even on false-positive marker detection with no actual calls.
        logger.warning(
            f"Stream {response_id}: tool_choice='required' but no tool calls produced"
        )
        error_data = {
            "id": response_id,
            "object": "chat.completion.chunk",
            "error": {
                "message": (
                    f"{_describe_required_tool_choice(_stream_tool_choice)} was set but the model did not "
                    "produce any tool calls. Try rephrasing your prompt or using a "
                    "model with better tool-calling support."
                ),
                "type": "invalid_request_error",
                "code": "tool_calls_required",
            },
        }
        yield f"data: {json.dumps(error_data)}\n\n"

    # H4: Validate response_format at end of stream.
    # Streaming can't reject mid-stream, so validate the accumulated output and
    # log a warning. For strict mode, emit an error SSE event.
    _rf = getattr(request, "response_format", None)
    if _rf and content_was_emitted and not tool_call_buffering:
        _final_text = (
            accumulated_content.strip() if request_parser else accumulated_text.strip()
        )
        if _final_text:
            _xml_config = _xml_response_format_config(_rf)
            if _xml_config is not None:
                _xml_report = repair_xml_output(
                    _final_text,
                    root_tag=_xml_config.get("root_tag"),
                    required_fields=_xml_config.get("required_fields") or (),
                )
                if not _xml_report.get("is_valid"):
                    rf_error = _xml_report.get("error")
                    if _xml_config.get("strict"):
                        logger.warning(
                            f"Stream {response_id}: XML validation failed (strict): {rf_error}"
                        )
                        error_data = {
                            "id": response_id,
                            "object": "chat.completion.chunk",
                            "error": {
                                "message": f"response_format strict mode: {rf_error}",
                                "type": "invalid_request_error",
                                "code": "xml_validation_failed",
                            },
                        }
                        yield f"data: {json.dumps(error_data)}\n\n"
                    else:
                        logger.warning(
                            f"Stream {response_id}: XML validation failed: {rf_error}"
                        )
            else:
                _, parsed_json, is_valid, rf_error = parse_json_output(_final_text, _rf)
                if not is_valid:
                    _rf_strict = False
                    if isinstance(_rf, dict):
                        _rf_strict = _rf.get("json_schema", {}).get("strict", False)
                    elif hasattr(_rf, "json_schema") and _rf.json_schema:
                        _rf_strict = getattr(_rf.json_schema, "strict", False)
                    if _rf_strict:
                        logger.warning(
                            f"Stream {response_id}: JSON schema validation failed (strict): {rf_error}"
                        )
                        error_data = {
                            "id": response_id,
                            "object": "chat.completion.chunk",
                            "error": {
                                "message": f"response_format strict mode: {rf_error}",
                                "type": "invalid_request_error",
                                "code": "json_validation_failed",
                            },
                        }
                        yield f"data: {json.dumps(error_data)}\n\n"
                    else:
                        logger.warning(
                            f"Stream {response_id}: JSON validation failed: {rf_error}"
                        )

    # Send final chunk with usage if requested
    if include_usage:
        _usage = Usage(
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=prompt_tokens + completion_tokens,
        )
        if cached_tokens > 0 or cache_detail:
            _usage.prompt_tokens_details = PromptTokensDetails(
                cached_tokens=cached_tokens, cache_detail=cache_detail
            )
        usage_chunk = ChatCompletionChunk(
            id=response_id,
            created=_created_ts,
            model=request.model,
            choices=[],  # Empty choices for usage-only chunk
            usage=_usage,
        )
        yield f"data: {_dump_chat_chunk(usage_chunk, terminal_usage=True)}\n\n"

    if (
        completion_tokens > 1
        and _decode_first_ts is not None
        and _decode_last_ts > _decode_first_ts
    ):
        _decode_elapsed = _decode_last_ts - _decode_first_ts
        logger.info(
            f"Chat completion (stream): {completion_tokens} tokens in "
            f"{_decode_elapsed:.2f}s "
            f"({(completion_tokens - _decode_first_count) / _decode_elapsed:.1f} tok/s decode) "
            f"therm={thermal_state_name()}"
        )

    yield "data: [DONE]\n\n"


async def stream_responses_api(
    engine: BaseEngine,
    messages: list,
    request: ResponsesRequest,
    fastapi_request: Request | None = None,
    history_messages: list | None = None,
    response_id: str | None = None,
    **kwargs,
) -> AsyncIterator[str]:
    """Stream response in OpenAI Responses API SSE format.

    Streams text deltas incrementally for real-time display. If tool call
    markers are detected mid-stream, switches to buffered mode and emits
    structured function_call events at the end.

    ``response_id`` accepts the route-minted id (minted BEFORE the stamped
    effort policy so the substitution registry keys match); direct callers
    without one get a fresh mint.
    """
    response_id = response_id or f"resp_{uuid.uuid4().hex[:12]}"
    kwargs["request_id"] = response_id
    kwargs.setdefault(
        "max_tokens",
        _resolve_max_tokens(getattr(request, "max_output_tokens", None), request.model),
    )
    seq = 0
    created_at = int(time.time())

    # ``response.usage`` is a private vMLX incremental-telemetry extension, not
    # an OpenAI Responses stream event.  Standard Responses clients receive
    # authoritative usage on response.completed.  Only an explicitly
    # negotiated client (the local Electron panel) may receive the extension;
    # a Chat-style stream_options.include_usage field alone must never alter
    # the public Responses event union.
    _usage_header = ""
    if fastapi_request is not None:
        _headers = getattr(fastapi_request, "headers", None)
        if _headers is not None:
            _usage_header = str(
                _headers.get("x-vmlx-stream-usage", "")
            ).strip().lower()
    incremental_usage_extension = _usage_header == "incremental"

    def _sse(event_type: str, data: dict) -> str:
        nonlocal seq
        data["sequence_number"] = seq
        seq += 1
        return f"event: {event_type}\ndata: {json.dumps(data, ensure_ascii=True)}\n\n"

    # Emit response.created
    yield _sse(
        "response.created",
        {
            "type": "response.created",
            "response": {
                "id": response_id,
                "object": "response",
                "created_at": created_at,
                "status": "in_progress",
                "model": request.model,
                "output": [],
            },
        },
    )

    # Responses output items are allocated lazily in the order they actually
    # begin.  Reasoning commonly starts before visible content, so pre-announcing
    # an empty message at index 0 corrupts continuation history into two turns.
    msg_id = f"item_{uuid.uuid4().hex[:12]}"
    reasoning_item_id = f"rs_{uuid.uuid4().hex[:12]}"
    next_output_index = 0
    message_output_index: int | None = None
    reasoning_output_index: int | None = None
    message_item_started = False
    reasoning_item_started = False
    reasoning_item_finished = False
    _final_reasoning_item: dict | None = None
    _indexed_output_items: dict[int, dict] = {}

    def _record_output_item(index: int | None, item: dict) -> None:
        if index is None:
            raise RuntimeError("Responses output item was finalized before allocation")
        _indexed_output_items[index] = item

    def _start_message_item_events() -> list[str]:
        nonlocal message_item_started, message_output_index, next_output_index
        if message_item_started:
            return []
        message_item_started = True
        message_output_index = next_output_index
        next_output_index += 1
        return [
            _sse(
                "response.output_item.added",
                {
                    "type": "response.output_item.added",
                    "output_index": message_output_index,
                    "item": {
                        "id": msg_id,
                        "type": "message",
                        "status": "in_progress",
                        "role": "assistant",
                        "content": [],
                    },
                },
            ),
            _sse(
                "response.content_part.added",
                {
                    "type": "response.content_part.added",
                    "item_id": msg_id,
                    "output_index": message_output_index,
                    "content_index": 0,
                    "part": {
                        "type": "output_text",
                        "text": "",
                        "annotations": [],
                    },
                },
            ),
        ]

    def _function_call_item_events(calls: list) -> list[str]:
        """Emit parsed tool calls as complete function_call output items."""
        nonlocal next_output_index
        events: list[str] = []
        for tc in calls:
            func = tc.function if hasattr(tc, "function") else tc
            tc_name = func.name if hasattr(func, "name") else func.get("name", "")
            tc_args = (
                func.arguments
                if hasattr(func, "arguments")
                else func.get("arguments", "")
            )
            call_id = tc.id if hasattr(tc, "id") else f"call_{uuid.uuid4().hex[:8]}"
            fc_id = f"fc_{uuid.uuid4().hex[:12]}"
            output_index = next_output_index
            next_output_index += 1

            events.append(
                _sse(
                    "response.output_item.added",
                    {
                        "type": "response.output_item.added",
                        "output_index": output_index,
                        "item": {
                            "id": fc_id,
                            "type": "function_call",
                            "status": "in_progress",
                            "call_id": call_id,
                            "name": tc_name,
                            "arguments": "",
                        },
                    },
                )
            )
            # Emit arguments incrementally in ~16-char chunks per OpenAI spec
            _ARG_CHUNK = 16
            if tc_args:
                for _ci in range(0, len(tc_args), _ARG_CHUNK):
                    events.append(
                        _sse(
                            "response.function_call_arguments.delta",
                            {
                                "type": "response.function_call_arguments.delta",
                                "item_id": fc_id,
                                "output_index": output_index,
                                "delta": tc_args[_ci : _ci + _ARG_CHUNK],
                            },
                        )
                    )
            else:
                # Empty arguments — emit one delta to satisfy clients
                events.append(
                    _sse(
                        "response.function_call_arguments.delta",
                        {
                            "type": "response.function_call_arguments.delta",
                            "item_id": fc_id,
                            "output_index": output_index,
                            "delta": "",
                        },
                    )
                )
            events.append(
                _sse(
                    "response.function_call_arguments.done",
                    {
                        "type": "response.function_call_arguments.done",
                        "item_id": fc_id,
                        "output_index": output_index,
                        "arguments": tc_args,
                    },
                )
            )
            fc_item = {
                "id": fc_id,
                "type": "function_call",
                "status": _response_output_status,
                "call_id": call_id,
                "name": tc_name,
                "arguments": tc_args,
            }
            events.append(
                _sse(
                    "response.output_item.done",
                    {
                        "type": "response.output_item.done",
                        "output_index": output_index,
                        "item": fc_item,
                    },
                )
            )
            _record_output_item(output_index, fc_item)
        return events

    def _start_reasoning_item_events() -> list[str]:
        nonlocal reasoning_item_started, reasoning_output_index, next_output_index
        if reasoning_item_started:
            return []
        reasoning_item_started = True
        reasoning_output_index = next_output_index
        next_output_index += 1
        return [
            _sse(
                "response.output_item.added",
                {
                    "type": "response.output_item.added",
                    "output_index": reasoning_output_index,
                    "item": {
                        "id": reasoning_item_id,
                        "type": "reasoning",
                        "status": "in_progress",
                        "summary": [],
                        "content": [],
                    },
                },
            ),
            _sse(
                "response.reasoning_summary_part.added",
                {
                    "type": "response.reasoning_summary_part.added",
                    "item_id": reasoning_item_id,
                    "output_index": reasoning_output_index,
                    "summary_index": 0,
                    "part": {"type": "summary_text", "text": ""},
                },
            ),
        ]

    def _finish_reasoning_item_events(
        text: str,
        *,
        status: str = "completed",
    ) -> list[str]:
        nonlocal reasoning_item_finished, _final_reasoning_item
        if reasoning_item_finished or not text:
            return []
        events = _start_reasoning_item_events()
        reasoning_item_finished = True
        summary_part = {"type": "summary_text", "text": text}
        _final_reasoning_item = {
            "id": reasoning_item_id,
            "type": "reasoning",
            "status": status,
            "summary": [summary_part],
            "content": [],
        }
        events.extend(
            [
                _sse(
                    "response.reasoning_summary_text.done",
                    {
                        "type": "response.reasoning_summary_text.done",
                        "item_id": reasoning_item_id,
                        "output_index": reasoning_output_index,
                        "summary_index": 0,
                        "text": text,
                    },
                ),
                _sse(
                    "response.reasoning_summary_part.done",
                    {
                        "type": "response.reasoning_summary_part.done",
                        "item_id": reasoning_item_id,
                        "output_index": reasoning_output_index,
                        "summary_index": 0,
                        "part": summary_part,
                    },
                ),
                _sse(
                    "response.output_item.done",
                    {
                        "type": "response.output_item.done",
                        "output_index": reasoning_output_index,
                        "item": _final_reasoning_item,
                    },
                ),
            ]
        )
        _record_output_item(reasoning_output_index, _final_reasoning_item)
        return events

    # Bug 5 (Responses API): start dropped-tool-call diagnostic capture
    _begin_tool_call_drop_capture()

    _suppress_tools = getattr(request, "tool_choice", None) == "none"
    _request_has_tools = bool(_effective_tools_for_tool_parsing(request))
    _stream_tools_available = _tools_available_for_generation(
        request, kwargs.get("tools")
    )
    # Streaming ``_suppress_tools`` only records tool_choice=="none".  The
    # non-stream handlers additionally flip it via
    # _suppress_tool_parsing_when_no_tools when the request carries no tool
    # schema at all; mirror that union for every visible-display decision so
    # native tool markup never streams as content on a no-tools request.
    _suppress_markup_display = _suppress_tools or not _stream_tools_available
    tool_call_active = (
        _stream_tools_available
        and not _suppress_tools
        and not _tool_call_parser_disabled_explicitly
    )
    # An explicit single-call contract has no legitimate visible prose before
    # the FIRST function call. Buffer that selection turn from token one so a
    # model that closes </think> early and continues meta-reasoning cannot leak
    # it through output_text.done. Once a tool result follows the latest user
    # message, the required call has already happened: keep marker detection
    # armed for any new call, but stream ordinary answer content progressively.
    _exact_once_requested = _request_explicitly_requires_one_tool_once(request)
    _has_post_user_tool_result = _responses_messages_have_tool_result_after_latest_user(
        messages
    )
    _exact_once_tool_contract = bool(
        tool_call_active
        and _exact_once_requested
        and not _has_post_user_tool_result
    )
    if tool_call_active and _exact_once_requested:
        logger.info(
            "Responses exact-once tool gate: initial_selection=%s "
            "post_user_tool_result=%s message_shapes=%s",
            _exact_once_tool_contract,
            _has_post_user_tool_result,
            [
                (message.get("role"), message.get("type"))
                for message in messages
                if isinstance(message, dict)
            ],
        )
    tool_call_buffering = _exact_once_tool_contract
    # Early-stop after a complete tool-call turn (opt-in per tool parser via
    # STREAM_STOPS_AFTER_COMPLETE_CALL) — mirrors stream_chat_completion.
    _tc_stop_parser = (
        _stream_tool_call_early_stop_parser(request) if tool_call_active else None
    )
    _tc_stop_complete_chunks = 0

    full_text = ""
    streamed_text = ""  # Text already sent as deltas (before tool call marker)
    accumulated_content = ""  # Content-only text for tool call marker detection
    accumulated_reasoning = ""  # Reasoning text for fallback
    _early_stopped_tool_text: str | None = None
    _draining_tool_parser_stop = False
    streamed_reasoning_text = ""  # Tool-safe reasoning already sent to the client
    content_was_emitted = False
    reasoning_was_streamed = False  # Whether reasoning was sent to client as deltas
    prompt_tokens = 0
    completion_tokens = 0
    _cached = 0
    _cache_detail: str | None = None
    _decode_first_ts: float | None = None
    _decode_first_count = 1
    _decode_last_ts = 0.0
    _decode_last_count = 0
    last_output = (
        None  # Track last engine output for finish_reason (status: incomplete)
    )
    _stream_disconnected = False

    # Resolve effective enable_thinking:
    # Priority: top-level field > chat_template_kwargs > server default > auto-detect
    # (None = fall through to template/tokenizer auto-detect below — this site
    # drives SSE parser behavior, not engine kwargs, so no Gemma4+tools override.)
    _ct_kwargs = _merge_ct_kwargs(
        request.chat_template_kwargs,
        getattr(request, "reasoning_effort", None),
    )
    _effective_thinking = _resolve_enable_thinking(
        request_value=request.enable_thinking,
        ct_kwargs=_ct_kwargs,
        tools_present=bool(getattr(request, "tools", None)),
        model_key=_model_path or _model_name or request.model,
        engine=engine,
        auto_detect=True,
        reasoning_effort=request.reasoning_effort,
    )
    if _effective_thinking is not None:
        kwargs["enable_thinking"] = _effective_thinking
        request.enable_thinking = _effective_thinking
        _ct_kwargs["enable_thinking"] = _effective_thinking
        kwargs["chat_template_kwargs"] = dict(
            kwargs.get("chat_template_kwargs") or {}, **_ct_kwargs
        )

    # Reasoning parser setup (mirrors stream_chat_completion)
    from .model_config_registry import get_model_config_registry

    _model_config = get_model_config_registry().lookup(
        _model_path or _model_name or request.model
    )
    _family_name = getattr(_model_config, "family_name", None)
    _is_minimax_m3 = _family_name in (
        "minimax_m3",
        "minimax_m3_vl",
    )
    _m3_thinking_mode = (
        (kwargs.get("chat_template_kwargs") or _ct_kwargs or {}).get("thinking_mode")
        if _is_minimax_m3
        else None
    )
    think_in_template = _model_config.think_in_template

    # Fallback only for unknown configs. Known families may expose thinking
    # tokens in vocab without opening a reasoning rail in the rendered prompt.
    think_in_template = _apply_tokenizer_thinking_vocab_fallback(
        think_in_template,
        reasoning_parser=_reasoning_parser,
        tokenizer=engine.tokenizer,
        model_config=_model_config,
    )

    # S5 seed detection (mirrors Chat Completions path)
    _template_completed_thinking = False
    if think_in_template:
        if _template_completes_thinking(engine.tokenizer, _model_name or request.model):
            _template_completed_thinking = True
            think_in_template = False

    # When user explicitly disables thinking, check if template actually respects it.
    # The final parser seed below uses the engine's post-render prompt contract.
    if _effective_thinking is False and think_in_template:
        if not _template_always_thinks(engine.tokenizer, _model_name or request.model):
            think_in_template = False

    _reasoning_seed_probe_needed = bool(
        _reasoning_parser
        or getattr(_model_config, "reasoning_parser", None)
        or getattr(_model_config, "think_in_template", False)
    )
    if _reasoning_seed_probe_needed:
        _prompt_enable = True if _effective_thinking is None else bool(_effective_thinking)
        _tools_present_for_prompt = _tools_available_for_generation(
            request, kwargs.get("tools")
        )
        if _engine_prompt_starts_in_reasoning(
            engine.tokenizer,
            model_name=_model_name or request.model,
            enable_thinking=_prompt_enable,
            family_name=getattr(_model_config, "family_name", None),
            tools_present=_tools_present_for_prompt,
        ):
            think_in_template = True
        else:
            think_in_template = False

    if _stamped_think_template_requires_reasoning_seed(
        _model_config,
        _effective_thinking,
        template_completed_thinking=_template_completed_thinking,
    ):
        think_in_template = True

    if _hy3_prompt_starts_in_reasoning(
        model_key=_model_path or _model_name or request.model,
        enable_thinking=_effective_thinking,
        ct_kwargs=kwargs.get("chat_template_kwargs") or _ct_kwargs,
    ):
        think_in_template = True

    if _synthetic_mllm_think_prompt_starts(
        model_key=_model_path or _model_name or request.model,
        enable_thinking=_effective_thinking,
        engine=engine,
    ):
        think_in_template = True

    # MiniMax-M3's enabled mode prompt-opens <mm:think> in the rendered
    # generation prompt, so streamed output starts inside reasoning without
    # emitting an opening tag. Seed the streaming parser the same way the
    # non-streaming parser is seeded, otherwise internal reasoning is emitted
    # as visible content on /v1/responses stream=true.
    # Adaptive emits no template prefix: wait for an actual <mm:think> marker.
    # Only enabled mode starts decode inside an already-open reasoning rail.
    if _m3_thinking_mode == "enabled":
        think_in_template = True

    # The parser seed must match the final prompt the engine renders. Tool
    # requests may intentionally leave reasoning open; no-tool thinking-off
    # requests may close it before decode.
    effective_think_in_template = think_in_template

    # Suppress reasoning output when user explicitly disabled thinking
    suppress_reasoning = _effective_thinking is False
    m3_reasoning_only_answer_budget: int | None = None
    m3_reasoning_only_answer_enabled = False
    m3_tools_fallback_answer_budget: int | None = None
    reasoning_only_answer_budget: int | None = None
    reasoning_only_answer_enabled = False
    reasoning_only_answer_family = ""
    reasoning_tools_fallback_answer_budget: int | None = None
    _explicit_answer_pass_mtt = getattr(request, "max_thinking_tokens", None)
    _dsv4_default_reserve = False
    if _explicit_answer_pass_mtt is None:
        # Server-managed-budget families (DSV4, Nemotron): reserve answer
        # budget so the never-empty answer pass below can arm. No-op for
        # every other family. The SOFT-cap flag stays DSV4-only — its engine
        # rail implements the lift-at-</think> kwarg; Nemotron hard-splits.
        _explicit_answer_pass_mtt = _dsv4_answer_pass_thinking_cap(
            _family_name, _effective_thinking, kwargs.get("max_tokens")
        )
        _dsv4_default_reserve = (
            _explicit_answer_pass_mtt is not None
            and _family_name == "deepseek_v4"
        )
    if (
        _explicit_answer_pass_mtt is not None
        and _is_minimax_m3
        and (
            _m3_thinking_mode in ("enabled", "adaptive")
            or _effective_thinking is True
        )
    ):
        try:
            _requested_output_budget = int(kwargs.get("max_tokens") or 256)
            _requested_thinking_budget = max(1, int(_explicit_answer_pass_mtt))
            if _requested_thinking_budget < _requested_output_budget:
                kwargs = dict(kwargs)
                kwargs["max_tokens"] = _requested_thinking_budget
                if _stream_tools_available:
                    m3_tools_fallback_answer_budget = _requested_output_budget
                else:
                    m3_reasoning_only_answer_budget = _requested_output_budget
                    m3_reasoning_only_answer_enabled = True
        except Exception:
            m3_reasoning_only_answer_budget = None
            m3_reasoning_only_answer_enabled = False
            m3_tools_fallback_answer_budget = None
    if (
        _explicit_answer_pass_mtt is not None
        and _family_name == "gemma4"
        and _effective_thinking is not False
        and not _stream_tools_available
    ):
        try:
            _requested_output_budget = int(kwargs.get("max_tokens") or 256)
            _requested_thinking_budget = max(1, int(_explicit_answer_pass_mtt))
            if _requested_thinking_budget < _requested_output_budget:
                kwargs = dict(kwargs)
                kwargs["max_tokens"] = _requested_thinking_budget
                reasoning_only_answer_budget = _requested_output_budget
                reasoning_only_answer_enabled = True
                reasoning_only_answer_family = "Gemma4"
        except Exception:
            reasoning_only_answer_budget = None
            reasoning_only_answer_enabled = False
            reasoning_only_answer_family = ""
    if (
        not reasoning_only_answer_enabled
        and _explicit_answer_pass_mtt is not None
        and (
            _family_name in _THINKING_BUDGET_CAP_FAMILIES
            or _family_name == "deepseek_v4"
        )
        and _effective_thinking is not False
    ):
        # Explicit two-stage parity with Chat. Implicit Auto/On is always a
        # single native generation and never receives a synthetic retry.
        try:
            _requested_output_budget = int(kwargs.get("max_tokens") or 256)
            _requested_thinking_budget = max(1, int(_explicit_answer_pass_mtt))
            if _requested_thinking_budget < _requested_output_budget:
                reasoning_only_answer_family = _reasoning_answer_pass_family_label(
                    _family_name
                )
                if _stream_tools_available:
                    reasoning_tools_fallback_answer_budget = _requested_output_budget
                else:
                    reasoning_only_answer_budget = _requested_output_budget
                    reasoning_only_answer_enabled = True
                kwargs = dict(kwargs)
                if _dsv4_default_reserve:
                    # DSV4 default reserve: SOFT cap enforced engine-side only
                    # while inside the thinking rail; lifts at </think> so the
                    # same pass spends the reserved answer budget instead of
                    # stranding it (v1.6.23 hard split truncated answers that
                    # started just before the cap). Reasoning-only runs still
                    # finish=length at the cap, so the answer pass below arms
                    # exactly as before. Explicit max_thinking_tokens keeps the
                    # hard split contract.
                    kwargs["dsv4_thinking_soft_cap"] = _requested_thinking_budget
                else:
                    kwargs["max_tokens"] = _requested_thinking_budget
        except Exception:
            reasoning_only_answer_budget = None
            reasoning_only_answer_enabled = False
            reasoning_only_answer_family = ""
            reasoning_tools_fallback_answer_budget = None

    logger.debug(
        "Responses reasoning-answer fallback init: family=%s "
        "effective_thinking=%r tools_available=%s enabled=%s fallback_budget=%s",
        _family_name,
        _effective_thinking,
        _stream_tools_available,
        reasoning_only_answer_enabled,
        reasoning_tools_fallback_answer_budget,
    )

    # Create a per-request parser instance to avoid mutable-state conflicts
    # when multiple requests stream concurrently.
    _harmony_prefix_active = (
        "prompt_suffix" in kwargs
        and kwargs.get("prompt_suffix", "").startswith(
            "<|start|>assistant<|channel|>analysis"
        )
    ) or _reasoning_parser_is_harmony(_reasoning_parser)
    request_parser = _new_request_reasoning_parser(
        configured_parser=_reasoning_parser,
        model_config=_model_config,
        effective_think_in_template=effective_think_in_template,
        harmony_active=_harmony_prefix_active,
        stream_surface="responses",
        adaptive_mode=bool(_is_minimax_m3 and _m3_thinking_mode == "adaptive"),
    )
    if request_parser is None:
        logger.debug("[responses] No reasoning parser active for this request")

    # Use per-request timeout if provided, otherwise server default
    _stream_timeout = (
        request.timeout if request.timeout is not None else _default_timeout
    )

    try:
        async for output in _stream_with_keepalive(
            engine.stream_chat(messages=messages, **kwargs),
            total_timeout=_stream_timeout,
            progress_probe=(
                None
                if request.timeout is not None
                else lambda: _engine_request_progress(engine, response_id)
            ),
        ):
            # Keep-alive sentinel — emit SSE comment to prevent connection timeout
            if output is None:
                yield ": keep-alive\n\n"
                continue

            if fastapi_request and await fastapi_request.is_disconnected():
                logger.info(f"Client disconnected, aborting request {response_id}")
                _stream_disconnected = True
                if hasattr(engine, "abort_request"):
                    await engine.abort_request(response_id)
                break

            last_output = output
            delta_text = output.new_text

            # Track token counts from output BEFORE any continue statements
            # (must run unconditionally — reasoning parser's continue skips
            # code below, so token tracking must happen first)
            if hasattr(output, "prompt_tokens") and output.prompt_tokens:
                prompt_tokens = output.prompt_tokens
            if hasattr(output, "completion_tokens") and output.completion_tokens:
                completion_tokens = output.completion_tokens
            if completion_tokens > _decode_last_count:
                _decode_last_ts = _decode_output_timestamp(output)
                if _decode_first_ts is None:
                    _decode_first_ts = _decode_last_ts
                    _decode_first_count = completion_tokens
                _decode_last_count = completion_tokens
            _chunk_cached = int(getattr(output, "cached_tokens", 0) or 0)
            if _chunk_cached > 0:
                _cached = _chunk_cached
            _detail_chunk = getattr(output, "cache_detail", "") or None
            if _detail_chunk is not None:
                _cache_detail = _detail_chunk
            if getattr(output, "error", None):
                raise RuntimeError(str(getattr(output, "error")))

            if _draining_tool_parser_stop:
                # See Chat Completions: wait for the real engine terminal and
                # its durability barrier while withholding internal drain text.
                if output.finished:
                    break
                continue

            if delta_text or output.finished:
                if delta_text:
                    full_text += delta_text

                # Stop generation once the tool-call turn is complete (opt-in
                # per parser) — mirrors stream_chat_completion. The
                # post-stream parse below then emits the function_call output
                # items exactly as if the model had stopped on its own.
                if (
                    _tc_stop_parser is not None
                    and tool_call_buffering
                    and not output.finished
                ):
                    if _tc_stop_parser.stream_tool_calls_complete(full_text):
                        _tc_stop_complete_chunks += 1
                        _tc_stop_grace = int(
                            getattr(
                                _tc_stop_parser,
                                "_stream_stop_grace_chunks",
                                _STREAM_TOOL_CALL_STOP_GRACE_CHUNKS,
                            )
                        )
                        if (
                            _tc_stop_complete_chunks
                            > _tc_stop_grace
                        ):
                            logger.info(
                                "Responses stream %s: complete tool call parsed "
                                "but model kept generating %d chunks past it — "
                                "stopping generation (parser=%s)",
                                response_id,
                                _tc_stop_complete_chunks,
                                type(_tc_stop_parser).__name__,
                            )
                            # Drop the post-call rambling so it neither leaks
                            # to the client nor steers the post-stream parse
                            # to the wrong channel.
                            full_text = (
                                _tc_stop_parser.stream_tool_call_stop_truncate(
                                    full_text
                                )
                            )
                            _early_stopped_tool_text = full_text
                            if _tc_stop_parser.stream_tool_calls_complete(
                                accumulated_content
                            ):
                                accumulated_content = (
                                    _tc_stop_parser.stream_tool_call_stop_truncate(
                                        accumulated_content
                                    )
                                )
                            elif _tc_stop_parser.stream_tool_calls_complete(
                                accumulated_reasoning
                            ):
                                # Call arrived mid-reasoning: accumulated
                                # content came AFTER the call and was never
                                # streamed while buffering — drop it.
                                accumulated_reasoning = (
                                    _tc_stop_parser.stream_tool_call_stop_truncate(
                                        accumulated_reasoning
                                    )
                                )
                                accumulated_content = ""
                            if await _request_tool_parser_graceful_stop(
                                engine, response_id
                            ):
                                _draining_tool_parser_stop = True
                                continue
                            if hasattr(engine, "abort_request"):
                                await engine.abort_request(response_id)
                            break
                    else:
                        _tc_stop_complete_chunks = 0

                # Use reasoning parser if enabled
                if request_parser:
                    previous_text = (
                        full_text[: -len(delta_text)] if delta_text else full_text
                    )
                    if delta_text:
                        delta_msg = _extract_reasoning_stream_delta(
                            request_parser,
                            previous_text,
                            full_text,
                            delta_text,
                            finished=bool(output.finished),
                        )
                    else:
                        delta_msg = ChatCompletionChunkDelta()
                    if delta_msg is None:
                        # Skip this chunk entirely (e.g., <think> token itself)
                        # Must use continue (not pass) to avoid falling through
                        # to token tracking and usage emission below.
                        if output.finished:
                            delta_msg = ChatCompletionChunkDelta()
                        else:
                            continue
                    if delta_msg is not None:
                        # Post-parse cleaning — mirror the chat_completions
                        # streaming path so Responses API clients don't see
                        # residual `<channel|>` / `thought\n` / `<turn|>` etc.
                        # that the parser's split leaves in content. Use the
                        # delta-safe stripper that preserves whitespace —
                        # clean_output_text's trailing `.strip()` eats per-
                        # delta leading spaces and concatenates the stream
                        # into " Itlooksliketypo" garbage.
                        if delta_msg.content:
                            delta_msg.content = strip_marker_tokens_delta(delta_msg.content)
                        if delta_msg.reasoning:
                            delta_msg.reasoning = strip_marker_tokens_delta(delta_msg.reasoning)
                        # Accumulate for marker detection (before buffering check).
                        # Suppressed reasoning stays internal and must not be
                        # mirrored into visible output_text/history.
                        if delta_msg.content:
                            accumulated_content += delta_msg.content
                        if delta_msg.reasoning:
                            accumulated_reasoning += delta_msg.reasoning

                        # Check for tool call markers in content and reasoning
                        if tool_call_active and not tool_call_buffering:
                            _buffer_trigger = None
                            if delta_msg.content and accumulated_content:
                                if _has_tool_marker_or_partial_suffix(
                                    accumulated_content
                                ):
                                    tool_call_buffering = True
                                    _buffer_trigger = "content-marker"
                                elif _content_forms_raw_json_tool_call(
                                    accumulated_content
                                ):
                                    tool_call_buffering = True
                                    _buffer_trigger = "raw-json"
                            if not tool_call_buffering and delta_msg.reasoning:
                                _reasoning_tail = (
                                    accumulated_reasoning[-30:]
                                    if len(accumulated_reasoning) > 30
                                    else accumulated_reasoning
                                )
                                # #199-2A: see stream_chat_completion — buffer only
                                # when the reasoning tail is ACTIVELY emitting a
                                # tool marker, not on a mere mention in prose.
                                tool_call_buffering = _text_ends_with_tool_marker(
                                    _reasoning_tail
                                )
                                if tool_call_buffering:
                                    _buffer_trigger = "reasoning-marker"
                            # GPT-OSS/Harmony native tool format: to=<name> code{...}
                            if not tool_call_buffering:
                                _tc_check = (
                                    accumulated_content
                                    or (
                                        accumulated_reasoning[-30:]
                                        if (
                                            accumulated_reasoning
                                            and _parser_routes_tools_via_reasoning_channel(
                                                request_parser, _harmony_prefix_active
                                            )
                                        )
                                        else ""
                                    )
                                    or ""
                                )
                                if re.search(r"\bto=\w[\w.]*\s+code\{", _tc_check):
                                    tool_call_buffering = True
                                    _buffer_trigger = "harmony"

                            if tool_call_buffering:
                                logger.info(
                                    "Responses dynamic tool buffering activated: "
                                    "trigger=%s content_chars=%d reasoning_chars=%d",
                                    _buffer_trigger,
                                    len(accumulated_content),
                                    len(accumulated_reasoning),
                                )

                        if tool_call_buffering:
                            if (
                                _exact_once_tool_contract
                                and not suppress_reasoning
                                and delta_msg.reasoning
                            ):
                                # Exact-once requests buffer from token one, so
                                # genuine reasoning must still stream. DSV4 can
                                # emit its canonical DSML call on that same
                                # reasoning rail, however. Derive the visible
                                # delta from the full reasoning prefix and stop
                                # at the first native tool marker; never expose
                                # the structured call as reasoning text.
                                _safe_reasoning = (
                                    _visible_prefix_before_unparsed_tool_markup(
                                        accumulated_reasoning
                                    )
                                )
                                if _safe_reasoning.startswith(streamed_reasoning_text):
                                    _reasoning_delta = _safe_reasoning[
                                        len(streamed_reasoning_text) :
                                    ]
                                else:
                                    # The safe-prefix helper may trim whitespace
                                    # immediately before a newly seen marker. SSE
                                    # deltas cannot retract already-sent text.
                                    _reasoning_delta = ""
                                if _reasoning_delta:
                                    streamed_reasoning_text += _reasoning_delta
                                    reasoning_was_streamed = True
                                    for _event in _start_reasoning_item_events():
                                        yield _event
                                    yield _sse(
                                        "response.reasoning_summary_text.delta",
                                        {
                                            "type": "response.reasoning_summary_text.delta",
                                            "item_id": reasoning_item_id,
                                            "output_index": reasoning_output_index,
                                            "summary_index": 0,
                                            "delta": _reasoning_delta,
                                        },
                                    )
                            # Emit heartbeat during tool call buffering so the client
                            # sees activity (matches ChatCompletion heartbeat behavior).
                            yield _sse(
                                "response.heartbeat",
                                {
                                    "type": "response.heartbeat",
                                    "tool_call_generating": True,
                                },
                            )
                            continue

                        if not tool_call_buffering:
                            # Suppressed reasoning is never redirected into
                            # visible output_text. Boundary deltas can still
                            # carry post-</think> content, which remains
                            # visible.
                            if suppress_reasoning:
                                emit_content = delta_msg.content
                                emit_reasoning = None
                                if not emit_content and not output.finished:
                                    yield _sse(
                                        "response.in_progress",
                                        {"type": "response.in_progress"},
                                    )
                                    continue
                            else:
                                emit_reasoning = delta_msg.reasoning
                                emit_content = delta_msg.content

                            if tool_call_active and emit_reasoning:
                                safe_reasoning_prefix = _tool_safe_stream_prefix(
                                    accumulated_reasoning,
                                    finished=output.finished,
                                )
                                emit_reasoning = (
                                    safe_reasoning_prefix[
                                        len(streamed_reasoning_text) :
                                    ]
                                    if safe_reasoning_prefix.startswith(
                                        streamed_reasoning_text
                                    )
                                    else None
                                )

                            if _suppress_markup_display and emit_content:
                                safe_content_prefix = (
                                    _tool_safe_stream_prefix(
                                        accumulated_content, finished=output.finished
                                    )
                                    if tool_call_active
                                    else accumulated_content
                                )
                                emit_content = _suppressed_tool_display_delta(
                                    safe_content_prefix,
                                    streamed_text,
                                    request,
                                )
                            elif emit_content:
                                safe_content_prefix = (
                                    _tool_safe_stream_prefix(
                                        accumulated_content, finished=output.finished
                                    )
                                    if tool_call_active
                                    else accumulated_content
                                )
                                emit_content = _visual_grounding_display_delta(
                                    safe_content_prefix,
                                    streamed_text,
                                )

                            if output.finished and not tool_call_buffering:
                                terminal_suffix = _terminal_visible_stream_suffix(
                                    getattr(output, "text", ""),
                                    streamed_text + (emit_content or ""),
                                    parser=request_parser,
                                    request=request,
                                    suppress_markup=_suppress_markup_display,
                                    tools_active=tool_call_active,
                                )
                                if terminal_suffix:
                                    emit_content = (emit_content or "") + terminal_suffix
                                    accumulated_content += terminal_suffix

                            # Emit reasoning as OpenAI Responses reasoning-summary events.
                            if emit_reasoning:
                                streamed_reasoning_text += emit_reasoning
                                reasoning_was_streamed = True
                                for _event in _start_reasoning_item_events():
                                    yield _event
                                yield _sse(
                                    "response.reasoning_summary_text.delta",
                                    {
                                        "type": "response.reasoning_summary_text.delta",
                                        "item_id": reasoning_item_id,
                                        "output_index": reasoning_output_index,
                                        "summary_index": 0,
                                        "delta": emit_reasoning,
                                    },
                                )
                            # Emit content as standard text delta
                            if emit_content:
                                if reasoning_item_started and not reasoning_item_finished:
                                    for _event in _finish_reasoning_item_events(
                                        streamed_reasoning_text or accumulated_reasoning
                                    ):
                                        yield _event
                                for _event in _start_message_item_events():
                                    yield _event
                                content_was_emitted = True
                                streamed_text += emit_content
                                yield _sse(
                                    "response.output_text.delta",
                                    {
                                        "type": "response.output_text.delta",
                                        "item_id": msg_id,
                                        "output_index": message_output_index,
                                        "content_index": 0,
                                        "delta": emit_content,
                                    },
                                )
                else:
                    # Standard path without reasoning parsing
                    content = delta_text

                    # Check for tool call markers
                    if tool_call_active and not tool_call_buffering:
                        tool_call_buffering = _has_tool_marker_or_partial_suffix(
                            full_text
                        )

                    if tool_call_buffering:
                        # Emit heartbeat during tool call buffering (standard path)
                        yield _sse(
                            "response.heartbeat",
                            {
                                "type": "response.heartbeat",
                                "tool_call_generating": True,
                            },
                        )
                        continue
                    else:
                        if _suppress_markup_display and content:
                            safe_text_prefix = (
                                _tool_safe_stream_prefix(
                                    full_text, finished=output.finished
                                )
                                if tool_call_active
                                else full_text
                            )
                            content = _suppressed_tool_display_delta(
                                safe_text_prefix,
                                streamed_text,
                                request,
                            )
                        elif content:
                            safe_text_prefix = (
                                _tool_safe_stream_prefix(
                                    full_text, finished=output.finished
                                )
                                if tool_call_active
                                else full_text
                            )
                            content = _visual_grounding_display_delta(
                                safe_text_prefix,
                                streamed_text,
                            )

                        if output.finished and not tool_call_buffering:
                            terminal_suffix = _terminal_visible_stream_suffix(
                                getattr(output, "text", ""),
                                streamed_text + (content or ""),
                                request=request,
                                suppress_markup=_suppress_markup_display,
                                tools_active=tool_call_active,
                            )
                            if terminal_suffix:
                                content = (content or "") + terminal_suffix

                        if content:
                            if reasoning_item_started and not reasoning_item_finished:
                                for _event in _finish_reasoning_item_events(
                                    streamed_reasoning_text or accumulated_reasoning
                                ):
                                    yield _event
                            for _event in _start_message_item_events():
                                yield _event
                            content_was_emitted = True
                            streamed_text += content
                            yield _sse(
                                "response.output_text.delta",
                                {
                                    "type": "response.output_text.delta",
                                    "item_id": msg_id,
                                    "output_index": message_output_index,
                                    "content_index": 0,
                                    "delta": content,
                                },
                            )

            # Private local-panel telemetry.  Standard Responses usage remains
            # on the terminal response.completed object below.
            if incremental_usage_extension and (prompt_tokens or completion_tokens):
                usage_obj = {
                    "input_tokens": prompt_tokens,
                    "output_tokens": completion_tokens,
                    "total_tokens": prompt_tokens + completion_tokens,
                }
                _decode_usage = _decode_usage_snapshot(
                    completion_tokens=completion_tokens,
                    first_token_ts=_decode_first_ts,
                    last_token_ts=_decode_last_ts,
                    first_token_count=_decode_first_count,
                )
                if _decode_usage is not None:
                    usage_obj["vmlx_decode"] = _decode_usage
                if _cached > 0 or _cache_detail:
                    _ictd = {"cached_tokens": _cached}
                    if _cache_detail:
                        _ictd["cache_detail"] = _cache_detail
                    usage_obj["input_tokens_details"] = _ictd
                yield _sse(
                    "response.usage",
                    {
                        "type": "response.usage",
                        "usage": usage_obj,
                    },
                )
    # PrefillAdmissionError rides along: same class of client error (the
    # device cannot serve this context), and the body below uses only
    # str(e), so it needs no PromptTooLongError-specific fields.
    except (
        MediaControlsUnmeetableError,
        MediaInputError,
        PromptTooLongError,
        PrefillAdmissionError,
        VLMImagePrefillBudgetError,
        UnsupportedMediaModalityError,
    ) as e:
        # A typed request rejection is FATAL for the stream: emit the typed
        # error event for incremental consumers, then the failed terminal,
        # and stop. Live (e6262e3a, strict-multi-4S-033105 resp_b8b3d8425246):
        # these handlers yielded the error event and fell through into the
        # normal finalization, which emitted response.completed with an
        # empty output — a fatal rejection reported as a success.
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        _typed_code = (
            "prompt_too_long"
            if isinstance(e, (PromptTooLongError, PrefillAdmissionError))
            else type(e).code
        )
        _typed_error = {
            "type": "invalid_request_error",
            "message": str(e),
            "code": _typed_code,
        }
        yield _sse("error", {"type": "error", "error": dict(_typed_error)})
        _err_usage = {}
        if prompt_tokens > 0 or completion_tokens > 0:
            _err_usage = {
                "usage": {
                    "input_tokens": prompt_tokens,
                    "output_tokens": completion_tokens,
                    "total_tokens": prompt_tokens + completion_tokens,
                },
            }
        yield _sse(
            "response.failed",
            {
                "type": "response.failed",
                "response": {
                    "id": response_id,
                    "object": "response",
                    "status": "failed",
                    "error": dict(_typed_error),
                    **_err_usage,
                },
            },
        )
        return
    except asyncio.CancelledError:
        logger.info("Responses stream cancelled, aborting %s", response_id)
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        raise
    except Exception as e:
        # On any error, abort the request and emit an error SSE event
        # so the client knows what happened instead of a silent EOF.
        logger.error(f"Stream error for {response_id}: {e}", exc_info=True)
        if hasattr(engine, "abort_request"):
            await engine.abort_request(response_id)
        yield _sse(
            "error",
            {
                "type": "error",
                "error": {
                    "type": "server_error",
                    "message": f"Stream generation failed: {e}",
                    "code": "internal_error",
                },
            },
        )
        # M8: Include partial usage in failed response so client gets token counts
        _err_usage = {}
        if prompt_tokens > 0 or completion_tokens > 0:
            _err_usage = {
                "usage": {
                    "input_tokens": prompt_tokens,
                    "output_tokens": completion_tokens,
                    "total_tokens": prompt_tokens + completion_tokens,
                },
            }
        yield _sse(
            "response.failed",
            {
                "type": "response.failed",
                "response": {
                    "id": response_id,
                    "object": "response",
                    "status": "failed",
                    "error": {"type": "server_error", "message": str(e)},
                    **_err_usage,
                },
            },
        )
        return

    _response_was_cancelled = bool(
        _stream_disconnected
        or (
            last_output is not None
            and getattr(last_output, "finish_reason", None) == "aborted"
        )
    )
    _resp_finish = getattr(last_output, "finish_reason", None) if last_output else None
    _note_request_diagnostics_id(response_id)
    _response_terminal = _responses_terminal_state(
        _resp_finish,
        cancelled=_response_was_cancelled,
        request_id=response_id,
    )
    _response_output_status = _response_terminal.item_status

    # Tool calls may share the reasoning rail (DSV4 emits canonical DSML there).
    # Preserve the raw accumulator for final tool parsing, but expose only the
    # genuine reasoning prefix through summary events and completed output.
    visible_reasoning_text = accumulated_reasoning
    if tool_call_active and visible_reasoning_text:
        visible_reasoning_text = _visible_prefix_before_unparsed_tool_markup(
            visible_reasoning_text
        )

    # Close the same reasoning item announced before the first summary delta.
    # This keeps strict Responses clients able to correlate every event by ID
    # and output_index instead of receiving deltas attached to a message item.
    if visible_reasoning_text and not suppress_reasoning:
        for _event in _finish_reasoning_item_events(
            visible_reasoning_text,
            status=_response_output_status,
        ):
            yield _event

    # Build output items list for the completed response
    all_output_items = []
    output_index = next_output_index

    # Parse tool calls from the accumulated text (skip when tool_choice="none").
    # Strip think tags before parsing — reasoning text may precede tool calls
    # (mirrors the Chat Completions streaming path at lines 2468-2475).
    tool_calls = None
    cleaned_text = full_text
    _tool_parse_from_reasoning_only = False
    if tool_call_active:
        # Use content-only text when reasoning parser separated it (avoids losing
        # tool calls that appear inside <think> blocks during regex stripping).
        # If content is empty but reasoning has tool markers, check reasoning too.
        if _early_stopped_tool_text:
            # See Chat Completions sibling: the stop point precedes processing
            # the close-marker delta, so use the complete truncated raw call.
            parse_text = _early_stopped_tool_text
        elif request_parser and accumulated_content.strip():
            parse_text = accumulated_content.strip()
        elif request_parser and accumulated_reasoning.strip():
            parse_text = accumulated_reasoning.strip()
            _tool_parse_from_reasoning_only = True
        else:
            parse_text = _strip_think_for_tool_parse(full_text)
        cleaned_text, tool_calls = _parse_tool_calls_with_parser(
            parse_text or full_text, request
        )
        if _tool_parse_from_reasoning_only and not tool_calls:
            # Reasoning-only text is only a candidate tool-call source. If it is
            # not actually a tool call, never recycle it as visible output_text;
            # that creates hidden-only/empty UI rows or pollutes chat history.
            cleaned_text = ""
    elif _suppress_markup_display:
        cleaned_text = _clean_suppressed_tool_markup_for_display(
            full_text,
            request,
        )

    # Tool markup that lands on the reasoning rail must be *extracted*, not
    # discarded. This used to require ``suppress_reasoning``, so it never ran on
    # the Responses API, where reasoning is streamed as a summary rather than
    # suppressed. A DSV4 turn that emitted its DSML block inside the reasoning
    # rail therefore fell through to the buffered-markup path, which threw the
    # markup away as an unsafe control suffix and finalized the response as
    # ``response.incomplete`` with no function call at all — even though the
    # DSML parser accepts that exact block and returns a valid `file_info` call.
    # The markup is already withheld from the visible reasoning summary, so
    # extracting it adds no leak: it only turns a dropped call into a real one.
    if (
        not tool_calls
        and accumulated_reasoning
        and not _suppress_markup_display
        and _private_reasoning_has_tool_syntax(accumulated_reasoning)
    ):
        logger.info(
            f"Request {response_id}: tool markers in reasoning rail "
            f"(suppressed={suppress_reasoning}) — extracting before Responses "
            "API finalization"
        )
        _tc_calls = _parse_private_reasoning_tool_calls(
            accumulated_reasoning, request
        )
        if _tc_calls:
            cleaned_text = ""
            tool_calls = _tc_calls

    _buffered_reasoning_only = False
    if tool_call_buffering and not tool_calls:
        # The stream advertised only a speculative buffering heartbeat. A
        # malformed/truncated or schema-rejected native call is not a function
        # call and its raw XML/JSON control suffix is not assistant prose.
        # Reconcile the final Responses text to the already-visible safe prefix.
        # If the candidate came from the reasoning rail, keep it on that rail.
        # Falling back to ``full_text`` here used to copy already-streamed private
        # Qwen reasoning into ``accumulated_content`` after an incomplete
        # post-tool ``<tool_call>`` suffix. Besides leaking reasoning as terminal
        # output_text, that made the visible-answer gate think content existed and
        # skipped its bounded direct-answer pass.
        _buffered_reasoning_only = bool(
            _tool_parse_from_reasoning_only
            or (
                request_parser is not None
                and accumulated_reasoning.strip()
                and not accumulated_content.strip()
            )
        )
        _buffered_candidate = (
            accumulated_reasoning
            if _buffered_reasoning_only
            else (accumulated_content or cleaned_text or full_text)
        )
        _safe_visible_prefix = _visible_prefix_before_unparsed_tool_markup(
            _buffered_candidate
        )
        if _safe_visible_prefix != _buffered_candidate:
            _discarded_suffix = _buffered_candidate[len(_safe_visible_prefix):]
            logger.warning(
                "Request %s: buffered tool markup produced no valid call; "
                "discarding %d unsafe control characters after the visible "
                "prefix; raw_suffix=%r",
                response_id,
                len(_discarded_suffix),
                _discarded_suffix[:500].replace("\n", "\\n"),
            )
            _record_tool_call_drop(
                "Buffered native tool markup did not produce a schema-valid "
                "function call. The incomplete control suffix was hidden; try a "
                "clearer tool-use prompt or raise max_output_tokens."
            )
            if _buffered_reasoning_only:
                # The safe prefix is still reasoning, not assistant-visible text.
                # ``visible_reasoning_text`` was independently cleaned above for
                # reasoning-summary finalization.
                accumulated_content = ""
                cleaned_text = ""
            else:
                accumulated_content = _safe_visible_prefix
                cleaned_text = _safe_visible_prefix

    # When the reasoning parser already separated a private rail, only its
    # accumulated CONTENT can satisfy the visible-answer gate.  A tool_choice=none
    # request still enters the suppressed-tools cleanup path; using cleaned_text
    # there recycled full_text (the private reasoning rail) and falsely told the
    # gate that visible content existed.  The result was a reasoning-only terminal
    # with no bounded answer pass for any affected Responses reasoning family.
    # Models without a separated reasoning rail keep the suppressed-tools cleaned
    # text so raw native tool markup remains hidden from ordinary content.
    if request_parser and accumulated_reasoning.strip():
        _fallback_visible_content = accumulated_content
        if _suppress_markup_display and _fallback_visible_content:
            _fallback_visible_content = _clean_suppressed_tool_markup_for_display(
                _fallback_visible_content,
                request,
            )
    else:
        _fallback_visible_content = (
            cleaned_text if _suppress_markup_display else accumulated_content
        )
    _explicit_tool_intent = _request_explicitly_requests_tool_use(request)

    logger.debug(
        "Responses reasoning-answer fallback gate: family=%s "
        "effective_thinking=%r tools_available=%s enabled=%s "
        "fallback_budget=%s content_chars=%d fallback_chars=%d "
        "reasoning_chars=%d tool_calls=%s explicit_tool_intent=%s",
        _family_name,
        _effective_thinking,
        _stream_tools_available,
        reasoning_only_answer_enabled,
        reasoning_tools_fallback_answer_budget,
        len(accumulated_content),
        len(_fallback_visible_content or ""),
        len(accumulated_reasoning),
        len(tool_calls or []),
        _explicit_tool_intent,
    )

    _rearm_reasoning_answer = bool(
        not tool_calls
        and not (_fallback_visible_content or "").strip()
        and not reasoning_only_answer_enabled
        and reasoning_tools_fallback_answer_budget is not None
        and accumulated_reasoning.strip()
        and not _explicit_tool_intent
    )

    if (
        not tool_calls
        and not (_fallback_visible_content or "").strip()
        and not m3_reasoning_only_answer_enabled
        and m3_tools_fallback_answer_budget is not None
        and accumulated_reasoning.strip()
    ):
        # The native parser has rejected the speculative tool prefix. Re-run
        # M3 on its direct rail without tools so a reasoning-only turn cannot
        # finalize as a blank assistant message.
        logger.info(
            "MiniMax-M3 tools-enabled Responses stream produced no valid tool "
            "call or visible content; re-arming bounded thinking-off answer pass"
        )
        m3_reasoning_only_answer_budget = m3_tools_fallback_answer_budget
        m3_reasoning_only_answer_enabled = True

    if _rearm_reasoning_answer:
        # Tools were offered, but the finalized parser found no call. Re-arm
        # the established bounded direct-answer pass so an ordinary no-tool
        # answer cannot end as a reasoning-only/blank assistant row.
        logger.info(
            "%s tools-enabled Responses stream produced no valid tool call or "
            "visible content; re-arming bounded %s answer pass",
            reasoning_only_answer_family or "reasoning model",
            (
                "native tools-free"
                if _family_name in _NATIVE_REASONING_TOOL_RECOVERY_FAMILIES
                else "thinking-off"
            ),
        )
        reasoning_only_answer_budget = reasoning_tools_fallback_answer_budget
        reasoning_only_answer_enabled = True

    display_text = ""

    if tool_calls:
        # Apply reasoning parser to the cleaned (pre-tool-call) text
        if _exact_once_tool_contract:
            # The user explicitly required one native call before any prose.
            # Any content preceding the valid call is model meta-commentary,
            # not assistant output. It may already be represented correctly on
            # the reasoning rail, so never duplicate it into output_text.
            cleaned_text = ""
        elif request_parser and cleaned_text:
            reasoning_text, content_text = request_parser.extract_reasoning(
                cleaned_text
            )
            if content_text:
                cleaned_text = content_text
            elif reasoning_text:
                cleaned_text = reasoning_text

        # Finalize the text message with whatever content was before the tool call
        final_text = (cleaned_text or "").strip()
        final_text = _finalize_visible_text_for_request(final_text, request, minimum_partial=4)
        if final_text or message_item_started:
            _message_was_started = message_item_started
            for _event in _start_message_item_events():
                yield _event
            if final_text and not _message_was_started:
                yield _sse(
                    "response.output_text.delta",
                    {
                        "type": "response.output_text.delta",
                        "item_id": msg_id,
                        "output_index": message_output_index,
                        "content_index": 0,
                        "delta": final_text,
                    },
                )
            yield _sse(
                "response.output_text.done",
                {
                    "type": "response.output_text.done",
                    "item_id": msg_id,
                    "output_index": message_output_index,
                    "content_index": 0,
                    "text": final_text,
                },
            )
            yield _sse(
                "response.content_part.done",
                {
                    "type": "response.content_part.done",
                    "item_id": msg_id,
                    "output_index": message_output_index,
                    "content_index": 0,
                    "part": {
                        "type": "output_text",
                        "text": final_text,
                        "annotations": [],
                    },
                },
            )
            message_item = {
                "id": msg_id,
                "type": "message",
                "status": _response_output_status,
                "role": "assistant",
                "content": [
                    {"type": "output_text", "text": final_text, "annotations": []}
                ],
            }
            yield _sse(
                "response.output_item.done",
                {
                    "type": "response.output_item.done",
                    "output_index": message_output_index,
                    "item": message_item,
                },
            )
            _record_output_item(message_output_index, message_item)

        # Emit each tool call as a function_call output item
        for _event in _function_call_item_events(tool_calls):
            yield _event
    else:
        # No tool calls — use content accumulated during streaming (reasoning already separated)
        _ans_tool_calls = None
        # Once any output_text deltas were emitted, their monotonic accumulator
        # owns the corresponding done event.  Re-cleaning raw/full_text can
        # reintroduce a held partial marker or omit a detokenizer-finalized
        # suffix, making Responses contradict its own delta stream.
        display_text = streamed_text or cleaned_text or ""
        if request_parser:
            # Reasoning was already emitted during streaming, so the monotonic
            # content-only accumulator owns Responses finalization.  This is
            # also where a terminal detokenizer suffix is reconciled.  The
            # suppressed-markup cleanup below still applies before emission;
            # preferring the raw incremental accumulator here made
            # output_text.done one byte shorter than its own final delta stream.
            if streamed_text:
                display_text = streamed_text
            elif accumulated_content and not _suppress_markup_display:
                display_text = accumulated_content
            elif (
                accumulated_reasoning
                and not reasoning_was_streamed
                and not _buffered_reasoning_only
                and not suppress_reasoning
                and not _is_minimax_m3
            ):
                # The completed reasoning item above owns this late parser
                # block.  Keep output_text empty rather than duplicating private
                # reasoning into visible content/history.
                display_text = ""
            elif display_text:
                # Fallback: re-parse if streaming didn't accumulate
                reasoning_text, content_text = request_parser.extract_reasoning(
                    display_text
                )
                if content_text:
                    display_text = content_text
                elif reasoning_text and not reasoning_was_streamed:
                    # The reasoning output item owns this text.  Never mirror it
                    # into output_text, even when the parser emitted it only at
                    # finalization.
                    display_text = ""
                else:
                    # Reasoning streamed + no content extractable → empty
                    # final text. Caller (panel) should fall back to
                    # reasoning_content for display, not output_text.
                    display_text = ""

        if not display_text:
            # If reasoning was streamed and we have no
            # content, keep display_text EMPTY rather than falling back to
            # full_text (which contains the reasoning text). Empty
            # output_text is the correct signal — client renders the
            # already-streamed reasoning_content. Falling back to full_text
            # here was the bug that pollutes history.
            if not reasoning_was_streamed and not _buffered_reasoning_only:
                display_text = clean_output_text(full_text) if full_text else ""
        if (
            not _response_was_cancelled
            and not display_text
            and (m3_reasoning_only_answer_enabled or reasoning_only_answer_enabled)
            and accumulated_reasoning.strip()
            and not tool_calls
            and _remaining_answer_pass_budget(
                (
                    m3_reasoning_only_answer_budget
                    if m3_reasoning_only_answer_enabled
                    else reasoning_only_answer_budget
                ) or 256,
                completion_tokens,
            ) > 0
        ):
            _answer_family = (
                "MiniMax-M3"
                if m3_reasoning_only_answer_enabled
                else (reasoning_only_answer_family or "reasoning model")
            )
            _answer_budget = (
                m3_reasoning_only_answer_budget
                if m3_reasoning_only_answer_enabled
                else reasoning_only_answer_budget
            )
            logger.info(
                "%s reasoning produced no visible content; "
                "running bounded %s answer pass "
                "(reasoning_chars=%d, answer_budget=%s)",
                _answer_family,
                (
                    "native tools-free"
                    if _family_name in _NATIVE_REASONING_TOOL_RECOVERY_FAMILIES
                    else "thinking-off"
                ),
                len(accumulated_reasoning),
                _answer_budget,
            )
            answer_messages = _answer_pass_messages(
                messages, _family_name, accumulated_reasoning
            )
            answer_kwargs = dict(kwargs)
            _native_reasoning_retry = (
                _family_name in _NATIVE_REASONING_TOOL_RECOVERY_FAMILIES
            )
            # Register the answer-pass stream under the id the disconnect handler
            # aborts (`{response_id}:visible-answer`); otherwise abort_request()
            # misses and the answer-pass generation leaks on the GPU after a
            # mid-answer-pass client disconnect. Mirror of the Chat Completions site.
            answer_kwargs["request_id"] = f"{response_id}:visible-answer"
            if not _native_reasoning_retry:
                _force_answer_pass_direct_rail(
                    answer_kwargs,
                    family_name=_family_name,
                )
            answer_kwargs["max_tokens"] = _remaining_answer_pass_budget(
                _answer_budget or 256,
                completion_tokens,
            )
            answer_ct_kwargs = dict(answer_kwargs.get("chat_template_kwargs") or {})
            if _native_reasoning_retry:
                pass
            elif _answer_family == "MiniMax-M3":
                answer_ct_kwargs["thinking_mode"] = "disabled"
            elif _answer_family == "openPangu":
                answer_ct_kwargs["thinking"] = False
            else:
                # Qwen3.5/3.6 VLM/MTP templates consume enable_thinking from
                # chat_template_kwargs; the top-level kwarg alone is not enough to
                # keep the bounded visible-answer retry on the direct rail.
                answer_ct_kwargs["enable_thinking"] = False
            answer_kwargs["chat_template_kwargs"] = answer_ct_kwargs
            answer_kwargs.pop("dsv4_thinking_soft_cap", None)
            answer_kwargs.pop("tools", None)
            answer_kwargs.pop("_vmlx_tools_present", None)
            answer_kwargs.pop("_vmlx_template_tools", None)
            try:
                # Standards-safe phase marker. SSE consumers ignore comments;
                # the negotiated local panel uses it to keep the UI visibly
                # active and to exclude this second prefill from decode TPS.
                yield ": vmlx-answer-pass-start\n\n"
                # F6: STREAM the answer pass token-by-token (see the Chat
                # Completions site for the full rationale + mechanics). The MLLM
                # stream only assembles GenerationOutput.text at finished=True, so
                # accumulate new_text and apply the SAME clean_output_text +
                # `</think>` split the non-streaming path used, holding back a
                # marker-length tail so transient partial-marker fragments are
                # re-stripped before they escape. Final text is identical to the
                # old single delta — just incremental.
                # Families in _ANSWER_PASS_LEAK_GUARD_FAMILIES still buffer and
                # emit only after a clean pass; see the Chat Completions site.
                # Qwen3.5/3.6 uses fresh context and is intentionally progressive.
                _buffer_answer_pass = _family_name in _ANSWER_PASS_LEAK_GUARD_FAMILIES
                _ans_budget_cap = int(answer_kwargs.get("max_tokens") or 0)
                _ans_raw = ""
                _ans_sent = ""
                _ans_ct = 0
                _ans_last_out = None
                _ans_disconnected = False
                async for answer_output in _stream_with_keepalive(
                    engine.stream_chat(messages=answer_messages, **answer_kwargs),
                    total_timeout=_stream_timeout,
                    progress_probe=(
                        None
                        if request.timeout is not None
                        else lambda: _engine_request_progress(
                            engine, f"{response_id}:visible-answer"
                        )
                    ),
                ):
                    if answer_output is None:
                        continue
                    if fastapi_request and await fastapi_request.is_disconnected():
                        if hasattr(engine, "abort_request"):
                            await engine.abort_request(f"{response_id}:visible-answer")
                        _ans_disconnected = True
                        break
                    _ans_last_out = answer_output
                    # Keep the decode-window timestamps live through the answer
                    # pass; otherwise the final decode tok/s line divides BOTH
                    # passes' tokens by only the first pass's span and
                    # overreports.
                    _decode_last_ts = _decode_output_timestamp(answer_output)
                    if _decode_first_ts is None:
                        _decode_first_ts = _decode_last_ts
                    _ans_ct = (
                        int(getattr(answer_output, "completion_tokens", 0) or 0)
                        or _ans_ct
                    )
                    _ans_raw += getattr(answer_output, "new_text", "") or ""
                    if incremental_usage_extension:
                        # The first pass already established authoritative
                        # cumulative usage.  Continue that same counter during
                        # the second pass; otherwise the Electron counter
                        # freezes while answer text is actively decoding.
                        _answer_usage = {
                            "input_tokens": prompt_tokens,
                            "output_tokens": completion_tokens + _ans_ct,
                            "total_tokens": (
                                prompt_tokens + completion_tokens + _ans_ct
                            ),
                        }
                        _answer_decode_usage = _decode_usage_snapshot(
                            completion_tokens=completion_tokens + _ans_ct,
                            first_token_ts=_decode_first_ts,
                            last_token_ts=_decode_last_ts,
                            first_token_count=_decode_first_count,
                        )
                        if _answer_decode_usage is not None:
                            _answer_usage["vmlx_decode"] = _answer_decode_usage
                        # The answer pass is a continuation of the same
                        # Responses request. Preserve the first pass's cache
                        # accounting instead of making the last incremental
                        # usage event appear to have lost its L1/L2 hit.
                        if _cached > 0 or _cache_detail:
                            _answer_input_details = {"cached_tokens": _cached}
                            if _cache_detail:
                                _answer_input_details["cache_detail"] = _cache_detail
                            _answer_usage["input_tokens_details"] = (
                                _answer_input_details
                            )
                        yield _sse(
                            "response.usage",
                            {
                                "type": "response.usage",
                                "usage": _answer_usage,
                            },
                        )
                    if _buffer_answer_pass:
                        continue
                    _delta, _ans_sent = _answer_pass_visible_delta(
                        _ans_raw,
                        _ans_sent,
                        request,
                        bool(getattr(answer_output, "finished", False)),
                        holdback=_answer_pass_stream_holdback(
                            _family_name,
                            buffer_answer_pass=_buffer_answer_pass,
                        ),
                        think_in_prompt=_native_reasoning_retry,
                        markup_guard=True,
                    )
                    if not _delta:
                        continue
                    for _event in _start_message_item_events():
                        yield _event
                    yield _sse(
                        "response.output_text.delta",
                        {
                            "type": "response.output_text.delta",
                            "item_id": msg_id,
                            "output_index": message_output_index,
                            "content_index": 0,
                            "delta": _delta,
                        },
                    )
                if _buffer_answer_pass:
                    _ans_truncated = (
                        getattr(_ans_last_out, "finish_reason", None) == "length"
                        or (_ans_budget_cap and _ans_ct >= _ans_budget_cap)
                    )
                    _full_delta, _ans_sent = _answer_pass_visible_delta(
                        _ans_raw,
                        "",
                        request,
                        True,
                        holdback=0,
                        think_in_prompt=_native_reasoning_retry,
                    )
                    logger.debug(
                        "%s buffered Responses answer pass result: "
                        "finish=%s ct=%d/%d raw_chars=%d visible_chars=%d "
                        "thinking_reentry=%s",
                        _answer_family,
                        getattr(_ans_last_out, "finish_reason", None),
                        _ans_ct,
                        _ans_budget_cap,
                        len(_ans_raw),
                        len(_full_delta),
                        _answer_pass_thinking_reentry(_ans_raw),
                    )
                    # Parity with the Chat Completions site (2026-07-12): emit a
                    # length-truncated but CLEAN answer instead of discarding to
                    # empty; discard ONLY on an actual <think> re-entry leak.
                    _ans_reasoning_leak = _answer_pass_thinking_reentry(_ans_raw)
                    if _full_delta and not _ans_reasoning_leak:
                        for _event in _start_message_item_events():
                            yield _event
                        yield _sse(
                            "response.output_text.delta",
                            {
                                "type": "response.output_text.delta",
                                "item_id": msg_id,
                                "output_index": message_output_index,
                                "content_index": 0,
                                "delta": _full_delta,
                            },
                        )
                    else:
                        _ans_sent = ""
                        if _ans_reasoning_leak:
                            logger.info(
                                "%s streaming Responses answer pass re-entered "
                                "reasoning (<think> leak, ct=%d/%d) — discarding to "
                                "avoid planning-prose leak; raise max_tokens",
                                _answer_family, _ans_ct, _ans_budget_cap,
                            )
                        elif _ans_truncated:
                            logger.info(
                                "%s streaming Responses answer pass truncated with "
                                "no visible content (ct=%d/%d) — raise max_tokens",
                                _answer_family, _ans_ct, _ans_budget_cap,
                            )
                if not _buffer_answer_pass and not _ans_disconnected and _ans_raw:
                    # Terminal disposition for the progressive lane (mirror of
                    # the Chat Completions site): the in-loop markup guard held
                    # back everything from the first native tool marker onward;
                    # resolve that remainder like the non-streaming answer pass
                    # — parse into structured function_call items when the
                    # original request offered tools, otherwise strip it as
                    # suppressed control markup. Clean prose finalizes to the
                    # already-streamed text and emits nothing new.
                    _ans_final_text, _ans_tool_calls = _answer_pass_finalize_visible(
                        _ans_raw,
                        request,
                        think_in_prompt=_native_reasoning_retry,
                        suppress_tools=_suppress_markup_display,
                    )
                    if _ans_final_text and _ans_final_text.startswith(_ans_sent):
                        _ans_final_tail = _ans_final_text[len(_ans_sent):]
                        if _ans_final_tail:
                            _ans_sent = _ans_final_text
                            for _event in _start_message_item_events():
                                yield _event
                            yield _sse(
                                "response.output_text.delta",
                                {
                                    "type": "response.output_text.delta",
                                    "item_id": msg_id,
                                    "output_index": message_output_index,
                                    "content_index": 0,
                                    "delta": _ans_final_tail,
                                },
                            )
                _answer_pass_succeeded = bool(_ans_sent) or bool(_ans_tool_calls)
                if _answer_pass_succeeded:
                    display_text = _ans_sent
                    streamed_text += _ans_sent
                    completion_tokens += int(_ans_ct or 0)
                    # The visible-answer pass now owns the terminal status. The
                    # first reasoning pass commonly ended with finish=length by
                    # design; retaining that stale output incorrectly emitted
                    # response.incomplete even when this pass stopped cleanly.
                    if _ans_last_out is not None:
                        last_output = _ans_last_out
                        _resp_finish = getattr(last_output, "finish_reason", None)
                        _note_request_diagnostics_id(response_id)
                        _response_terminal = _responses_terminal_state(
                            _resp_finish,
                            cancelled=_response_was_cancelled,
                            request_id=response_id,
                        )
                        _response_output_status = _response_terminal.item_status
                    if _ans_tool_calls:
                        logger.info(
                            "%s bounded Responses answer pass re-emitted a "
                            "schema-valid native tool call; emitting structured "
                            "function_call items instead of raw markup",
                            _answer_family,
                        )
                        for _event in _function_call_item_events(_ans_tool_calls):
                            yield _event
            except asyncio.CancelledError:
                logger.info(
                    "%s Responses visible answer pass cancelled, aborting %s",
                    _answer_family,
                    response_id,
                )
                if hasattr(engine, "abort_request"):
                    await engine.abort_request(f"{response_id}:visible-answer")
                    await engine.abort_request(response_id)
                raise
            except Exception as e:
                logger.error(
                    "%s visible answer pass failed for %s: %s",
                    _answer_family,
                    response_id,
                    e,
                    exc_info=True,
                )
        if not display_text and not _ans_tool_calls:
            # If reasoning was suppressed and model produced reasoning, the response
            # is intentionally empty. Report it as a diagnostic warning, not as
            # assistant output that would pollute user-visible text/history.
            if suppress_reasoning and accumulated_reasoning:
                display_text = ""
                logger.info(
                    f"Request {response_id}: model produced only reasoning ({len(accumulated_reasoning)} chars) — suppressed per user setting"
                )
                yield _sse(
                    "response.warning",
                    {
                        "type": "response.warning",
                        "code": "reasoning_only_no_content",
                        "message": (
                            "The model produced only internal reasoning, and "
                            "reasoning was suppressed for this request."
                        ),
                    },
                )
            elif reasoning_was_streamed:
                # Preserve the already-streamed reasoning rail, but leave
                # display_text empty. Finalization below marks this as
                # response.incomplete unless a visible answer or tool call
                # exists.
                display_text = ""
                logger.info(
                    f"Request {response_id}: reasoning-only completion "
                    f"({len(accumulated_reasoning)} chars reasoning, no content) — "
                    f"final response will be marked incomplete"
                )
            else:
                display_text = ""
                logger.warning(
                    f"Request {response_id}: empty response in Responses API; "
                    "leaving output_text empty instead of injecting a diagnostic assistant message"
                )
                yield _sse(
                    "response.warning",
                    {
                        "type": "response.warning",
                        "code": "empty_model_response",
                        "message": (
                            "The model produced no visible response. Check server logs "
                            "for generation details."
                        ),
                    },
                )

        if _suppress_markup_display and display_text:
            display_text = _clean_suppressed_tool_markup_for_display(
                display_text,
                request,
            )
        if display_text:
            display_text = _finalize_visible_text_for_request(display_text, request, minimum_partial=4)

        if display_text or message_item_started or _final_reasoning_item is None:
            _message_was_started = message_item_started
            for _event in _start_message_item_events():
                yield _event
            if display_text and not _message_was_started:
                yield _sse(
                    "response.output_text.delta",
                    {
                        "type": "response.output_text.delta",
                        "item_id": msg_id,
                        "output_index": message_output_index,
                        "content_index": 0,
                        "delta": display_text,
                    },
                )
            yield _sse(
                "response.output_text.done",
                {
                    "type": "response.output_text.done",
                    "item_id": msg_id,
                    "output_index": message_output_index,
                    "content_index": 0,
                    "text": display_text,
                },
            )
            yield _sse(
                "response.content_part.done",
                {
                    "type": "response.content_part.done",
                    "item_id": msg_id,
                    "output_index": message_output_index,
                    "content_index": 0,
                    "part": {
                        "type": "output_text",
                        "text": display_text,
                        "annotations": [],
                    },
                },
            )
            message_item = {
                "id": msg_id,
                "type": "message",
                "status": _response_output_status,
                "role": "assistant",
                "content": [
                    {"type": "output_text", "text": display_text, "annotations": []}
                ],
            }
            yield _sse(
                "response.output_item.done",
                {
                    "type": "response.output_item.done",
                    "output_index": message_output_index,
                    "item": message_item,
                },
            )
            _record_output_item(message_output_index, message_item)

    all_output_items = [
        _indexed_output_items[index] for index in sorted(_indexed_output_items)
    ]

    # H4: Validate text format at end of stream.
    _text_fmt = getattr(request, "text", None)
    # Convert Pydantic model to dict for uniform access
    if _text_fmt and hasattr(_text_fmt, "model_dump"):
        _text_fmt = _text_fmt.model_dump(exclude_none=True)
    if (
        _text_fmt
        and isinstance(_text_fmt, dict)
        and _text_fmt.get("type") not in (None, "text")
    ):
        _rf_type = _text_fmt.get("type", "")
        if _rf_type == "xml" and display_text:
            _xml_config = _xml_response_format_config(_text_fmt)
            if _xml_config is not None:
                _xml_report = repair_xml_output(
                    display_text,
                    root_tag=_xml_config.get("root_tag"),
                    required_fields=_xml_config.get("required_fields") or (),
                )
                if not _xml_report.get("is_valid"):
                    _err = _xml_report.get("error")
                    if _xml_config.get("strict"):
                        logger.warning(
                            f"Stream {response_id}: XML validation failed (strict): {_err}"
                        )
                        yield _sse(
                            "error",
                            {
                                "type": "error",
                                "message": f"response_format strict mode: {_err}",
                                "code": "xml_validation_failed",
                            },
                        )
                    else:
                        logger.warning(
                            f"Stream {response_id}: XML validation failed: {_err}"
                        )
        elif _rf_type in ("json_schema", "json_object") and display_text:
            _, _pj, _valid, _err = parse_json_output(display_text, _text_fmt)
            if not _valid:
                _strict = _text_fmt.get("json_schema", {}).get("strict", False)
                if _strict:
                    logger.warning(
                        f"Stream {response_id}: JSON schema validation failed (strict): {_err}"
                    )
                    yield _sse(
                        "error",
                        {
                            "type": "error",
                            "message": f"response_format strict mode: {_err}",
                            "code": "json_validation_failed",
                        },
                    )
                else:
                    logger.warning(
                        f"Stream {response_id}: JSON validation failed: {_err}"
                    )

    # Enforce tool_choice="required" in Responses API streaming.  An error
    # event followed by response.completed is contradictory: strict clients
    # dispatch terminal handling from the response.* event and can therefore
    # mistake an unmet required-tool contract for success.  Keep the error
    # event for incremental consumers, then terminate with response.failed.
    _resp_stream_tc = getattr(request, "tool_choice", None)
    _required_tool_contract_failed = bool(
        _is_pending_required_tool_choice(request) and not tool_calls
    )
    _required_tool_error = None
    if _required_tool_contract_failed:
        _required_tool_error = {
            "type": "invalid_request_error",
            "message": (
                f"{_describe_required_tool_choice(_resp_stream_tc)} was set but the model did not "
                "produce any tool calls. Try rephrasing your prompt or using a "
                "model with better tool-calling support."
            ),
            "code": "tool_calls_required",
        }
        logger.warning(
            f"Stream {response_id}: tool_choice='required' but no tool calls produced"
        )
        yield _sse(
            "error",
            {
                "type": "error",
                "error": _required_tool_error,
                "message": _required_tool_error["message"],
                "code": _required_tool_error["code"],
            },
        )

    # Emit the terminal event that matches the final response status. OpenAI's
    # Responses stream uses response.incomplete when max_output_tokens is hit;
    # a response.completed envelope with status=incomplete breaks clients that
    # dispatch terminal handling by event type.
    # Compute the terminal only after any visible-answer pass has replaced
    # ``last_output``. The second pass owns the terminal cause when its output
    # was accepted; retaining the first pass's length here falsely marked a
    # clean visible answer incomplete.
    _resp_finish = getattr(last_output, "finish_reason", None) if last_output else None
    # Reasoning-only detection mirrors the non-stream path. Empty streaming
    # output_text shells do not count as visible output. Compute this before the
    # terminal state so a natural EOS inside the reasoning rail cannot be
    # reported as response.completed.
    _stream_reasoning_only = _responses_output_is_reasoning_only(all_output_items)
    _note_request_diagnostics_id(response_id)
    _response_terminal = _responses_terminal_state(
        _resp_finish,
        cancelled=_response_was_cancelled,
        failed=_required_tool_contract_failed,
        reasoning_only_no_content=_stream_reasoning_only,
        request_id=response_id,
    )
    _resp_status = _response_terminal.response_status
    _resp_extra: dict = {}
    if _response_terminal.incomplete_details:
        _resp_extra["incomplete_details"] = _response_terminal.incomplete_details

    # The terminal response is the authoritative snapshot. Keep every retained
    # item aligned with it even when an earlier reasoning stage ended before a
    # bounded visible-answer continuation selected the final terminal cause.
    for _item in all_output_items:
        if isinstance(_item, dict) and "status" in _item:
            _item["status"] = _response_terminal.item_status
    _stream_chain_warnings = _chain_warnings_for_previous_response_id(
        getattr(request, "previous_response_id", None)
    )
    # Bug 5: surface dropped-tool-call diagnostics on the Responses API too
    # (same root cause + same UX gap as the Chat Completions stream).
    _dropped_tc_diagnostics = _take_tool_call_drop_diagnostics()
    _stream_warnings = _merge_responses_warnings(
        _stream_chain_warnings,
        _current_response_warnings_for_reasoning_only(
            _stream_reasoning_only,
            _resp_finish,
        ),
        _dropped_tc_diagnostics or None,
    )

    # Effort substitution rides the terminal snapshot additively (chat-stream
    # parity). Pop, not peek — this snapshot builds exactly once per stream.
    from vmlx_engine.context_limits import pop_effort_substitution as _pop_effort

    _effort_record = _pop_effort(str(response_id))
    completed_response = {
        "id": response_id,
        "object": "response",
        "created_at": created_at,
        "status": _resp_status,
        "model": request.model,
        "output_text": display_text,
        "output": all_output_items,
        **_resp_extra,
        **({"effort_substitution": _effort_record} if _effort_record else {}),
        **({"error": _required_tool_error} if _required_tool_error else {}),
        **({"warnings": _stream_warnings} if _stream_warnings else {}),
        "usage": {
            "input_tokens": prompt_tokens,
            "output_tokens": completion_tokens,
            "total_tokens": prompt_tokens + completion_tokens,
            **(
                {
                    "input_tokens_details": (
                        {"cached_tokens": _cached, "cache_detail": _cache_detail}
                        if _cache_detail
                        else {"cached_tokens": _cached}
                    )
                }
                if _cached > 0 or _cache_detail
                else {}
            ),
        },
    }
    if not _response_was_cancelled and not _required_tool_contract_failed:
        _responses_store_history(
            response_id,
            (history_messages if history_messages is not None else messages)
            + _responses_output_to_assistant_messages(all_output_items),
            reasoning_only=_stream_reasoning_only,
        )
    if (
        completion_tokens > 1
        and _decode_first_ts is not None
        and _decode_last_ts > _decode_first_ts
    ):
        _decode_elapsed = _decode_last_ts - _decode_first_ts
        logger.info(
            f"Response (stream): {completion_tokens} tokens in "
            f"{_decode_elapsed:.2f}s "
            f"({(completion_tokens - _decode_first_count) / _decode_elapsed:.1f} tok/s decode) "
            f"therm={thermal_state_name()}"
        )
    # Parser branches can ``continue`` after token tracking (reasoning and
    # tool-control paths in particular), skipping the per-output private usage
    # event above. The local Electron client needs one unconditional full-count
    # receipt before the standard terminal so an agent/tool exchange cannot
    # end on a stale partial token/timing snapshot. This event remains behind
    # the explicit local-only negotiation header; public Responses streams keep
    # their standard terminal usage shape and event union.
    if incremental_usage_extension:
        _terminal_private_usage = dict(completed_response["usage"])
        _terminal_decode_usage = _decode_usage_snapshot(
            completion_tokens=completion_tokens,
            first_token_ts=_decode_first_ts,
            last_token_ts=_decode_last_ts,
            first_token_count=_decode_first_count,
        )
        if _terminal_decode_usage is not None:
            _terminal_private_usage["vmlx_decode"] = _terminal_decode_usage
        yield _sse(
            "response.usage",
            {
                "type": "response.usage",
                "usage": _terminal_private_usage,
            },
        )
    yield _sse(
        _response_terminal.event_type,
        {
            "type": _response_terminal.event_type,
            "response": completed_response,
        },
    )


# =============================================================================
# MCP Initialization
# =============================================================================


def _discover_mcp_config_for_startup() -> str | None:
    """Return an MCP config path worth starting, or None.

    ``load_mcp_config(None)`` already implements the expected search order:
    env var, cwd ``mcp.json``/``mcp.yaml``, then the user config directory.
    Startup should use that path when it declares servers, but it should not
    initialize the MCP manager for an absent or empty config.
    """
    explicit_env_config = False
    try:
        from pathlib import Path

        from vmlx_engine.mcp.config import (
            CONFIG_ENV_VAR,
            _find_config_file,
            load_mcp_config,
        )

        env_config = os.environ.get(CONFIG_ENV_VAR)
        explicit_env_config = bool(env_config)
        if explicit_env_config:
            config_path = Path(env_config).expanduser()
            config = load_mcp_config(config_path)
        else:
            config = load_mcp_config(None)
            config_path = _find_config_file(None)
            if config_path is None:
                return None

        config_path = Path(config_path).expanduser().resolve()
        if not config.servers:
            logger.info("MCP config discovered at %s but contains no servers", config_path)
            return None
        return str(config_path)
    except FileNotFoundError:
        if explicit_env_config:
            raise
        return None
    except Exception as e:
        if explicit_env_config:
            raise
        logger.error("Failed to discover MCP config — continuing without MCP: %s", e)
        return None


async def init_mcp(config_path: str):
    """Initialize MCP manager from config file."""
    global _mcp_manager, _mcp_policy

    try:
        from vmlx_engine.mcp import MCPClientManager, load_mcp_config

        config = load_mcp_config(config_path)
        _mcp_policy = _load_mcp_policy_from_env()
        _mcp_manager = MCPClientManager(config)
        await _mcp_manager.start()

        logger.info(
            f"MCP initialized with {len(_mcp_manager.get_all_tools(policy=_mcp_policy))} effective tools"
        )

    except ImportError:
        logger.error("MCP SDK not installed. Install with: pip install mcp")
        raise
    except Exception as e:
        logger.error(f"Failed to initialize MCP: {e}")
        raise


# =============================================================================
# Main Entry Point
# =============================================================================


def _raise_nofile_soft_limit() -> None:
    """Raise the open-file soft limit before serving.

    macOS shells default RLIMIT_NOFILE to 256, which a long-context serve can
    burst through (per-thread SQLite handles + block payload reads + sockets).
    Running out mid-request degrades importlib/disk reads into broad-except
    fallbacks and poisons cache lookups, so lift the ceiling up front.
    """
    try:
        import resource

        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
        for target in (65536, 10240, 8192, 4096):
            if soft >= target:
                return
            new_soft = target if hard == resource.RLIM_INFINITY else min(target, hard)
            if new_soft <= soft:
                continue
            try:
                resource.setrlimit(resource.RLIMIT_NOFILE, (new_soft, hard))
            except (ValueError, OSError):
                continue
            logger.info(
                "Raised RLIMIT_NOFILE soft limit %d -> %d", soft, new_soft
            )
            return
    except Exception as exc:
        logger.warning("Could not raise RLIMIT_NOFILE soft limit: %s", exc)


def _delegate_module_main_to_cli(argv: list[str] | None = None) -> bool:
    """Route ``python -m vmlx_engine.server`` through the CLI's serve path.

    This module's ``main()`` grew its own argparse, and it is a SECOND LAUNCHER:
    it applies none of the family policy that ``cli.py`` applies. Started this
    way, an engine gets ``--timeout 300`` with no slow-family lift, no
    paged-cache default, no cache-index sizing by target tokens, and no
    TQ/DSV4 policy — the same "same build, different launcher" class as the
    max-cache-blocks 1000-vs-4097 defect, which cost a 77k prompt all of its
    reuse depending only on how the process was started.

    It is not dead code, which is why it cannot simply be deleted: the panel
    parses and ADOPTS processes started this way (`sessions.ts` looks for
    "python -m vmlx_engine.server"), so a session created from one silently
    inherits the unpoliced defaults.

    The two parsers are near-identical — of this module's 35 flags, the CLI's
    serve subcommand already accepts 33 by the same name, and the other two map
    cleanly (``--model X`` is the CLI's positional, ``--mllm`` is its
    ``--is-mllm``). So translate and delegate rather than maintain two
    launchers. Returns True when it handled the invocation.
    """
    argv = list(sys.argv[1:] if argv is None else argv)
    translated: list[str] = []
    model: str | None = None
    index = 0
    while index < len(argv):
        token = argv[index]
        if token == "--model":
            if index + 1 >= len(argv):
                return False  # malformed; let the local parser report it
            model = argv[index + 1]
            index += 2
            continue
        if token.startswith("--model="):
            model = token.split("=", 1)[1]
            index += 1
            continue
        if token == "--mllm":
            translated.append("--is-mllm")
            index += 1
            continue
        translated.append(token)
        index += 1

    from .cli import main as cli_main

    serve_argv = ["serve"]
    if model is not None:
        serve_argv.append(model)
    serve_argv.extend(translated)

    logger.warning(
        "`python -m vmlx_engine.server` is delegating to `vmlx-engine serve`. "
        "The module entry point applies no family policy of its own, so "
        "running it directly used to skip the slow-family timeout, the paged "
        "cache default and the token-sized cache index. Prefer "
        "`vmlx-engine serve <model>`."
    )
    sys.argv = [sys.argv[0], *serve_argv]
    cli_main()
    return True


def main():
    """Run the server."""
    _raise_nofile_soft_limit()
    parser = argparse.ArgumentParser(
        description="vmlx-engine OpenAI-compatible server for LLM and MLLM inference",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
    # Start with simple mode (maximum throughput)
    python -m vmlx_engine.server --model mlx-community/Llama-3.2-3B-Instruct-4bit

    # Start with continuous batching (for multiple users)
    python -m vmlx_engine.server --model mlx-community/Llama-3.2-3B-Instruct-4bit --continuous-batching

    # With MCP tools
    python -m vmlx_engine.server --model mlx-community/Qwen3-4B-4bit --mcp-config mcp.json
        """,
    )
    parser.add_argument(
        "--model",
        type=str,
        default="mlx-community/Llama-3.2-3B-Instruct-4bit",
        help="Model to load (HuggingFace model name or local path)",
    )
    parser.add_argument(
        "--host",
        type=str,
        default="127.0.0.1",
        help="Host to bind to (use 0.0.0.0 for LAN access)",
    )
    parser.add_argument(
        "--port",
        type=int,
        default=8000,
        help="Port to bind to",
    )
    parser.add_argument(
        "--mllm",
        action="store_true",
        help="Force loading as MLLM (multimodal language model)",
    )
    parser.add_argument(
        "--continuous-batching",
        dest="continuous_batching",
        action="store_true",
        default=True,
        help="Enable continuous batching/cache-stack path (default: enabled)",
    )
    parser.add_argument(
        "--no-continuous-batching",
        dest="continuous_batching",
        action="store_false",
        help="Use SimpleEngine and disable cache-stack features that require batching",
    )
    # Smelt options
    parser.add_argument(
        "--smelt",
        action="store_true",
        help="Enable MoE Smelt mode (partial expert loading for JANG MoE models)",
    )
    parser.add_argument(
        "--smelt-experts",
        type=int,
        default=50,
        help="Percentage of experts to load in Smelt mode (default: 50)",
    )
    parser.add_argument(
        "--mcp-config",
        type=str,
        default=None,
        help="Path to MCP configuration file (JSON/YAML)",
    )
    parser.add_argument(
        "--mcp-enabled-servers",
        type=str,
        default=None,
        help="Comma-separated MCP server allow-list for this model session",
    )
    parser.add_argument(
        "--mcp-disabled-servers",
        type=str,
        default=None,
        help="Comma-separated MCP server deny-list for this model session",
    )
    parser.add_argument(
        "--mcp-enabled-tools",
        type=str,
        default=None,
        help="Comma-separated MCP tool allow-list for this model session",
    )
    parser.add_argument(
        "--mcp-disabled-tools",
        type=str,
        default=None,
        help="Comma-separated MCP tool deny-list for this model session",
    )
    parser.add_argument(
        "--max-tokens",
        type=int,
        default=_FALLBACK_MAX_OUTPUT_TOKENS,
        help=(
            "Default max tokens for generation when explicitly supplied. "
            "If omitted, request > bundle max_new_tokens > bounded engine fallback applies."
        ),
    )
    parser.add_argument(
        "--max-prompt-tokens",
        type=int,
        default=None,
        help="Maximum prompt/context tokens accepted before prefill. "
        "If omitted, vMLX uses the automatic memory-safe prompt limit.",
    )
    parser.add_argument(
        "--api-key",
        type=str,
        default=None,
        help="API key for authentication (if not set, no auth required)",
    )
    parser.add_argument(
        "--enable-private-cache-attestation",
        action="store_true",
        help=argparse.SUPPRESS,
    )
    parser.add_argument(
        "--private-cache-attestation-token-file",
        type=str,
        default=None,
        help=argparse.SUPPRESS,
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=300.0,
        help="Default request timeout in seconds (default: 300)",
    )
    parser.add_argument(
        "--rate-limit",
        type=int,
        default=0,
        help="Rate limit requests per minute per client (0 = disabled)",
    )
    # Reasoning parser options - choices loaded dynamically from registry
    from .reasoning import list_parsers

    reasoning_choices = list_parsers()
    parser.add_argument(
        "--reasoning-parser",
        type=str,
        default=None,
        choices=["auto", "none"] + reasoning_choices,
        help=(
            "Enable reasoning content extraction with specified parser. "
            "Use 'auto' to detect from model name, or 'none' to disable explicitly. "
            f"Options: auto, none, {', '.join(reasoning_choices)}."
        ),
    )
    parser.add_argument(
        "--embedding-model",
        type=str,
        default=None,
        help="Pre-load an embedding model at startup (e.g. mlx-community/all-MiniLM-L6-v2-4bit)",
    )
    parser.add_argument(
        "--default-temperature",
        type=float,
        default=None,
        help="Default temperature for generation when not specified in request",
    )
    parser.add_argument(
        "--default-top-p",
        type=float,
        default=None,
        help="Default top_p for generation when not specified in request",
    )
    parser.add_argument(
        "--default-top-k",
        type=int,
        default=None,
        help="Default top_k for generation when not specified in request",
    )
    parser.add_argument(
        "--default-min-p",
        type=float,
        default=None,
        help="Default min_p for generation when not specified in request",
    )
    parser.add_argument(
        "--default-repetition-penalty",
        type=float,
        default=None,
        help=(
            "Default repetition penalty when not specified in request. "
            "1.0 = no penalty, higher = less repetition. "
            "Without this flag, external API clients (curl, Ollama, OpenAI SDK, "
            "Anthropic SDK) use bundle metadata when present; otherwise no "
            "server-wide repetition penalty is applied."
        ),
    )
    parser.add_argument(
        "--native-mtp-depth",
        type=int,
        default=None,
        help="Depth for native in-model MTP heads on preserved-MTP bundles (1-3).",
    )
    parser.add_argument(
        "--native-mtp-depth-policy",
        choices=["adaptive", "fixed"],
        default=None,
        help="Native-MTP depth policy: adaptive may change the selected starting "
        "depth per request; fixed keeps it exact for non-tool requests.",
    )
    parser.add_argument(
        "--native-mtp-sampling-policy",
        choices=["compatible-only", "deterministic-defaults", "greedy-only"],
        default="compatible-only",
        help="Native MTP request policy for startup diagnostics and app defaults.",
    )
    parser.add_argument(
        "--disable-native-mtp",
        action="store_true",
        default=False,
        help="Disable native in-model MTP even when bundle metadata is available.",
    )
    parser.add_argument(
        "--omni-backend",
        choices=["stage1", "stage2"],
        default=None,
        help="Nemotron-Omni multimodal backend. stage1 is correctness-first "
        "PyTorch/MPS; stage2 opts into native MLX RADIO + Parakeet via "
        "VMLINUX_OMNI_BACKEND=stage2.",
    )
    parser.add_argument(
        "--default-enable-thinking",
        type=str,
        default=None,
        choices=["true", "false"],
        help="Server-level default for enable_thinking when not specified in request. "
        "Without this, models with reasoning parsers default to thinking ON. "
        "Use 'false' to disable thinking for external API clients (OpenCode, etc.)",
    )
    parser.add_argument(
        "--enable-auto-tool-choice",
        action="store_true",
        help="Enable automatic tool choice for supported models",
    )
    parser.add_argument(
        "--tool-call-parser",
        type=str,
        default=None,
        help="Tool call parser to use (auto, hermes, qwen, llama, step3p5, mistral, etc.)",
    )
    parser.add_argument(
        "--served-model-name",
        type=str,
        default=None,
        help="Custom model name exposed via the API (overrides actual model name in /v1/models)",
    )

    max_tokens_explicit = _argv_has_option(sys.argv[1:], "--max-tokens")
    args = parser.parse_args()

    # Set global configuration
    global _api_key, _default_timeout, _rate_limiter
    global _private_cache_attestation_enabled, _private_cache_attestation_token
    global _default_temperature, _default_top_p, _default_top_k, _default_min_p, _default_repetition_penalty, _default_enable_thinking
    global _native_mtp_sampling_policy
    global _inference_endpoints, _wake_timeout
    global _smelt_enabled, _smelt_experts

    _api_key = args.api_key or os.environ.get("VLLM_API_KEY")
    _private_cache_attestation_enabled = False
    _private_cache_attestation_token = None
    private_attestation_enabled = bool(args.enable_private_cache_attestation)
    private_attestation_token_file = args.private_cache_attestation_token_file
    if private_attestation_enabled != bool(private_attestation_token_file):
        parser.error(
            "private cache attestation requires both its enable flag and token file"
        )
    if private_attestation_enabled:
        try:
            _private_cache_attestation_token = (
                _load_private_cache_attestation_token_file(
                    private_attestation_token_file
                )
            )
        except (OSError, ValueError) as exc:
            parser.error(f"invalid private cache attestation token file: {exc}")
        _private_cache_attestation_enabled = True
        os.environ["VMLX_STRICT_BLOCK_DISK_WRITE_FENCE"] = "1"
    _default_timeout = args.timeout
    if getattr(args, "inference_endpoints", None):
        _inference_endpoints = [
            e.strip() for e in args.inference_endpoints.split(",") if e.strip()
        ]
    if getattr(args, "wake_timeout", None) is not None:
        _wake_timeout = args.wake_timeout

    if getattr(args, "smelt", False):
        _smelt_enabled = True
        _smelt_experts = getattr(args, "smelt_experts", 50)

    if args.default_temperature is not None:
        _default_temperature = args.default_temperature
    if args.default_top_p is not None:
        _default_top_p = args.default_top_p
    if getattr(args, "default_top_k", None) is not None:
        _default_top_k = args.default_top_k
    if getattr(args, "default_min_p", None) is not None:
        _default_min_p = args.default_min_p
    if getattr(args, "default_repetition_penalty", None) is not None:
        _default_repetition_penalty = args.default_repetition_penalty
    if getattr(args, "disable_native_mtp", False):
        os.environ["VMLINUX_NATIVE_MTP"] = "0"
    if getattr(args, "native_mtp_depth", None) is not None:
        from .native_mtp import native_mtp_max_depth

        os.environ["VMLINUX_NATIVE_MTP_DEPTH"] = str(
            max(1, min(native_mtp_max_depth(), int(args.native_mtp_depth)))
        )
    if getattr(args, "native_mtp_depth_policy", None) is not None:
        os.environ["VMLINUX_NATIVE_MTP_ADAPTIVE_DEPTH"] = (
            "0" if args.native_mtp_depth_policy == "fixed" else "1"
        )
    _native_mtp_sampling_policy = getattr(args, "native_mtp_sampling_policy", "compatible-only")
    os.environ["VMLINUX_NATIVE_MTP_SAMPLING_POLICY"] = _native_mtp_sampling_policy
    if _native_mtp_sampling_policy in {"deterministic-defaults", "greedy-only"}:
        if _default_temperature is None:
            _default_temperature = 0.0
        if _default_top_p is None:
            _default_top_p = 1.0
        if _default_top_k is None:
            _default_top_k = 0
        if _default_min_p is None:
            _default_min_p = 0.0
    if getattr(args, "omni_backend", None):
        os.environ["VMLINUX_OMNI_BACKEND"] = args.omni_backend
    if args.default_enable_thinking is not None:
        _default_enable_thinking = args.default_enable_thinking == "true"

    # Configure rate limiter
    if args.rate_limit > 0:
        _rate_limiter = RateLimiter(requests_per_minute=args.rate_limit, enabled=True)
        logger.info(
            f"Rate limiting enabled: {args.rate_limit} requests/minute per client"
        )

    # Security summary at startup
    logger.info("=" * 60)
    logger.info("SECURITY CONFIGURATION")
    logger.info("=" * 60)
    if _api_key:
        logger.info("  Authentication: ENABLED (API key required)")
    else:
        logger.warning("  Authentication: DISABLED - Use --api-key to enable")
    if args.rate_limit > 0:
        logger.info(f"  Rate limiting: ENABLED ({args.rate_limit} req/min)")
    else:
        logger.warning("  Rate limiting: DISABLED - Use --rate-limit to enable")
    logger.info(f"  Request timeout: {args.timeout}s")
    logger.info("=" * 60)

    # Set MCP config for lifespan
    if args.mcp_config:
        os.environ["VLLM_MLX_MCP_CONFIG"] = args.mcp_config
    if args.mcp_enabled_servers:
        os.environ["VLLM_MLX_MCP_ENABLED_SERVERS"] = args.mcp_enabled_servers
    if args.mcp_disabled_servers:
        os.environ["VLLM_MLX_MCP_DISABLED_SERVERS"] = args.mcp_disabled_servers
    if args.mcp_enabled_tools:
        os.environ["VLLM_MLX_MCP_ENABLED_TOOLS"] = args.mcp_enabled_tools
    if args.mcp_disabled_tools:
        os.environ["VLLM_MLX_MCP_DISABLED_TOOLS"] = args.mcp_disabled_tools

    # Auto-detect reasoning and tool parsers from model name
    from .model_config_registry import get_model_config_registry

    model_name = args.model or ""
    registry = get_model_config_registry()

    # Initialize reasoning parser (auto-detect or explicit)
    global _reasoning_parser, _reasoning_parser_disabled_explicitly
    from .reasoning import get_parser

    parser_name = args.reasoning_parser
    # Auto-detect from model config if not explicitly set
    if not parser_name:
        detected = registry.get_reasoning_parser(model_name)
        if detected:
            parser_name = detected
            logger.info(
                f"Auto-detected reasoning parser: {parser_name} (from model config)"
            )
    elif parser_name == "none":
        # Explicitly disabled by user
        parser_name = None
        _reasoning_parser_disabled_explicitly = True
        logger.info("Reasoning parser explicitly disabled via --reasoning-parser none")
    elif parser_name == "auto":
        detected = registry.get_reasoning_parser(model_name)
        if detected:
            parser_name = detected
            logger.info(
                f"Auto-detected reasoning parser: {parser_name} (from model name)"
            )
        else:
            logger.info("Reasoning parser 'auto': no parser detected for this model")
            parser_name = None

    if parser_name:
        try:
            parser_cls = get_parser(parser_name)
            _set_active_reasoning_parser(parser_cls(), parser_name)
            logger.info(f"Reasoning parser enabled: {parser_name}")
        except KeyError:
            logger.warning(
                f"Reasoning parser '{parser_name}' not found. "
                f"Available: {list_parsers()}"
            )

    # Initialize tool call parser from CLI args
    global _tool_call_parser, _enable_auto_tool_choice
    global _tool_call_parser_disabled_explicitly
    # An explicit `none` is a disable regardless of --enable-auto-tool-choice.
    # The per-request fallbacks auto-detect a parser from the registry whenever
    # a request carries tools, with or without that flag, so clearing
    # _tool_call_parser alone leaves the opt-out inert exactly as it did on the
    # reasoning side. cli.py publishes this; this second launcher did not.
    if args.tool_call_parser == "none":
        _tool_call_parser_disabled_explicitly = True
    if args.enable_auto_tool_choice:
        _enable_auto_tool_choice = True
        _tool_call_parser = args.tool_call_parser or "auto"
        if _tool_call_parser == "none":
            # Explicitly disabled by user
            _enable_auto_tool_choice = False
            _tool_call_parser = None
            logger.info("Tool calling explicitly disabled via --tool-call-parser none")
        elif _tool_call_parser == "auto":
            detected_tool = registry.get_tool_parser(model_name)
            if detected_tool:
                _tool_call_parser = detected_tool
                logger.info(
                    f"Auto-detected tool call parser: {_tool_call_parser} (from model name)"
                )
            else:
                logger.info(
                    "Tool call parser 'auto': no specific parser detected, using generic"
                )
                _tool_call_parser = None
        if _tool_call_parser:
            logger.info(f"Tool calling enabled (parser: {_tool_call_parser})")

    # Pre-load embedding model if specified
    load_embedding_model(args.embedding_model, lock=True)

    # Load model before starting server
    load_model(
        args.model,
        use_batching=args.continuous_batching,
        max_tokens=args.max_tokens,
        max_tokens_explicit=max_tokens_explicit,
        max_prompt_tokens=args.max_prompt_tokens,
        force_mllm=args.mllm,
        served_model_name=args.served_model_name,
        smelt=getattr(args, "smelt", False),
        smelt_experts=getattr(args, "smelt_experts", 50),
    )

    # Start server
    uvicorn.run(app, host=args.host, port=args.port)


if __name__ == "__main__":
    # Only the MODULE entry point delegates. Anything that imports and calls
    # server.main() directly keeps the old behaviour, so this cannot change a
    # caller that already has its own policy layer.
    if not _delegate_module_main_to_cli():
        main()
